const STATION_STATE_LAST_WRITE_COALESCE_REQUESTED = process.env.BACKEND_STATION_STATE_LAST_WRITE_COALESCE === "1", STATION_STATE_LAST_WRITE_COALESCE = STATION_STATE_LAST_WRITE_COALESCE_REQUESTED && DB_MODE === "mysql" && APP_STATE_DEVICE_STATUS_SPLIT_MODE !== "externalized", STATION_STATE_LAST_WRITE_COALESCE_INTERVAL_MS = Math.max(25, Math.min(parsePositiveInt(process.env.BACKEND_STATION_STATE_LAST_WRITE_COALESCE_INTERVAL_MS, 250), 5_000));
if (STATION_STATE_LAST_WRITE_COALESCE_REQUESTED && APP_STATE_DEVICE_STATUS_SPLIT_MODE === "externalized") throw new Error("Coalescing lastWriteAt station-state incompatibile con device status externalized.");
const LANE_CROSS_EXCLUSION_ORDERS = process.env.LANE_CROSS_EXCLUSION_ORDERS !== "0", LANE_CROSS_EXCLUSION_TABLES = process.env.LANE_CROSS_EXCLUSION_TABLES !== "0", LANE_CROSS_EXCLUSION_PAYMENTS = process.env.LANE_CROSS_EXCLUSION_PAYMENTS !== "0", LANE_CROSS_EXCLUSION_PRESENCE = process.env.LANE_CROSS_EXCLUSION_PRESENCE !== "0";
let printSpoolWorker = Promise.resolve(), printSpoolWorkerQueued = false, printSpoolOwnerPollTimer = null;
let printSpoolRetryTimer = null;
