function orderLanePeerRunningForRoomLikeLanes() {
  return LANE_CROSS_EXCLUSION_ORDERS && orderSyncLaneRunning > 0;
}

function roomLikeLanePeerRunningForOrderLane() {
  if (!LANE_CROSS_EXCLUSION_ORDERS) return false;
  return (
    roomLaneRunning > 0 ||
    reservationLane.runningCount() > 0 ||
    notificationLane.runningCount() > 0
  );
}

function roomLanePeerRunningForReservationLane() {
  return LANE_CROSS_EXCLUSION_TABLES && roomLaneRunning > 0;
}

function reservationLanePeerRunningForRoomLane() {
  return LANE_CROSS_EXCLUSION_TABLES && reservationLane.runningCount() > 0;
}

function notificationLanePeerRunningForRoomLikeLanes() { return LANE_CROSS_EXCLUSION_TABLES && notificationLane.runningCount() > 0; }

function roomLikeLanePeerRunningForNotificationLane() { return LANE_CROSS_EXCLUSION_TABLES && (roomLaneRunning > 0 || reservationLane.runningCount() > 0); }

function paymentLanePeerRunningForDomainLanes() {
  return LANE_CROSS_EXCLUSION_PAYMENTS && paymentLaneRunning > 0;
}

function domainLanePeerRunningForPaymentLane() {
  if (!LANE_CROSS_EXCLUSION_PAYMENTS) return false;
  return (
    orderSyncLaneRunning > 0 ||
    roomLaneRunning > 0 ||
    reservationLane.runningCount() > 0 ||
    notificationLane.runningCount() > 0 ||
    waiterPauseLane?.runningCount?.() > 0 ||
    stationStateLane.runningCount() > 0
  );
}

function presenceLanePeerRunningForRoomLikeLanes() { if (!LANE_CROSS_EXCLUSION_PRESENCE) return false; return waiterPauseLane?.runningCount?.() > 0 || stationStateLane?.runningCount?.() > 0; }
function roomLikeLanePeerRunningForPresenceLane() { if (!LANE_CROSS_EXCLUSION_PRESENCE) return false; return roomLaneRunning > 0 || reservationLane.runningCount() > 0 || notificationLane.runningCount() > 0; }
function stationStateLanePeerRunningForOrderLane() { return LANE_CROSS_EXCLUSION_PRESENCE && stationStateLane?.runningCount?.() > 0; }
function domainLaneRunningCount() {
  return (
    orderSyncLaneRunning +
    paymentLaneRunning +
    roomLaneRunning +
    reservationLane.runningCount() +
    notificationLane.runningCount() +
    waiterPauseLane.runningCount() +
    stationStateLane.runningCount()
  );
}

function hasDomainLaneRunning() {
  return domainLaneRunningCount() > 0;
}

function domainLanePeerQueuePressureDepth(target) {
  return getLanePeerQueuePressureDepth(
    target,
    {
      order: orderSyncLaneQueue.length,
      payment: paymentLaneQueue.length,
      room: roomLaneQueue.length,
      reservation: reservationLane?.depth?.() ?? 0,
      notification: notificationLane?.depth?.() ?? 0,
      waiterPause: waiterPauseLane?.depth?.() ?? 0,
      stationState: stationStateLane?.depth?.() ?? 0,
    },
    {
      orders: LANE_CROSS_EXCLUSION_ORDERS,
      tables: LANE_CROSS_EXCLUSION_TABLES,
      payments: LANE_CROSS_EXCLUSION_PAYMENTS,
      presence: LANE_CROSS_EXCLUSION_PRESENCE,
    },
  );
}

function resetDomainLaneBurst(target) {
  if (target === "order") orderSyncLaneBurstCount = 0;
  else if (target === "payment") paymentLaneBurstCount = 0;
  else if (target === "room") roomLaneBurstCount = 0;
  else if (target === "reservation") reservationLane?.resetBurst?.();
  else if (target === "notification") notificationLane?.resetBurst?.();
  else if (target === "waiterPause") waiterPauseLane?.resetBurst?.();
  else if (target === "stationState") stationStateLane?.resetBurst?.();
}

function beginDomainLaneTurn(target) {
  const idlePeerIds = selectIdlePeerLaneIds(
    target,
    [
      { id: "order", runningCount: orderSyncLaneRunning },
      { id: "payment", runningCount: paymentLaneRunning },
      { id: "room", runningCount: roomLaneRunning },
      {
        id: "reservation",
        runningCount: reservationLane?.runningCount?.() ?? 0,
      },
      {
        id: "notification",
        runningCount: notificationLane?.runningCount?.() ?? 0,
      },
      {
        id: "waiterPause",
        runningCount: waiterPauseLane?.runningCount?.() ?? 0,
      },
      {
        id: "stationState",
        runningCount: stationStateLane?.runningCount?.() ?? 0,
      },
    ],
    {
      orders: LANE_CROSS_EXCLUSION_ORDERS,
      tables: LANE_CROSS_EXCLUSION_TABLES,
      payments: LANE_CROSS_EXCLUSION_PAYMENTS,
      presence: LANE_CROSS_EXCLUSION_PRESENCE,
    },
  );
  idlePeerIds.forEach((id) => resetDomainLaneBurst(id));
}

