printLane = createSerializedMutationLane({ enabled: PRINT_LANE_ENABLED, concurrency: PRINT_LANE_CONCURRENCY, burst: PRINT_LANE_BURST, blockingPriority: PRINT_LANE_BLOCKING_PRIORITY, kind: "printLane", counterName: "printLaneEnqueued", warningPrefix: "[db:print-lane]", fallbackLabel: "print_lane_mutation", runtimeMetrics, slowWaitMs: DB_MUTATION_SLOW_WAIT_MS, slowRunMs: DB_MUTATION_SLOW_RUN_MS, recordQueueDepth: () => recordMutationQueueDepth(), scheduleNext: () => scheduleNextDbMutationTask(), isDbMutationRunning: () => dbMutationQueueRunning, getDbMutationQueue: () => dbMutationQueue });
waiterPauseLane = createSerializedMutationLane({ enabled: WAITER_PAUSE_LANE_ENABLED, concurrency: 1, burst: WAITER_PAUSE_LANE_BURST, starvationWaitMs: DOMAIN_LANE_STARVATION_WAIT_MS, nextFairSequence: nextDomainLaneFairSequence, blockingPriority: NOTIFICATION_LANE_BLOCKING_PRIORITY, kind: "waiterPauseLane", counterName: "waiterPauseLaneEnqueued", warningPrefix: "[db:waiter-pause-lane]", fallbackLabel: "waiter_pause_lane_mutation", runtimeMetrics, slowWaitMs: DB_MUTATION_SLOW_WAIT_MS, slowRunMs: DB_MUTATION_SLOW_RUN_MS, clearHotCaches: clearIntegrationHotResponseCaches, recordQueueDepth: () => recordMutationQueueDepth(), scheduleNext: () => scheduleNextDbMutationTask(), onScheduleStart: () => beginDomainLaneTurn("waiterPause"), isDbMutationRunning: () => dbMutationQueueRunning, getDbMutationQueue: () => dbMutationQueue, hasPeerRunning: () => paymentLanePeerRunningForDomainLanes() || roomLikeLanePeerRunningForPresenceLane(), getQueuePressureDepth: () => domainLanePeerQueuePressureDepth("waiterPause") });
stationStateLane = createSerializedMutationLane({ enabled: STATION_STATE_LANE_ENABLED, concurrency: STATION_STATE_LANE_CONCURRENCY, burst: STATION_STATE_LANE_BURST, starvationWaitMs: DOMAIN_LANE_STARVATION_WAIT_MS, nextFairSequence: nextDomainLaneFairSequence, blockingPriority: STATION_STATE_LANE_BLOCKING_PRIORITY, kind: "stationStateLane", counterName: "stationStateLaneEnqueued", warningPrefix: "[db:station-state-lane]", fallbackLabel: "station_state_lane_mutation", runtimeMetrics, slowWaitMs: DB_MUTATION_SLOW_WAIT_MS, slowRunMs: DB_MUTATION_SLOW_RUN_MS, clearHotCaches: clearIntegrationHotResponseCaches, recordQueueDepth: () => recordMutationQueueDepth(), scheduleNext: () => scheduleNextDbMutationTask(), onScheduleStart: () => beginDomainLaneTurn("stationState"), isDbMutationRunning: () => dbMutationQueueRunning, getDbMutationQueue: () => dbMutationQueue, hasPeerRunning: () => paymentLanePeerRunningForDomainLanes() || roomLikeLanePeerRunningForPresenceLane(), getQueuePressureDepth: () => domainLanePeerQueuePressureDepth("stationState") });
