async function enqueueAutoPrintOrdersForStations(db, order, stationStates) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const settings = sanitizePosSettings(db?.posSettings, {
    menuItems: db?.menuItems,
    users: db?.users,
  });
  const targetStations = [
    resolveIntegrationOrderPrintStation(safeOrder, {
      station: safeOrder.station,
    }),
  ];

  const queuedStations = [];
  for (const station of targetStations) {
    const stationState =
      (Array.isArray(stationStates) ? stationStates : []).find(
        (entry) => normalizeIntegrationStationName(entry?.station) === station,
      ) ?? null;

    const payload = withOrderOperationalRoutingPayload(safeOrder, {
      kind: "order",
      orderId: safeOrder.id,
      station,
      fallbackStation: PRIMARY_INTEGRATION_STATION,
      text: buildIntegrationOrderPrintText(
        safeOrder,
        station,
        settings.printPreferences?.order,
        db?.posSettings,
      ),
      printPreferences: settings.printPreferences,
      clientApp: "postazione-auto-print",
      deviceUuid: String(
        stationState?.deviceUuid ?? safeOrder.assignedStationDeviceUuid ?? "",
      ).trim(),
    });
    const resolvedTarget = resolvePrinterFromSettings(settings, payload);
    if (
      PRINTING_ENABLED &&
      !resolvedTarget &&
      !supportsLocalDefaultPrintFallback()
    ) {
      continue;
    }
    try {
      await enqueuePrintSpoolJob(payload);
      queuedStations.push(station);
    } catch (error) {
      console.error("[integration:auto-print]", station, error);
    }
  }

  return queuedStations;
}

function withOrderOperationalRoutingPayload(order, payload) {
  const snapshot =
    order?.operationalSnapshot && typeof order.operationalSnapshot === "object"
      ? order.operationalSnapshot
      : null;
  if (!snapshot || Number(snapshot.schemaVersion) !== 2) return payload;
  return {
    ...payload,
    operationalSchemaVersion: 2,
    activityId: String(snapshot.activityId ?? payload.activityId ?? "").trim(),
    roomId: String(
      snapshot.roomId ?? payload.roomId ?? order?.roomId ?? "",
    ).trim(),
    tableId: String(
      snapshot.tableId ?? payload.tableId ?? order?.tableId ?? "",
    ).trim(),
  };
}

function hasOperationalPrintRouting(payload) {
  return (
    Number(payload?.operationalSchemaVersion) === 2 &&
    String(payload?.activityId ?? "").trim() &&
    String(payload?.roomId ?? "").trim()
  );
}

function withOrderPrintOperationalRoutingPayload(settings, order, payload) {
  const routedPayload = withOrderOperationalRoutingPayload(order, payload);
  if (hasOperationalPrintRouting(routedPayload)) return routedPayload;

  const snapshot =
    order?.operationalSnapshot && typeof order.operationalSnapshot === "object"
      ? order.operationalSnapshot
      : null;
  // Quando si ristampa una comanda, la sala autorevole e' quella salvata nella
  // comanda: il payload puo' contenere la sala attualmente selezionata dal device.
  const roomId = String(
    snapshot?.roomId ??
      order?.roomId ??
      payload?.roomId ??
      payload?.areaId ??
      "",
  ).trim();
  const activityId = resolveTablePrecontoActivityId(
    settings,
    roomId,
    payload?.activityId ??
      payload?.operationalActivityId ??
      snapshot?.activityId,
  );
  if (!activityId || !roomId) return routedPayload;

  return {
    ...routedPayload,
    operationalSchemaVersion: 2,
    activityId,
    roomId,
    tableId: String(
      payload?.tableId ?? snapshot?.tableId ?? order?.tableId ?? "",
    ).trim(),
  };
}

async function enqueueAutoPrintPrecontoForStation(
  db,
  order,
  stationStates,
  stationOverride = "",
) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const settings = sanitizePosSettings(db?.posSettings, {
    menuItems: db?.menuItems,
    users: db?.users,
  });
  const station =
    normalizeOptionalIntegrationStationName(stationOverride) ??
    resolveIntegrationOrderPrintStation(safeOrder, {
      station: safeOrder.station,
    });
  const stationState =
    (Array.isArray(stationStates) ? stationStates : []).find(
      (entry) => normalizeIntegrationStationName(entry?.station) === station,
    ) ?? null;
  const payload = withOrderOperationalRoutingPayload(safeOrder, {
    kind: "preconto",
    orderId: safeOrder.id,
    station,
    fallbackStation: station,
    text: buildIntegrationPrecontoPrintTextWithOptions(
      safeOrder,
      settings.printPreferences,
      settings,
      {
        profile: "cash",
      },
    ),
    printPreferences: settings.printPreferences,
    clientApp: "cassa-frontend",
    precontoProfile: "cash",
    deviceUuid: String(
      stationState?.deviceUuid ?? safeOrder.assignedStationDeviceUuid ?? "",
    ).trim(),
  });
  const resolvedTarget = resolvePrinterFromSettings(settings, payload);
  if (
    PRINTING_ENABLED &&
    !resolvedTarget &&
    !supportsLocalDefaultPrintFallback()
  ) {
    return null;
  }
  try {
    await enqueuePrintSpoolJob(payload);
    return station;
  } catch (error) {
    console.error("[integration:auto-preconto]", station, error);
    return null;
  }
}

function isPizzaInRivaNoFiscalOrder(order) {
  const createdByUserId = String(
    order?.createdByUserId ?? order?.createdBy ?? "",
  ).trim();
  const createdByUsername = normalizeUsername(
    order?.createdByUsername ?? order?.username ?? "",
  );
  const waiter = String(order?.waiter ?? "")
    .trim()
    .toLowerCase();
  return (
    createdByUserId === PIZZA_IN_RIVA_USER_ID ||
    createdByUsername === PIZZA_IN_RIVA_USERNAME ||
    waiter === PIZZA_IN_RIVA_FULL_NAME.toLowerCase()
  );
}

function buildAutoPrintPayloadsForOrder(db, order, stationStates, options = {}) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const settings = options.settings && typeof options.settings === "object"
    ? options.settings
    : sanitizePosSettings(db?.posSettings, { menuItems: db?.menuItems, users: db?.users });
  const station = resolveIntegrationOrderPrintStation(safeOrder, {
    station: safeOrder.station,
  });
  const stationState =
    (Array.isArray(stationStates) ? stationStates : []).find(
      (entry) => normalizeIntegrationStationName(entry?.station) === station,
    ) ?? null;
  const deviceUuid = String(
    stationState?.deviceUuid ?? safeOrder.assignedStationDeviceUuid ?? "",
  ).trim();
  const orderPayload = withOrderOperationalRoutingPayload(safeOrder, {
    kind: "order",
    orderId: safeOrder.id,
    station,
    fallbackStation: PRIMARY_INTEGRATION_STATION,
    text: buildIntegrationOrderPrintText(
      safeOrder,
      station,
      settings.printPreferences?.order,
      db?.posSettings,
    ),
    printPreferences: settings.printPreferences,
    clientApp: "postazione-auto-print",
    deviceUuid,
  });
  const resolvedOrderTarget = resolvePrinterFromSettings(
    settings,
    orderPayload,
  );
  if (
    PRINTING_ENABLED &&
    !resolvedOrderTarget &&
    !supportsLocalDefaultPrintFallback()
  ) {
    return [];
  }

  const precontoPayload = withOrderOperationalRoutingPayload(safeOrder, {
    kind: "preconto",
    orderId: safeOrder.id,
    station,
    fallbackStation: station,
    text: buildIntegrationPrecontoPrintTextWithOptions(
      safeOrder,
      settings.printPreferences,
      settings,
      {
        profile: "cash",
      },
    ),
    printPreferences: settings.printPreferences,
    clientApp: "cassa-frontend",
    precontoProfile: "cash",
    deviceUuid,
  });
  const payloads = [orderPayload, precontoPayload];
  if (isPizzaInRivaNoFiscalOrder(safeOrder)) {
    payloads.push({
      ...precontoPayload,
      printerId: PIZZA_IN_RIVA_PRECONTO_PRINTER_ID,
      clientApp: "francesca-preconto-mirror",
    });
  }
  return payloads;
}

async function enqueuePrintSpoolJobsOnDb(db, payloads = [], options = {}) {
  const safeEntries = (Array.isArray(payloads) ? payloads : [])
    .map((payload, index) => ({
      payload,
      jobId: String(options.jobIds?.[index] ?? "").trim(),
    }))
    .filter((entry) => entry.payload && typeof entry.payload === "object");
  if (safeEntries.length === 0) return [];

  const settings = options.settings && typeof options.settings === "object"
    ? options.settings
    : sanitizePosSettings(db.posSettings, { menuItems: db.menuItems, users: db.users });
  const resolvedEntries = [];
  for (const entry of safeEntries) {
    const { payload } = entry;
    const resolvedTarget = resolvePrinterFromSettings(settings, payload);
    if (
      PRINTING_ENABLED &&
      !resolvedTarget &&
      !supportsLocalDefaultPrintFallback()
    ) {
      continue;
    }
    resolvedEntries.push({
      ...entry,
      payload: {
        ...payload,
        printerId: payload.printerId ?? resolvedTarget?.printer?.id,
      },
    });
  }

  if (resolvedEntries.length === 0) return [];
  let nextJobs;
  if (PRINT_SPOOL_SQL_PRIMARY && !shouldFastAppendDisabledPrintSpoolJob()) {
    const repository = requirePrintSpoolSqlPrimaryRepository();
    let duplicateCount = 0;
    const pendingEntries = resolvedEntries.filter((entry) => {
      if (!entry.jobId || !repository.getById(entry.jobId)) return true;
      duplicateCount += 1;
      return false;
    });
    if (duplicateCount > 0) {
      runtimeMetrics.incrementCounter("printSpoolAutoPrintOwnerDuplicates", duplicateCount);
      options.onSkippedExisting?.(duplicateCount);
    }
    if (pendingEntries.length === 0) return [];
    const batch = await persistSqlPrimaryPrintBatch({
      payloads: pendingEntries.map((entry) => entry.payload),
      repository,
      buildJob: (payload, index) => buildPrintSpoolJobFromPayload(db, payload, {
        settings,
        jobId: pendingEntries[index]?.jobId,
      }),
      persistJobFile: persistPrintSpoolJobFile,
    });
    nextJobs = batch.jobs;
    runtimeMetrics.recordOperation("printSpool", "acceptBatch", batch.durationMs);
    for (const nextJob of nextJobs) {
      runtimeMetrics.recordOperation("printSpool", "accept", batch.durationMs);
      emitPrintRequestedEvent(nextJob);
      if (PRINT_SPOOL_INITIAL_STATUS_EVENTS) emitPrintStatusEvent(nextJob, nextJob.status);
      else runtimeMetrics.incrementCounter("printSpoolInitialEventsSkipped");
      if (PRINT_SPOOL_LEGACY_MIRROR_ENABLED && process.env.PRINT_SPOOL_LEGACY_MIRROR_REMOTE_OWNER !== "1") {
        upsertLegacyPrintSpoolMirror(db, nextJob);
      } else {
        mirrorLegacyPrintSpoolJobBestEffort(nextJob, "enqueue");
      }
    }
    refreshPrintSpoolQueueGauges();
  } else {
    nextJobs = [];
    for (const entry of resolvedEntries) nextJobs.push(await appendPrintSpoolJobToDb(db, entry.payload));
  }

  prunePrintSpoolJobs(db);
  db.meta.lastWriteAt = nowIso();
  if (!PRINT_SPOOL_SQL_PRIMARY) await writePrintSpoolDb(db);
  if (PRINTING_ENABLED) queuePrintSpoolWorker();
  return nextJobs;
}

async function enqueueMobileElectronicPaymentReceipts(options = {}) {
  const clientApp = normalizeClientApp(options?.clientApp);
  if (clientApp !== "mobile-frontend") {
    return [];
  }
  const settings = sanitizePosSettings(options?.settings, {
    menuItems: options?.menuItems,
    users: options?.users,
  });
  const table =
    options?.table && typeof options.table === "object" ? options.table : null;
  const tableBills = Array.isArray(options?.tableBills)
    ? options.tableBills
    : [];
  const orderReferenceLabel = buildMobilePaymentOrderReferenceLabel(
    tableBills,
    options?.selectedBillIds,
    options?.fallbackOrderId,
  );
  const waiterName =
    String(options?.waiterName ?? "").trim() ||
    String(options?.user?.fullName ?? options?.user?.username ?? "").trim() ||
    "Cameriere";
  const tableNumber = Number.isFinite(Number(table?.number))
    ? Math.trunc(Number(table.number))
    : 0;
  const tableLabel =
    sanitizeIntegrationTableLabel(
      options?.tableLabel ?? options?.logicalTableLabel,
    ) || (tableNumber > 0 ? String(tableNumber) : "");
  const roomId = String(options?.roomId ?? "").trim();
  const roomName = resolvePrintRoomLabel(
    settings,
    roomId,
    options?.roomName ?? options?.roomLabel ?? "",
  );
  const userId = String(options?.user?.id ?? "").trim();
  const deviceUuid = String(options?.deviceUuid ?? "").trim();
  const paymentId = String(options?.paymentId ?? "").trim() || "payment";
  const defaultPaymentNote = normalizePaymentPrintNote(
    options?.note ?? options?.paymentNote,
  );
  const queuedJobs = [];

  for (const tx of Array.isArray(options?.transactions)
    ? options.transactions
    : []) {
    const methodType = String(tx?.methodType ?? tx?.method ?? "").trim();
    const methodId = String(tx?.methodId ?? "").trim();
    const methodLabel = String(tx?.methodLabel ?? "").trim();
    if (!isElectronicPaymentReceiptMethod(methodType, methodId, methodLabel)) {
      continue;
    }
    const amount = roundMoney(
      Math.max(Number(tx?.amount ?? tx?.amountPaid) || 0, 0),
    );
    if (amount <= 0) {
      continue;
    }
    const transactionId = String(
      tx?.transactionId ?? tx?.id ?? tx?.paymentTxId ?? "",
    ).trim();
    const paymentNote = normalizePaymentPrintNote(
      tx?.note ?? tx?.paymentNote ?? defaultPaymentNote,
    );
    const createdAtMs = new Date(String(tx?.createdAt ?? nowIso())).getTime();
    const payload = {
      kind: "payment",
      orderId: paymentId,
      roomId,
      station: PRIMARY_INTEGRATION_STATION,
      fallbackStation: PRIMARY_INTEGRATION_STATION,
      text: buildMobileElectronicPaymentPrintText(
        {
          waiter: waiterName,
          tableNumber,
          tableLabel,
          roomName,
          orderReference: orderReferenceLabel,
          amount,
          methodType,
          methodLabel,
          transactionId,
          cashGiven: tx?.cashGiven,
          changeGiven: tx?.changeGiven,
          note: paymentNote,
          createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : Date.now(),
        },
        settings.printPreferences?.order,
      ),
      printPreferences: settings.printPreferences,
      clientApp,
      userId,
      deviceUuid,
    };
    const resolvedTarget = resolvePrinterFromSettings(settings, payload);
    if (!resolvedTarget && !supportsLocalDefaultPrintFallback()) {
      continue;
    }
    try {
      const queuedJob = await enqueuePrintSpoolJob(payload);
      queuedJobs.push(queuedJob);
    } catch (error) {
      console.error("[payment:electronic-print]", paymentId, error);
    }
  }

  return queuedJobs;
}

function applyIntegrationWorkflowRouteTransitions(
  order,
  previousWorkflow,
  actor = {},
) {
  const previous = String(previousWorkflow ?? "")
    .trim()
    .toLowerCase();
  const next = String(order?.workflowStatus ?? "")
    .trim()
    .toLowerCase();
  const lineRoutes = Array.isArray(order?.lineRoutes)
    ? order.lineRoutes.map((entry) => ({ ...entry }))
    : [];
  const routeEvents = [];
  if (lineRoutes.length === 0) {
    return { lineRoutes, routeEvents };
  }
  const actorUserId =
    typeof actor.userId === "string" && actor.userId.trim().length > 0
      ? actor.userId.trim()
      : null;
  const actorUsername =
    typeof actor.username === "string" && actor.username.trim().length > 0
      ? actor.username.trim()
      : null;

  lineRoutes.forEach((route) => {
    if (!route || typeof route !== "object") return;
    const updateEvent = (action, fieldName, byUserField, byNameField) => {
      route[fieldName] = String(route[fieldName] ?? "").trim() || nowIso();
      if (actorUserId) route[byUserField] = actorUserId;
      if (actorUsername) route[byNameField] = actorUsername;
      routeEvents.push({
        action,
        routeId: route.id,
        lineId: route.lineId,
        stationId: route.stationId,
        occurredAt: route[fieldName],
      });
    };

    const needsReceived =
      !route.receivedAt &&
      ["prep", "ready", "delivered"].includes(next) &&
      !["prep", "ready", "delivered"].includes(previous);
    if (needsReceived) {
      updateEvent(
        "order.route_received",
        "receivedAt",
        "receivedByUserId",
        "receivedByUsername",
      );
    }
    const needsReady =
      !route.readyAt &&
      ["ready", "delivered"].includes(next) &&
      !["ready", "delivered"].includes(previous);
    if (needsReady) {
      updateEvent(
        "order.route_ready",
        "readyAt",
        "readyByUserId",
        "readyByUsername",
      );
    }
    const needsPickup =
      !route.pickedUpAt && next === "delivered" && previous !== "delivered";
    if (needsPickup) {
      updateEvent(
        "order.route_picked_up",
        "pickedUpAt",
        "pickedUpByUserId",
        "pickedUpByUsername",
      );
    }
    const needsDelivered =
      !route.deliveredAt && next === "delivered" && previous !== "delivered";
    if (needsDelivered) {
      updateEvent(
        "order.route_delivered",
        "deliveredAt",
        "deliveredByUserId",
        "deliveredByUsername",
      );
    }
  });

  return { lineRoutes, routeEvents };
}

const {
  assertIntegrationWorkflowTransitionAllowed,
  isIntegrationWorkflowRegression,
  resolveIntegrationWorkflowRank,
} = createIntegrationWorkflowStateMachine({
  enabled: ORDER_STATE_MACHINE_ENABLED,
  createTransitionError: (violation) =>
    new HttpError(409, violation.message, {
      code: violation.code,
      details: violation.details,
    }),
});

const printStateMachine = createPrintStateMachine({
  enabled: PRINT_STATE_MACHINE_ENABLED,
  createTransitionError: (violation) =>
    new HttpError(409, violation.message, {
      code: violation.code,
      details: violation.details,
    }),
});

function applyPrintSpoolClaimStateTransition(job) {
  let nextJob = job;
  const currentState = printStateMachine.resolvePrintRuntimeState(nextJob).printState;
  if (currentState === "failed_retryable") {
    nextJob = printStateMachine.applyTransition(nextJob, "queued", {
      allowRetry: true,
    });
  }
  return printStateMachine.applyTransition(nextJob, "claimed");
}

function applyPrintSpoolCompletionStateTransition(job, terminalState) {
  let nextJob = job;
  let currentState = printStateMachine.resolvePrintRuntimeState(nextJob).printState;
  if (currentState === "failed_retryable") {
    nextJob = printStateMachine.applyTransition(nextJob, "queued", {
      allowRetry: true,
    });
    currentState = "queued";
  }
  if (currentState === "queued") {
    nextJob = printStateMachine.applyTransition(nextJob, "claimed");
    currentState = "claimed";
  }
  if (currentState === "claimed") {
    nextJob = printStateMachine.applyTransition(nextJob, "sent");
  }
  return printStateMachine.applyTransition(nextJob, terminalState);
}

