function mergeIntegrationSyncItems(currentItems, rawItems) {
  if (!Array.isArray(rawItems)) return currentItems;
  const currentByKey = new Map();
  (Array.isArray(currentItems) ? currentItems : []).forEach((item) => {
    const keys = [item?.id, item?.lineId]
      .map((value) => String(value ?? "").trim())
      .filter(Boolean);
    keys.forEach((key) => currentByKey.set(key, item));
  });

  return rawItems.map((rawItem) => {
    const keyCandidates = [rawItem?.id, rawItem?.lineId]
      .map((value) => String(value ?? "").trim())
      .filter(Boolean);
    const currentItem =
      keyCandidates.map((key) => currentByKey.get(key)).find((item) => item) ??
      null;
    if (!currentItem) return rawItem;

    const mergedItem = { ...currentItem, ...rawItem };
    ["unitPriceApplied", "listPriceAtTime", "lineTotal"].forEach(
      (fieldName) => {
        const currentValue = Number(currentItem[fieldName]);
        const rawValue = Number(rawItem?.[fieldName]);
        if (
          Number.isFinite(currentValue) &&
          currentValue > 0 &&
          (!Number.isFinite(rawValue) || rawValue <= 0)
        ) {
          mergedItem[fieldName] = currentItem[fieldName];
        }
      },
    );
    return mergedItem;
  });
}

function findIntegrationBellClaim(integration, notificationIdRaw) {
  const notificationId = String(notificationIdRaw ?? "").trim();
  if (!notificationId) return null;
  return (
    getIntegrationRecentBellClaims(integration).find(
      (claim) => claim.notificationId === notificationId,
    ) ?? null
  );
}

function upsertIntegrationBellClaim(integration, record) {
  if (!integration || typeof integration !== "object") return null;
  const next = sanitizeIntegrationBellClaim(record);
  if (!next) return null;
  const claims = getIntegrationRecentBellClaims(integration);
  const claimIndex = claims.findIndex(
    (claim) => claim.notificationId === next.notificationId,
  );
  if (claimIndex >= 0) {
    claims[claimIndex] = next;
  } else {
    claims.push(next);
  }
  integration.recentBellClaims = claims;
  return next;
}

function sanitizeIntegrationFulfillmentHistoryEvent(
  event,
  fallbackId = "fulfillment_1",
) {
  const source = event && typeof event === "object" ? event : {};
  const orderId = String(source.orderId ?? "").trim();
  const stationId = normalizeOptionalIntegrationStationName(
    source.stationId ?? source.station,
  );
  const operatorUserId = String(
    source.operatorUserId ?? source.userId ?? "",
  ).trim();
  const itemsCount = Math.max(Math.trunc(Number(source.itemsCount) || 0), 1);
  const durationSeconds = Math.max(Number(source.durationSeconds) || 0, 0);
  const secondsPerItemRaw = Number(source.secondsPerItem);
  const secondsPerItem =
    Number.isFinite(secondsPerItemRaw) && secondsPerItemRaw > 0
      ? secondsPerItemRaw
      : durationSeconds > 0
        ? durationSeconds / itemsCount
        : 0;
  if (!orderId || !stationId || secondsPerItem <= 0) return null;
  return {
    id: String(source.id ?? fallbackId).trim() || fallbackId,
    orderId,
    stationId,
    operatorUserId,
    operatorUsername: String(
      source.operatorUsername ?? source.username ?? "",
    ).trim(),
    itemsCount,
    startedAt: normalizeIntegrationOrderTimestamp(source.startedAt),
    completedAt:
      normalizeIntegrationOrderTimestamp(source.completedAt) ?? nowIso(),
    durationSeconds,
    secondsPerItem,
    isTimingAnomaly: source.isTimingAnomaly === true,
    anomalyReason: String(source.anomalyReason ?? "").trim(),
    includedInOperationalAverage:
      source.includedInOperationalAverage === true ||
      (source.includedInOperationalAverage !== false &&
        source.isTimingAnomaly !== true),
  };
}

function buildIntegrationFulfillmentAnomalyStats(history) {
  const stats = {
    global: { total: 0, anomalies: 0 },
    byStation: {},
    byUser: {},
    byStationUser: {},
  };
  const increment = (bucket, key, isAnomaly) => {
    if (!key) return;
    const current = bucket[key] ?? { total: 0, anomalies: 0 };
    current.total += 1;
    if (isAnomaly) current.anomalies += 1;
    bucket[key] = current;
  };

  (Array.isArray(history) ? history : []).forEach((event) => {
    const safe = sanitizeIntegrationFulfillmentHistoryEvent(event);
    if (!safe) return;
    const isAnomaly = safe.isTimingAnomaly === true;
    stats.global.total += 1;
    if (isAnomaly) stats.global.anomalies += 1;
    increment(stats.byStation, safe.stationId, isAnomaly);
    increment(
      stats.byUser,
      safe.operatorUserId || safe.operatorUsername,
      isAnomaly,
    );
    increment(
      stats.byStationUser,
      `${safe.stationId}::${safe.operatorUserId || safe.operatorUsername}`,
      isAnomaly,
    );
  });
  return stats;
}

function appendIntegrationOrderFulfillmentHistoryEvent(
  db,
  previousOrder,
  completedOrder,
  payload = {},
) {
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  const history = Array.isArray(db.integration.orderFulfillmentHistory)
    ? db.integration.orderFulfillmentHistory
    : [];
  const orderId = String(completedOrder?.id ?? previousOrder?.id ?? "").trim();
  if (
    !orderId ||
    history.some((event) => String(event?.orderId ?? "").trim() === orderId)
  ) {
    return null;
  }

  const stationId =
    normalizeOptionalIntegrationStationName(
      completedOrder?.lockedByStationId,
    ) ??
    normalizeOptionalIntegrationStationName(completedOrder?.ownerStation) ??
    normalizeOptionalIntegrationStationName(
      completedOrder?.assignedStationId,
    ) ??
    normalizeOptionalIntegrationStationName(completedOrder?.station);
  const operatorUserId =
    String(completedOrder?.lockedByUserId ?? "").trim() ||
    String(payload?.userId ?? "").trim() ||
    String(previousOrder?.lockedByUserId ?? "").trim() ||
    String(completedOrder?.createdByUserId ?? "").trim();
  const operatorUsername =
    String(payload?.username ?? "").trim() ||
    String(completedOrder?.ownerOperator ?? "").trim() ||
    String(completedOrder?.createdByUsername ?? "").trim();
  const startedAt =
    normalizeIntegrationOrderTimestamp(completedOrder?.preparationStartedAt) ??
    normalizeIntegrationOrderTimestamp(previousOrder?.preparationStartedAt) ??
    normalizeIntegrationOrderTimestamp(completedOrder?.lockedAt) ??
    normalizeIntegrationOrderTimestamp(previousOrder?.lockedAt) ??
    normalizeIntegrationOrderTimestamp(completedOrder?.ownerAtMs) ??
    normalizeIntegrationOrderTimestamp(completedOrder?.receivedAtMs);
  const completedAt =
    normalizeIntegrationOrderTimestamp(completedOrder?.readyAtMs) ??
    normalizeIntegrationOrderTimestamp(completedOrder?.completedAtMs) ??
    nowIso();
  const startedAtMs = Date.parse(startedAt ?? "");
  const completedAtMs = Date.parse(completedAt);
  if (
    !stationId ||
    !Number.isFinite(startedAtMs) ||
    !Number.isFinite(completedAtMs)
  ) {
    return null;
  }

  const durationSeconds = Math.max(
    Math.round((completedAtMs - startedAtMs) / 1000),
    1,
  );
  const itemsCount = Math.max(countOrderItems(completedOrder), 1);
  const secondsPerItem = durationSeconds / itemsCount;
  const averages = getHistoricalAverages(db, {
    config: LOAD_BALANCER_DEFAULTS,
  });
  const baseEvent = {
    id: `fulfillment_${orderId}_${completedAtMs}`,
    orderId,
    stationId,
    operatorUserId,
    operatorUsername,
    itemsCount,
    startedAt,
    completedAt,
    durationSeconds,
    secondsPerItem,
  };
  const classification = classifyTimingEvent(baseEvent, {
    averageSecondsPerItem: averages.global.avgSecondsPerItem,
    sampleCount: averages.global.samples,
    config: LOAD_BALANCER_DEFAULTS,
  });
  const event = {
    ...baseEvent,
    ...classification,
    includedInOperationalAverage: false,
  };
  const candidateHistory = [...history, event];
  event.includedInOperationalAverage = shouldIncludeTimingInOperationalAverage(
    event,
    {
      history: candidateHistory,
      config: LOAD_BALANCER_DEFAULTS,
    },
  );

  db.integration.orderFulfillmentHistory = [...history, event]
    .map((entry, index) =>
      sanitizeIntegrationFulfillmentHistoryEvent(
        entry,
        `fulfillment_${index + 1}`,
      ),
    )
    .filter((entry) => entry !== null)
    .sort((a, b) => Date.parse(a.completedAt) - Date.parse(b.completedAt))
    .slice(-INTEGRATION_MAX_ORDER_FULFILLMENT_HISTORY);
  db.integration.fulfillmentAnomalyStats =
    buildIntegrationFulfillmentAnomalyStats(
      db.integration.orderFulfillmentHistory,
    );
  return event;
}

function applyIntegrationAutoAssignment(db, order, context = {}) {
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  db.integration.stationStates =
    buildIntegrationStationStatesWithSessionRecovery(db);

  const current = sanitizeIntegrationOrder(order, order?.id ?? "00000");
  if (
    current.assignmentReason === "manual_transfer" ||
    current.manuallyTransferredAt
  ) {
      return { order: current, choice: null, changed: false };
  }

  const assignmentPlan = buildOrderCreateAutoAssignmentPlan({
    allowDemoStations: SHOW_DEMO_STATIONS,
    chooseBestStationForOrder,
    findMenuItemForLine: findIntegrationMenuItemForLine,
    menuItemsByName: buildIntegrationMenuItemsByName(db),
    normalizeClientApp,
    normalizeStation: normalizeIntegrationStationName,
    nowIso,
    order: current,
    settings: sanitizePosSettings(db.posSettings, {
      menuItems: db.menuItems,
      users: db.users,
    }),
    state: db,
  });
  if (!assignmentPlan.choice?.stationId) {
    console.warn(
      `[integration:load-balancer] Nessuna postazione attiva per comanda ${current.id}: ${assignmentPlan.choice?.reason}`,
    );
    return {
      order: sanitizeIntegrationOrder(
        {
          ...current,
          ...assignmentPlan.orderPatch,
        },
        current.id,
      ),
      choice: assignmentPlan.choice,
      changed: assignmentPlan.changed,
    };
  }

  const assignedOrder = rerouteOrderOperationalStation(
    {
      ...current,
      ...assignmentPlan.orderPatch,
    },
    assignmentPlan.targetStationId,
  );
  return {
    order: sanitizeIntegrationOrder(assignedOrder, current.id),
    choice: assignmentPlan.choice,
    changed: assignmentPlan.changed,
    context,
  };
}

function assignQueuedUnassignedIntegrationOrders(db, context = {}) {
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  if (
    !Array.isArray(db.integration.orders) ||
    db.integration.orders.length === 0
  ) {
    return [];
  }
  const assigned = [];
  db.integration.orders = db.integration.orders.map((rawOrder, index) => {
    const order = sanitizeIntegrationOrder(
      rawOrder,
      String(index + 1).padStart(5, "0"),
    );
    const workflow = normalizeIntegrationWorkflowStatus(
      order.workflowStatus,
      order.items,
      order.completedAtMs,
      {
        lineRoutes: order.lineRoutes,
        ownerStation: order.ownerStation,
      },
    );
    const isOpenForAutoAssignment =
      workflow !== "prep" &&
      workflow !== "ready" &&
      workflow !== "delivered" &&
      order.lockStatus !== "locked" &&
      !order.manuallyTransferredAt &&
      order.assignmentReason !== "manual_transfer";
    const isQueuedWithoutStation =
      !order.assignedStationId ||
      order.assignmentStatus === "queued_unassigned" ||
      order.assignmentReasonDetail === "no_active_station";
    if (!isOpenForAutoAssignment || !isQueuedWithoutStation) {
      return rawOrder;
    }
    const assignment = applyIntegrationAutoAssignment(db, order, {
      ...context,
      source: context.source ?? "station_state_upsert",
    });
    if (assignment.choice?.stationId) {
      assigned.push({
        orderId: order.id,
        stationId: assignment.choice.stationId,
        reason: assignment.choice.reason,
      });
    }
    return assignment.order;
  });
  if (assigned.length > 0) {
    db.integration.lastWriteAt = nowIso();
    db.meta.lastWriteAt = nowIso();
  }
  return assigned;
}

function integrationOrderQueueStation(order) { return resolveIntegrationOrderQueueStation(order, { normalizeIntegrationStationName, normalizeOptionalIntegrationStationName, primaryStation: PRIMARY_INTEGRATION_STATION }); }

