function normalizeReservation(value) {
  if (!value || typeof value !== "object") return null;
  const time =
    typeof value.time === "string" &&
    /^([01]\d|2[0-3]):([0-5]\d)$/.test(value.time)
      ? value.time
      : null;
  if (!time) return null;
  const people = Number.isFinite(value.people)
    ? Math.max(Number(value.people), 0)
    : 0;
  return {
    time,
    people,
    mergeFlag: value.mergeFlag === true,
  };
}

function normalizeStringList(value, maxLength = 12, itemMaxLength = 40) {
  if (!Array.isArray(value)) return [];
  const out = [];
  const seen = new Set();
  for (const raw of value) {
    const next = String(raw ?? "")
      .trim()
      .slice(0, itemMaxLength);
    if (!next) continue;
    const key = next.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(next);
    if (out.length >= maxLength) break;
  }
  return out;
}

function normalizeSeatedAtMs(value) {
  const raw = Number(value);
  if (!Number.isFinite(raw) || raw <= 0) return null;
  return Math.trunc(raw);
}

function timeStringFromTimestamp(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return "";
  const date = new Date(parsed);
  const ts = date.getTime();
  if (!Number.isFinite(ts)) return "";
  return `${pad2(date.getHours())}:${pad2(date.getMinutes())}`;
}

function roundMoney(value) {
  return Math.round(value * 100) / 100;
}

function clampInt(value, min, max, fallback = min) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  const safe = Math.trunc(parsed);
  return Math.min(max, Math.max(min, safe));
}

function toPosRole(value) {
  const role = String(value ?? "")
    .trim()
    .toLowerCase();
  if (role === "admin" || role === "responsabile") return role;
  return "operator";
}

function isPosPrivilegedRole(role) {
  const normalized = toPosRole(role);
  return normalized === "admin" || normalized === "responsabile";
}

function buildPosRoomListFromSettings(settings) {
  const safeSettings = sanitizePosSettings(settings);
  const roomsById = new Map();
  const activityIdsByRoomId = new Map();
  (Array.isArray(safeSettings.activityRoomBindings)
    ? safeSettings.activityRoomBindings
    : []
  ).forEach((binding) => {
    if (binding?.status === "disabled") return;
    const roomId = String(binding?.roomId ?? "").trim();
    const activityId = String(binding?.activityId ?? "").trim();
    if (!roomId || !activityId) return;
    const current = activityIdsByRoomId.get(roomId) ?? new Set();
    current.add(activityId);
    activityIdsByRoomId.set(roomId, current);
  });
  const addRoom = (room) => {
    const id = String(room?.id ?? room?.roomId ?? "").trim();
    const name = String(
      room?.name ?? room?.label ?? room?.roomName ?? id,
    ).trim();
    if (!id || !name) return;
    const activityIds = [...(activityIdsByRoomId.get(id) ?? new Set())].sort(
      (a, b) => a.localeCompare(b, "it-IT"),
    );
    roomsById.set(id, {
      id,
      name,
      activityId: activityIds[0] ?? "",
      activityIds,
    });
  };

  for (const room of buildIntegrationLayoutFromSettings(safeSettings).rooms) {
    addRoom(room);
  }
  for (const area of Array.isArray(safeSettings.areas)
    ? safeSettings.areas
    : []) {
    addRoom(area);
  }

  return [...roomsById.values()].sort((a, b) =>
    a.name.localeCompare(b.name, "it-IT"),
  );
}

function buildPosAllowedRoomsForRole(settings, role) {
  const rooms = buildPosRoomListFromSettings(settings).filter(
    (room) => room.id && room.name,
  );
  return rooms;
}

function buildPosAllowedRoomsForUser(settings, user) {
  const rooms = buildPosRoomListFromSettings(settings).filter(
    (room) => room.id && room.name,
  );
  if (isPosPrivilegedRole(user?.role)) {
    return rooms;
  }
  const authorizedRoomIds = sanitizeAuthorizedRoomIds(
    user?.authorizedRoomIds,
    settings,
  );
  if (authorizedRoomIds.length === 0) {
    return buildPosAllowedRoomsForRole(settings, user?.role);
  }
  const roomsById = new Map(rooms.map((room) => [room.id, room]));
  return authorizedRoomIds
    .map((roomId) => roomsById.get(roomId))
    .filter(Boolean);
}

function sanitizeEnabledRoomIds(value, settings = null) {
  const rooms = buildPosRoomListFromSettings(settings).filter(
    (room) => room.id,
  );
  const validRoomIds = new Set(rooms.map((room) => room.id));
  if (!Array.isArray(value) || value.length === 0) {
    return rooms.map((room) => room.id);
  }
  const normalized = [
    ...new Set(
      value
        .map((entry) => String(entry ?? "").trim())
        .filter((roomId) => roomId && validRoomIds.has(roomId)),
    ),
  ];
  return normalized;
}

function buildMobileRoomSettings(user, allRooms, settings = null) {
  const rooms = (Array.isArray(allRooms) ? allRooms : []).filter(
    (room) => room.id && room.name,
  );
  const enabledRoomIds = isPosPrivilegedRole(user?.role)
    ? rooms.map((room) => room.id)
    : sanitizeEnabledRoomIds(user?.enabledRoomIds, settings);
  const enabledSet = new Set(enabledRoomIds);
  const authorizedRoomIds = isPosPrivilegedRole(user?.role)
    ? rooms.map((room) => room.id)
    : sanitizeAuthorizedRoomIds(user?.authorizedRoomIds, settings).filter(
        (roomId) => enabledSet.has(roomId),
      );
  const authorizedSet = new Set(authorizedRoomIds);
  return {
    enabledRoomIds,
    authorizedRoomIds,
    rooms: rooms.map((room) => {
      const enabled = enabledSet.has(room.id);
      const authorized = authorizedSet.has(room.id);
      return {
        roomId: room.id,
        roomName: room.name,
        id: room.id,
        name: room.name,
        activityId: room.activityId || "",
        activityIds: Array.isArray(room.activityIds) ? room.activityIds : [],
        enabled,
        authorized,
        requiresAdminAuth: enabled && !authorized,
      };
    }),
  };
}

function resolveMobileInitialRoom(user, roomSettings) {
  const rooms = Array.isArray(roomSettings?.rooms) ? roomSettings.rooms : [];
  const enabledRooms = rooms.filter((room) => room.enabled);
  const authorizedRooms = rooms.filter(
    (room) => room.enabled && room.authorized,
  );
  const byId = new Map(rooms.map((room) => [room.roomId, room]));
  const toInitial = (room, source) =>
    room
      ? {
          roomId: room.roomId,
          roomName: room.roomName,
          id: room.roomId,
          name: room.roomName,
          activityId: room.activityId || "",
          activityIds: Array.isArray(room.activityIds) ? room.activityIds : [],
          authorized: room.authorized,
          enabled: room.enabled,
          requiresAdminAuth: room.requiresAdminAuth === true,
          source,
        }
      : null;

  const lastRoomId = String(user?.lastSelectedRoomId ?? "").trim();
  const lastRoom = lastRoomId ? (byId.get(lastRoomId) ?? null) : null;
  if (lastRoom?.enabled && lastRoom.authorized)
    return toInitial(lastRoom, "last_selected_authorized");
  if (authorizedRooms.length === 1)
    return toInitial(authorizedRooms[0], "single_authorized");

  const defaultRoomId = String(user?.defaultRoomId ?? "").trim();
  const defaultRoom = defaultRoomId ? (byId.get(defaultRoomId) ?? null) : null;
  if (defaultRoom?.enabled && defaultRoom.authorized) {
    return toInitial(defaultRoom, "default_room");
  }

  const operativaRoom =
    enabledRooms.find(
      (room) =>
        normalizeUsername(room.roomName) === normalizeUsername("Operativa"),
    ) ?? null;
  if (operativaRoom && operativaRoom.authorized) {
    return toInitial(operativaRoom, "operativa_fallback");
  }

  if (authorizedRooms.length > 0)
    return toInitial(authorizedRooms[0], "first_authorized");
  if (lastRoom?.enabled && lastRoom.requiresAdminAuth)
    return toInitial(lastRoom, "last_selected_requires_admin");
  if (defaultRoom?.enabled && defaultRoom.requiresAdminAuth)
    return toInitial(defaultRoom, "default_room_requires_admin");
  if (enabledRooms.length > 0)
    return toInitial(enabledRooms[0], "first_enabled_requires_admin");
  return null;
}

function canViewRoom(user, roomId, settings) {
  if (isPosPrivilegedRole(user?.role)) return true;
  return buildMobileRoomSettings(
    user,
    buildPosRoomListFromSettings(settings),
    settings,
  ).enabledRoomIds.includes(String(roomId ?? "").trim());
}

function canDirectlyEnterRoom(user, roomId, settings) {
  if (isPosPrivilegedRole(user?.role)) return true;
  return buildMobileRoomSettings(
    user,
    buildPosRoomListFromSettings(settings),
    settings,
  ).authorizedRoomIds.includes(String(roomId ?? "").trim());
}

function requiresAdminForRoomChange(user, roomId, settings) {
  const targetRoomId = String(roomId ?? "").trim();
  return (
    canViewRoom(user, targetRoomId, settings) &&
    !canDirectlyEnterRoom(user, targetRoomId, settings)
  );
}

function findPosAllowedRoom(settings, role, roomIdRaw) {
  const roomId = String(roomIdRaw ?? "").trim();
  if (!roomId) return null;
  return (
    buildPosAllowedRoomsForRole(settings, role).find(
      (room) => room.id === roomId,
    ) ?? null
  );
}

function findPosAllowedRoomForUser(settings, user, roomIdRaw) {
  const roomId = String(roomIdRaw ?? "").trim();
  if (!roomId) return null;
  if (!canViewRoom(user, roomId, settings)) return null;
  return (
    buildPosRoomListFromSettings(settings).find((room) => room.id === roomId) ??
    null
  );
}

function canUserChangeRoomDirectly(user, targetRoomIdRaw, settings) {
  return canDirectlyEnterRoom(user, targetRoomIdRaw, settings);
}

function findPosRoomById(settings, roomIdRaw) {
  const roomId = String(roomIdRaw ?? "").trim();
  if (!roomId) return null;
  return (
    buildPosRoomListFromSettings(settings).find((room) => room.id === roomId) ??
    null
  );
}

function findPosTableWithLayout(settings, tableIdRaw) {
  const tableId = String(tableIdRaw ?? "").trim();
  if (!tableId) return null;
  const safeSettings = sanitizePosSettings(settings);
  const tableIndex = safeSettings.tables.findIndex(
    (table) => table.id === tableId,
  );
  if (tableIndex < 0) return null;
  const table = safeSettings.tables[tableIndex];
  const layoutTable =
    buildIntegrationLayoutFromSettings(safeSettings).tables.find(
      (entry) => entry.id === tableId,
    ) ?? null;
  return {
    table,
    tableIndex,
    layoutTable,
    roomId: String(layoutTable?.roomId ?? "").trim(),
    roomName: String(layoutTable?.roomName ?? "").trim(),
    settings: safeSettings,
  };
}

const {
  buildTableWorkLock,
  canOverrideTableWorkLock,
  isSameTableLockOwner,
  isTableWorkLockExpired,
  sanitizeTableWorkLock,
  shouldReuseRecentTableWorkLock,
} = createTableWorkLockHelpers({
  hasPermission,
  heartbeatWriteMinIntervalMs: TABLE_LOCK_HEARTBEAT_WRITE_MIN_INTERVAL_MS,
  isAdminUser,
  nowIso,
  tableLockTtlMs: TABLE_LOCK_TTL_MS,
});

function assertUserCanOperateInTableRoom(user, settings, tableInfo) {
  const roomId = String(tableInfo?.roomId ?? "").trim();
  if (!roomId) return;
  if (
    canDirectlyEnterRoom(user, roomId, settings) ||
    canOverrideTableWorkLock(user)
  )
    return;
  throw new HttpError(403, "Utente non autorizzato a operare in questa sala.");
}

function assertUserCanOperateInRemovedTableRoom(
  user,
  settings,
  tableInfo,
  { session = null } = {},
) {
  const roomId = String(tableInfo?.roomId ?? "").trim();
  if (!roomId) return;
  if (findPosRoomById(settings, roomId)) {
    assertUserCanOperateInTableRoom(user, settings, tableInfo);
    return;
  }
  if (canOverrideTableWorkLock(user)) return;

  const normalizeHistoricalRoomIds = (value) =>
    new Set(
      (Array.isArray(value) ? value : [])
        .map((entry) => String(entry ?? "").trim())
        .filter(Boolean),
    );
  const enabledRoomIds = normalizeHistoricalRoomIds(user?.enabledRoomIds);
  const authorizedRoomIds = normalizeHistoricalRoomIds(
    user?.authorizedRoomIds,
  );
  const wasEnabled = enabledRoomIds.size === 0 || enabledRoomIds.has(roomId);
  if (wasEnabled && authorizedRoomIds.has(roomId)) return;

  const userId = String(user?.id ?? "").trim();
  const sessionRoomId = String(session?.roomId ?? "").trim();
  const evidenceUserIds = normalizeHistoricalRoomIds(
    tableInfo?.removedOperationalEvidenceUserIds,
  );
  if (
    userId &&
    (sessionRoomId === roomId || evidenceUserIds.has(userId))
  ) {
    return;
  }
  throw new HttpError(403, "Utente non autorizzato a operare in questa sala.");
}

function appendTableLockAudit(
  db,
  action,
  { actor, tableInfo, previousLock = null, nextLock = null },
) {
  if (!shouldPersistTableLockAudit(action)) return;
  appendAuditEvent(db, {
    ...actor,
    action,
    entityType: "table",
    entityId:
      tableInfo?.table?.id ?? nextLock?.tableId ?? previousLock?.tableId ?? "",
    roomId: tableInfo?.roomId || actor.roomId,
    payload: {
      tableId:
        tableInfo?.table?.id ??
        nextLock?.tableId ??
        previousLock?.tableId ??
        "",
      tableNumber: tableInfo?.table?.number ?? null,
      roomId: tableInfo?.roomId ?? "",
      previousLock,
      nextLock,
      timestamp: nowIso(),
    },
  });
}

const TABLE_LOCK_IMPORTANT_AUDIT_ACTIONS = new Set([
  "table.lock_denied",
  "table.lock_required",
  "table.lock_expired",
  "table.lock_force_released",
]);

function shouldPersistTableLockAudit(action) {
  if (!mysqlTableLocksRepository?.enabled) return true;
  if (MYSQL_TABLE_LOCKS_VERBOSE_AUDIT) return true;
  return TABLE_LOCK_IMPORTANT_AUDIT_ACTIONS.has(String(action ?? "").trim());
}

function acquireOrRefreshTableWorkLock(
  db,
  tableId,
  {
    user,
    session,
    payload = {},
    purpose = "table_mutation",
    forceHeartbeat = false,
  },
) {
  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const tableInfo = findPosTableWithLayout(settings, tableId);
  if (!tableInfo) {
    throw new HttpError(404, "Tavolo non trovato.");
  }
  assertUserCanOperateInTableRoom(user, settings, tableInfo);

  const actor = buildAuditActor(user, { ...payload, roomId: tableInfo.roomId });
  const table = tableInfo.table;
  const previousLock = sanitizeTableWorkLock(table.workLock);
  const expired = previousLock ? isTableWorkLockExpired(previousLock) : false;
  if (previousLock && expired) {
    appendTableLockAudit(db, "table.lock_expired", {
      actor,
      tableInfo,
      previousLock,
      nextLock: null,
    });
  }

  if (
    previousLock &&
    !expired &&
    !isSameTableLockOwner(previousLock, user, session, payload)
  ) {
    appendTableLockAudit(db, "table.lock_denied", {
      actor,
      tableInfo,
      previousLock,
      nextLock: previousLock,
    });
    throw new HttpError(
      409,
      `Il tavolo è già in modifica da ${previousLock.username}.`,
      {
        code: "TABLE_LOCKED",
        details: {
          lockedByUsername: previousLock.username,
          purpose: previousLock.purpose,
          expiresAt: previousLock.expiresAt,
        },
      },
    );
  }

  const normalizedPurpose =
    String(purpose ?? "table_mutation").trim() || "table_mutation";
  if (
    !forceHeartbeat &&
    previousLock &&
    !expired &&
    shouldReuseRecentTableWorkLock(previousLock, normalizedPurpose)
  ) {
    return { lock: previousLock, tableInfo };
  }

  const nextLock =
    previousLock && !expired
      ? sanitizeTableWorkLock({
          ...previousLock,
          heartbeatAt: nowIso(),
          expiresAt: new Date(Date.now() + TABLE_LOCK_TTL_MS).toISOString(),
          purpose: normalizedPurpose,
        })
      : buildTableWorkLock({
          tableId: table.id,
          user,
          session,
          payload,
          purpose: normalizedPurpose,
        });
  table.workLock = nextLock;
  const nextSettings = sanitizePosSettings(
    {
      ...settings,
      tables: settings.tables.map((entry) =>
        entry.id === table.id ? table : entry,
      ),
    },
    { menuItems: db.menuItems, users: db.users },
  );
  db.posSettings = nextSettings;
  appendTableLockAudit(
    db,
    previousLock && !expired ? "table.lock_heartbeat" : "table.lock_acquired",
    {
      actor,
      tableInfo: { ...tableInfo, table },
      previousLock: previousLock && !expired ? previousLock : null,
      nextLock,
    },
  );
  return {
    lock: nextLock,
    tableInfo: findPosTableWithLayout(nextSettings, table.id) ?? {
      ...tableInfo,
      table,
    },
  };
}

function assertActiveTableWorkLock(
  db,
  tableId,
  {
    user,
    session,
    payload = {},
    purpose = "table_mutation",
    requireExisting = false,
  },
) {
  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const tableInfo = findPosTableWithLayout(settings, tableId);
  if (!tableInfo) {
    throw new HttpError(404, "Tavolo non trovato.");
  }
  assertUserCanOperateInTableRoom(user, settings, tableInfo);
  const lock = sanitizeTableWorkLock(tableInfo.table.workLock);
  if (!lock || isTableWorkLockExpired(lock)) {
    if (requireExisting) {
      const actor = buildAuditActor(user, {
        ...payload,
        roomId: tableInfo.roomId,
      });
      appendTableLockAudit(db, "table.lock_required", {
        actor,
        tableInfo,
        previousLock: lock ?? null,
        nextLock: lock ?? null,
      });
      throw new HttpError(
        428,
        "Il tavolo deve essere bloccato prima di confermare il pagamento. Riapri il dettaglio tavolo e riprova.",
        {
          code: "TABLE_LOCK_REQUIRED",
          details: {
            tableId,
            purpose,
            expired: Boolean(lock),
          },
        },
      );
    }
    return acquireOrRefreshTableWorkLock(db, tableId, {
      user,
      session,
      payload,
      purpose,
    });
  }
  if (!isSameTableLockOwner(lock, user, session, payload)) {
    const actor = buildAuditActor(user, {
      ...payload,
      roomId: tableInfo.roomId,
    });
    appendTableLockAudit(db, "table.lock_denied", {
      actor,
      tableInfo,
      previousLock: lock,
      nextLock: lock,
    });
    throw new HttpError(
      409,
      "Il tavolo è già in modifica da un altro operatore.",
      {
        code: "TABLE_LOCKED",
        details: {
          lockedByUsername: lock.username,
          purpose: lock.purpose,
          expiresAt: lock.expiresAt,
        },
      },
    );
  }
  return acquireOrRefreshTableWorkLock(db, tableId, {
    user,
    session,
    payload,
    purpose,
  });
}

function releaseTableWorkLock(
  db,
  tableId,
  { user, session, payload = {}, force = false },
) {
  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const tableInfo = findPosTableWithLayout(settings, tableId);
  if (!tableInfo) {
    throw new HttpError(404, "Tavolo non trovato.");
  }
  const previousLock = sanitizeTableWorkLock(tableInfo.table.workLock);
  if (!previousLock) return { released: false, previousLock: null, tableInfo };
  const actor = buildAuditActor(user, { ...payload, roomId: tableInfo.roomId });
  if (!force && !isSameTableLockOwner(previousLock, user, session, payload)) {
    throw new HttpError(
      403,
      "Solo l'operatore che ha il lock puo rilasciarlo.",
    );
  }
  if (force && !canOverrideTableWorkLock(user)) {
    throw new HttpError(
      403,
      "Permesso insufficiente per forzare il rilascio del tavolo.",
    );
  }
  tableInfo.table.workLock = null;
  db.posSettings = sanitizePosSettings(
    {
      ...settings,
      tables: settings.tables.map((entry) =>
        entry.id === tableInfo.table.id ? tableInfo.table : entry,
      ),
    },
    { menuItems: db.menuItems, users: db.users },
  );
  appendTableLockAudit(
    db,
    force ? "table.lock_force_released" : "table.lock_released",
    {
      actor,
      tableInfo,
      previousLock,
      nextLock: null,
    },
  );
  return { released: true, previousLock, tableInfo };
}

function clearEmbeddedTableWorkLock(db, tableId) {
  const normalizedTableId = String(tableId ?? "").trim();
  if (!normalizedTableId) return false;
  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  let changed = false;
  const tables = settings.tables.map((entry) => {
    if (String(entry?.id ?? "").trim() !== normalizedTableId) return entry;
    if (!entry?.workLock) return entry;
    changed = true;
    return { ...entry, workLock: null };
  });
  if (!changed) return false;
  db.posSettings = sanitizePosSettings(
    {
      ...settings,
      tables,
    },
    { menuItems: db.menuItems, users: db.users },
  );
  return true;
}

async function appendTableLockAuditFast(
  action,
  { actor, tableInfo, previousLock = null, nextLock = null },
) {
  if (!shouldPersistTableLockAudit(action)) return;
  if (!mysqlAuditEventsSplitRepository?.enabled) return;
  await mysqlAuditEventsSplitRepository.appendEvent({
    ...actor,
    action,
    entityType: "table",
    entityId:
      tableInfo?.table?.id ?? nextLock?.tableId ?? previousLock?.tableId ?? "",
    roomId: tableInfo?.roomId || actor.roomId,
    payload: {
      tableId:
        tableInfo?.table?.id ??
        nextLock?.tableId ??
        previousLock?.tableId ??
        "",
      tableNumber: tableInfo?.table?.number ?? null,
      roomId: tableInfo?.roomId ?? "",
      previousLock,
      nextLock,
      timestamp: nowIso(),
      fastPath: "mysql_table_locks",
    },
  });
}

function resolveTableWorkLockContext(db, tableId, { user, payload = {} }) {
  const cachedTableInfo = tableLockWorkerRequestFastPath.resolveTableContext(db, tableId);
  const settings = cachedTableInfo === undefined ? sanitizePosSettings(db.posSettings, { menuItems: db.menuItems, users: db.users }) : cachedTableInfo?.settings;
  const tableInfo = cachedTableInfo === undefined ? findPosTableWithLayout(settings, tableId) : cachedTableInfo;
  if (!tableInfo) {
    throw new HttpError(404, "Tavolo non trovato.");
  }
  assertUserCanOperateInTableRoom(user, settings, tableInfo);
  const actor = buildAuditActor(user, { ...payload, roomId: tableInfo.roomId });
  return { actor, settings, tableInfo };
}

async function acquireOrRefreshTableWorkLockFast(
  db,
  tableId,
  {
    user,
    session,
    payload = {},
    purpose = "table_mutation",
    forceHeartbeat = false,
  },
) {
  const { actor, tableInfo } = resolveTableWorkLockContext(db, tableId, {
    user,
    payload,
  });
  const tableLocksRepository = getTableWorkLocksFastRepository();
  if (!tableLocksRepository) {
    throw new Error("Fast path table locks non disponibile.");
  }
  const table = tableInfo.table;
  const normalizedPurpose =
    String(purpose ?? "table_mutation").trim() || "table_mutation";
  let auditEvent = null;
  const result = await tableLocksRepository.mutateTableLock(
    table.id,
    (currentLock) => {
      const previousLock = sanitizeTableWorkLock(currentLock);
      const expired = previousLock
        ? isTableWorkLockExpired(previousLock)
        : false;
      if (previousLock && expired) {
        auditEvent = {
          action: "table.lock_expired",
          previousLock,
          nextLock: null,
        };
      }

      if (
        previousLock &&
        !expired &&
        !isSameTableLockOwner(previousLock, user, session, payload)
      ) {
        auditEvent = {
          action: "table.lock_denied",
          previousLock,
          nextLock: previousLock,
        };
        return {
          error: new HttpError(
            409,
            `Il tavolo è già in modifica da ${previousLock.username}.`,
            {
              code: "TABLE_LOCKED",
              details: {
                lockedByUsername: previousLock.username,
                purpose: previousLock.purpose,
                expiresAt: previousLock.expiresAt,
              },
            },
          ),
        };
      }

      if (
        !forceHeartbeat &&
        previousLock &&
        !expired &&
        shouldReuseRecentTableWorkLock(previousLock, normalizedPurpose)
      ) {
        return {
          lock: previousLock,
          nextLock: null,
          changed: false,
        };
      }

      const nextLock =
        previousLock && !expired
          ? sanitizeTableWorkLock({
              ...previousLock,
              heartbeatAt: nowIso(),
              expiresAt: new Date(Date.now() + TABLE_LOCK_TTL_MS).toISOString(),
              purpose: normalizedPurpose,
            })
          : buildTableWorkLock({
              tableId: table.id,
              user,
              session,
              payload,
              purpose: normalizedPurpose,
            });
      return {
        lock: nextLock,
        nextLock,
        changed: true,
      };
    }, { namedLock: !MYSQL_TABLE_LOCKS_HYBRID || !forceHeartbeat });
  if (auditEvent) {
    await appendTableLockAuditFast(auditEvent.action, {
      actor,
      tableInfo,
      previousLock: auditEvent.previousLock,
      nextLock: auditEvent.nextLock,
    });
  }
  if (result.error) throw result.error;
  const lock = sanitizeTableWorkLock(result.lock);
  const tableWithLock = {
    ...tableInfo.table,
    workLock: lock,
  };
  if (!tableLockWorkerRequestFastPath.isEnabled()) { const currentSettings = sanitizePosSettings(db.posSettings, { menuItems: db.menuItems, users: db.users }); db.posSettings = sanitizePosSettings({ ...currentSettings, tables: currentSettings.tables.map((entry) => entry.id === tableInfo.table.id ? tableWithLock : entry) }, { menuItems: db.menuItems, users: db.users }); }
  return {
    lock,
    tableInfo: {
      ...tableInfo,
      table: tableWithLock,
    },
  };
}

async function releaseTableWorkLockFast(
  db,
  tableId,
  { user, session, payload = {}, force = false },
) {
  const { actor, tableInfo } = resolveTableWorkLockContext(db, tableId, {
    user,
    payload,
  });
  const tableLocksRepository = getTableWorkLocksFastRepository();
  if (!tableLocksRepository) {
    throw new Error("Fast path table locks non disponibile.");
  }
  let auditEvent = null;
  const result = await tableLocksRepository.mutateTableLock(
    tableInfo.table.id,
    (currentLock) => {
      const previousLock = sanitizeTableWorkLock(currentLock);
      if (!previousLock) {
        return { released: false, previousLock: null };
      }
      if (!force && !isSameTableLockOwner(previousLock, user, session, payload)) {
        return {
          error: new HttpError(
            403,
            "Solo l'operatore che ha il lock puo rilasciarlo.",
          ),
          previousLock,
        };
      }
      if (force && !canOverrideTableWorkLock(user)) {
        return {
          error: new HttpError(
            403,
            "Permesso insufficiente per forzare il rilascio del tavolo.",
          ),
          previousLock,
        };
      }
      if (force) {
        auditEvent = {
          action: "table.lock_force_released",
          previousLock,
          nextLock: null,
        };
      }
      return {
        delete: true,
        released: true,
        previousLock,
      };
    }, { namedLock: !MYSQL_TABLE_LOCKS_HYBRID });
  if (auditEvent) {
    await appendTableLockAuditFast(auditEvent.action, {
      actor,
      tableInfo,
      previousLock: auditEvent.previousLock,
      nextLock: auditEvent.nextLock,
    });
  }
  if (result.error) throw result.error;
  const tableWithoutLock = {
    ...tableInfo.table,
    workLock: null,
  };
  if (!tableLockWorkerRequestFastPath.isEnabled()) { const currentSettings = sanitizePosSettings(db.posSettings, { menuItems: db.menuItems, users: db.users }); db.posSettings = sanitizePosSettings({ ...currentSettings, tables: currentSettings.tables.map((entry) => entry.id === tableInfo.table.id ? tableWithoutLock : entry) }, { menuItems: db.menuItems, users: db.users }); }
  return {
    released: Boolean(result.released),
    previousLock: result.previousLock ?? null,
    tableInfo: {
      ...tableInfo,
      table: tableWithoutLock,
    },
  };
}

function toPosServiceDateKey(value) {
  const raw = String(value ?? "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) return null;
  const parsed = new Date(raw);
  if (!Number.isFinite(parsed.getTime())) return null;
  return localDateKeyFromDate(parsed);
}

function toPosReservationStateKey(roomId, serviceDate) {
  return `${roomId}__${serviceDate}`;
}

function toPosReservationId() {
  return `res_${Date.now()}_${randomUUID().replace(/-/g, "").slice(0, 8)}`;
}

function toPosReservationLockId() {
  return `lock_${Date.now()}_${randomUUID().replace(/-/g, "").slice(0, 8)}`;
}

function clonePosReservation(reservation) {
  const publicReservation = { ...(reservation && typeof reservation === "object" ? reservation : {}) };
  delete publicReservation.offlineReplay;
  return {
    ...publicReservation,
    assignedTableIds: normalizePosReservationTableIds(
      reservation?.assignedTableIds,
      reservation?.assignedTableId,
    ),
  };
}

function clonePosReservationState(state) {
  return {
    key: state.key,
    roomId: state.roomId,
    serviceDate: state.serviceDate,
    version: state.version,
    reservations: state.reservations.map(clonePosReservation),
  };
}

function sanitizePosRoomChangeRequestRecord(entry, availableRoomsById = null) {
  if (!entry || typeof entry !== "object") return null;
  const requestId = String(entry.requestId ?? "").trim();
  const userId = String(entry.userId ?? "").trim();
  const deviceUuid = String(entry.deviceUuid ?? "").trim();
  const targetRoomId = String(
    entry.targetRoomId ?? entry?.targetRoom?.id ?? "",
  ).trim();
  const targetRoomNameInput = String(
    entry.targetRoomName ?? entry?.targetRoom?.name ?? "",
  ).trim();
  if (!requestId || !userId || !deviceUuid || !targetRoomId) return null;
  const createdAt = Number(entry.createdAt);
  const createdAtMs = Number.isFinite(createdAt)
    ? Math.max(0, Math.trunc(createdAt))
    : Date.now();
  const roomFromSettings =
    availableRoomsById && availableRoomsById instanceof Map
      ? availableRoomsById.get(targetRoomId)
      : null;
  const targetRoomName =
    roomFromSettings?.name || targetRoomNameInput || targetRoomId;
  return {
    requestId,
    userId,
    sessionId: String(entry.sessionId ?? "").trim(),
    deviceUuid,
    targetRoomId,
    targetRoomName,
    createdAt: createdAtMs,
    revision: clampInt(entry.revision, 1, 1_000_000, 1),
  };
}

const {
  buildPosTableRoomMoveNotificationPayload,
  buildPosTableRoomMoveResponse,
  resolvePendingPosTableRoomMoveRequest,
  sanitizePosTableRoomMoveRequestRecord,
} = createTableRoomMoveHelpers({
  approvalTimeoutMs: POS_TABLE_ROOM_MOVE_APPROVAL_TIMEOUT_MS,
});

function sanitizePosReservationRecord(entry, fallback) {
  if (!entry || typeof entry !== "object") return null;
  const id = String(entry.id ?? fallback.id).trim() || fallback.id;
  const roomId =
    String(entry.roomId ?? fallback.roomId).trim() || fallback.roomId;
  const serviceDate =
    toPosServiceDateKey(entry.serviceDate) ?? fallback.serviceDate;
  const reservationAt = Number(entry.reservationAt);
  const reservationAtMs = Number.isFinite(reservationAt)
    ? Math.trunc(reservationAt)
    : Date.now();
  const customerName = String(entry.customerName ?? "")
    .trim()
    .slice(0, 80);
  if (!customerName) return null;
  const customerPhone = String(entry.customerPhone ?? "")
    .trim()
    .slice(0, 24);
  const covers = normalizeTableCovers(entry.covers, { minimum: 1, fallback: 2 });
  const intolerances = String(entry.intolerances ?? "")
    .trim()
    .slice(0, 180);
  const note = String(entry.note ?? "")
    .trim()
    .slice(0, 280);
  const assignedTableIds = normalizePosReservationTableIds(
    entry.assignedTableIds,
    entry.assignedTableId,
  );
  const assignedTableId = assignedTableIds[0] ?? null;
  const createdAtRaw = Number(entry.createdAt);
  const updatedAtRaw = Number(entry.updatedAt);
  const releasedAtRaw = Number(entry.releasedAt);
  const arrivedAtRaw = Number(entry.arrivedAt);
  const noShowAtRaw = Number(entry.noShowAt);
  const cancelledAtRaw = Number(entry.cancelledAt);
  const createdAt = Number.isFinite(createdAtRaw)
    ? Math.max(0, Math.trunc(createdAtRaw))
    : reservationAtMs;
  const updatedAt = Number.isFinite(updatedAtRaw)
    ? Math.max(0, Math.trunc(updatedAtRaw))
    : createdAt;
  const releasedAt =
    Number.isFinite(releasedAtRaw) && releasedAtRaw > 0
      ? Math.max(0, Math.trunc(releasedAtRaw))
      : null;
  const arrivedAt =
    Number.isFinite(arrivedAtRaw) && arrivedAtRaw > 0
      ? Math.max(0, Math.trunc(arrivedAtRaw))
      : null;
  const noShowAt =
    Number.isFinite(noShowAtRaw) && noShowAtRaw > 0
      ? Math.max(0, Math.trunc(noShowAtRaw))
      : null;
  const cancelledAt =
    Number.isFinite(cancelledAtRaw) && cancelledAtRaw > 0
      ? Math.max(0, Math.trunc(cancelledAtRaw))
      : null;
  const statusRaw = String(entry.status ?? "")
    .trim()
    .toLowerCase();
  const status =
    statusRaw === "arrived" ||
    statusRaw === "no_show" ||
    statusRaw === "cancelled" ||
    statusRaw === "released"
      ? statusRaw
      : "booked";
  const offlineReplaySource =
    entry.offlineReplay && typeof entry.offlineReplay === "object"
      ? entry.offlineReplay
      : null;
  const offlineReplayRequestId = String(offlineReplaySource?.requestId ?? "")
    .trim()
    .slice(0, 160);
  const offlineReplayIdempotencyKey = String(
    offlineReplaySource?.idempotencyKey ?? "",
  )
    .trim()
    .slice(0, 160);
  return {
    id,
    roomId,
    serviceDate,
    status,
    reservationAt: reservationAtMs,
    customerName,
    customerPhone,
    covers,
    intolerances,
    note,
    assignedTableId,
    assignedTableIds,
    createdAt,
    updatedAt,
    ...(releasedAt ? { releasedAt } : {}),
    ...(arrivedAt ? { arrivedAt } : {}),
    ...(noShowAt ? { noShowAt } : {}),
    ...(cancelledAt ? { cancelledAt } : {}),
    ...(offlineReplayRequestId && offlineReplayIdempotencyKey
      ? {
          offlineReplay: {
            requestId: offlineReplayRequestId,
            idempotencyKey: offlineReplayIdempotencyKey,
          },
        }
      : {}),
  };
}

function sanitizePosReservationStateRecord(entry) {
  if (!entry || typeof entry !== "object") return null;
  const roomId = String(entry.roomId ?? "").trim();
  const serviceDate = toPosServiceDateKey(entry.serviceDate);
  if (!roomId || !serviceDate) return null;
  const key = toPosReservationStateKey(roomId, serviceDate);
  const version = clampInt(entry.version, 1, Number.MAX_SAFE_INTEGER, 1);
  const reservationsRaw = Array.isArray(entry.reservations)
    ? entry.reservations
    : [];
  const reservations = reservationsRaw
    .map((reservation, index) =>
      sanitizePosReservationRecord(reservation, {
        id: `res_${index + 1}`,
        roomId,
        serviceDate,
      }),
    )
    .filter((reservation) => reservation !== null);
  return {
    key,
    roomId,
    serviceDate,
    version,
    reservations,
  };
}

function sanitizePosReservationLockRecord(entry) {
  if (!entry || typeof entry !== "object") return null;
  const reservationId = String(entry.reservationId ?? "").trim();
  const lockId = String(entry.lockId ?? "").trim();
  const userId = String(entry.userId ?? "").trim();
  const deviceUuid = String(entry.deviceUuid ?? "").trim();
  const expiresAtRaw = Number(entry.expiresAt);
  const expiresAt = Number.isFinite(expiresAtRaw)
    ? Math.max(0, Math.trunc(expiresAtRaw))
    : 0;
  if (!reservationId || !lockId || !userId || !deviceUuid || expiresAt <= 0) {
    return null;
  }
  return {
    reservationId,
    lockId,
    userId,
    deviceUuid,
    expiresAt,
  };
}

function ensurePosDataCollections(db) {
  if (!Array.isArray(db.posRoomChangeRequests)) {
    db.posRoomChangeRequests = [];
  }
  if (!Array.isArray(db.posTableRoomMoveRequests)) {
    db.posTableRoomMoveRequests = [];
  }
  if (!Array.isArray(db.posReservationStates)) {
    db.posReservationStates = [];
  }
  if (!Array.isArray(db.posReservationLocks)) {
    db.posReservationLocks = [];
  }
}

function getOrCreatePosReservationState(db, roomId, serviceDate) {
  ensurePosDataCollections(db);
  const key = toPosReservationStateKey(roomId, serviceDate);
  const index = db.posReservationStates.findIndex(
    (entry) => entry?.key === key,
  );
  if (index >= 0) {
    const existing = sanitizePosReservationStateRecord(
      db.posReservationStates[index],
    );
    if (existing) {
      db.posReservationStates[index] = existing;
      return { state: existing, created: false };
    }
  }
  const created = {
    key,
    roomId,
    serviceDate,
    version: 1,
    reservations: [],
  };
  db.posReservationStates.push(created);
  return { state: created, created: true };
}

function pruneExpiredPosRoomChangeRequests(db, nowMs = Date.now()) {
  ensurePosDataCollections(db);
  const before = db.posRoomChangeRequests.length;
  db.posRoomChangeRequests = db.posRoomChangeRequests
    .map((entry) => sanitizePosRoomChangeRequestRecord(entry))
    .filter((entry) => entry !== null)
    .filter((entry) => nowMs - entry.createdAt <= POS_ROOM_CHANGE_MAX_AGE_MS);
  return db.posRoomChangeRequests.length !== before;
}

function pruneExpiredPosTableRoomMoveRequests(db, nowMs = Date.now()) {
  ensurePosDataCollections(db);
  const before = db.posTableRoomMoveRequests.length;
  db.posTableRoomMoveRequests = db.posTableRoomMoveRequests
    .map((entry) => sanitizePosTableRoomMoveRequestRecord(entry))
    .filter((entry) => entry !== null)
    .filter((entry) => {
      if (entry.status === "pending")
        return nowMs - entry.createdAt <= POS_ROOM_CHANGE_MAX_AGE_MS;
      const resolvedAt =
        entry.approvedAt || entry.rejectedAt || entry.expiresAt;
      return nowMs - resolvedAt <= POS_ROOM_CHANGE_MAX_AGE_MS;
    });
  return db.posTableRoomMoveRequests.length !== before;
}

function pruneExpiredPosReservationLocks(db, nowMs = Date.now()) {
  ensurePosDataCollections(db);
  const before = db.posReservationLocks.length;
  db.posReservationLocks = db.posReservationLocks
    .map((entry) => sanitizePosReservationLockRecord(entry))
    .filter((entry) => entry !== null && entry.expiresAt > nowMs);
  return db.posReservationLocks.length !== before;
}

function getPosActiveReservationLock(db, reservationId, nowMs = Date.now()) {
  pruneExpiredPosReservationLocks(db, nowMs);
  return (
    db.posReservationLocks.find(
      (entry) => entry.reservationId === reservationId,
    ) ?? null
  );
}

function requirePosReservationWritableLock(
  db,
  reservationId,
  lockId,
  userId,
  deviceUuid,
) {
  const lock = getPosActiveReservationLock(db, reservationId);
  if (!lock) {
    throw new HttpError(
      409,
      "Blocco modifica scaduto. Riapri la prenotazione.",
    );
  }
  if (lock.lockId !== lockId) {
    throw new HttpError(409, "Blocco modifica non valido.");
  }
  if (lock.userId !== userId || lock.deviceUuid !== deviceUuid) {
    throw new HttpError(409, "Prenotazione in modifica da un altro operatore.");
  }
}

const POS_RESERVATION_MIN_TABLE_GAP_MINUTES = 60;
const POS_RESERVATION_DANGER_GAP_MINUTES = 90;
const POS_RESERVATION_WARNING_GAP_MINUTES = 120;

const {
  buildPosAvailabilityLabel,
  classifyPosReservationDistance,
  findPosNearestReservation,
  posClockFromTimestamp,
} = createPosReservationAvailabilityHelpers({
  dangerGapMinutes: POS_RESERVATION_DANGER_GAP_MINUTES,
  minTableGapMinutes: POS_RESERVATION_MIN_TABLE_GAP_MINUTES,
  warningGapMinutes: POS_RESERVATION_WARNING_GAP_MINUTES,
});

function normalizePosReservationSaveInput(input, current = null) {
  const source = input && typeof input === "object" ? input : {};
  const reservationAtRaw =
    source.reservationAt ??
    (current && Number.isFinite(current.reservationAt)
      ? current.reservationAt
      : Date.now());
  const reservationAt = Number(reservationAtRaw);
  if (!Number.isFinite(reservationAt)) {
    throw new HttpError(400, "Orario prenotazione non valido.");
  }

  const customerName = String(
    source.customerName ?? current?.customerName ?? "",
  )
    .trim()
    .slice(0, 80);
  if (!customerName) {
    throw new HttpError(400, "Nome prenotazione obbligatorio.");
  }

  const customerPhone = String(
    source.customerPhone ?? current?.customerPhone ?? "",
  )
    .trim()
    .slice(0, 24);
  const covers = normalizeTableCovers(source.covers ?? current?.covers, {
    minimum: 1,
    fallback: 2,
  });
  const intolerances = String(
    source.intolerances ?? current?.intolerances ?? "",
  )
    .trim()
    .slice(0, 180);
  const note = String(source.note ?? current?.note ?? "")
    .trim()
    .slice(0, 280);
  const hasAssignedTableIds = Object.prototype.hasOwnProperty.call(
    source,
    "assignedTableIds",
  );
  const hasAssignedTableId = Object.prototype.hasOwnProperty.call(
    source,
    "assignedTableId",
  );
  const assignedTableIds =
    hasAssignedTableIds || hasAssignedTableId
      ? normalizePosReservationTableIds(
          source.assignedTableIds,
          source.assignedTableId,
        )
      : normalizePosReservationTableIds(
          current?.assignedTableIds,
          current?.assignedTableId,
        );
  const assignedTableId = assignedTableIds[0] ?? null;

  return {
    reservationAt: Math.trunc(reservationAt),
    customerName,
    customerPhone,
    covers,
    intolerances,
    note,
    assignedTableId,
    assignedTableIds,
  };
}

function assertPosReservationAssignable(
  reservations,
  reservationAt,
  tableId,
  ignoreReservationId = "",
) {
  const availability = findPosNearestReservation(
    reservations,
    tableId,
    reservationAt,
    ignoreReservationId,
  );
  if (availability.status === "conflict") {
    throw new HttpError(
      409,
      `Tavolo gia assegnato a meno di ${POS_RESERVATION_MIN_TABLE_GAP_MINUTES} minuti da un'altra prenotazione.`,
    );
  }
}

const POS_RESERVATION_BLOCK_WINDOW_MS = 30 * 60_000;
const POS_RESERVATION_LATE_GRACE_MS = 30 * 60_000;

const { isPosReservationReleased, shouldActivatePosReservation } =
  createPosReservationStateHelpers({
    blockWindowMs: POS_RESERVATION_BLOCK_WINDOW_MS,
    lateGraceMs: POS_RESERVATION_LATE_GRACE_MS,
  });

function isSamePosReservationGuest(table, reservation) {
  const tableName = normalizeUsername(
    table?.guestName ?? table?.tableName ?? "",
  );
  const reservationName = normalizeUsername(reservation?.customerName ?? "");
  const tablePhone = normalizeUsername(table?.customerPhone ?? "");
  const reservationPhone = normalizeUsername(reservation?.customerPhone ?? "");
  return Boolean(
    (tableName && reservationName && tableName === reservationName) ||
    (tablePhone && reservationPhone && tablePhone === reservationPhone),
  );
}

function isPosReservationTableReleasable(table, reservation) {
  const safeTable = sanitizePosTable(table, Number(table?.number) || 1);
  const status = String(safeTable.status ?? "free").trim();
  const hasFinancials =
    Number(safeTable.totalDue) > 0 ||
    (Array.isArray(safeTable.pendingBills) &&
      safeTable.pendingBills.length > 0);
  if (hasFinancials) return false;
  if (status === "free" || status === "reserved" || status === "no_orders")
    return true;
  return isSamePosReservationGuest(safeTable, reservation);
}

function buildPosReservationTableGroup(tableIds) {
  const rootTableId = tableIds[0];
  if (!rootTableId || tableIds.length < 2) return null;
  return {
    id: rootTableId,
    type: "complex",
    children: tableIds.map((tableId) => ({
      id: tableId,
      type: "simple",
    })),
    updatedAt: nowIso(),
  };
}

function activateDuePosReservationsOnLayout(
  db,
  settingsInput,
  nowMs = Date.now(),
) {
  ensurePosDataCollections(db);
  const settings = sanitizePosSettings(settingsInput ?? db.posSettings, {
    menuItems: db.menuItems,
  });
  const validIds = new Set(
    settings.tables
      .map((table) => String(table.id ?? "").trim())
      .filter(Boolean),
  );
  const tableById = new Map(
    settings.tables.map((table, index) => [
      String(table.id ?? "").trim(),
      { table, index },
    ]),
  );
  const integration =
    db.integration && typeof db.integration === "object" ? db.integration : {};
  const currentGroups = sanitizeIntegrationTableGroups(
    integration.tableGroups,
    { validIds },
  );
  let changed = false;
  let groups = currentGroups;

  for (const state of db.posReservationStates) {
    const reservations = Array.isArray(state?.reservations)
      ? state.reservations
      : [];
    for (const reservation of reservations) {
      if (isPosReservationReleased(reservation)) continue;
      const tableIds = posReservationAssignedTableIds(reservation).filter(
        (tableId) => validIds.has(tableId),
      );
      if (
        tableIds.length === 0 ||
        !shouldActivatePosReservation(reservation?.reservationAt, nowMs)
      )
        continue;
      const targets = tableIds
        .map((tableId) => tableById.get(tableId))
        .filter((entry) => entry && entry.table);
      if (targets.length !== tableIds.length) continue;
      if (
        !targets.every(({ table }) =>
          isPosReservationTableReleasable(table, reservation),
        )
      )
        continue;

      const targetSet = new Set(tableIds);
      const overlappingGroups = groups.filter((group) => {
        const groupIds = new Set([
          String(group.id ?? "").trim(),
          ...collectIntegrationTableGroupLeafIds(group),
        ]);
        return [...targetSet].some((tableId) => groupIds.has(tableId));
      });
      const desiredGroup = buildPosReservationTableGroup(tableIds);
      const matchingGroup =
        desiredGroup && overlappingGroups.length === 1
          ? overlappingGroups[0]
          : null;
      const matchingLeaves = matchingGroup
        ? collectIntegrationTableGroupLeafIds(matchingGroup)
        : new Set();
      const groupAlreadyActive =
        desiredGroup &&
        matchingGroup &&
        String(matchingGroup.id ?? "").trim() === desiredGroup.id &&
        matchingLeaves.size === targetSet.size &&
        [...targetSet].every((tableId) => matchingLeaves.has(tableId));
      if (
        !groupAlreadyActive &&
        (overlappingGroups.length > 0 || desiredGroup)
      ) {
        groups = groups.filter((group) => {
          const groupIds = new Set([
            String(group.id ?? "").trim(),
            ...collectIntegrationTableGroupLeafIds(group),
          ]);
          return ![...targetSet].some((tableId) => groupIds.has(tableId));
        });
        if (desiredGroup) {
          groups.push({
            ...desiredGroup,
            updatedAt: String(matchingGroup?.updatedAt ?? nowIso()),
          });
        }
        changed = true;
      }

      const rootTableId = tableIds[0];
      const rootEntry = tableById.get(rootTableId);
      if (!rootEntry) continue;
      const reservationTime = posClockFromTimestamp(reservation.reservationAt);
      const nextRoot = sanitizePosTable(
        {
          ...rootEntry.table,
          status: "reserved",
          guestName: reservation.customerName,
          customerPhone: reservation.customerPhone,
          covers: reservation.covers,
          reservation: normalizeReservation({
            time: reservationTime,
            people: reservation.covers,
            mergeFlag: tableIds.length > 1,
          }),
          note: reservation.note || rootEntry.table.note || "",
          totalDue: 0,
          pendingBills: [],
          seatedAt: null,
        },
        rootEntry.index + 1,
      );
      if (
        JSON.stringify(settings.tables[rootEntry.index]) !==
        JSON.stringify(nextRoot)
      ) {
        settings.tables[rootEntry.index] = nextRoot;
        changed = true;
      }

      for (const tableId of tableIds.slice(1)) {
        const childEntry = tableById.get(tableId);
        if (!childEntry) continue;
        const nextChild = sanitizePosTable(
          {
            ...childEntry.table,
            status: "free",
            guestName: "",
            covers: 0,
            totalDue: 0,
            reservation: null,
            pendingBills: [],
            customerPhone: "",
            note: "",
            seatedAt: null,
          },
          childEntry.index + 1,
        );
        if (
          JSON.stringify(settings.tables[childEntry.index]) !==
          JSON.stringify(nextChild)
        ) {
          settings.tables[childEntry.index] = nextChild;
          changed = true;
        }
      }
    }
  }

  if (!changed) {
    return { changed: false, settings, groups: currentGroups };
  }

  db.posSettings = sanitizePosSettings(settings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  db.integration = {
    ...integration,
    tableGroups: sanitizeIntegrationTableGroups(groups, { validIds }),
    lastWriteAt: nowIso(),
  };
  return {
    changed: true,
    settings: db.posSettings,
    groups: db.integration.tableGroups,
  };
}

function releaseActivatedPosReservationTableGroup(
  db,
  tableIdRaw,
  currentTable,
  nowMs = Date.now(),
  completionStatus = "released",
) {
  const tableId = String(tableIdRaw ?? "").trim();
  const hasActiveReservationContext =
    currentTable?.reservation?.mergeFlag === true ||
    currentTable?.reservation ||
    String(currentTable?.status ?? "").trim() === "reserved";
  if (!tableId || !hasActiveReservationContext) {
    return { changed: false, releasedReservationIds: [] };
  }
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
  });
  const validIds = new Set(
    settings.tables
      .map((table) => String(table.id ?? "").trim())
      .filter(Boolean),
  );
  const previousGroups = sanitizeIntegrationTableGroups(
    db.integration.tableGroups,
    { validIds },
  );
  const shouldSplitGroup = currentTable?.reservation?.mergeFlag === true;
  const nextGroups = shouldSplitGroup
    ? previousGroups.filter((group) => {
        const groupIds = new Set([
          String(group.id ?? "").trim(),
          ...collectIntegrationTableGroupLeafIds(group),
        ]);
        return !groupIds.has(tableId);
      })
    : previousGroups;
  const releasedReservationIds = [];
  const currentReservationTime = String(
    currentTable?.reservation?.time ?? "",
  ).trim();
  const safeCompletionStatus =
    completionStatus === "arrived" ||
    completionStatus === "no_show" ||
    completionStatus === "cancelled"
      ? completionStatus
      : "released";
  ensurePosDataCollections(db);
  db.posReservationStates = db.posReservationStates.map((state) => {
    const safeState = sanitizePosReservationStateRecord(state);
    if (!safeState) return state;
    let stateChanged = false;
    const reservations = safeState.reservations.map((reservation) => {
      if (isPosReservationReleased(reservation)) return reservation;
      if (!posReservationIncludesTable(reservation, tableId))
        return reservation;
      if (
        currentReservationTime &&
        posClockFromTimestamp(reservation.reservationAt) !==
          currentReservationTime
      ) {
        return reservation;
      }
      if (!shouldActivatePosReservation(reservation.reservationAt, nowMs))
        return reservation;
      stateChanged = true;
      releasedReservationIds.push(reservation.id);
      return {
        ...reservation,
        status: safeCompletionStatus,
        releasedAt: nowMs,
        ...(safeCompletionStatus === "arrived" ? { arrivedAt: nowMs } : {}),
        ...(safeCompletionStatus === "no_show" ? { noShowAt: nowMs } : {}),
        ...(safeCompletionStatus === "cancelled" ? { cancelledAt: nowMs } : {}),
        updatedAt: nowMs,
      };
    });
    if (!stateChanged) return safeState;
    return {
      ...safeState,
      version: safeState.version + 1,
      reservations,
    };
  });

  const groupsChanged =
    JSON.stringify(previousGroups) !== JSON.stringify(nextGroups);
  if (!groupsChanged && releasedReservationIds.length === 0) {
    return { changed: false, releasedReservationIds: [] };
  }
  if (groupsChanged) {
    db.integration.tableGroups = nextGroups;
    db.integration.lastWriteAt = nowIso();
  }
  return {
    changed: true,
    releasedReservationIds,
  };
}

function applyPosReservationStatusToAssignedTables(
  db,
  reservation,
  statusRaw,
  nowMs = Date.now(),
) {
  const status = String(statusRaw ?? "")
    .trim()
    .toLowerCase();
  if (
    status !== "arrived" &&
    status !== "no_show" &&
    status !== "released" &&
    status !== "cancelled"
  ) {
    return { changed: false, tableIds: [] };
  }
  const tableIds = posReservationAssignedTableIds(reservation);
  if (tableIds.length === 0) return { changed: false, tableIds: [] };

  if (status === "arrived") {
    activateDuePosReservationsOnLayout(db, db.posSettings, nowMs);
  }

  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const byId = new Map(
    settings.tables.map((table, index) => [
      String(table.id ?? "").trim(),
      { table, index },
    ]),
  );
  const touchedTableIds = [];
  const reservationTime = posClockFromTimestamp(reservation?.reservationAt);
  let changed = false;

  const tableLooksLikeReservation = (table) => {
    const tableReservationTime = String(table?.reservation?.time ?? "").trim();
    if (
      tableReservationTime &&
      reservationTime &&
      tableReservationTime === reservationTime
    )
      return true;
    return isSamePosReservationGuest(table, reservation);
  };

  if (status === "arrived") {
    const rootTableId = tableIds[0];
    const root = byId.get(rootTableId);
    if (root?.table && tableLooksLikeReservation(root.table)) {
      const nextRoot = sanitizePosTable(
        {
          ...root.table,
          status: "no_orders",
          guestName: reservation.customerName,
          customerPhone: reservation.customerPhone,
          covers: reservation.covers,
          reservation: null,
          seatedAt: normalizeSeatedAtMs(root.table.seatedAt) ?? nowMs,
          totalDue: 0,
          pendingBills: [],
          note: reservation.note || root.table.note || "",
        },
        root.index + 1,
      );
      if (
        JSON.stringify(settings.tables[root.index]) !== JSON.stringify(nextRoot)
      ) {
        settings.tables[root.index] = nextRoot;
        touchedTableIds.push(rootTableId);
        changed = true;
      }
    }
  } else {
    for (const tableId of tableIds) {
      const entry = byId.get(tableId);
      if (!entry?.table) continue;
      if (String(entry.table.status ?? "").trim() !== "reserved") continue;
      if (!tableLooksLikeReservation(entry.table)) continue;
      const nextTable = sanitizePosTable(
        {
          ...entry.table,
          status: "free",
          guestName: "",
          customerPhone: "",
          covers: 0,
          reservation: null,
          seatedAt: null,
          totalDue: 0,
          pendingBills: [],
          note: "",
          allergens: [],
          manualIntolerance: "",
          workLock: null,
        },
        entry.index + 1,
      );
      if (
        JSON.stringify(settings.tables[entry.index]) !==
        JSON.stringify(nextTable)
      ) {
        settings.tables[entry.index] = nextTable;
        touchedTableIds.push(tableId);
        changed = true;
      }
    }
  }

  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  const validIds = new Set(
    settings.tables
      .map((table) => String(table.id ?? "").trim())
      .filter(Boolean),
  );
  const previousGroups = sanitizeIntegrationTableGroups(
    db.integration.tableGroups,
    { validIds },
  );
  const targetSet = new Set(tableIds);
  const nextGroups =
    status === "arrived"
      ? previousGroups
      : previousGroups.filter((group) => {
          const groupIds = new Set([
            String(group.id ?? "").trim(),
            ...collectIntegrationTableGroupLeafIds(group),
          ]);
          return ![...targetSet].some((tableId) => groupIds.has(tableId));
        });
  if (JSON.stringify(previousGroups) !== JSON.stringify(nextGroups)) {
    db.integration.tableGroups = nextGroups;
    db.integration.lastWriteAt = nowIso();
    changed = true;
  }

  if (!changed) return { changed: false, tableIds: touchedTableIds };
  db.posSettings = sanitizePosSettings(settings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  clearIntegrationHotResponseCaches();
  return { changed: true, tableIds: touchedTableIds };
}


