function buildPosAreaSeedListFromTables(tables) {
  const usedAreaIds = new Set();
  const areasByKey = new Map();

  for (const table of Array.isArray(tables) ? tables : []) {
    const explicitRoomId = normalizePosRoomId(
      table?.roomId ?? table?.areaId ?? "",
    );
    const typeKey =
      String(table?.type ?? "")
        .trim()
        .toLowerCase() || "sala";
    const areaKey = explicitRoomId || `type:${typeKey}`;
    if (areasByKey.has(areaKey)) continue;
    const room = resolveIntegrationRoomFromTable(table, usedAreaIds);
    areasByKey.set(areaKey, {
      id: room.id,
      name: room.name,
      notes: "",
      menuIds: [],
      priceListIds: [],
      waiterUserIds: [],
      printerIds: [],
      cashPoints: [],
      workstations: [],
    });
  }

  return [...areasByKey.values()].sort((a, b) =>
    a.name.localeCompare(b.name, "it-IT"),
  );
}

function sanitizePosAreaMenu(entry, fallbackId = "menu_area") {
  if (!entry || typeof entry !== "object") return null;
  const name = String(entry.name ?? "")
    .trim()
    .slice(0, 48);
  if (!name) return null;
  return {
    id: normalizeConfigId(entry.id, fallbackId),
    name,
    categories: normalizeStringList(entry.categories, 32, 48),
  };
}

