function normalizeReferenceIdList(value, validIds = null, maxLength = 16) {
  const normalized = normalizeStringList(value, maxLength, 64).map((entry) =>
    normalizeConfigId(entry, ""),
  );
  if (!validIds) {
    return normalized.filter(Boolean);
  }
  return normalized.filter((entry) => entry && validIds.has(entry));
}

