function normalizePrintCharWidthMode(value) {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();
  if (["normal", "wide", "extra_wide"].includes(normalized)) {
    return normalized;
  }
  return "normal";
}

function sanitizePrintLogoDataUrl(value) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  if (!/^data:image\/(?:png|jpe?g|webp|gif);base64,[a-z0-9+/=]+$/i.test(raw)) {
    return "";
  }
  return raw.slice(0, 400_000);
}

function sanitizePrintEscposBase64(value) {
  const raw = String(value ?? "").replace(/\s+/g, "");
  if (!raw) return "";
  if (!/^[a-z0-9+/=]+$/i.test(raw)) {
    return "";
  }
  return raw.slice(0, 500_000);
}

function sanitizePrintExtraLines(value, maxLines = 8, maxLength = 64) {
  const source = Array.isArray(value)
    ? value
    : String(value ?? "").split(/\r?\n/);
  return source
    .map((entry) =>
      String(entry ?? "")
        .trim()
        .slice(0, maxLength),
    )
    .filter(Boolean)
    .slice(0, maxLines);
}

function sanitizePosPrintPreferences(entry) {
  const source = entry && typeof entry === "object" ? entry : {};
  const branding =
    source.branding && typeof source.branding === "object"
      ? source.branding
      : {};
  const preconto =
    source.preconto && typeof source.preconto === "object"
      ? source.preconto
      : {};
  const order =
    source.order && typeof source.order === "object" ? source.order : {};

  return {
    branding: {
      logoDataUrl: sanitizePrintLogoDataUrl(branding.logoDataUrl),
      logoEscposBase64: sanitizePrintEscposBase64(branding.logoEscposBase64),
      venueName: String(branding.venueName ?? "")
        .trim()
        .slice(0, 72),
      address: String(branding.address ?? "")
        .trim()
        .slice(0, 120),
      phone: String(branding.phone ?? "")
        .trim()
        .slice(0, 40),
      companyName: String(branding.companyName ?? "")
        .trim()
        .slice(0, 120),
      vatNumber: String(branding.vatNumber ?? "")
        .trim()
        .slice(0, 32),
    },
    preconto: {
      lineWidth: clampInt(
        preconto.lineWidth,
        32,
        48,
        DEFAULT_POS_SETTINGS.printPreferences.preconto.lineWidth,
      ),
      lineSpacing: clampInt(
        preconto.lineSpacing,
        0,
        48,
        DEFAULT_POS_SETTINGS.printPreferences.preconto.lineSpacing,
      ),
      showLogo: preconto.showLogo !== false,
      showVenueName: preconto.showVenueName !== false,
      showAddress: preconto.showAddress !== false,
      showPhone: preconto.showPhone !== false,
      showCompanyName: preconto.showCompanyName !== false,
      showVatNumber: preconto.showVatNumber !== false,
      showDocumentLabel: preconto.showDocumentLabel !== false,
    },
    order: {
      lineWidth: clampInt(
        order.lineWidth,
        24,
        48,
        DEFAULT_POS_SETTINGS.printPreferences.order.lineWidth,
      ),
      fontScalePercent: clampInt(
        order.fontScalePercent,
        80,
        220,
        DEFAULT_POS_SETTINGS.printPreferences.order.fontScalePercent,
      ),
      charWidthMode: normalizePrintCharWidthMode(order.charWidthMode),
      charSpacing: clampInt(
        order.charSpacing,
        0,
        8,
        DEFAULT_POS_SETTINGS.printPreferences.order.charSpacing,
      ),
      lineSpacing: clampInt(
        order.lineSpacing,
        0,
        24,
        DEFAULT_POS_SETTINGS.printPreferences.order.lineSpacing,
      ),
      bold: order.bold === true,
      italic: order.italic === true,
      underline: order.underline === true,
      extraTopLines: sanitizePrintExtraLines(order.extraTopLines),
      extraBottomLines: sanitizePrintExtraLines(order.extraBottomLines),
      showStation: order.showStation !== false,
      showOrderId: order.showOrderId !== false,
      showTable: order.showTable !== false,
      showWaiter: order.showWaiter !== false,
      showTime: order.showTime !== false,
      showVariants: order.showVariants !== false,
      showLineNotes: order.showLineNotes !== false,
      showOrderNotes: order.showOrderNotes !== false,
      showCommunications: order.showCommunications !== false,
      showTotal: order.showTotal !== false,
    },
  };
}

function sanitizeOrderWorkflowSettings(entry) {
  const source = entry && typeof entry === "object" ? entry : {};
  const deliveryConfirmationEnabled =
    source.deliveryConfirmationEnabled !== false;
  return {
    deliveryConfirmationEnabled,
    requireReadyForDelivery:
      deliveryConfirmationEnabled && source.requireReadyForDelivery !== false,
    requireDeliveredForPayment:
      deliveryConfirmationEnabled &&
      source.requireDeliveredForPayment !== false,
  };
}

const posSettingsSanitizeCache = new WeakMap();
const POS_SETTINGS_SANITIZE_CACHE_VARIANTS = 6;

function readCachedPosSettingsSanitize(settings, options = {}) {
  if (!settings || typeof settings !== "object" || options.cache === false) {
    return null;
  }
  const entries = posSettingsSanitizeCache.get(settings);
  if (!Array.isArray(entries)) return null;
  const menuItems = Array.isArray(options.menuItems) ? options.menuItems : null;
  const users = Array.isArray(options.users) ? options.users : null;
  return (
    entries.find(
      (entry) => entry.menuItems === menuItems && entry.users === users,
    )?.value ?? null
  );
}

function writeCachedPosSettingsSanitize(settings, options = {}, value) {
  if (!settings || typeof settings !== "object" || options.cache === false) {
    return value;
  }
  const menuItems = Array.isArray(options.menuItems) ? options.menuItems : null;
  const users = Array.isArray(options.users) ? options.users : null;
  const entries = posSettingsSanitizeCache.get(settings) ?? [];
  const existingIndex = entries.findIndex(
    (entry) => entry.menuItems === menuItems && entry.users === users,
  );
  const nextEntry = { menuItems, users, value };
  if (existingIndex >= 0) {
    entries.splice(existingIndex, 1);
  }
  entries.unshift(nextEntry);
  if (entries.length > POS_SETTINGS_SANITIZE_CACHE_VARIANTS) {
    entries.length = POS_SETTINGS_SANITIZE_CACHE_VARIANTS;
  }
  posSettingsSanitizeCache.set(settings, entries);
  return value;
}

function sanitizePosSettings(settings, options = {}) {
  const cached = readCachedPosSettingsSanitize(settings, options);
  if (cached) return cached;
  const sideBars = settings?.sideBars ?? {};
  const paymentMethods = sanitizePaymentMethods(settings?.paymentMethods);
  const paymentTerminals = sanitizePaymentTerminals(settings?.paymentTerminals);
  const smartCash = normalizeSmartCashSettings(settings?.smartCash, options);
  const tables = Array.isArray(settings?.tables) ? settings.tables : [];
  const locale = sanitizePosLocale(settings?.locale);
  const locales = sanitizePosLocales(settings?.locales, locale);
  const configuredActivities = (
    Array.isArray(settings?.activities) ? settings.activities : []
  )
    .map((entry, index) => sanitizePosActivity(entry, `activity_${index + 1}`))
    .filter((entry) => entry !== null);
  let activities = configuredActivities.length
    ? configuredActivities
    : [
        {
          id: "activity_default",
          name: "Operativa",
          type: "operational",
          status: "active",
          fiscalPolicy: "standard",
          fiscalDeviceIds: [],
          menuIds: [],
          priceListIds: [],
          printerIds: [],
          workstationIds: [],
          menuSchedules: [],
          priceListSchedules: [],
        },
      ];
  const pedanaSeededTables = ensureMinimumTablesForType(
    tables
      .filter((table) => table && typeof table === "object")
      .map((table, index) => sanitizePosTable(table, index + 1))
      .sort((a, b) => a.number - b.number),
    "Pedana",
    20,
  );
  const gazeboSeededTables = ensureMinimumTablesForType(
    pedanaSeededTables,
    "Gazebo",
    25,
  );
  const menuConfiguration = normalizeMenuConfiguration(
    settings,
    options.menuItems,
  );
  const areaMenus = menuConfiguration.areaMenus
    .map((entry, index) => sanitizePosAreaMenu(entry, `area_menu_${index + 1}`))
    .filter((entry) => entry !== null);
  const printers = (Array.isArray(settings?.printers) ? settings.printers : [])
    .map((entry, index) => sanitizePosPrinter(entry, `printer_${index + 1}`))
    .filter((entry) => entry !== null);
  const fiscalDevices = (
    Array.isArray(settings?.fiscalDevices) ? settings.fiscalDevices : []
  )
    .map((entry, index) =>
      sanitizePosFiscalDevice(entry, `fiscal_device_${index + 1}`),
    )
    .filter((entry) => entry !== null);
  const mobileDevices = sanitizeMobileDeviceSettings(settings?.mobileDevices);
  const automaticCash = sanitizeAutomaticCashSettings(settings?.automaticCash);
  const radioChannels = sanitizeRadioChannels(settings?.radioChannels);
  const radioPreferences = sanitizeRadioPreferences(
    settings?.radioPreferences,
    radioChannels,
  );
  const printerIds = new Set(printers.map((entry) => entry.id));
  const menuIds = new Set(areaMenus.map((entry) => entry.id));
  const rawWorkstations = Array.isArray(settings?.workstations)
    ? settings.workstations
    : [];
  let workstations = rawWorkstations
    .map((entry, index) => {
      const normalized = sanitizePosAreaWorkstation(
        entry,
        `workstation_${index + 1}`,
        {
          printerIds,
          menuIds,
        },
      );
      if (!normalized) return null;
      const roomIds = normalizeReferenceIdList(
        entry?.roomIds ?? entry?.rooms ?? entry?.areaIds,
        null,
        64,
      );
      return roomIds.length > 0 ? { ...normalized, roomIds } : normalized;
    })
    .filter((entry) => entry !== null);
  const userIds = new Set(
    (Array.isArray(options.users) ? options.users : [])
      .map((user) => String(user?.id ?? "").trim())
      .filter(Boolean),
  );
  const configuredAreaSources = [
    ...(Array.isArray(settings?.rooms) ? settings.rooms : []).map((room) => ({
      id: room?.id ?? room?.roomId,
      name: room?.name ?? room?.label ?? room?.roomName,
      notes: room?.notes ?? "",
      minimumTables:
        room?.minimumTables ?? room?.tableCount ?? room?.tablesCount,
      menuIds: room?.menuIds,
      priceListIds: room?.priceListIds,
      waiterUserIds: room?.waiterUserIds,
      printerIds: room?.printerIds,
      cashPoints: room?.cashPoints,
      workstations: room?.workstations,
    })),
    ...(Array.isArray(settings?.areas) ? settings.areas : []),
  ];
  const configuredAreas = configuredAreaSources
    .map((entry, index) =>
      sanitizePosArea(entry, `area_${index + 1}`, {
        printerIds,
        menuIds,
        userIds: userIds.size ? userIds : null,
      }),
    )
    .filter((entry) => entry !== null);
  const normalizedAreas = dedupeCanonicalPosAreas(
    ensureDefaultVirtualWaitingRoomArea(configuredAreas),
  );
  const normalizedTables = canonicalizeAndDedupePosTables(
    ensureMinimumTablesForConfiguredAreas(gazeboSeededTables, normalizedAreas),
    normalizedAreas,
  ).sort((a, b) => {
    const leftRoom = String(a.roomId || a.type || "").localeCompare(
      String(b.roomId || b.type || ""),
      "it-IT",
    );
    if (leftRoom !== 0) return leftRoom;
    return a.number - b.number;
  });
  const inferredAreas = buildPosAreaSeedListFromTables(normalizedTables);
  const areasById = new Map(normalizedAreas.map((entry) => [entry.id, entry]));
  inferredAreas.forEach((entry, index) => {
    if (areasById.has(entry.id)) return;
    const normalized = sanitizePosArea(entry, `area_seed_${index + 1}`, {
      printerIds,
      menuIds,
      userIds: userIds.size ? userIds : null,
    });
    if (normalized) {
      areasById.set(normalized.id, normalized);
    }
  });
  const areas = [...areasById.values()].sort((a, b) =>
    a.name.localeCompare(b.name, "it-IT"),
  );
  const activityIds = new Set(activities.map((entry) => entry.id));
  const roomIds = new Set(areas.map((entry) => entry.id));
  const configuredActivityRoomBindings = (
    Array.isArray(settings?.activityRoomBindings)
      ? settings.activityRoomBindings
      : []
  )
    .map((entry, index) =>
      sanitizePosActivityRoomBinding(entry, `activity_room_${index + 1}`, {
        activityIds,
        roomIds,
      }),
    )
    .filter((entry) => entry !== null);
  const activityRoomBindings =
    configuredActivityRoomBindings.length > 0
      ? configuredActivityRoomBindings
      : buildDefaultPosActivityRoomBindings(activities, areas);

  const sanitized = {
    sideBars: {
      leftMode: normalizeSideBarMode(sideBars.leftMode, "fixed"),
      rightMode: normalizeSideBarMode(sideBars.rightMode, "collapse"),
    },
    demoMode: settings?.demoMode === true,
    locale,
    locales,
    activities,
    activityRoomBindings,
    paymentMethods,
    paymentTerminals,
    smartCash,
    tables: normalizedTables,
    menus: menuConfiguration.menus,
    areaMenus,
    priceLists: menuConfiguration.priceLists,
    priceListSchedules: menuConfiguration.priceListSchedules,
    menuSchedules: menuConfiguration.menuSchedules,
    printers,
    fiscalDevices,
    mobileDevices,
    automaticCash,
    radioChannels,
    radioPreferences,
    workstations,
    areas,
    orderWorkflow: sanitizeOrderWorkflowSettings(settings?.orderWorkflow),
    printPreferences: sanitizePosPrintPreferences(
      settings?.printPreferences ?? DEFAULT_POS_SETTINGS.printPreferences,
    ),
  };
  return writeCachedPosSettingsSanitize(settings, options, sanitized);
}

function isValidDbShape(data) {
  return (
    data &&
    typeof data === "object" &&
    Array.isArray(data.users) &&
    Array.isArray(data.sessions) &&
    data.meta &&
    typeof data.meta === "object"
  );
}

function ensureArrayProperty(data, key) {
  if (!Array.isArray(data[key])) {
    data[key] = [];
    return true;
  }
  return false;
}

function normalizeTemplate(template, fallbackId) {
  const now = nowIso();
  const startTime =
    timeToMinutes(template.startTime) === null ? "09:00" : template.startTime;
  const endTime =
    timeToMinutes(template.endTime) === null ? "17:00" : template.endTime;
  return {
    id: String(template.id ?? fallbackId),
    name:
      String(template.name ?? "Sessione Vendita").trim() || "Sessione Vendita",
    startTime,
    endTime,
    enabled: template.enabled !== false,
    createdByUserId: String(template.createdByUserId ?? "system"),
    createdAt: String(template.createdAt ?? now),
    updatedAt: String(template.updatedAt ?? now),
  };
}

