const relationalRuntime = createRelationalRuntime({
  env: process.env,
  defaultDbPath: DEFAULT_RELATIONAL_DB_PATH,
  logger: console,
  nowIso,
  runtimeMetrics,
}); const postgresqlRuntime = createPostgresqlRuntime({ env: process.env, logger: console, runtimeMetrics });
async function syncMonitorResetExternalStores(appState) {
  if (!["shadow", "primary"].includes(relationalRuntime.mode)) {
    return {
      relational: {
        enabled: false,
        mode: relationalRuntime.mode,
      },
    };
  }
  await relationalRuntime.initialize();
  if (!relationalRuntime?.db) {
    throw new HttpError(503, "DB relazionale non disponibile per il reset monitor.", {
      code: "MONITOR_RESET_RELATIONAL_UNAVAILABLE",
    });
  }
  const db = relationalRuntime.db;
  return {
    relational: {
      enabled: true,
      mode: relationalRuntime.mode,
      orders: syncOrdersFromAppState(db, appState, { nowIso }),
      payments: syncPaymentsFromAppState(db, appState, { nowIso }),
      tablesBills: syncTablesBillsFromAppState(db, appState, { nowIso }),
      reservations: syncReservationsFromAppState(db, appState, { nowIso }),
      saleSessions: syncSaleSessionsFromAppState(db, appState, { nowIso }),
      auditEvents: syncAuditEventsFromAppState(db, appState, { nowIso }),
    },
  };
}

