function resolveFiscalCommandPaymentTransactionId(payload = {}) {
  const candidates = [
    payload.paymentTransactionId,
    payload.paymentTxId,
    payload.transactionId,
    payload.paymentId,
    payload.movementId,
    payload.recordId,
  ];
  for (const candidate of candidates) {
    const normalized = String(candidate ?? "").trim();
    if (normalized) return normalized;
  }
  return null;
}

function buildRelationalFiscalCommandPayload({
  command,
  payload,
  fiscalResult,
  middleware,
  paymentTransactionId,
  user,
  recordedAt,
}) {
  return {
    command,
    fiscalStatus: fiscalResult?.fiscalStatus ?? null,
    fiscalProvider: fiscalResult?.fiscalProvider ?? null,
    fiscalProviderRef: middleware?.responseCode ?? null,
    responseCode: middleware?.responseCode ?? null,
    responseMessage: middleware?.responseMessage ?? null,
    requiresFiscalRetry: fiscalResult?.requiresFiscalRetry === true,
    paymentTransactionId,
    requestedPaymentTransactionId: resolveFiscalCommandPaymentTransactionId(payload),
    createdByUserId: user?.id ?? null,
    createdByUsername: user?.username ?? null,
    recordedAt,
    technicalCommand: true,
  };
}

function normalizeFiscalOutboxStatusFromReceipt(receipt = {}) {
  const statusText = String(
    receipt.fiscalStatus ??
      receipt.status ??
      receipt.payload?.fiscalStatus ??
      receipt.payload?.responseCode ??
      "",
  )
    .trim()
    .toUpperCase();
  const requiresRetry =
    receipt.requiresFiscalRetry === true ||
    receipt.payload?.requiresFiscalRetry === true;
  if (statusText.includes("ISSUED") || statusText === "OK" || statusText.includes("_OK")) {
    return "issued";
  }
  if (statusText.includes("PROCESS")) return "processing";
  if (statusText.includes("QUEUE") || statusText.includes("PENDING") || statusText.includes("REQUEST")) {
    return "requested";
  }
  if (requiresRetry) return "retrying";
  if (statusText.includes("MANUAL")) return "manual_required";
  if (statusText.includes("FAIL") || statusText.includes("ERROR") || statusText.includes("EXPIRED")) {
    return "failed";
  }
  return "requested";
}

function collectRelationalFiscalReceiptsForOutbox(domainResult = {}, fallbackReceipts = []) {
  const receipts = [
    ...(Array.isArray(domainResult.receipts) ? domainResult.receipts : []),
    domainResult.receipt,
    ...(Array.isArray(fallbackReceipts) ? fallbackReceipts : []),
  ].filter(Boolean);
  const seen = new Set();
  return receipts.filter((receipt) => {
    const id = String(receipt?.id ?? "").trim();
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
}

function enqueueFiscalOutboxRows(connection, {
  domainResult,
  receipts,
  source,
  occurredAt,
  paymentContainer,
  idempotencyKey,
} = {}) {
  if (!FISCAL_OUTBOX_ENABLED) return [];
  const outboxRepo = new FiscalOutboxRepository(connection, { nowIso });
  const safeOccurredAt = String(occurredAt ?? nowIso());
  return collectRelationalFiscalReceiptsForOutbox(domainResult, receipts).map((receipt) => {
    const paymentTransactionId =
      String(receipt.paymentTransactionId ?? receipt.paymentId ?? "").trim() ||
      String(domainResult?.transaction?.id ?? "").trim() ||
      null;
    const status = normalizeFiscalOutboxStatusFromReceipt(receipt);
    return outboxRepo.enqueue({
      fiscalId: `fiscal_out_${receipt.id}`,
      storeId: String(receipt.storeId ?? paymentContainer?.storeId ?? "").trim() || null,
      aggregateType: "fiscal_receipt",
      aggregateId: receipt.id,
      paymentId: paymentTransactionId,
      status,
      issuedAt: status === "issued" ? receipt.issuedAt ?? receipt.createdAt ?? safeOccurredAt : null,
      createdAt: safeOccurredAt,
      updatedAt: safeOccurredAt,
      payload: {
        source: String(source ?? "payment").trim() || "payment",
        receiptId: receipt.id,
        paymentTransactionId,
        paymentContainerId: paymentContainer?.id ?? null,
        idempotencyKey: idempotencyKey ?? null,
        fiscalProvider: receipt.fiscalProvider ?? null,
        fiscalStatus: receipt.fiscalStatus ?? receipt.status ?? null,
        fiscalDocumentNumber: receipt.fiscalDocumentNumber ?? receipt.fiscalProviderRef ?? null,
        receipt,
      },
    });
  });
}

async function ensureRelationalFiscalCommandWritePrimary() {
  await relationalRuntime.initialize();
  if (!relationalRuntime?.db) {
    throw new HttpError(503, "DB relazionale fiscale non disponibile.", {
      code: "RELATIONAL_FISCAL_DB_UNAVAILABLE",
    });
  }
  return relationalRuntime.db;
}

async function recordRelationalFiscalCommandResult({
  command,
  payload,
  fiscalResult,
  middleware,
  user,
  recordedAt,
} = {}) {
  const relationalDb = await ensureRelationalFiscalCommandWritePrimary();

  const requestedPaymentTransactionId = resolveFiscalCommandPaymentTransactionId(payload);
  const receiptId = `fiscal_cmd_${randomUUID().replace(/-/g, "")}`;
  const occurredAt = String(recordedAt ?? nowIso());

  return withTransactionalOutboxEvent(relationalDb, {
    nowIso,
    paymentWrite(connection) {
      const paymentsRepo = new PaymentsRelationalRepository(connection);
      const existingTransaction = requestedPaymentTransactionId
        ? paymentsRepo.getTransactionById(requestedPaymentTransactionId)
        : null;
      const linkedPaymentTransactionId = existingTransaction?.id ?? null;
      const commandPayload = buildRelationalFiscalCommandPayload({
        command,
        payload,
        fiscalResult,
        middleware,
        paymentTransactionId: linkedPaymentTransactionId,
        user,
        recordedAt: occurredAt,
      });

      let updatedTransaction = existingTransaction;
      if (existingTransaction?.id) {
        const currentRaw =
          existingTransaction?.rawJson &&
          typeof existingTransaction.rawJson === "object"
            ? existingTransaction.rawJson
            : { ...existingTransaction };
        updatedTransaction = paymentsRepo.updateTransactionWithRevision(
          existingTransaction.id,
          existingTransaction.revision,
          {
            updatedAt: occurredAt,
            rawJson: {
              ...currentRaw,
              currentRevision: existingTransaction.revision + 1,
              revision: existingTransaction.revision + 1,
              fiscalCommandRetry: commandPayload,
            },
          },
        );
        if (!updatedTransaction) {
          throw new HttpError(409, "Conflitto revisione transazione fiscale.", {
            code: "PAYMENT_TRANSACTION_REVISION_CONFLICT",
            details: { paymentTransactionId: existingTransaction.id },
          });
        }
      }

      const receipt = paymentsRepo.createFiscalReceipt({
        id: receiptId,
        paymentTransactionId: linkedPaymentTransactionId,
        attemptScope: `command:${String(command ?? "fiscal").trim() || "fiscal"}`,
        fiscalProvider: commandPayload.fiscalProvider,
        fiscalStatus: commandPayload.fiscalStatus,
        fiscalDocumentNumber: commandPayload.fiscalProviderRef,
        issuedAt: occurredAt,
        payloadJson: commandPayload,
        rawJson: commandPayload,
      });
      if (!receipt) {
        throw new HttpError(500, "Registrazione fiscale relazionale non riuscita.", {
          code: "RELATIONAL_FISCAL_RECEIPT_WRITE_FAILED",
        });
      }
      const fiscalOutbox = enqueueFiscalOutboxRows(connection, {
        domainResult: { receipt, transaction: updatedTransaction },
        source: "fiscal.command",
        occurredAt,
        idempotencyKey: payload?.idempotencyKey ?? payload?.requestId ?? null,
      });
      return {
        receipt,
        fiscalOutbox,
        transaction: updatedTransaction,
        paymentTransactionId: linkedPaymentTransactionId,
        requestedPaymentTransactionId,
        commandPayload,
      };
    },
    outboxEvent(domainResult) {
      return {
        eventType: "payment.status",
        aggregateType: "fiscal_receipt",
        aggregateId: domainResult.receipt.id,
        scope: "fiscal.command",
        occurredAt,
        payload: {
          type: "fiscal.command",
          receiptId: domainResult.receipt.id,
          command,
          fiscalStatus: domainResult.commandPayload.fiscalStatus,
          fiscalProvider: domainResult.commandPayload.fiscalProvider,
          fiscalProviderRef: domainResult.commandPayload.fiscalProviderRef,
          paymentTransactionId: domainResult.paymentTransactionId,
          requestedPaymentTransactionId: domainResult.requestedPaymentTransactionId,
          requiresFiscalRetry: domainResult.commandPayload.requiresFiscalRetry,
        },
      };
    },
  });
}

