async function recordRelationalTicketPayment({
  paymentContainer,
  paymentPart,
  paymentTx,
  paymentRecord,
  receipt,
  posFiscalResult,
  idempotencyKey,
  realtimePayload,
  occurredAt,
} = {}) {
  const relationalDb = await ensureRelationalPaymentsTicketWritePrimary();
  const safeOccurredAt = String(occurredAt ?? nowIso());
  return withTransactionalOutboxEvent(relationalDb, {
    nowIso,
    paymentWrite(connection) {
      const paymentsRepo = new PaymentsRelationalRepository(connection);
      const result = paymentsRepo.createTicketPaymentFromAppState({
        paymentContainer,
        paymentPart,
        paymentTransaction: paymentTx,
        paymentRecord,
        fiscalReceipts: [
          receipt,
          posFiscalResult?.receipt ?? null,
        ].filter(Boolean),
      });
      if (!result?.ok) {
        throw new HttpError(409, "Pagamento ticket relazionale non registrato.", {
          code: "RELATIONAL_PAYMENT_TICKET_WRITE_FAILED",
          details: {
            reason: result?.reason ?? "unknown",
            idempotencyKey: idempotencyKey ?? null,
          },
        });
      }
      const fiscalOutbox = result.replayed
        ? []
        : enqueueFiscalOutboxRows(connection, {
            domainResult: result,
            receipts: [receipt, posFiscalResult?.receipt].filter(Boolean),
            source: "payments.ticket",
            occurredAt: safeOccurredAt,
            paymentContainer,
            idempotencyKey,
          });
      return { ...result, fiscalOutbox };
    },
    outboxEvent(domainResult) {
      const payload =
        realtimePayload && typeof realtimePayload === "object"
          ? realtimePayload
          : buildIntegrationNotificationStreamPayload("payment_status_changed", {
              paymentId: paymentRecord?.id ?? paymentContainer?.id ?? null,
              paymentContainerId: paymentContainer?.id ?? null,
              paymentStatus: "COMPLETED",
              source: "ticket_payment",
            });
      const eventType = resolveIntegrationRealtimeEventType(payload.reason);
      return {
        eventType,
        aggregateType: resolveRealtimeOutboxAggregateType(eventType),
        aggregateId: resolveRealtimeOutboxAggregateId(payload, eventType),
        scope: resolveRealtimeOutboxScope(payload),
        occurredAt: safeOccurredAt,
        payload: {
          ...payload,
          detail: {
            ...(payload.detail && typeof payload.detail === "object"
              ? payload.detail
              : {}),
            relationalWritePrimary: true,
            relationalReplay: domainResult.replayed === true,
          },
        },
      };
    },
  });
}

