const mqttRealtimeBridgeConfig = normalizeMqttBridgeConfig(process.env);
const mqttRealtimeBridge = createMqttRealtimeBridge({
  config: mqttRealtimeBridgeConfig,
  logger: console,
  metrics: runtimeMetrics,
});
function canPublishRealtimeOutboxEvent() {
  return (
    integrationNotificationStreamRuntime.clientCount() > 0 ||
    (mqttRealtimeBridge.enabled && mqttRealtimeBridge.isReady())
  );
}
function publishRealtimeOutboxEvent(payload, event) {
  const sseDelivered = publishIntegrationNotificationStreamPayload(payload, event);
  if (!mqttRealtimeBridge.enabled) return sseDelivered;
  const envelope = event
    ? toRealtimeEventEnvelope(event)
    : {
        type: resolveIntegrationRealtimeEventType(payload?.reason),
        payload: payload && typeof payload === "object" ? payload : {},
        createdAt: nowIso(),
      };
  const mqttResult = mqttRealtimeBridge.publishEvent(envelope, event);
  if (!mqttResult.ok) return false;
  return sseDelivered || mqttResult.published === true || mqttResult.skipped === true;
}
const realtimeEventOutboxCoordinator = createEventOutboxCoordinator({
  enabled: REALTIME_BACKBONE_CONFIG.eventOutboxEnabled,
  relationalRuntime,
  nowIso,
  logger: console,
  metrics: runtimeMetrics,
  canPublish: canPublishRealtimeOutboxEvent,
  publish: publishRealtimeOutboxEvent,
  afterEnqueue: RELATIONAL_AGGREGATE_LAST_EVENT_BINDING
    ? (event, db) => bindAggregateLastEventId(db, event, { metrics: runtimeMetrics })
    : undefined,
  retentionHours: EVENT_OUTBOX_RETENTION_HOURS,
  retentionIntervalMs: EVENT_OUTBOX_RETENTION_INTERVAL_MS,
  backlogMetricsIntervalMs: EVENT_OUTBOX_BACKLOG_METRICS_INTERVAL_MS,
});

// Step 5 — Event Outbox autoritativa: emissione durabile degli eventi dei piloti.
// Best-effort: l'append all'outbox e' atomico ma non deve mai far fallire la
// richiesta business. Gated su EVENT_OUTBOX_ENABLED. Con la command inbox in
// enforce_pilot i retry fanno short-circuit prima dell'handler, quindi ogni
// evento e' emesso esattamente una volta.
function enqueueRealtimePilotEvent(event = {}) {
  if (!REALTIME_BACKBONE_CONFIG.eventOutboxEnabled) return null;
  const startedAt = Date.now();
  try {
    const queued = realtimeEventOutboxCoordinator.enqueue(event);
    runtimeMetrics.recordOperation("eventOutbox", "insert", Date.now() - startedAt);
    runtimeMetrics.incrementCounter("realtimePilotEventsEmitted");
    return queued;
  } catch (error) {
    runtimeMetrics.incrementCounter("realtimePilotEventsFailed");
    console.warn(
      `[event-outbox] emissione evento pilota '${event?.eventType ?? "?"}' fallita: ${error instanceof Error ? error.message : String(error)}`,
    );
    return null;
  }
}

// Step 6 — Print Spool Async Durable: coda relazionale autoritativa + circuit
// breaker + eventi print.status via outbox.
const printerCircuitBreaker = createPrinterCircuitBreaker({
  enabled: PRINT_CIRCUIT_BREAKER_ENABLED,
  failureThreshold: PRINT_CIRCUIT_BREAKER_THRESHOLD,
  cooldownMs: PRINT_CIRCUIT_BREAKER_COOLDOWN_MS,
  metrics: runtimeMetrics,
});
let printSpoolRepositorySingleton = null;
function getPrintSpoolRepository() {
  if (!PRINT_SPOOL_SQL_PRIMARY || !["shadow", "primary"].includes(relationalRuntime.mode)) return null;
  const relationalDb = relationalRuntime.db;
  if (!relationalDb) return null;
  if (!printSpoolRepositorySingleton || printSpoolRepositorySingleton.db !== relationalDb) {
    printSpoolRepositorySingleton = new PrintSpoolRepository(relationalDb, { nowIso });
  }
  return printSpoolRepositorySingleton;
}

// Emette print.status via l'event outbox durabile (riuso Step 5). Best-effort.
function emitPrintStatusEvent(job, status) {
  if (!job || typeof job !== "object") return;
  const jobId = String(job.id ?? "").trim() || null;
  const orderId = String(job.orderId ?? "").trim() || null;
  enqueueRealtimePilotEvent({
    eventType: "print.status", aggregateType: "print", aggregateId: jobId, scope: orderId,
    payload: {
      jobId, orderId, printerId: String(job.printerId ?? "").trim() || null,
      status: String(status ?? job.status ?? "").trim(),
      attemptCount: Math.max(0, Math.trunc(Number(job.attempts ?? job.attemptCount) || 0)),
    },
  });
}

function emitPrintRequestedEvent(job) {
  if (!job || typeof job !== "object") return;
  const jobId = String(job.id ?? "").trim() || null;
  const orderId = String(job.orderId ?? "").trim() || null;
  enqueueRealtimePilotEvent({
    eventType: "print.requested",
    aggregateType: "print",
    aggregateId: jobId,
    scope: orderId,
    payload: {
      jobId,
      orderId,
      kind: String(job.kind ?? "").trim() || null,
      printerId: String(job.printerId ?? "").trim() || null,
    },
  });
}

function warnPrintSpool(action, id, error) {
  console.warn(`[print-spool] mirror ${action} fallito per '${id ?? "?"}': ${error instanceof Error ? error.message : String(error)}`);
}

// Aggiorna i gauge di profondità/lag della coda relazionale di stampa.
function refreshPrintSpoolQueueGauges() {
  const repo = getPrintSpoolRepository();
  if (!repo) return;
  try {
    const summary = repo.countSummary();
    runtimeMetrics.setGauge("printSpoolQueueDepth", summary.pending);
    const oldestMs = Date.parse(String(summary.oldestPendingAt ?? ""));
    const nowMs = Date.parse(nowIso());
    runtimeMetrics.setGauge("printSpoolQueueLagMs",
      Number.isFinite(oldestMs) && Number.isFinite(nowMs) && summary.pending > 0 ? Math.max(0, nowMs - oldestMs) : 0);
  } catch { /* best-effort */ }
}

// Inserisce il job nella coda relazionale autoritativa (best-effort: non deve
// mai far fallire l'accettazione della stampa).
function mirrorPrintSpoolJobEnqueue(job, startedAtMs) {
  const repo = getPrintSpoolRepository();
  if (!repo || !job) return;
  try {
    repo.enqueue({
      id: job.id, status: job.status, kind: job.kind, orderId: job.orderId,
      printerId: job.printerId, printerHost: job.printerHost, printerPort: job.printerPort,
      errorMessage: job.errorMessage, requestedAt: job.requestedAt, payload: job,
    });
    if (Number.isFinite(startedAtMs)) runtimeMetrics.recordOperation("printSpool", "accept", Date.now() - startedAtMs);
    emitPrintStatusEvent(job, job.status);
    refreshPrintSpoolQueueGauges();
  } catch (error) { warnPrintSpool("enqueue", job?.id, error); }
}

// Mirror del claim del worker legacy nella coda relazionale + print.status.
function mirrorPrintSpoolClaim(job, claimStartedAt) {
  if (!job) return;
  try {
    if (PRINT_SPOOL_SQL_PRIMARY) {
      if (PRINT_SPOOL_INTERMEDIATE_STATUS_EVENTS) mirrorLegacyPrintSpoolJobBestEffort(job, "claim");
    } else {
      getPrintSpoolRepository()?.markClaimed(job.id, { workerId: process.env.BACKEND_PROCESS_ROLE || "worker", leaseMs: PRINT_SPOOL_CLAIM_LEASE_MS });
      runtimeMetrics.incrementCounter("printSpoolClaimed");
    }
    if (Number.isFinite(claimStartedAt)) runtimeMetrics.recordOperation("printSpool", "claim", Date.now() - claimStartedAt);
    if (PRINT_SPOOL_INTERMEDIATE_STATUS_EVENTS) emitPrintStatusEvent(job, "claimed"); else runtimeMetrics.incrementCounter("printSpoolIntermediateEventsSkipped");
  } catch (error) { warnPrintSpool("claim", job?.id, error); }
}

// Mirror dell'esito del worker + circuit breaker + print.status.
// `completedJob` ha status: printed | queued(retry) | failed.
function mirrorPrintSpoolCompletion(completedJob) {
  if (!completedJob) return;
  const repo = getPrintSpoolRepository();
  const printerId = String(completedJob.printerId ?? "").trim();
  const status = String(completedJob.status ?? "").trim();
  try {
    if (status === "printed") {
      printerCircuitBreaker.recordSuccess(printerId);
      if (!PRINT_SPOOL_SQL_PRIMARY) repo?.markConfirmed(completedJob.id);
      runtimeMetrics.incrementCounter("printSpoolConfirmed");
      emitPrintStatusEvent(completedJob, "confirmed");
      return;
    }
    const retryable = status === "queued" && Boolean(completedJob.nextRetryAt);
    printerCircuitBreaker.recordFailure(printerId);
    runtimeMetrics.incrementCounter("printerTimeouts");
    runtimeMetrics.incrementCounter("printSpoolFailed");
    if (!PRINT_SPOOL_SQL_PRIMARY) {
      repo?.markFailed(completedJob.id, { retryable, retryDelayMs: PRINT_SPOOL_RETRY_DELAY_MS, errorMessage: completedJob.errorMessage });
    }
    emitPrintStatusEvent(completedJob, retryable ? "failed_retryable" : "failed_final");
  } catch (error) { warnPrintSpool("completion", completedJob?.id, error); }
}
