function normalizeSplitDomainHints(options = {}) {
  const rawHints =
    options && typeof options === "object"
      ? (options.splitDomains ?? options.domains ?? [])
      : [];
  if (!Array.isArray(rawHints) || rawHints.length === 0) return null;
  const hints = new Set(
    rawHints
      .map((entry) => String(entry ?? "").trim())
      .filter(Boolean),
  );
  return hints.size > 0 ? hints : null;
}
