async function syncAppStateSplitDomains(appState, options = {}) {
  const splitDomainHints = normalizeSplitDomainHints(options);
  const sessionsSyncOptions = resolveSessionsSplitSyncOptions(options);
  const automaticCashGuard = await automaticCashSplitGuard.beforeDomainSync({ selectedDomains: splitDomainHints, requestRoute: requestMetricsStorage.getStore()?.route });
  if (shouldSyncSplitDomain(splitDomainHints, "sessions")) {
    await mysqlSessionsSplitRepository.syncFromAppState(
      appState,
      sessionsSyncOptions,
    );
  }
  if (shouldSyncSplitDomain(splitDomainHints, "auditEvents")) {
    await mysqlAuditEventsSplitRepository.syncFromAppState(appState);
  }
  if (shouldSyncSplitDomain(splitDomainHints, "tableLocks")) {
    await mysqlTableLocksRepository.syncFromAppState(appState);
  }
  const appStateWithoutMysqlTableLocks =
    await mysqlTableLocksRepository.prepareAppStateForPersistenceComparison(
      appState,
    );
  await mysqlAppStateDomainsSplitRepository.syncFromAppState(
    appStateWithoutMysqlTableLocks,
    {
      ...(splitDomainHints ? { domains: [...splitDomainHints] } : {}),
      ...automaticCashGuard.syncOptions,
    },
  );
  await automaticCashSplitGuard.afterDomainSync({ guard: automaticCashGuard, states: [appState, appStateWithoutMysqlTableLocks] });
  if (shouldSyncSplitDomain(splitDomainHints, "auditEvents")) {
    await auditEventsSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
    );
  }
  if (shouldSyncSplitDomain(splitDomainHints, "printSpoolJobs")) {
    await printSpoolJobsSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
    );
  }
  const shouldSyncDeviceStatusSessions = shouldSyncSplitDomain(
    splitDomainHints,
    "sessions",
  );
  const shouldSyncDeviceStatusIntegration = shouldSyncSplitDomain(
    splitDomainHints,
    "integration",
  );
  if (shouldSyncDeviceStatusSessions || shouldSyncDeviceStatusIntegration) {
    await deviceStatusSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
      {
        sessionsSync: shouldSyncDeviceStatusSessions
          ? sessionsSyncOptions
          : { skip: true },
      },
    );
  }
  if (shouldSyncSplitDomain(splitDomainHints, "tableLocks")) {
    await tableLocksSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
    );
  }
  if (shouldSyncSplitDomain(splitDomainHints, "posSettings")) {
    await tableStateSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
    );
  }
  if (shouldSyncSplitDomain(splitDomainHints, "integration")) {
    await ordersSplitRepository.syncFromAppState(appStateWithoutMysqlTableLocks);
  }
  if (
    shouldSyncSplitDomain(
      splitDomainHints,
      "payments",
      "paymentContainers",
      "paymentParts",
      "paymentTransactions",
      "fiscalReceipts",
      "fiscalEvents",
    )
  ) {
    await paymentsFiscalSplitRepository.syncFromAppState(
      appStateWithoutMysqlTableLocks,
    );
  }
}
