function buildFullyExternalizedAppStateDomains() {
  const domains = new Set();
  if (mysqlSessionsSplitRepository.enabled) domains.add("sessions");
  if (mysqlAuditEventsSplitRepository.enabled) domains.add("auditEvents");
  if (mysqlAppStateDomainsSplitRepository.enabled) {
    MYSQL_APP_STATE_DOMAINS.forEach((domain) => domains.add(domain));
  }
  if (auditEventsSplitRepository.externalized) domains.add("auditEvents");
  if (printSpoolJobsSplitRepository.externalized) domains.add("printSpoolJobs");
  if (tableLocksSplitRepository.externalized) domains.add("tableLocks");
  if (paymentsFiscalSplitRepository.externalized) {
    [
      "payments",
      "paymentContainers",
      "paymentParts",
      "paymentTransactions",
      "paymentProviderTransactions",
      "cashTxDenoms",
      "fiscalReceipts",
      "fiscalEvents",
      "smartNonFiscal",
    ].forEach((domain) => domains.add(domain));
  }
  return [...domains];
}

const FULLY_EXTERNALIZED_APP_STATE_DOMAINS =
  buildFullyExternalizedAppStateDomains();

function buildDefaultDirtyTrackingSplitDomains(fullyExternalizedDomains) {
  if (!APP_STATE_DIRTY_TRACKING_WRITE_FASTPATH) return [];
  const externalized = new Set(fullyExternalizedDomains);
  const initialDomains = Object.keys(buildInitialAppState()).filter(
    (domain) => domain !== "meta",
  );
  const missingInitialDomains = initialDomains.filter(
    (domain) => !externalized.has(domain),
  );
  if (missingInitialDomains.length > 0) {
    console.warn(
      `[app-state] Dirty tracking default disabilitato: domini non esternalizzati ${missingInitialDomains.join(", ")}`,
    );
    return [];
  }
  return [...externalized].filter((domain) => domain !== "meta");
}

const DEFAULT_DIRTY_TRACKING_SPLIT_DOMAINS =
  buildDefaultDirtyTrackingSplitDomains(FULLY_EXTERNALIZED_APP_STATE_DOMAINS);

function hasExplicitDirtyTrackingDomains(options = {}) {
  const splitDomains = Array.isArray(options.splitDomains)
    ? options.splitDomains
    : [];
  const domains = Array.isArray(options.domains) ? options.domains : [];
  return splitDomains.length > 0 || domains.length > 0;
}

function withDefaultDirtyTrackingSplitDomains(options = {}) {
  const currentOptions =
    options && typeof options === "object" && !Array.isArray(options)
      ? options
      : {};
  if (!APP_STATE_DIRTY_TRACKING_WRITE_FASTPATH) return currentOptions;
  if (DEFAULT_DIRTY_TRACKING_SPLIT_DOMAINS.length === 0) {
    return currentOptions;
  }
  if (hasExplicitDirtyTrackingDomains(currentOptions)) return currentOptions;
  return {
    ...currentOptions,
    splitDomains: DEFAULT_DIRTY_TRACKING_SPLIT_DOMAINS,
  };
}

const RELATIONAL_SHADOW_DIRTY_DOMAIN_FILTER =
  ORDERS_ANY_ASYNC_ACK || RELATIONAL_ORDERS_ANY_WRITE_PRIMARY;

function buildRelationalShadowAfterWriteContext(writeContext = {}) {
  return {
    dirtyDomainFilter: RELATIONAL_SHADOW_DIRTY_DOMAIN_FILTER,
    dirtyDomains: RELATIONAL_SHADOW_DIRTY_DOMAIN_FILTER
      ? writeContext.dirtyDomains
      : [],
    skipDomains: [
      ...(RELATIONAL_ORDERS_ANY_WRITE_PRIMARY ? ["orders"] : []),
      ...(ORDERS_ANY_ASYNC_ACK ? ["auditEvents"] : []),
    ],
  };
}

function mergeRequestStringList(current = [], next = []) {
  return [
    ...new Set(
      [
        ...(Array.isArray(current) ? current : []),
        ...(Array.isArray(next) ? next : []),
      ]
        .map((entry) => String(entry ?? "").trim())
        .filter(Boolean),
    ),
  ].sort();
}

function markRequestDirtyTrackingEvent(event = {}) {
  const context = requestMetricsStorage.getStore();
  if (!context) return;
  context.dirtyTrackingMode = String(event.mode ?? APP_STATE_DIRTY_TRACKING_MODE);
  context.detectedDirtyDomains = mergeRequestStringList(
    context.detectedDirtyDomains,
    event.changedDomains,
  );
  context.undeclaredDirtyDomains = mergeRequestStringList(
    context.undeclaredDirtyDomains,
    event.missingDeclaredDomains,
  );
  context.overDeclaredDirtyDomains = mergeRequestStringList(
    context.overDeclaredDirtyDomains,
    event.overDeclaredDomains,
  );
  if (event.fullStateFallbackUsed === true) {
    context.fullStateFallbackUsed = true;
  }
  if (Number.isFinite(Number(event.comparableBytes))) {
    context.serializedBytes = Math.max(
      Number(context.serializedBytes) || 0,
      Math.trunc(Number(event.comparableBytes) || 0),
    );
  }
}

function markRequestMysqlWriteRetry(event = {}) {
  const context = requestMetricsStorage.getStore();
  if (!context) return;
  context.mysqlRetryCount = Math.max(0, Number(context.mysqlRetryCount) || 0) + 1;
  context.mysqlRetryScopes = mergeRequestStringList(
    context.mysqlRetryScopes,
    ["app-state"],
  );
  context.mysqlRetryCodes = mergeRequestStringList(
    context.mysqlRetryCodes,
    [event.code],
  );
  context.mysqlRetryStages = mergeRequestStringList(
    context.mysqlRetryStages,
    [event.stage],
  );
  context.mysqlRetryLabels = mergeRequestStringList(
    context.mysqlRetryLabels,
    [event.label],
  );
}

