let appStateBackgroundFlushRunning = false;
let appStateBackgroundFlushSnapshot = null;
let appStateBackgroundFlushOptions = null;
function mergeAppStateFlushOptions(current = {}, next = {}) {
  const currentDomains = Array.isArray(current.splitDomains)
    ? current.splitDomains
    : [];
  const nextDomains = Array.isArray(next.splitDomains) ? next.splitDomains : [];
  const splitDomains = [...new Set([...currentDomains, ...nextDomains])];
  return {
    ...current,
    ...next,
    ...(splitDomains.length > 0 ? { splitDomains } : {}),
  };
}
function scheduleAppStateBackgroundFlush(label, db, options = {}) {
  appStateBackgroundFlushSnapshot = cloneJson(db, db);
  appStateBackgroundFlushOptions = mergeAppStateFlushOptions(
    appStateBackgroundFlushOptions ?? {},
    options,
  );
  if (appStateBackgroundFlushRunning) return;
  appStateBackgroundFlushRunning = true;
  setImmediate(async () => {
    try {
      while (appStateBackgroundFlushSnapshot) {
        const snapshot = appStateBackgroundFlushSnapshot;
        const flushOptions = appStateBackgroundFlushOptions ?? {};
        appStateBackgroundFlushSnapshot = null;
        appStateBackgroundFlushOptions = null;
        try {
          await writeDb(snapshot, { metricLabel: `${label}.backgroundFlush.appStateWrite`, ...flushOptions });
        } catch (error) {
          console.warn(
            `[db:background-flush] ${label} non persistito subito:`,
            error?.message || error,
          );
        }
      }
    } finally {
      appStateBackgroundFlushRunning = false;
      if (appStateBackgroundFlushSnapshot) {
        scheduleAppStateBackgroundFlush(label, appStateBackgroundFlushSnapshot, {
          ...(appStateBackgroundFlushOptions ?? {}),
        });
      }
    }
  });
}

