async function captureRelationalOrderFinancialTableGuard({ enabled = false, metricLabel = "orders.create.relationalFinancialTableGuardRead", tableIds = [] } = {}) {
  const ids = normalizeIntegrationOrderWriteIds(tableIds);
  if (!enabled || ids.length === 0) return null;
  const startedAt = Date.now();
  try {
    await relationalRuntime.initialize();
    if (!relationalRuntime?.db) {
      throw new HttpError(503, "DB relazionale tavoli non disponibile.", {
        code: "RELATIONAL_TABLES_DB_UNAVAILABLE",
      });
    }
    const tablesRepo = new TablesBillsRelationalRepository(relationalRuntime.db);
    return {
      enabled: true,
      tableIds: ids,
      tokens: buildOrderFinancialTableRevisionTokens({
        includeSnapshots: true,
        tableIds: ids,
        getTableState: (tableId) => tablesRepo.getTableState(tableId),
      }),
    };
  } finally {
    runtimeMetrics.recordOperation(
      "orderWorkflow",
      metricLabel,
      Date.now() - startedAt,
    );
  }
}

async function persistRelationalOrderFinancialTables({ appState, enabled = false, metricLabel = "orders.create.relationalFinancialTableWrite", tableIds = [] } = {}) {
  const ids = normalizeIntegrationOrderWriteIds(tableIds);
  if (!enabled || ids.length === 0) return null;
  const startedAt = Date.now();
  try {
    await relationalRuntime.initialize();
    if (!relationalRuntime?.db) {
      throw new HttpError(503, "DB relazionale tavoli non disponibile.", {
        code: "RELATIONAL_TABLES_DB_UNAVAILABLE",
      });
    }
    const persistedTables = new TablesBillsRelationalRepository(relationalRuntime.db).replaceTablesFromAppState(
      appState,
      ids,
      { enforceRevision: true },
    );
    if (persistedTables?.reason === "revision_conflict") {
      throw new HttpError(409, "Conflitto revisione tavolo.", {
        code: "TABLE_REVISION_CONFLICT",
        details: { conflicts: persistedTables.conflicts ?? [] },
      });
    }
    if (!persistedTables?.ok) {
      throw new HttpError(400, "Snapshot tavolo relazionale non valido.", {
        code: "RELATIONAL_TABLE_FINANCIAL_SYNC_FAILED",
        details: { reason: persistedTables?.reason ?? "unknown", tableIds: ids },
      });
    }
    return persistedTables;
  } finally {
    runtimeMetrics.recordOperation(
      "orderWorkflow",
      metricLabel,
      Date.now() - startedAt,
    );
  }
}

