async function withDbMutation(label, mutator, options = {}) {
  const requestMetricsContext = requestMetricsStorage.getStore();
  const mutationLabel = String(label ?? "db_mutation").trim() || "db_mutation";
  const shouldPreserveHotCaches =
    typeof options.shouldPreserveHotCaches === "function"
      ? options.shouldPreserveHotCaches
      : null;
  return new Promise((resolve, reject) => {
	    dbMutationQueue.push({
	      label: mutationLabel,
      priority: dbMutationPriority(mutationLabel, options),
      sequence: dbMutationQueueSequence++,
      enqueuedAt: Date.now(),
      requestMetricsContext,
      resolve,
      reject,
      run: async () => requestMetricsStorage.run(requestMetricsContext, async () => {
        try {
          const result = await mutator();
          if (!shouldPreserveHotCaches?.()) {
            clearIntegrationHotResponseCaches();
          }
          return result;
        } catch (error) {
          error.mutationLabel = error.mutationLabel ?? mutationLabel;
          throw error;
	        }
	      }),
	    });
	    runtimeMetrics.incrementCounter("dbMutationEnqueued");
	    runtimeMetrics.recordQueueDepth({
	      dbDepth: dbMutationQueue.length,
	      dbRunning: dbMutationQueueRunning,
	      orderLaneDepth: orderSyncLaneQueue.length,
	      orderLaneRunning: orderSyncLaneRunning,
	    });
	    scheduleNextDbMutationTask();
	  });
}
function withPrintLaneMutation(label, keys, mutator, options = {}) { return printLane.enqueue(label, keys, mutator, { fallback: () => withDbMutation(label, mutator, options), metricLabel: options.metricLabel, shouldPreserveHotCaches: options.shouldPreserveHotCaches }); }
function shouldSerializeApiMutation(method, pathname) {
  const safeMethod = String(method ?? "")
    .trim()
    .toUpperCase();
  const safePath = String(pathname ?? "").trim();
  if (!safePath.startsWith("/api/") || safeMethod === "OPTIONS") {
    return false;
  }
  if (
    isTableWorkLockFastPathEnabled() &&
    safeMethod === "POST" &&
    safePath.startsWith("/api/tables/lock/")
  ) {
    return false;
  }
  if (safeMethod === "POST" && safePath === "/api/internal/orders/async-appstate-flush") return false;
  if (safeMethod === "POST" && safePath === "/api/internal/print-spool/legacy-mirror") return false;
  if (safeMethod === "POST" && safePath === "/api/internal/print-spool/auto-print") return false;
  if (
    safeMethod === "POST" &&
    safePath === "/api/integration/print" &&
    (!PRINTING_ENABLED || canUsePrintSpoolFastWorker())
  ) {
    return false;
  }
  const registeredMutation = routeRegistry?.isMutation?.(safeMethod, safePath);
  if (typeof registeredMutation === "boolean") {
    return registeredMutation;
  }
  return safeMethod !== "GET";
}
