const loginRateLimitBuckets = new Map();

function getLoginRequestIp(req) {
  return String(
    req?.headers?.["x-forwarded-for"] ?? req?.socket?.remoteAddress ?? "",
  )
    .split(",")[0]
    .trim();
}

function normalizeLoginRateKeyPart(value) {
  return (
    String(value ?? "")
      .trim()
      .toLowerCase() || "-"
  );
}

function assertLoginAttemptAllowed({ username, deviceUuid, ipAddress }) {
  const now = Date.now();
  const keys = [
    `user:${normalizeLoginRateKeyPart(username)}`,
    `device:${normalizeLoginRateKeyPart(deviceUuid)}`,
    `ip:${normalizeLoginRateKeyPart(ipAddress)}`,
  ];
  for (const key of keys) {
    const bucket = loginRateLimitBuckets.get(key);
    if (!bucket) continue;
    if (bucket.resetAt <= now) {
      loginRateLimitBuckets.delete(key);
      continue;
    }
    if (bucket.count >= LOGIN_RATE_LIMIT_MAX_ATTEMPTS) {
      throw new HttpError(429, "Troppi tentativi di login. Riprova tra poco.", {
        code: "LOGIN_RATE_LIMITED",
        details: { retryAfterMs: Math.max(bucket.resetAt - now, 0) },
      });
    }
  }
}

function recordLoginAttempt({ username, deviceUuid, ipAddress, ok }) {
  const now = Date.now();
  const keys = [
    `user:${normalizeLoginRateKeyPart(username)}`,
    `device:${normalizeLoginRateKeyPart(deviceUuid)}`,
    `ip:${normalizeLoginRateKeyPart(ipAddress)}`,
  ];
  for (const key of keys) {
    if (ok) {
      loginRateLimitBuckets.delete(key);
      continue;
    }
    const current = loginRateLimitBuckets.get(key);
    if (!current || current.resetAt <= now) {
      loginRateLimitBuckets.set(key, {
        count: 1,
        resetAt: now + LOGIN_RATE_LIMIT_WINDOW_MS,
      });
      continue;
    }
    current.count += 1;
    loginRateLimitBuckets.set(key, current);
  }
}

