function resolveLoginWorkstationContext(db, payload = {}, clientApp = "") {
  if (normalizeClientApp(clientApp) !== "postazione") return null;
  const settings = db?.posSettings ?? {};
  const candidate =
    payload.workstationId ??
    payload.stationId ??
    payload.stationName ??
    payload.station ??
    payload.workstation ??
    "";
  const rawStationName = String(
    payload.stationName ?? payload.station ?? "",
  ).trim();
  const workstationId = resolveConfiguredWorkstationId(settings, candidate);
  const match = findWorkstationConfig(
    settings,
    workstationId,
    rawStationName || candidate,
  );
  const workstation = match?.workstation ?? null;
  const resolvedId = String(
    workstation?.id ?? workstation?.stationId ?? workstationId ?? "",
  ).trim();
  if (!resolvedId) return null;
  return {
    workstationId: resolvedId,
    stationName:
      String(
        workstation?.stationName ??
          workstation?.station ??
          workstation?.name ??
          rawStationName ??
          resolvedId,
      ).trim() || resolvedId,
  };
}

function assertWorkstationLoginAvailable(
  db,
  user,
  workstationContext = null,
  options = {},
) {
  if (normalizeClientApp(options.clientApp) !== "postazione") return;
  const workstationId = String(workstationContext?.workstationId ?? "").trim();
  if (!workstationId) return;
  pruneExpiredLoginSessions(db);
  const userId = String(user?.id ?? "").trim();
  const deviceUuid = String(options.deviceUuid ?? "").trim();
  const conflict = (Array.isArray(db?.sessions) ? db.sessions : []).find(
    (session) => {
      if (normalizeClientApp(session?.clientApp) !== "postazione") return false;
      if (String(session?.workstationId ?? "").trim() !== workstationId)
        return false;
      if (userId && String(session?.userId ?? "").trim() === userId)
        return false;
      if (deviceUuid && String(session?.deviceUuid ?? "").trim() === deviceUuid)
        return false;
      return true;
    },
  );
  if (!conflict) return;
  const conflictUser = authRepository.getUserById(
    db,
    String(conflict.userId ?? "").trim(),
  );
  throw new HttpError(409, "Postazione gia in uso da un altro operatore.", {
    code: "WORKSTATION_ALREADY_IN_USE",
    workstationId,
    stationName: workstationContext?.stationName ?? "",
    activeUserId: conflict.userId ?? "",
    activeUsername: conflictUser?.username ?? "",
    activeFullName: conflictUser?.fullName ?? "",
  });
}

function assertUserLoginWorkstationAllowed(db, user, workstationContext) {
  const workstationId = String(workstationContext?.workstationId ?? "").trim();
  if (!workstationId) {
    throw new HttpError(400, "Seleziona una postazione valida.", {
      code: "WORKSTATION_REQUIRED",
    });
  }
  const allowed = findUserLoginWorkstation(user, db?.posSettings, workstationId);
  if (!allowed) {
    throw new HttpError(403, "Postazione non abilitata per questo utente.", {
      code: "WORKSTATION_NOT_ALLOWED",
      workstationId,
    });
  }
  return {
    workstationId: allowed.id,
    stationName: allowed.stationName,
    name: allowed.name,
  };
}

