function validateSessionContext(db, payload) {
  const token = typeof payload.token === "string" ? payload.token.trim() : "";
  const userId =
    typeof payload.userId === "string" ? payload.userId.trim() : "";
  const deviceUuid =
    typeof payload.deviceUuid === "string" ? payload.deviceUuid.trim() : "";

  if (!token || !deviceUuid) {
    throw new HttpError(401, "Sessione login richiesta.");
  }

  const tokenHash = hashSessionToken(token);
  let session = authRepository.findSessionByTokenHash(db, {
    tokenHash,
    userId,
    deviceUuid,
  });

  return validateResolvedSessionContext(db, payload, session);
}

function validateResolvedSessionContext(db, payload, session) {
  const token = typeof payload.token === "string" ? payload.token.trim() : "";
  const deviceUuid =
    typeof payload.deviceUuid === "string" ? payload.deviceUuid.trim() : "";

  if (
    !token ||
    !deviceUuid ||
    !session ||
    String(session.tokenHash ?? "").trim() !== hashSessionToken(token) ||
    String(session.deviceUuid ?? "").trim() !== deviceUuid
  ) {
    throw new HttpError(401, "Sessione login non valida o scaduta.");
  }

  const nowMs = Date.now();
  const expiresAtMs = new Date(session.expiresAt ?? "").getTime();
  const lastSeenAtMs = new Date(
    session.lastSeenAt ?? session.createdAt ?? "",
  ).getTime();
  if (
    (Number.isFinite(expiresAtMs) && expiresAtMs <= nowMs) ||
    (Number.isFinite(lastSeenAtMs) &&
      lastSeenAtMs + SESSION_IDLE_TIMEOUT_MS <= nowMs)
  ) {
    db.sessions = db.sessions.filter(
      (entry) => String(entry.id ?? "") !== String(session.id ?? ""),
    );
    appendAuditEvent(db, {
      ...buildAuditActor(null, {
        userId: String(session.userId ?? "").trim(),
        deviceUuid,
      }),
      action: "auth.session_expired",
      entityType: "session",
      entityId: String(session.id ?? ""),
      payload: {
        sessionId: String(session.id ?? ""),
        userId: String(session.userId ?? "").trim(),
        deviceUuid,
        expiresAt: session.expiresAt ?? null,
        lastSeenAt: session.lastSeenAt ?? null,
      },
    });
    db.meta.lastWriteAt = nowIso();
    throw new HttpError(401, "Sessione login non valida o scaduta.", {
      code: "SESSION_EXPIRED",
    });
  }

  const effectiveUserId = String(session.userId ?? "").trim();
  const user = authRepository.getUserById(db, effectiveUserId);
  if (!user) {
    throw new HttpError(401, "Utente non valido.");
  }
  assertUserSessionAppAllowed(user, session.clientApp, payload.clientApp);

  return { user, session };
}

function createSession(userId, deviceUuid, clientApp = "", options = {}) {
  const token = `sess_${randomUUID().replace(/-/g, "")}${randomUUID().replace(/-/g, "")}`;
  const timestamp = nowIso();
  const expiresAt = new Date(Date.now() + SESSION_TTL_MS).toISOString();
  const workstationId = String(options?.workstationId ?? "").trim();
  const stationName = String(options?.stationName ?? "").trim();
  const session = {
    id: `sess_${randomUUID().replace(/-/g, "")}`,
    tokenHash: hashSessionToken(token),
    userId,
    deviceUuid,
    clientApp: normalizeClientApp(clientApp),
    createdAt: timestamp,
    lastSeenAt: timestamp,
    expiresAt,
  };
  if (workstationId) {
    session.workstationId = workstationId;
    session.stationName = stationName || workstationId;
  }
  return { token, session };
}

function pruneExpiredLoginSessions(db, nowMs = Date.now()) {
  if (!db || !Array.isArray(db.sessions)) {
    if (db) db.sessions = [];
    return 0;
  }
  const beforeCount = db.sessions.length;
  db.sessions = db.sessions.filter((session) => {
    if (!session || typeof session !== "object") return false;
    const expiresAtMs = new Date(session.expiresAt ?? "").getTime();
    const lastSeenAtMs = new Date(
      session.lastSeenAt ?? session.createdAt ?? "",
    ).getTime();
    if (Number.isFinite(expiresAtMs) && expiresAtMs <= nowMs) return false;
    if (
      Number.isFinite(lastSeenAtMs) &&
      lastSeenAtMs + SESSION_IDLE_TIMEOUT_MS <= nowMs
    )
      return false;
    return true;
  });
  return Math.max(beforeCount - db.sessions.length, 0);
}

function enforceLoginSessionPolicy(db, user, options = {}) {
  if (!db || !Array.isArray(db.sessions)) {
    db.sessions = [];
    return 0;
  }

  const userId = String(user?.id ?? "").trim();
  if (!userId) return 0;

  const deviceUuid = String(options.deviceUuid ?? "").trim();
  const clientApp = normalizeClientApp(options.clientApp);
  pruneExpiredLoginSessions(db);
  let revokedCount = 0;

  const beforeCount = db.sessions.length;
  db.sessions = db.sessions.filter((session) => {
    if (String(session?.userId ?? "").trim() !== userId) return true;
    if (clientApp && normalizeClientApp(session?.clientApp) !== clientApp)
      return true;
    // Le sessioni sono stabili per device su tutti i frontend: un nuovo login
    // pulisce il token precedente dello stesso terminale senza espellere altri
    // device dello stesso operatore. I vincoli di occupazione postazione sono
    // gestiti da assertWorkstationLoginAvailable.
    if (deviceUuid) {
      return String(session?.deviceUuid ?? "").trim() !== deviceUuid;
    }
    return false;
  });
  revokedCount += Math.max(beforeCount - db.sessions.length, 0);
  return revokedCount;
}

function buildPosSettingsPayload(settings) {
  const configuredIntegrationStations =
    resolveConfiguredIntegrationStations(settings);
  const tableTypes = [
    ...new Set(settings.tables.map((table) => table.type)),
  ].sort((a, b) => a.localeCompare(b, "it-IT"));
  return {
    ok: true,
    sideBars: settings.sideBars,
    demoMode: settings.demoMode === true,
    paymentMethods: settings.paymentMethods,
    smartCash: settings.smartCash,
    tableTypes,
    tables: settings.tables,
    locale: settings.locale ?? sanitizePosLocale(),
    locales:
      settings.locales ??
      sanitizePosLocales([], settings.locale ?? sanitizePosLocale()),
    activities: settings.activities ?? [],
    activityRoomBindings: settings.activityRoomBindings ?? [],
    menus: settings.menus ?? [],
    areaMenus: settings.areaMenus ?? [],
    priceLists: settings.priceLists ?? [],
    priceListSchedules: settings.priceListSchedules ?? [],
    menuSchedules: settings.menuSchedules ?? [],
    printers: settings.printers ?? [],
    fiscalDevices: settings.fiscalDevices ?? [],
    mobileDevices: settings.mobileDevices ?? [],
    automaticCash: settings.automaticCash ?? sanitizeAutomaticCashSettings(),
    radioChannels: settings.radioChannels ?? [],
    radioPreferences: settings.radioPreferences ?? [],
    workstations: settings.workstations ?? [],
    areas: settings.areas ?? [],
    orderWorkflow: settings.orderWorkflow ?? sanitizeOrderWorkflowSettings(),
    printPreferences:
      settings.printPreferences ??
      sanitizePosPrintPreferences(cloneDefaultPosPrintPreferences()),
    printerDefaults: {
      port: DEFAULT_NETWORK_PRINTER_PORT,
      fiscalModel: DEFAULT_FISCAL_PRINTER_MODEL,
    },
    printerModels: clonePrinterModels(),
    integrationStations: configuredIntegrationStations,
    configuredStations: configuredIntegrationStations,
  };
}


function sanitizePrintSpoolJob(record, fallbackId = `print_job_${Date.now()}`) {
  if (!record || typeof record !== "object") return null;
  const id = normalizeConfigId(record.id, fallbackId);
  const status = PRINT_SPOOL_STATUSES.has(record.status)
    ? record.status
    : "queued";
  const kind = sanitizePrintFileToken(record.kind, "ticket");
  const orderId = sanitizePrintFileToken(record.orderId, "order");
  const printerId = normalizeConfigId(record.printerId, "");
  const precontoProfileRaw = String(record.precontoProfile ?? "")
    .trim()
    .toLowerCase();
  const precontoProfile = precontoProfileRaw === "cash" ? "cash" : null;
  const printPreferences =
    record.printPreferences && typeof record.printPreferences === "object"
      ? sanitizePosPrintPreferences(record.printPreferences)
      : null;
  const requestedAt = String(record.requestedAt ?? nowIso());
  const processedAt =
    typeof record.processedAt === "string" &&
    record.processedAt.trim().length > 0
      ? record.processedAt
      : null;
  const lastAttemptAt =
    typeof record.lastAttemptAt === "string" &&
    record.lastAttemptAt.trim().length > 0
      ? record.lastAttemptAt
      : null;
  const nextRetryAt =
    typeof record.nextRetryAt === "string" &&
    record.nextRetryAt.trim().length > 0
      ? record.nextRetryAt
      : null;
  const printRuntimeState = resolvePrintRuntimeState({
    status,
    printState: record.printState,
    printStatePath: record.printStatePath,
    nextRetryAt,
  });
  const printStateUpdatedAt =
    typeof record.printStateUpdatedAt === "string" &&
    record.printStateUpdatedAt.trim().length > 0
      ? record.printStateUpdatedAt
      : lastAttemptAt ?? processedAt ?? requestedAt;
  const fileNameRaw =
    typeof record.fileName === "string" && record.fileName.trim().length > 0
      ? record.fileName.trim()
      : `${id}.txt`;
  return {
    id,
    status,
    kind,
    orderId: String(record.orderId ?? "").trim(),
    areaId: String(record.areaId ?? "").trim(),
    deviceId: String(record.deviceId ?? "").trim(),
    station: String(record.station ?? "").trim(),
    printerId: printerId || null,
    printerName: String(record.printerName ?? "").trim(),
    printerHost: String(record.printerHost ?? "").trim(),
    printerPort: normalizePrinterPort(record.printerPort),
    requestedAt,
    processedAt,
    printState: printRuntimeState.printState,
    printStatePath: printRuntimeState.path,
    printStateUpdatedAt,
    fileName:
      sanitizePrintFileToken(
        fileNameRaw.replace(/\.txt$/i, ""),
        `${kind}_${id}`,
      ) + ".txt",
    textPreview: String(record.textPreview ?? "").slice(
      0,
      PRINT_SPOOL_TEXT_PREVIEW_MAX_LEN,
    ),
    bytes: Math.max(Math.trunc(Number(record.bytes) || 0), 0),
    precontoProfile,
    attempts: Math.max(Math.trunc(Number(record.attempts) || 0), 0),
    lastAttemptAt,
    nextRetryAt,
    recoveredAt:
      typeof record.recoveredAt === "string" &&
      record.recoveredAt.trim().length > 0
        ? record.recoveredAt
        : null,
    errorMessage:
      typeof record.errorMessage === "string" &&
      record.errorMessage.trim().length > 0
        ? record.errorMessage.trim().slice(0, 240)
        : "",
    requestedBy: {
      userId: String(record.requestedBy?.userId ?? "").trim(),
      deviceUuid: String(record.requestedBy?.deviceUuid ?? "").trim(),
      clientApp: normalizeClientApp(record.requestedBy?.clientApp),
    },
    printPreferences,
  };
}

function sanitizePrintSpoolJobs(records) {
  if (!Array.isArray(records)) return [];
  return records
    .map((entry, index) =>
      sanitizePrintSpoolJob(entry, `print_job_${index + 1}`),
    )
    .filter((entry) => entry !== null)
    .sort(
      (a, b) =>
        new Date(a.requestedAt).getTime() - new Date(b.requestedAt).getTime(),
    );
}

function parsePrintSpoolTimestamp(value, fallback = 0) {
  const timestamp = Date.parse(String(value ?? ""));
  return Number.isFinite(timestamp) ? timestamp : fallback;
}

function isRetryablePrintSpoolError(errorMessage = "") {
  const message = String(errorMessage ?? "")
    .trim()
    .toLowerCase();
  if (!message) return true;
  return (
    message.includes("timeout") ||
    message.includes("econnrefused") ||
    message.includes("econnreset") ||
    message.includes("ehostunreach") ||
    message.includes("enetunreach") ||
    message.includes("etimedout") ||
    message.includes("socket") ||
    message.includes("stampante non raggiungibile") ||
    message.includes("connessione stampante") ||
    message.includes("stampa cups non riuscita")
  );
}

function shouldRetryPrintSpoolJob(job, errorMessage = "") {
  if (!PRINTING_ENABLED || !job || typeof job !== "object") return false;
  if (job.status === "printed" || job.status === "disabled") return false;
  if (
    Math.max(Math.trunc(Number(job.attempts) || 0), 0) >=
    PRINT_SPOOL_RETRY_MAX_ATTEMPTS
  )
    return false;
  return isRetryablePrintSpoolError(errorMessage || job.errorMessage);
}

function isPrintSpoolJobReadyForAttempt(job, nowMs = Date.now()) {
  if (!job || job.status !== "queued") return false;
  const nextRetryAt = parsePrintSpoolTimestamp(job.nextRetryAt, 0);
  return nextRetryAt <= nowMs;
}

function getNextPrintSpoolRetryDelayMs(jobs, nowMs = Date.now()) {
  const futureRetryTimes = sanitizePrintSpoolJobs(jobs)
    .filter((entry) => entry.status === "queued")
    .map((entry) => parsePrintSpoolTimestamp(entry.nextRetryAt, 0))
    .filter((timestamp) => timestamp > nowMs);
  if (futureRetryTimes.length === 0) return null;
  return Math.max(0, Math.min(...futureRetryTimes) - nowMs);
}

function resolveIntegrationOrderPrintStation(order, payload = {}) {
  return (
    normalizeOptionalIntegrationStationName(order?.assignedStationId) ??
    normalizeOptionalIntegrationStationName(order?.ownerStation) ??
    normalizeOptionalIntegrationStationName(order?.lockedByStationId) ??
    normalizeOptionalIntegrationStationName(order?.originalAssignedStationId) ??
    normalizeOptionalIntegrationStationName(order?.station) ??
    normalizeOptionalIntegrationStationName(payload?.station) ??
    PRIMARY_INTEGRATION_STATION
  );
}

function findLatestIntegrationPrintTarget(db, orderId, kinds = []) {
  const safeOrderId = String(orderId ?? "").trim();
  if (!safeOrderId) return null;
  const allowedKinds = new Set(
    (Array.isArray(kinds) ? kinds : [kinds])
      .map((entry) =>
        String(entry ?? "")
          .trim()
          .toLowerCase(),
      )
      .filter(Boolean),
  );
  const jobs = sanitizePrintSpoolJobs(db?.printSpoolJobs);
  for (let index = jobs.length - 1; index >= 0; index -= 1) {
    const job = jobs[index];
    const jobKind = String(job?.kind ?? "")
      .trim()
      .toLowerCase();
    if (String(job?.orderId ?? "").trim() !== safeOrderId) continue;
    if (allowedKinds.size > 0 && !allowedKinds.has(jobKind)) continue;
    if (job?.status === "disabled") continue;
    const printerId = normalizeConfigId(job?.printerId, "");
    const station = normalizeOptionalIntegrationStationName(job?.station);
    const areaId = String(job?.areaId ?? "").trim();
    const deviceId = String(job?.deviceId ?? "").trim();
    if (printerId || station || areaId || deviceId) {
      return { printerId, station, areaId, deviceId };
    }
  }
  return null;
}

function applyIntegrationPrintTarget(payload, target, fallbackStation) {
  const station =
    target?.station ?? fallbackStation ?? PRIMARY_INTEGRATION_STATION;
  return {
    ...payload,
    station,
    fallbackStation: station,
    ...(target?.printerId ? { printerId: target.printerId } : {}),
    ...(target?.areaId ? { areaId: target.areaId } : {}),
    ...(target?.deviceId ? { deviceId: target.deviceId } : {}),
  };
}

function findIntegrationOrderForPrint(db, orderId) {
  const safeOrderId = String(orderId ?? "").trim();
  if (!safeOrderId || !Array.isArray(db?.integration?.orders)) return null;
  const orderIndex = findIntegrationOrderIndexByLookup(
    db.integration.orders,
    safeOrderId,
  );
  if (orderIndex < 0) return null;
  return sanitizeIntegrationOrder(
    db.integration.orders[orderIndex],
    String(db.integration.orders[orderIndex]?.id ?? safeOrderId).trim() ||
      safeOrderId,
  );
}

function normalizeTablePrecontoMode(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase() === "current"
    ? "current"
    : "complete";
}

function collectTablePrecontoOrderIds(payload = {}) {
  const fromOrderIds = Array.isArray(payload?.orderIds) ? payload.orderIds : [];
  const fromOrders = Array.isArray(payload?.orders)
    ? payload.orders.map((entry) => entry?.id ?? entry?.orderId)
    : [];
  return [...fromOrderIds, ...fromOrders]
    .map((entry) => String(entry ?? "").trim())
    .filter(Boolean);
}

function collectIntegrationOrdersForTablePreconto(db, payload = {}) {
  const explicitOrderIds = collectTablePrecontoOrderIds(payload);
  const explicitOrders = explicitOrderIds
    .map((orderId) => findIntegrationOrderForPrint(db, orderId))
    .filter((order) => order !== null);
  const tableId = String(payload?.tableId ?? "").trim();
  const sourceOrders =
    explicitOrders.length > 0
      ? explicitOrders
      : (Array.isArray(db?.integration?.orders) ? db.integration.orders : [])
          .map((entry, index) =>
            sanitizeIntegrationOrder(
              entry,
              String(entry?.id ?? `order_${index + 1}`),
            ),
          )
          .filter((order) => {
            if (!tableId || String(order.tableId ?? "").trim() !== tableId)
              return false;
            if (isCancelledIntegrationWorkflowStatus(order.workflowStatus))
              return false;
            return (
              Array.isArray(order.items) &&
              order.items.some((item) => !item?.voidedAt)
            );
          });
  return sourceOrders
    .map((order) => applyIntegrationOrderCompsToPrintableOrder(order, db))
    .filter(
      (order) => !isCancelledIntegrationWorkflowStatus(order.workflowStatus),
    )
    .sort((left, right) => {
      const leftTime =
        Number(left.receivedAtMs ?? left.createdAtMs ?? left.createdAt ?? 0) ||
        0;
      const rightTime =
        Number(
          right.receivedAtMs ?? right.createdAtMs ?? right.createdAt ?? 0,
        ) || 0;
      if (leftTime !== rightTime) return leftTime - rightTime;
      return String(left.id ?? "").localeCompare(
        String(right.id ?? ""),
        "it-IT",
      );
    });
}

function findLegacyTablePrecontoPrintTarget(db, orders) {
  for (const order of Array.isArray(orders) ? orders : []) {
    const safeOrderId = String(order?.id ?? "").trim();
    if (!safeOrderId) continue;
    const orderTarget = findLatestIntegrationPrintTarget(db, safeOrderId, [
      "order",
    ]);
    if (orderTarget) return orderTarget;
  }
  return null;
}

function resolveTablePrecontoActivityId(
  settings,
  roomIdRaw,
  fallbackActivityId = "",
) {
  const fallbackActivity = normalizeConfigId(fallbackActivityId, "");
  if (fallbackActivity) return fallbackActivity;
  const roomId = normalizeConfigId(roomIdRaw, "");
  if (!roomId) return "";
  const activitiesById = new Map(
    (Array.isArray(settings?.activities) ? settings.activities : [])
      .map((activity) => [normalizeConfigId(activity?.id, ""), activity])
      .filter(([activityId]) => Boolean(activityId)),
  );
  const binding = (
    Array.isArray(settings?.activityRoomBindings)
      ? settings.activityRoomBindings
      : []
  ).find((entry) => {
    const bindingRoomId = normalizeConfigId(entry?.roomId, "");
    const bindingActivityId = normalizeConfigId(entry?.activityId, "");
    const activity = activitiesById.get(bindingActivityId);
    return (
      bindingRoomId === roomId &&
      bindingActivityId &&
      entry?.status !== "disabled" &&
      activity?.status !== "disabled"
    );
  });
  return normalizeConfigId(binding?.activityId, "");
}

function buildTablePrecontoResidualItem(order, amount) {
  const safeAmount = roundMoney(Math.max(Number(amount) || 0, 0));
  if (safeAmount <= 0.009) return null;
  const orderId = String(order?.id ?? "").trim() || "?";
  return {
    id: `residual_${orderId}`,
    lineId: `residual_${orderId}`,
    productNameSnapshot: `Residuo comanda #${orderId}`,
    name: `Residuo comanda #${orderId}`,
    qty: 1,
    unitPriceApplied: safeAmount,
    listPriceAtTime: safeAmount,
    lineTotal: safeAmount,
    finalLinePrice: safeAmount,
  };
}

function scaleTablePrecontoItemsToTotal(items, targetTotal) {
  const safeItems = Array.isArray(items) ? items : [];
  const targetCents = Math.max(Math.round((Number(targetTotal) || 0) * 100), 0);
  if (targetCents <= 0) return [];
  const sourceCents = safeItems.reduce(
    (sum, item) => sum + Math.max(Math.round((Number(item?.lineTotal) || 0) * 100), 0),
    0,
  );
  if (sourceCents <= 0) return safeItems;
  if (Math.abs(sourceCents - targetCents) <= 1) return safeItems;

  let allocatedCents = 0;
  return safeItems
    .map((item, index) => {
      const itemCents = Math.max(Math.round((Number(item?.lineTotal) || 0) * 100), 0);
      const nextCents =
        index === safeItems.length - 1
          ? Math.max(targetCents - allocatedCents, 0)
          : Math.min(
              Math.max(Math.round((targetCents * itemCents) / Math.max(sourceCents, 1)), 0),
              Math.max(targetCents - allocatedCents, 0),
            );
      allocatedCents += nextCents;
      if (nextCents <= 0) return null;
      const qty = Math.max(1, Math.trunc(Number(item?.qty) || 1));
      const lineTotal = roundMoney(nextCents / 100);
      const unitPrice = roundMoney(lineTotal / qty);
      return {
        ...item,
        qty,
        unitPriceApplied: unitPrice,
        lineTotal,
        finalLinePrice: lineTotal,
      };
    })
    .filter(Boolean);
}

function buildCurrentTablePrecontoItemsForOrder(order) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const dueAmount = roundMoney(Math.max(Number(safeOrder.dueAmount) || 0, 0));
  const total = roundMoney(Math.max(Number(safeOrder.total) || 0, 0));
  const paidAmount = roundMoney(Math.max(Number(safeOrder.paidAmount) || 0, 0));
  const orderId = String(safeOrder.id ?? "").trim();
  const sourceItems = (Array.isArray(safeOrder.items) ? safeOrder.items : []).filter(
    (item) => item && !item.voidedAt,
  );
  if (dueAmount <= 0.009 || String(safeOrder.paymentStatus ?? "").trim().toLowerCase() === "paid") {
    return [];
  }

  const paidArticleUnits = new Set(normalizeStringList(safeOrder.paidArticleUnits, 1000, 120));
  if (paidArticleUnits.size === 0) {
    if (paidAmount > 0.009 && dueAmount + 0.009 < total) {
      return [buildTablePrecontoResidualItem(safeOrder, dueAmount)].filter(Boolean);
    }
    return scaleTablePrecontoItemsToTotal(sourceItems, dueAmount);
  }

  const groups = new Map();
  forEachIntegrationOrderArticleUnit(safeOrder, ({ unitId, amountCents, lineIndex, item }) => {
    if (paidArticleUnits.has(unitId)) return;
    const key = String(lineIndex);
    const current = groups.get(key) ?? {
      source: item,
      qty: 0,
      amountCents: 0,
    };
    current.qty += 1;
    current.amountCents += Math.max(Math.trunc(Number(amountCents) || 0), 0);
    groups.set(key, current);
  });

  let items = [...groups.values()]
    .map((group) => {
      const qty = Math.max(1, Math.trunc(Number(group.qty) || 1));
      const lineTotal = roundMoney(Math.max(Number(group.amountCents) || 0, 0) / 100);
      if (lineTotal <= 0.009) return null;
      const unitPrice = roundMoney(lineTotal / qty);
      return {
        ...group.source,
        qty,
        unitPriceApplied: unitPrice,
        lineTotal,
        finalLinePrice: lineTotal,
      };
    })
    .filter(Boolean);

  const itemTotal = roundMoney(
    items.reduce((sum, item) => sum + Math.max(Number(item?.lineTotal) || 0, 0), 0),
  );
  if (items.length === 0) {
    return [buildTablePrecontoResidualItem(safeOrder, dueAmount)].filter(Boolean);
  }
  if (dueAmount > itemTotal + 0.009) {
    items = [
      ...items,
      buildTablePrecontoResidualItem(safeOrder, roundMoney(dueAmount - itemTotal)),
    ].filter(Boolean);
  } else if (itemTotal > dueAmount + 0.009) {
    items = scaleTablePrecontoItemsToTotal(items, dueAmount);
  }
  if (!items.length && orderId) {
    return [buildTablePrecontoResidualItem(safeOrder, dueAmount)].filter(Boolean);
  }
  return items;
}

function buildTablePrecontoPrintableOrder(
  orders,
  payload = {},
  settings = null,
) {
  const tablePrecontoMode = normalizeTablePrecontoMode(
    payload?.tablePrecontoMode ?? payload?.mode,
  );
  const isCurrentPreconto = tablePrecontoMode === "current";
  const safeOrders = (Array.isArray(orders) ? orders : [])
    .map((order) =>
      sanitizeIntegrationOrder(order, String(order?.id ?? "order")),
    )
    .filter(
      (order) =>
        Array.isArray(order.items) &&
        order.items.some((item) => !item?.voidedAt),
    );
  if (safeOrders.length === 0) {
    throw new HttpError(
      404,
      "Nessuna comanda stampabile per il preconto tavolo.",
    );
  }
  const firstOrder = safeOrders[0];
  const firstSnapshot =
    firstOrder?.operationalSnapshot &&
    typeof firstOrder.operationalSnapshot === "object"
      ? firstOrder.operationalSnapshot
      : null;
  const tableId = String(
    payload?.tableId ?? firstSnapshot?.tableId ?? firstOrder.tableId ?? "",
  ).trim();
  const tableNumber = parseTableNumberFromValue(
    payload?.tableNumber ?? firstOrder.tableNumber ?? firstOrder.table,
    tableId,
  );
  const tableLabel =
    sanitizeIntegrationTableLabel(
      payload?.tableLabel ??
        firstOrder.tableLabel ??
        firstOrder.logicalTableLabel,
    ) || (tableNumber > 0 ? String(tableNumber) : tableId);
  const roomId = String(
    payload?.roomId ??
      payload?.areaId ??
      firstSnapshot?.roomId ??
      firstOrder.roomId ??
      "",
  ).trim();
  const activityId = resolveTablePrecontoActivityId(
    settings,
    roomId,
    payload?.activityId ??
      payload?.operationalActivityId ??
      firstSnapshot?.activityId,
  );
  const roomName = String(
    payload?.roomName ?? payload?.roomLabel ?? firstOrder.roomName ?? "",
  ).trim();
  const station =
    String(
      payload?.station ??
        firstOrder.station ??
        firstOrder.ownerStation ??
        PRIMARY_INTEGRATION_STATION,
    ).trim() || PRIMARY_INTEGRATION_STATION;
  const sourceItemsByOrder = isCurrentPreconto
    ? safeOrders.map((order) => buildCurrentTablePrecontoItemsForOrder(order))
    : safeOrders.map((order) =>
        (Array.isArray(order.items) ? order.items : []).filter((item) => !item?.voidedAt),
      );
  const items = safeOrders.flatMap((order, orderIndex) =>
    sourceItemsByOrder[orderIndex]
      .map((item, index) => ({
        ...item,
        id: `${order.id}_${item.id || index + 1}`,
        lineId: `${order.id}_${item.lineId || item.id || index + 1}`,
      })),
  );
  const total = roundMoney(
    safeOrders.reduce(
      (sum, order) => sum + Math.max(Number(order.total) || 0, 0),
      0,
    ),
  );
  const paidAmount = roundMoney(
    safeOrders.reduce(
      (sum, order) => sum + Math.max(Number(order.paidAmount) || 0, 0),
      0,
    ),
  );
  const dueAmountFromOrders = roundMoney(
    safeOrders.reduce(
      (sum, order) => sum + Math.max(Number(order.dueAmount) || 0, 0),
      0,
    ),
  );
  const dueAmount = roundMoney(
    Math.max(
      dueAmountFromOrders > 0 ? dueAmountFromOrders : total - paidAmount,
      0,
    ),
  );
  const printableTotal = isCurrentPreconto ? dueAmount : total;
  if (isCurrentPreconto && printableTotal <= 0.009) {
    throw new HttpError(404, "Nessun importo residuo per il preconto attuale.");
  }
  if (isCurrentPreconto && items.length === 0) {
    const residualItems = safeOrders
      .map((order) =>
        buildTablePrecontoResidualItem(
          order,
          roundMoney(Math.max(Number(order?.dueAmount) || 0, 0)),
        ),
      )
      .filter(Boolean);
    items.push(...residualItems);
  }
  return sanitizeIntegrationOrder(
    {
      id: `preconto_tavolo_${tableId || tableLabel}`,
      tableId,
      tableNumber,
      tableLabel,
      logicalTableLabel: tableLabel,
      roomId,
      roomName,
      station,
      ownerStation: station,
      operationalSnapshot:
        firstSnapshot || (activityId && roomId)
          ? {
              ...(firstSnapshot || {}),
              schemaVersion: 2,
              activityId,
              tableId: tableId || String(firstSnapshot?.tableId ?? "").trim(),
              roomId: roomId || String(firstSnapshot?.roomId ?? "").trim(),
            }
          : null,
      workflowStatus: "delivered",
      paymentStatus:
        printableTotal <= 0.009
          ? "paid"
          : isCurrentPreconto
            ? "unpaid"
            : paidAmount > 0.009
              ? "partial"
              : "unpaid",
      paidAmount: isCurrentPreconto ? 0 : paidAmount,
      dueAmount: isCurrentPreconto ? printableTotal : dueAmount,
      total: printableTotal,
      items,
    },
    `preconto_tavolo_${tableId || tableLabel || Date.now()}`,
  );
}

function collectIntegrationOrderCompAdjustmentsForPrint(db, orderId) {
  const safeOrderId = String(orderId ?? "").trim();
  if (!safeOrderId) return [];
  return (
    Array.isArray(db?.integration?.orderComps) ? db.integration.orderComps : []
  )
    .filter((record) => String(record?.orderId ?? "").trim() === safeOrderId)
    .map((record) => ({
      lineId: String(record?.lineId ?? "").trim(),
      productId: String(record?.productId ?? "").trim(),
      remaining: Math.max(Math.trunc(Number(record?.quantity) || 0), 0),
    }))
    .filter(
      (record) => record.remaining > 0 && (record.lineId || record.productId),
    );
}

function deriveIntegrationOrderCompAdjustmentsForPrint(order) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const explicitCompedAmount = roundMoney(
    Math.max(Number(safeOrder.compedAmount) || 0, 0),
  );
  const grossTotalBeforeComps = roundMoney(
    Math.max(Number(safeOrder.grossTotalBeforeComps) || 0, 0),
  );
  const currentTotal = roundMoney(Math.max(Number(safeOrder.total) || 0, 0));
  let remainingAmount =
    explicitCompedAmount > 0.009
      ? explicitCompedAmount
      : grossTotalBeforeComps > currentTotal
        ? roundMoney(grossTotalBeforeComps - currentTotal)
        : 0;
  if (remainingAmount <= 0.009) return [];
  const adjustments = [];
  for (const item of Array.isArray(safeOrder.items) ? safeOrder.items : []) {
    if (
      !item ||
      item.voidedAt ||
      item.lineType === BAR_CHARGE_REPLACEMENT_LINE_TYPE
    )
      continue;
    if (remainingAmount <= 0.009) break;
    const qty = Math.max(1, Math.trunc(Number(item.qty) || 1));
    const itemLineTotal = roundMoney(Math.max(Number(item.lineTotal) || 0, 0));
    const unitPrice =
      itemLineTotal > 0
        ? roundMoney(itemLineTotal / qty)
        : roundMoney(
            Math.max(
              Number(item.unitPriceApplied) ||
                Number(item.listPriceAtTime) ||
                0,
              0,
            ),
          );
    if (unitPrice <= 0.009) continue;
    const quantityToComp = Math.max(
      0,
      Math.min(qty, Math.round((remainingAmount + 0.001) / unitPrice)),
    );
    if (quantityToComp <= 0) continue;
    adjustments.push({
      lineId: String(item.lineId ?? "").trim(),
      productId: String(item.productId ?? "").trim(),
      remaining: quantityToComp,
    });
    remainingAmount = roundMoney(remainingAmount - unitPrice * quantityToComp);
  }
  return adjustments.filter(
    (record) => record.remaining > 0 && (record.lineId || record.productId),
  );
}

function applyIntegrationOrderCompsToPrintableOrder(order, db) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  let adjustments = collectIntegrationOrderCompAdjustmentsForPrint(
    db,
    safeOrder.id,
  );
  if (adjustments.length === 0 && safeOrder.totalAdjustedByComps === true) {
    adjustments = deriveIntegrationOrderCompAdjustmentsForPrint(safeOrder);
  }
  if (adjustments.length === 0) return safeOrder;
  const items = (Array.isArray(safeOrder.items) ? safeOrder.items : []).map(
    (item) => {
      if (
        !item ||
        item.voidedAt ||
        item.lineType === BAR_CHARGE_REPLACEMENT_LINE_TYPE
      )
        return item;
      let remainingQty = Math.max(1, Math.trunc(Number(item.qty) || 1));
      const itemLineId = String(item.lineId ?? "").trim();
      const itemProductId = String(item.productId ?? "").trim();
      for (const adjustment of adjustments) {
        if (remainingQty <= 0) break;
        const matchesLine =
          adjustment.lineId && itemLineId === adjustment.lineId;
        const matchesProduct =
          !matchesLine &&
          adjustment.productId &&
          itemProductId === adjustment.productId;
        if (!matchesLine && !matchesProduct) continue;
        const consume = Math.min(remainingQty, adjustment.remaining);
        adjustment.remaining -= consume;
        remainingQty -= consume;
      }
      if (remainingQty <= 0) {
        return {
          ...item,
          voidedAt: item.voidedAt || "comped-for-current-reprint",
        };
      }
      const originalQty = Math.max(1, Math.trunc(Number(item.qty) || 1));
      if (remainingQty === originalQty) return item;
      const originalLineTotal = roundMoney(
        Math.max(Number(item.lineTotal) || 0, 0),
      );
      const unitPrice =
        originalLineTotal > 0
          ? roundMoney(originalLineTotal / originalQty)
          : roundMoney(
              Math.max(
                Number(item.unitPriceApplied) ||
                  Number(item.listPriceAtTime) ||
                  0,
                0,
              ),
            );
      return {
        ...item,
        qty: remainingQty,
        lineTotal: roundMoney(unitPrice * remainingQty),
      };
    },
  );
  return sanitizeIntegrationOrder(
    {
      ...safeOrder,
      items,
    },
    safeOrder.id,
  );
}

function prunePrintSpoolJobs(db) {
  if (!Array.isArray(db.printSpoolJobs)) { db.printSpoolJobs = []; return; }
  // Chiamata a ogni accodamento: sanificare l'intera coda costava quanto la coda (1200 record
  // per pagamento). Sotto il tetto non serve, i job sono gia sanificati alla creazione.
  if (db.printSpoolJobs.length <= PRINT_SPOOL_MAX_JOBS) return;
  const jobs = sanitizePrintSpoolJobs(db.printSpoolJobs);
  if (jobs.length <= PRINT_SPOOL_MAX_JOBS) {
    db.printSpoolJobs = jobs;
    return;
  }
  const terminalStatuses = new Set([
    "printed",
    "failed",
    "failed_configuration",
    "unknown_after_crash",
    "disabled",
  ]);
  const activeJobs = jobs.filter((job) => !terminalStatuses.has(job.status));
  const terminalJobs = jobs.filter((job) => terminalStatuses.has(job.status));
  const terminalKeepCount = Math.max(
    0,
    PRINT_SPOOL_MAX_JOBS - activeJobs.length,
  );
  db.printSpoolJobs = [
    ...activeJobs,
    ...terminalJobs.slice(-terminalKeepCount),
  ].sort(
    (a, b) =>
      new Date(a.requestedAt).getTime() - new Date(b.requestedAt).getTime(),
  );
}

function buildPosAreasPayload(db, settings) {
  const roomOptions = buildPosRoomListFromSettings(settings);
  const userOptions = (Array.isArray(db.users) ? db.users : [])
    .map((user) => {
      const id = String(user?.id ?? "").trim();
      if (!id) return null;
      const fullName = String(user?.fullName ?? user?.username ?? "").trim();
      return {
        id,
        label: fullName || id,
        username: String(user?.username ?? "").trim(),
        role: normalizeUserRole(user?.role),
      };
    })
    .filter((entry) => entry !== null)
    .sort((a, b) => a.label.localeCompare(b.label, "it-IT"));
  const recentPrintJobs = sanitizePrintSpoolJobs(db.printSpoolJobs)
    .slice(-18)
    .reverse();

  return {
    ...buildPosSettingsPayload(settings),
    roomOptions,
    userOptions,
    recentPrintJobs,
  };
}

function normalizePrintLookupKey(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase();
}

function findConfiguredArea(settings, areaIdRaw) {
  const areaId = String(areaIdRaw ?? "").trim();
  if (!areaId) return null;
  return (
    (Array.isArray(settings?.areas) ? settings.areas : []).find(
      (entry) => entry.id === areaId,
    ) ?? null
  );
}

function pickPrinterFromIds(printerIds, printersById, purpose = "generic") {
  const printers = (Array.isArray(printerIds) ? printerIds : [])
    .map(
      (printerId) => printersById.get(String(printerId ?? "").trim()) ?? null,
    )
    .filter((printer) => printer && printer.active !== false);
  if (printers.length === 0) return null;
  if (purpose === "fiscal") {
    return (
      printers.find(
        (printer) => normalizePrinterPurpose(printer.purpose) === "fiscal",
      ) ?? null
    );
  }
  return (
    printers.find(
      (printer) => normalizePrinterPurpose(printer.purpose) !== "fiscal",
    ) ?? null
  );
}

function isPrinterCompatibleWithPurpose(printer, purpose = "generic") {
  if (!printer || printer.active === false) return false;
  const normalizedPurpose = normalizePrinterPurpose(purpose);
  const printerPurpose = normalizePrinterPurpose(printer.purpose);
  if (normalizedPurpose === "fiscal") return printerPurpose === "fiscal";
  return printerPurpose !== "fiscal";
}

function buildMissingPrintTargetErrorDetails(payload = {}) {
  return {
    kind: String(payload?.kind ?? "").trim() || null,
    printerId: String(payload?.printerId ?? "").trim() || null,
    activityId:
      String(
        payload?.activityId ?? payload?.operationalActivityId ?? "",
      ).trim() || null,
    roomId:
      String(
        payload?.roomId ?? payload?.areaId ?? payload?.operationalRoomId ?? "",
      ).trim() || null,
    workstationId:
      String(payload?.workstationId ?? payload?.stationId ?? "").trim() || null,
  };
}

function isResolvedPrintTargetUsable(resolvedTarget) {
  const printer = resolvedTarget?.printer;
  if (!printer || printer.active === false) return false;
  return String(printer.host ?? "").trim().length > 0;
}

function resolvePrintRoutingKind(payload = {}) {
  const rawKind = String(
    payload.kind ?? payload.printKind ?? payload.documentKind ?? "",
  )
    .trim()
    .toLowerCase();
  if (rawKind === "preconto" || rawKind.includes("preconto")) return "preconto";
  if (
    rawKind === "order" ||
    rawKind === "order_correction" ||
    rawKind === "order_cancellation" ||
    rawKind === "bar_replacement" ||
    rawKind.startsWith("order_")
  ) {
    return "order";
  }
  if (
    rawKind === "table_update" ||
    rawKind === "table_move" ||
    rawKind === "table_room_move" ||
    rawKind === "table_cancel_full" ||
    rawKind.startsWith("table_")
  ) {
    return "table_change";
  }
  return "generic";
}

function workstationAllowsPrint(workstation, routingKind) {
  if (!workstation || typeof workstation !== "object") return true;
  if (routingKind === "preconto")
    return workstation.printPrecontoEnabled !== false;
  if (routingKind === "order") return workstation.printOrderEnabled !== false;
  if (routingKind === "table_change")
    return workstation.printTableChangesEnabled !== false;
  return true;
}

function workstationUsesOwnPrinters(workstation) {
  if (!workstation || typeof workstation !== "object") return false;
  if (workstation.useOwnPrinters === true) return true;
  return (
    !Object.prototype.hasOwnProperty.call(workstation, "useOwnPrinters") &&
    Array.isArray(workstation.printerIds) &&
    workstation.printerIds.length > 0
  );
}

function pickRoutingPrinterIds(source, routingKind) {
  if (!source || typeof source !== "object") return [];
  if (
    routingKind === "preconto" &&
    Array.isArray(source.precontoPrinterIds) &&
    source.precontoPrinterIds.length > 0
  ) {
    return source.precontoPrinterIds;
  }
  return Array.isArray(source.printerIds) ? source.printerIds : [];
}

function findCashPointConfig(settings, deviceIdRaw, lookupRaw = "") {
  const deviceId = normalizeConfigId(deviceIdRaw, "");
  const lookupKey = normalizePrintLookupKey(lookupRaw || deviceIdRaw);
  for (const area of Array.isArray(settings?.areas) ? settings.areas : []) {
    for (const cashPoint of Array.isArray(area.cashPoints)
      ? area.cashPoints
      : []) {
      if (!cashPoint || typeof cashPoint !== "object") continue;
      if (
        deviceId &&
        (cashPoint.id === deviceId || cashPoint.code === deviceId)
      ) {
        return { area, cashPoint };
      }
      if (lookupKey) {
        const codeKey = normalizePrintLookupKey(cashPoint.code || "");
        const nameKey = normalizePrintLookupKey(cashPoint.name || "");
        if (codeKey === lookupKey || nameKey === lookupKey) {
          return { area, cashPoint };
        }
      }
    }
  }
  return null;
}

function findWorkstationConfig(settings, deviceIdRaw, stationRaw = "") {
  const deviceId = String(deviceIdRaw ?? "").trim();
  const stationKey = normalizePrintLookupKey(stationRaw);
  const resolvedDeviceId = resolveConfiguredWorkstationId(
    settings,
    deviceIdRaw,
  );
  const resolvedStationId = resolveConfiguredWorkstationId(
    settings,
    stationRaw,
  );
  const candidateIds = new Set(
    [deviceId, resolvedDeviceId, resolvedStationId]
      .map((entry) => String(entry ?? "").trim())
      .filter(Boolean),
  );
  for (const workstation of Array.isArray(settings?.workstations)
    ? settings.workstations
    : []) {
    if (!workstation || typeof workstation !== "object") continue;
    const workstationId = String(
      workstation.id ?? workstation.stationId ?? "",
    ).trim();
    const workstationNameKey = normalizePrintLookupKey(
      workstation.stationName || workstation.station || workstation.name,
    );
    if (
      (workstationId && candidateIds.has(workstationId)) ||
      (stationKey && workstationNameKey === stationKey)
    ) {
      const roomId = Array.isArray(workstation.roomIds)
        ? workstation.roomIds.find(Boolean)
        : "";
      return { area: findConfiguredArea(settings, roomId), workstation };
    }
  }
  for (const area of Array.isArray(settings?.areas) ? settings.areas : []) {
    for (const workstation of Array.isArray(area.workstations)
      ? area.workstations
      : []) {
      if (
        String(workstation?.id ?? "").trim() &&
        candidateIds.has(String(workstation.id ?? "").trim())
      ) {
        return { area, workstation };
      }
      if (stationKey) {
        const workstationNameKey = normalizePrintLookupKey(
          workstation.stationName || workstation.name,
        );
        if (workstationNameKey === stationKey) {
          return { area, workstation };
        }
      }
    }
  }
  return null;
}

function resolvePrinterFromOperationalContext(settings, payload = {}) {
  const schemaVersion = Number(
    payload.operationalSchemaVersion ??
      payload.schemaVersion ??
      payload.operationalSnapshot?.schemaVersion ??
      0,
  );
  const activityId = normalizeConfigId(
    payload.activityId ?? payload.operationalActivityId,
    "",
  );
  const roomId = normalizeConfigId(
    payload.roomId ?? payload.areaId ?? payload.operationalRoomId,
    "",
  );
  const isOperationalPayload = schemaVersion >= 2 || activityId;
  if (!isOperationalPayload) return null;
  const ignoreWorkstationRouting = payload.ignoreWorkstationRouting === true;
  if (!activityId || !roomId) {
    throw new HttpError(
      400,
      "activityId e roomId sono obbligatori per il routing operativo v2.",
      {
        code: "OPERATIONAL_CONTEXT_REQUIRED",
        activityId,
        roomId,
      },
    );
  }

  let operationalContext;
  try {
    operationalContext = resolveOperationalContext({
      settings,
      activityId,
      roomId,
      workstationId: ignoreWorkstationRouting
        ? ""
        : (payload.workstationId ?? payload.stationId ?? payload.station ?? ""),
      userId: payload.userId ?? payload.createdByUserId ?? "",
    });
  } catch (error) {
    if (error instanceof OperationalContextError) {
      throw new HttpError(error.status || 400, error.message, {
        code: error.code,
        ...(error.details && typeof error.details === "object"
          ? error.details
          : {}),
      });
    }
    throw error;
  }

  const printers = Array.isArray(settings?.printers) ? settings.printers : [];
  const printersById = new Map(
    printers.map((printer) => [printer.id, printer]),
  );
  const requestedPurpose = normalizePrinterPurpose(
    payload.printerPurpose ??
      (payload.fiscal === true || /fiscal/i.test(String(payload.kind ?? ""))
        ? "fiscal"
        : "generic"),
  );
  const routingKind = resolvePrintRoutingKind(payload);
  const workstationTarget = ignoreWorkstationRouting
    ? null
    : findWorkstationConfig(
        settings,
        payload.workstationId ??
          payload.stationId ??
          payload.deviceId ??
          payload.deviceUuid ??
          operationalContext.workstationId,
        payload.station ??
          payload.fallbackStation ??
          payload.preferredStation ??
          "",
      );
  const disabledWorkstation =
    workstationTarget?.workstation &&
    !workstationAllowsPrint(workstationTarget.workstation, routingKind);
  const resolveFiscalPrinter = () => {
    for (const fiscalDeviceId of Array.isArray(
      operationalContext.fiscalDeviceIds,
    )
      ? operationalContext.fiscalDeviceIds
      : []) {
      const safeFiscalDeviceId = normalizeConfigId(fiscalDeviceId, "");
      if (!safeFiscalDeviceId) continue;
      const directPrinter = printersById.get(safeFiscalDeviceId);
      if (
        directPrinter &&
        directPrinter.active !== false &&
        directPrinter.purpose === "fiscal"
      ) {
        return directPrinter;
      }
      if (safeFiscalDeviceId.startsWith("rt_")) {
        const printerId = safeFiscalDeviceId.slice(3);
        const printer = printersById.get(printerId);
        if (
          printer &&
          printer.active !== false &&
          printer.purpose === "fiscal"
        ) {
          return printer;
        }
      }
    }
    return null;
  };

  const resolveNonFiscalPrinter = () => {
    if (disabledWorkstation) return null;
    if (workstationUsesOwnPrinters(workstationTarget?.workstation)) {
      const workstationPrinter = pickPrinterFromIds(
        pickRoutingPrinterIds(workstationTarget.workstation, routingKind),
        printersById,
        requestedPurpose,
      );
      if (workstationPrinter) {
        return {
          printer: workstationPrinter,
          source: "operational_workstation",
        };
      }
    }
    const precontoIds =
      routingKind === "preconto" &&
      Array.isArray(operationalContext.effectivePrecontoPrinterIds)
        ? operationalContext.effectivePrecontoPrinterIds
        : [];
    const candidatePrinterIds =
      routingKind === "preconto"
        ? precontoIds
        : operationalContext.effectivePrinterIds;
    const printer = pickPrinterFromIds(
      candidatePrinterIds,
      printersById,
      requestedPurpose,
    );
    return printer
      ? {
          printer,
          source:
            routingKind === "preconto" && precontoIds.length > 0
              ? "operational_preconto_context"
              : "operational_context",
        }
      : null;
  };

  const resolvedPrinter =
    requestedPurpose === "fiscal"
      ? { printer: resolveFiscalPrinter(), source: "operational_context" }
      : resolveNonFiscalPrinter();
  const printer = resolvedPrinter?.printer ?? null;
  if (!printer) {
    return {
      printer: null,
      area: findConfiguredArea(settings, operationalContext.roomId),
      source: disabledWorkstation
        ? "operational_workstation_print_disabled"
        : "operational_context",
      operationalContext,
      warnings: [
        ...(Array.isArray(operationalContext.legacyWarnings)
          ? operationalContext.legacyWarnings
          : []),
        {
          code: disabledWorkstation
            ? "workstation_print_disabled"
            : requestedPurpose === "fiscal"
              ? "activity_fiscal_printer_missing"
              : routingKind === "preconto"
                ? "operational_preconto_printer_missing"
                : "operational_printer_missing",
          message: disabledWorkstation
            ? "La postazione corrente ha disabilitato questo tipo di stampa."
            : requestedPurpose === "fiscal"
              ? "Nessuna RT attiva configurata sull'attivita corrente."
              : routingKind === "preconto"
                ? "Nessuna stampante preconto dedicata attiva risolta dal contesto operativo."
                : "Nessuna stampante non fiscale attiva risolta dal contesto operativo.",
        },
      ],
    };
  }

  return {
    printer,
    area: findConfiguredArea(settings, operationalContext.roomId),
    source: resolvedPrinter?.source ?? "operational_context",
    operationalContext,
    warnings: Array.isArray(operationalContext.legacyWarnings)
      ? operationalContext.legacyWarnings
      : [],
  };
}

function markLegacyPrinterTarget(
  target,
  reason = "legacy_configuration_resolution",
) {
  if (!target) return null;
  return {
    ...target,
    source: "legacy",
    legacySource: target.source || "unknown",
    legacy: true,
    warnings: [
      ...(Array.isArray(target.warnings) ? target.warnings : []),
      {
        code: reason,
        message:
          "Routing stampante risolto con fallback legacy: activityId+roomId mancanti o configurazione non migrata.",
      },
    ],
  };
}

function shouldRequireOrderOperationalContext(payload = {}) {
  const schemaVersion = Number(
    payload.operationalSchemaVersion ??
      payload.schemaVersion ??
      payload.operationalSnapshot?.schemaVersion ??
      0,
  );
  return (
    schemaVersion >= 2 ||
    payload.activityId !== undefined ||
    payload.operationalActivityId !== undefined
  );
}

function buildOrderOperationalSnapshot({ db, payload, user, tableId }) {
  const requireContext = shouldRequireOrderOperationalContext(payload);
  const activityId = normalizeConfigId(
    payload.activityId ?? payload.operationalActivityId,
    "",
  );
  const roomId = normalizeConfigId(
    payload.roomId ?? payload.areaId ?? payload.operationalRoomId,
    "",
  );
  if (!activityId && !requireContext) {
    return {
      snapshot: null,
      legacyWarning: {
        code: "legacy_order_without_activity_context",
        message:
          "Comanda creata senza activityId: compatibilita legacy, nessuno snapshot operativo v2 salvato.",
      },
    };
  }
  if (!activityId || !roomId) {
    throw new HttpError(
      400,
      "activityId e roomId sono obbligatori per creare comande operative v2.",
      {
        code: "OPERATIONAL_CONTEXT_REQUIRED",
        activityId,
        roomId,
      },
    );
  }

  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  let context;
  try {
    context = resolveOperationalContext({
      settings,
      activityId,
      roomId,
      workstationId:
        payload.workstationId ?? payload.stationId ?? payload.station ?? "",
      userId: user?.id ?? payload.userId ?? "",
    });
  } catch (error) {
    if (error instanceof OperationalContextError) {
      throw new HttpError(error.status || 400, error.message, {
        code: error.code,
        ...(error.details && typeof error.details === "object"
          ? error.details
          : {}),
      });
    }
    throw error;
  }

  const fiscalTarget = resolvePrinterFromOperationalContext(settings, {
    activityId: context.activityId,
    roomId: context.roomId,
    workstationId: context.workstationId,
    printerPurpose: "fiscal",
  });
  const nonFiscalTarget = resolvePrinterFromOperationalContext(settings, {
    activityId: context.activityId,
    roomId: context.roomId,
    workstationId: context.workstationId,
    printerPurpose: "production",
    kind: "order",
  });
  const precontoTarget = resolvePrinterFromOperationalContext(settings, {
    activityId: context.activityId,
    roomId: context.roomId,
    workstationId: context.workstationId,
    printerPurpose: "production",
    kind: "preconto",
  });
  const settingsVersion = resolveSettingsVersion(db.meta);
  return {
    snapshot: {
      schemaVersion: 2,
      settingsVersion,
      localeId: context.localeId,
      activityId: context.activityId,
      roomId: context.roomId,
      tableId: String(tableId ?? payload.tableId ?? "").trim(),
      menuIds: context.effectiveMenuIds,
      priceListIds: context.effectivePriceListIds,
      fiscalPolicy: context.fiscalPolicy,
      fiscalDeviceIds: context.fiscalDeviceIds,
      printerRouting: {
        fiscalPrinterId: fiscalTarget?.printer?.id ?? null,
        fiscalSource: fiscalTarget?.source ?? null,
        nonFiscalPrinterIds: context.effectivePrinterIds,
        primaryNonFiscalPrinterId: nonFiscalTarget?.printer?.id ?? null,
        nonFiscalSource: nonFiscalTarget?.source ?? null,
        precontoPrinterIds: context.effectivePrecontoPrinterIds,
        primaryPrecontoPrinterId: precontoTarget?.printer?.id ?? null,
        precontoSource: precontoTarget?.source ?? null,
        legacyWarnings: [
          ...(Array.isArray(context.legacyWarnings)
            ? context.legacyWarnings
            : []),
          ...(Array.isArray(fiscalTarget?.warnings)
            ? fiscalTarget.warnings
            : []),
          ...(Array.isArray(nonFiscalTarget?.warnings)
            ? nonFiscalTarget.warnings
            : []),
          ...(Array.isArray(precontoTarget?.warnings)
            ? precontoTarget.warnings
            : []),
        ],
      },
      resolvedAt: context.resolvedAt,
    },
    legacyWarning: null,
  };
}

function resolvePrinterFromSettings(settings, payload = {}) {
  const printers = Array.isArray(settings?.printers) ? settings.printers : [];
  const printersById = new Map(
    printers.map((printer) => [printer.id, printer]),
  );
  const requestedPurpose = normalizePrinterPurpose(
    payload.printerPurpose ??
      (payload.fiscal === true || /fiscal/i.test(String(payload.kind ?? ""))
        ? "fiscal"
        : "generic"),
  );
  const routingKind = resolvePrintRoutingKind(payload);
  const explicitPrinterTarget = resolveExplicitPrinterTarget(payload);
  const explicitPrinterId = normalizeConfigId(payload.printerId, "");
  if (explicitPrinterId) {
    const printer = printersById.get(explicitPrinterId);
    if (printer && isPrinterCompatibleWithPurpose(printer, requestedPurpose)) {
      return markLegacyPrinterTarget(
        { printer, area: null, source: "explicit" },
        "legacy_explicit_printer_resolution",
      );
    }
    if (printer && printer.active !== false) {
      throw new HttpError(
        400,
        "Stampante non compatibile con il tipo di documento richiesto.",
        {
          code: "PRINTER_PURPOSE_MISMATCH",
          printerId: explicitPrinterId,
          requestedPurpose,
          printerPurpose: normalizePrinterPurpose(printer.purpose),
        },
      );
    }
    return null;
  }
  const operationalTarget = resolvePrinterFromOperationalContext(
    settings,
    payload,
  );
  if (operationalTarget) {
    return operationalTarget.printer ? operationalTarget : null;
  }

  const cashPointMatch = findCashPointConfig(
    settings,
    payload.cashPointId ?? payload.deviceId ?? payload.deviceUuid,
    payload.cashPointCode ??
      payload.deviceUuid ??
      payload.deviceId ??
      payload.cashPointName,
  );
  if (cashPointMatch) {
    const { area, cashPoint } = cashPointMatch;
    const fiscalPrinter =
      requestedPurpose === "fiscal" && cashPoint.fiscalPrinterId
        ? (printersById.get(cashPoint.fiscalPrinterId) ?? null)
        : null;
    const printer =
      fiscalPrinter && fiscalPrinter.active !== false
        ? fiscalPrinter
        : pickPrinterFromIds(
            cashPoint.printerIds,
            printersById,
            requestedPurpose,
          );
    if (printer) {
      return markLegacyPrinterTarget(
        {
          printer,
          area,
          source: "cash_point",
          deviceId: cashPoint.id,
          deviceName: cashPoint.name,
        },
        "legacy_cash_point_resolution",
      );
    }
    return null;
  }

  const workstationMatch = findWorkstationConfig(
    settings,
    payload.workstationId ?? payload.deviceId,
    payload.station,
  );
  if (workstationMatch) {
    const { area, workstation } = workstationMatch;
    if (!workstationAllowsPrint(workstation, routingKind)) {
      return null;
    }
    const usesOwnPrinters = workstationUsesOwnPrinters(workstation);
    const printer = usesOwnPrinters
      ? pickPrinterFromIds(
          pickRoutingPrinterIds(workstation, routingKind),
          printersById,
          requestedPurpose,
        )
      : pickPrinterFromIds(
          pickRoutingPrinterIds(area, routingKind),
          printersById,
          requestedPurpose,
        );
    if (printer) {
      return markLegacyPrinterTarget(
        {
          printer,
          area,
          source: usesOwnPrinters ? "workstation" : "workstation_area",
          deviceId: workstation.id,
          deviceName: workstation.name,
        },
        "legacy_workstation_resolution",
      );
    }
    return null;
  }

  const area = findConfiguredArea(settings, payload.areaId ?? payload.roomId);
  if (area) {
    const printer = pickPrinterFromIds(
      pickRoutingPrinterIds(area, routingKind),
      printersById,
      requestedPurpose,
    );
    if (printer) {
      return markLegacyPrinterTarget(
        { printer, area, source: "area" },
        "legacy_room_printer_resolution",
      );
    }
  }

  if (explicitPrinterTarget) {
    throw new HttpError(
      400,
      "Host stampante esplicito non consentito senza una stampante configurata.",
      {
        code: "EXPLICIT_PRINTER_HOST_NOT_ALLOWED",
        printerHost: explicitPrinterTarget?.printer?.host ?? null,
        printerPort: explicitPrinterTarget?.printer?.port ?? null,
      },
    );
  }

  return null;
}

function buildPrintPrependChunks(kind, printPreferences) {
  const safePreferences = sanitizePosPrintPreferences(
    printPreferences ?? DEFAULT_POS_SETTINGS.printPreferences,
  );
  if (
    String(kind ?? "")
      .trim()
      .toLowerCase() !== "preconto"
  ) {
    return [];
  }
  if (
    !safePreferences.preconto.showLogo ||
    !safePreferences.branding.logoEscposBase64
  ) {
    return [];
  }
  try {
    const logoBuffer = Buffer.from(
      safePreferences.branding.logoEscposBase64,
      "base64",
    );
    if (!logoBuffer || logoBuffer.length === 0) {
      return [];
    }
    return [
      Buffer.from([0x1b, 0x61, 0x01]),
      logoBuffer,
      Buffer.from("\r\n", "utf8"),
      Buffer.from([0x1b, 0x61, 0x00]),
    ];
  } catch {
    return [];
  }
}

function buildPrintJobOptions(kind, source) {
  const rawPreferences =
    source &&
    typeof source === "object" &&
    source.printPreferences &&
    typeof source.printPreferences === "object"
      ? source.printPreferences
      : source;
  const safePreferences = sanitizePosPrintPreferences(
    rawPreferences ?? DEFAULT_POS_SETTINGS.printPreferences,
  );
  const printKind = String(kind ?? "")
    .trim()
    .toLowerCase();
  const requestedByClientApp = normalizeClientApp(
    source?.requestedBy?.clientApp ?? source?.clientApp ?? "",
  );
  const shouldBeep = [
    "order",
    "order_correction",
    "order_cancellation",
    "bar_replacement",
  ].includes(printKind);
  if (printKind === "order") {
    return {
      kind: printKind,
      beep: shouldBeep,
      fontScalePercent: 100,
      charWidthMode: "normal",
      charSpacing: 0,
      lineSpacing: 0,
      bold: false,
      italic: false,
      underline: false,
      prependChunks: [],
    };
  }
  if (printKind === "preconto") {
    const isCashPreconto =
      requestedByClientApp === "cassa-frontend" ||
      source?.precontoProfile === "cash";
    return {
      kind: printKind,
      fontScalePercent: isCashPreconto ? 120 : 100,
      charWidthMode: "normal",
      charSpacing: 0,
      lineSpacing: isCashPreconto ? 8 : safePreferences.preconto.lineSpacing,
      bold: false,
      italic: false,
      underline: false,
      prependChunks: isCashPreconto
        ? []
        : buildPrintPrependChunks(printKind, safePreferences),
    };
  }
  return {
    kind: printKind,
    beep: shouldBeep,
    prependChunks: [],
  };
}

function buildEscPosBeepChunks(options = {}) {
  if (options?.beep !== true) return [];
  // Il beep viene inviato come comando separato prima del job di stampa:
  // tenerlo nel payload della comanda puo sporcare il layout su alcune ESC/POS.
  return [];
}

async function probeNetworkPrinter(
  printer,
  timeoutMs = PRINT_SPOOL_PRINTER_PROBE_TIMEOUT_MS,
) {
  const host = String(printer?.host ?? "").trim();
  const port = normalizePrinterPort(printer?.port);
  if (!host) return false;
  return new Promise((resolve) => {
    const socket = createConnection({ host, port });
    let settled = false;
    const settle = (ok) => {
      if (settled) return;
      settled = true;
      try {
        socket.destroy();
      } catch {
        // noop
      }
      resolve(ok);
    };
    socket.setTimeout(timeoutMs);
    socket.once("connect", () => settle(true));
    socket.once("timeout", () => settle(false));
    socket.once("error", () => settle(false));
  });
}

async function sendNetworkPrinterBeep(printer, options = {}) {
  const repeats = clampInt(options?.beepRepeats, 1, 9, 2);
  const duration = clampInt(options?.beepDuration, 1, 9, 3);
  const payloadBuffer = Buffer.concat([
    Buffer.from([0x1b, 0x40]),
    Buffer.from([0x1b, 0x42, repeats, duration]),
    Buffer.from([0x07]),
  ]);

  await new Promise((resolve, reject) => {
    const socket = createConnection({
      host: printer.host,
      port: printer.port,
    });
    let settled = false;
    const resolveOnce = () => {
      if (settled) return;
      settled = true;
      resolve();
    };
    const rejectOnce = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    socket.setTimeout(PRINT_TCP_TIMEOUT_MS);
    socket.setNoDelay(true);
    socket.once("connect", () => {
      let endScheduled = false;
      const endSocket = () => {
        if (endScheduled) return;
        endScheduled = true;
        setTimeout(() => {
          try {
            socket.end(() => {
              resolveOnce();
            });
          } catch {
            resolveOnce();
          }
        }, PRINT_TCP_END_DELAY_MS);
      };
      const flushed = socket.write(payloadBuffer, () => {
        endSocket();
      });
      if (!flushed) {
        socket.once("drain", endSocket);
      }
    });
    socket.once("close", () => {
      resolveOnce();
    });
    socket.once("timeout", () => {
      rejectOnce(new Error("Timeout beep stampante."));
      socket.destroy();
    });
    socket.once("error", (error) => {
      rejectOnce(error);
      socket.destroy();
    });
  });
}

async function sendNetworkDrawerKick(printer, options = {}) {
  const pulsePin = clampInt(options?.pulsePin, 0, 1, 0);
  const pulseOn = clampInt(options?.pulseOn, 1, 255, 25);
  const pulseOff = clampInt(options?.pulseOff, 1, 255, 250);
  const payloadBuffer = Buffer.from([
    0x1b,
    0x40,
    0x1b,
    0x70,
    pulsePin,
    pulseOn,
    pulseOff,
  ]);

  await new Promise((resolve, reject) => {
    const socket = createConnection({
      host: printer.host,
      port: printer.port,
    });
    let settled = false;
    const resolveOnce = () => {
      if (settled) return;
      settled = true;
      resolve();
    };
    const rejectOnce = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    socket.setTimeout(PRINT_TCP_TIMEOUT_MS);
    socket.setNoDelay(true);
    socket.once("connect", () => {
      let endScheduled = false;
      const endSocket = () => {
        if (endScheduled) return;
        endScheduled = true;
        setTimeout(() => {
          try {
            socket.end(() => {
              resolveOnce();
            });
          } catch {
            resolveOnce();
          }
        }, 180);
      };
      const flushed = socket.write(payloadBuffer, () => {
        endSocket();
      });
      if (!flushed) {
        socket.once("drain", endSocket);
      }
    });
    socket.once("close", () => {
      resolveOnce();
    });
    socket.once("timeout", () => {
      rejectOnce(new Error("Timeout apertura cassetto."));
      socket.destroy();
    });
    socket.once("error", (error) => {
      rejectOnce(error);
      socket.destroy();
    });
  });
}

function buildEscPosPrintPayloadBuffer(text, options = {}) {
  const printableTextBuffer = buildEscPosTextBufferWithRawMarkers(text);
  const kind = String(options?.kind ?? "")
    .trim()
    .toLowerCase();
  const isPreconto = kind === "preconto";
  const prependChunks = Array.isArray(options?.prependChunks)
    ? options.prependChunks.filter(
        (entry) => Buffer.isBuffer(entry) && entry.length > 0,
      )
    : [];
  const fontScalePercent = clampInt(options?.fontScalePercent, 80, 220, 100);
  const charSpacing = clampInt(options?.charSpacing, 0, 8, isPreconto ? 1 : 0);
  const lineSpacing = clampInt(
    options?.lineSpacing,
    0,
    48,
    isPreconto ? 34 : 0,
  );
  const underline = options?.underline === true;
  const bold = options?.bold === true;
  const italic = options?.italic === true;
  const charWidthMode = normalizePrintCharWidthMode(options?.charWidthMode);
  const heightScale = fontScalePercent >= 150 ? 1 : 0;
  const widthScale =
    charWidthMode === "extra_wide" ? 2 : charWidthMode === "wide" ? 1 : 0;
  const sizeByte = ((widthScale & 0x07) << 4) | (heightScale & 0x07);
  const styleChunks = [
    Buffer.from([0x1b, 0x20, charSpacing]),
    lineSpacing > 0
      ? Buffer.from([0x1b, 0x33, lineSpacing])
      : Buffer.from([0x1b, 0x32]),
    Buffer.from([0x1b, 0x45, bold ? 0x01 : 0x00]),
    Buffer.from([0x1b, 0x34, italic ? 0x01 : 0x00]),
    Buffer.from([0x1b, 0x2d, underline ? 0x01 : 0x00]),
    Buffer.from([0x1d, 0x21, sizeByte]),
  ];
  const resetChunks = [
    Buffer.from([0x1d, 0x21, 0x00]),
    Buffer.from([0x1b, 0x2d, 0x00]),
    Buffer.from([0x1b, 0x34, 0x00]),
    Buffer.from([0x1b, 0x45, 0x00]),
    Buffer.from([0x1b, 0x20, 0x00]),
    Buffer.from([0x1b, 0x32]),
  ];
  return Buffer.concat([
    Buffer.from([0x1b, 0x40]),
    Buffer.from([0x1b, 0x74, 0x00]),
    ...buildEscPosBeepChunks(options),
    ...prependChunks,
    ...styleChunks,
    printableTextBuffer,
    ...resetChunks,
    Buffer.from("\r\n\r\n", "utf8"),
    Buffer.from([0x1b, 0x64, 0x02]),
    Buffer.from([0x1d, 0x56, 0x41, 0x01]),
  ]);
}

async function sendNetworkPrintJob(printer, text, options = {}) {
  if (options?.beep === true) {
    await sendNetworkPrinterBeep(printer, options).catch((error) => {
      const reason = error instanceof Error ? error.message : String(error);
      console.warn(`[print] Beep stampante non riuscito: ${reason}`);
    });
  }

  const payloadBuffer = buildEscPosPrintPayloadBuffer(text, {
    ...options,
    beep: false,
  });
  await new Promise((resolve, reject) => {
    const socket = createConnection({
      host: printer.host,
      port: printer.port,
    });
    let settled = false;
    const resolveOnce = () => {
      if (settled) return;
      settled = true;
      resolve();
    };
    const rejectOnce = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    socket.setTimeout(PRINT_TCP_TIMEOUT_MS);
    socket.setNoDelay(true);
    socket.once("connect", () => {
      let endScheduled = false;
      const endSocket = () => {
        if (endScheduled) return;
        endScheduled = true;
        setTimeout(() => {
          try {
            socket.end(() => {
              resolveOnce();
            });
          } catch {
            resolveOnce();
          }
        }, 180);
      };
      const flushed = socket.write(payloadBuffer, () => {
        endSocket();
      });
      if (!flushed) {
        socket.once("drain", endSocket);
      }
    });
    socket.once("close", () => {
      resolveOnce();
    });
    socket.once("timeout", () => {
      rejectOnce(new Error("Timeout di connessione stampante."));
      socket.destroy();
    });
    socket.once("error", (error) => {
      rejectOnce(error);
      socket.destroy();
    });
  });
}

async function printFileWithWindowsDefault(filePath) {
  await new Promise((resolve, reject) => {
    let child;
    let timeoutHandle;
    let settled = false;

    const cleanup = () => {
      if (timeoutHandle) {
        clearTimeout(timeoutHandle);
        timeoutHandle = null;
      }
      if (child) {
        child.removeAllListeners("error");
        child.removeAllListeners("close");
      }
    };

    const settle = (error = null) => {
      if (settled) return;
      settled = true;
      cleanup();
      if (error) {
        reject(error);
      } else {
        resolve();
      }
    };

    try {
      child = spawn("notepad.exe", ["/p", filePath], {
        windowsHide: true,
        stdio: "ignore",
      });
    } catch (error) {
      settle(
        error instanceof Error
          ? error
          : new Error(String(error ?? "comando non riuscito")),
      );
      return;
    }

    timeoutHandle = setTimeout(() => {
      try {
        child.kill();
      } catch {
        // noop: il processo puo essere gia terminato
      }
      settle(new Error("Timeout stampa Windows predefinita."));
    }, PRINT_WINDOWS_DEFAULT_TIMEOUT_MS);

    child.once("error", (error) => {
      settle(
        error instanceof Error
          ? error
          : new Error(String(error ?? "comando non riuscito")),
      );
    });
    child.once("close", (code, signal) => {
      if (code === 0) {
        settle();
        return;
      }
      if (signal) {
        settle(new Error(`processo terminato da segnale ${signal}`));
        return;
      }
      settle(
        new Error(`codice ${typeof code === "number" ? code : "sconosciuto"}`),
      );
    });
  });
}

function resolveCupsPrinterName(source = {}) {
  const candidates = [
    PRINT_CUPS_DEFAULT_PRINTER,
    source?.cupsPrinter,
    source?.printerQueue,
    source?.printerName,
  ];
  for (const candidate of candidates) {
    const normalized = String(candidate ?? "").trim();
    if (!normalized || /^default$/i.test(normalized)) continue;
    if (/^[A-Za-z0-9_.@:-]{1,128}$/.test(normalized)) return normalized;
  }
  return "";
}

function isCommandNotFoundError(error) {
  return (
    error?.code === "ENOENT" ||
    /not found|no such file/i.test(String(error?.message ?? ""))
  );
}

function supportsLocalDefaultPrintFallback() {
  return false;
}

async function runPrintCommand(command, args, inputBuffer, timeoutMs, label) {
  await new Promise((resolve, reject) => {
    let child;
    let timeoutHandle;
    let stderr = "";
    let settled = false;

    const cleanup = () => {
      if (timeoutHandle) {
        clearTimeout(timeoutHandle);
        timeoutHandle = null;
      }
      if (child) {
        child.removeAllListeners("error");
        child.removeAllListeners("close");
        if (child.stderr) child.stderr.removeAllListeners("data");
      }
    };

    const settle = (error = null) => {
      if (settled) return;
      settled = true;
      cleanup();
      if (error) reject(error);
      else resolve();
    };

    try {
      child = spawn(command, args, {
        stdio: ["pipe", "ignore", "pipe"],
        windowsHide: true,
      });
    } catch (error) {
      settle(
        error instanceof Error
          ? error
          : new Error(String(error ?? "comando non riuscito")),
      );
      return;
    }

    timeoutHandle = setTimeout(() => {
      try {
        child.kill();
      } catch {
        // noop: il processo puo essere gia terminato
      }
      settle(new Error(`Timeout ${label}.`));
    }, timeoutMs);

    if (child.stderr) {
      child.stderr.on("data", (chunk) => {
        stderr =
          `${stderr}${chunk instanceof Buffer ? chunk.toString("utf8") : String(chunk)}`.slice(
            -2000,
          );
      });
    }

    child.once("error", (error) => {
      settle(
        error instanceof Error
          ? error
          : new Error(String(error ?? "comando non riuscito")),
      );
    });
    child.once("close", (code, signal) => {
      if (code === 0) {
        settle();
        return;
      }
      const suffix = stderr.trim() ? `: ${stderr.trim()}` : "";
      if (signal) {
        settle(
          new Error(
            `${label}: processo terminato da segnale ${signal}${suffix}`,
          ),
        );
        return;
      }
      settle(
        new Error(
          `${label}: codice ${typeof code === "number" ? code : "sconosciuto"}${suffix}`,
        ),
      );
    });

    try {
      if (inputBuffer && inputBuffer.length > 0) child.stdin.end(inputBuffer);
      else child.stdin.end();
    } catch (error) {
      settle(
        error instanceof Error
          ? error
          : new Error(String(error ?? "input stampa non riuscito")),
      );
    }
  });
}

async function printWithCups(text, source = {}) {
  const payloadBuffer = buildEscPosPrintPayloadBuffer(
    text,
    buildPrintJobOptions(source.kind, source),
  );
  const printerName = resolveCupsPrinterName(source);
  const lpArgs = ["-o", "raw"];
  if (printerName) lpArgs.push("-d", printerName);
  const lprArgs = [];
  if (printerName) lprArgs.push("-P", printerName);
  lprArgs.push("-o", "raw");

  let lpError = null;
  try {
    await runPrintCommand(
      "lp",
      lpArgs,
      payloadBuffer,
      PRINT_CUPS_DEFAULT_TIMEOUT_MS,
      "stampa CUPS lp",
    );
    return;
  } catch (error) {
    lpError =
      error instanceof Error
        ? error
        : new Error(String(error ?? "stampa CUPS lp non riuscita"));
  }

  try {
    await runPrintCommand(
      "lpr",
      lprArgs,
      payloadBuffer,
      PRINT_CUPS_DEFAULT_TIMEOUT_MS,
      "stampa CUPS lpr",
    );
    return;
  } catch (error) {
    const lprError =
      error instanceof Error
        ? error
        : new Error(String(error ?? "stampa CUPS lpr non riuscita"));
    if (isCommandNotFoundError(lpError) && isCommandNotFoundError(lprError)) {
      throw new Error("Comandi CUPS lp/lpr non disponibili sul sistema.");
    }
    throw new Error(
      `Stampa CUPS non riuscita. lp: ${lpError.message}; lpr: ${lprError.message}`,
    );
  }
}

