async function scheduleOrderCreateAutoPrint({ orderId, payloads, db, settings }) {
  const plans = normalizeAutoPrintOwnerPlans([{
    batchId: buildAutoPrintOwnerBatchId(orderId),
    payloads,
  }]);
  if (backendProcessRouteGuard.role === "api-worker") {
    if (!PRINT_SPOOL_SQL_PRIMARY || process.env.PRINT_SPOOL_AUTO_PRINT_REMOTE_OWNER !== "1") {
      runtimeMetrics.incrementCounter("printSpoolAutoPrintRemoteOwnerMisconfigured");
      throw new Error("Auto-print owner obbligatorio ma non configurato sull'API worker.");
    }
    const plan = plans[0];
    if (!printSpoolAutoPrintOwnerQueue.enqueue(plan.batchId, plan)) {
      throw new Error("Piano auto-print non accodabile.");
    }
    return { queued: true, remoteOwner: true };
  }
  const result = await withPrintLaneMutation(
    `owner auto-print ${orderId}`,
    [`order:${orderId}`],
    () => persistAutoPrintOwnerPlans(plans, { db, settings }),
    { metricLabel: "owner auto-print", shouldPreserveHotCaches: () => true },
  );
  return { queued: true, remoteOwner: false, ...result };
}

async function handleInternalPrintSpoolAutoPrint(req, res) {
  if (!SHOULD_RUN_BACKEND_OWNER_JOBS) {
    sendJson(res, 409, {
      ok: false,
      code: "PRINT_SPOOL_AUTO_PRINT_OWNER_REQUIRED",
      error: "Auto-print disponibile solo sull'owner.",
    });
    return;
  }
  if (!PRINT_SPOOL_SQL_PRIMARY) {
    sendJson(res, 409, {
      ok: false,
      code: "PRINT_SPOOL_SQL_PRIMARY_REQUIRED",
      error: "Coda stampa relazionale non disponibile.",
    });
    return;
  }
  let plans;
  try {
    plans = normalizeAutoPrintOwnerPlans((await readJsonBody(req))?.plans);
  } catch (error) {
    throw new HttpError(400, "Piano auto-print non valido.", {
      code: error?.code ?? "AUTO_PRINT_OWNER_PAYLOAD_INVALID",
    });
  }
  const result = await withPrintLaneMutation(
    `owner auto-print batch ${plans[0]?.batchId ?? "empty"}`,
    plans.flatMap((plan) => plan.payloads.map((payload) => `order:${payload.orderId}`)),
    () => persistAutoPrintOwnerPlans(plans),
    { metricLabel: "owner auto-print batch", shouldPreserveHotCaches: () => true },
  );
  runtimeMetrics.incrementCounter("printSpoolAutoPrintRemoteOwnerHandled", result.accepted);
  sendJson(res, 202, { ok: true, ...result });
}

