function requirePrintSpoolSqlPrimaryRepository() {
  const repo = getPrintSpoolRepository();
  if (repo) return repo;
  throw new HttpError(503, "Coda stampa SQL non disponibile.", {
    code: "PRINT_SPOOL_SQL_PRIMARY_UNAVAILABLE",
  });
}

function toRuntimePrintSpoolJob(sqlJob) {
  if (!sqlJob || typeof sqlJob !== "object") return null;
  const payload = sqlJob.payload && typeof sqlJob.payload === "object" ? sqlJob.payload : {};
  const sqlStatus = String(sqlJob.status ?? "").trim();
  const runtimeStatus =
    sqlStatus === "claimed" || sqlStatus === "sent"
      ? "processing"
      : sqlStatus === "confirmed"
        ? "printed"
        : sqlStatus === "failed_retryable"
          ? "queued"
          : sqlStatus === "failed_final"
            ? "failed"
            : payload.status ?? sqlStatus;
  const runtimePrintState = [
    "claimed",
    "sent",
    "confirmed",
    "failed_retryable",
    "failed_final",
  ].includes(sqlStatus)
    ? sqlStatus
    : payload.printState;
  const runtimePrintStatePath =
    sqlStatus === "claimed"
      ? ["queued", "claimed"]
      : sqlStatus === "sent"
        ? ["queued", "claimed", "sent"]
        : sqlStatus === "confirmed"
          ? ["queued", "claimed", "sent", "confirmed"]
          : sqlStatus === "failed_retryable"
            ? ["queued", "claimed", "sent", "failed_retryable"]
            : sqlStatus === "failed_final"
              ? ["queued", "claimed", "sent", "failed_final"]
              : payload.printStatePath;
  return sanitizePrintSpoolJob(
    {
      ...payload,
      id: sqlJob.id,
      status: runtimeStatus,
      printState: runtimePrintState,
      printStatePath: runtimePrintStatePath,
      kind: sqlJob.kind ?? payload.kind,
      orderId: sqlJob.orderId ?? payload.orderId,
      printerId: sqlJob.printerId ?? payload.printerId,
      printerHost: sqlJob.printerHost ?? payload.printerHost,
      printerPort: sqlJob.printerPort ?? payload.printerPort,
      requestedAt: sqlJob.requestedAt ?? payload.requestedAt,
      lastAttemptAt: sqlJob.claimedAt ?? payload.lastAttemptAt,
      nextRetryAt: sqlJob.nextRetryAt ?? payload.nextRetryAt,
      errorMessage: sqlJob.lastError ?? payload.errorMessage,
      attempts: Math.max(0, Math.trunc(Number(sqlJob.attemptCount ?? payload.attempts) || 0)),
    },
    sqlJob.id,
  );
}

async function enqueuePrintSpoolJobSqlPrimary(payload, options = {}) {
  const acceptStartedAt = Date.now();
  const repo = requirePrintSpoolSqlPrimaryRepository();
  const db = options.db && typeof options.db === "object" ? options.db : await readDb();
  const nextJob = buildPrintSpoolJobFromPayload(db, payload, {
    throwOnMissingTarget: options.throwOnMissingTarget === true,
    defaultPrinterName: options.defaultPrinterName,
  });
  await persistPrintSpoolJobFile(nextJob, payload);
  repo.enqueue({
    id: nextJob.id,
    status: nextJob.status,
    kind: nextJob.kind,
    orderId: nextJob.orderId,
    printerId: nextJob.printerId,
    printerHost: nextJob.printerHost,
    printerPort: nextJob.printerPort,
    errorMessage: nextJob.errorMessage,
    requestedAt: nextJob.requestedAt,
    payload: nextJob,
  });
  runtimeMetrics.recordOperation("printSpool", "accept", Date.now() - acceptStartedAt);
  emitPrintRequestedEvent(nextJob);
  if (PRINT_SPOOL_INITIAL_STATUS_EVENTS) emitPrintStatusEvent(nextJob, nextJob.status); else runtimeMetrics.incrementCounter("printSpoolInitialEventsSkipped");
  refreshPrintSpoolQueueGauges();
  if (PRINT_SPOOL_LEGACY_MIRROR_ENABLED && options.appendLegacyMirrorToDb === true && process.env.PRINT_SPOOL_LEGACY_MIRROR_REMOTE_OWNER !== "1") {
    upsertLegacyPrintSpoolMirror(db, nextJob);
  } else {
    mirrorLegacyPrintSpoolJobBestEffort(nextJob, "enqueue");
  }
  if (PRINTING_ENABLED && nextJob.status === "queued") queuePrintSpoolWorker();
  return nextJob;
}

async function claimNextPrintSpoolJobSqlPrimary() {
  const repo = getPrintSpoolRepository();
  if (!repo) {
    console.warn("[print-spool] PRINT_SPOOL_SQL_PRIMARY=1 ma repository SQL non disponibile.");
    return null;
  }
  const claimed = repo.claimNext({
    workerId: process.env.BACKEND_PROCESS_ROLE || "worker",
    leaseMs: PRINT_SPOOL_CLAIM_LEASE_MS,
  });
  if (!claimed) return null;
  runtimeMetrics.incrementCounter("printSpoolClaimed");
  refreshPrintSpoolQueueGauges();
  return toRuntimePrintSpoolJob(claimed);
}

function buildCompletedPrintSpoolJob(
  currentJob,
  safeJobId,
  safeStatus,
  errorMessage = "",
) {
  const completedAt = nowIso();
  const failureMessage = String(errorMessage || "Errore stampa sconosciuto.");
  const nextAttempts =
    safeStatus === "failed"
      ? Math.max(Math.trunc(Number(currentJob.attempts) || 0), 0) + 1
      : currentJob.attempts;
  const retryableJob = {
    ...currentJob,
    attempts: nextAttempts,
  };
  const shouldRetry =
    safeStatus === "failed" &&
    shouldRetryPrintSpoolJob(retryableJob, failureMessage);
  const terminalPrintState =
    safeStatus === "printed"
      ? "confirmed"
      : shouldRetry
        ? "failed_retryable"
        : "failed_final";
  const stateJob = applyPrintSpoolCompletionStateTransition(
    retryableJob,
    terminalPrintState,
  );

  return sanitizePrintSpoolJob(
    {
      ...stateJob,
      status: shouldRetry ? "queued" : safeStatus,
      attempts: nextAttempts,
      lastAttemptAt: completedAt,
      nextRetryAt: shouldRetry
        ? new Date(Date.now() + PRINT_SPOOL_RETRY_DELAY_MS).toISOString()
        : null,
      processedAt:
        shouldRetry || safeStatus !== "failed"
          ? safeStatus === "printed"
            ? completedAt
            : null
          : completedAt,
      errorMessage:
        safeStatus === "failed"
          ? shouldRetry
            ? `Riprovo stampa (${nextAttempts}/${PRINT_SPOOL_RETRY_MAX_ATTEMPTS}): ${failureMessage}`
            : failureMessage
          : "",
    },
    safeJobId,
  );
}

async function claimNextPrintSpoolJobFast() {
  const db = await readDb();
  const queue = sanitizePrintSpoolJobs(db.printSpoolJobs);
  const nextJob =
    queue.find((entry) => isPrintSpoolJobReadyForAttempt(entry)) ?? null;
  if (!nextJob) return null;

  const processingIndex = db.printSpoolJobs.findIndex(
    (entry) => String(entry?.id ?? "").trim() === nextJob.id,
  );
  if (processingIndex < 0) return null;

  const currentJob = sanitizePrintSpoolJob(
    db.printSpoolJobs[processingIndex],
    nextJob.id,
  );
  if (!currentJob) return null;

  const liveSettings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const printPreferenceSource =
    currentJob.printPreferences && typeof currentJob.printPreferences === "object"
      ? currentJob.printPreferences
      : liveSettings.printPreferences;

  const claimedJob = applyPrintSpoolClaimStateTransition(currentJob);
  const processingJob = sanitizePrintSpoolJob(
    {
      ...claimedJob,
      status: "processing",
      errorMessage: "",
      lastAttemptAt: nowIso(),
      nextRetryAt: null,
      printPreferences: printPreferenceSource,
    },
    nextJob.id,
  );
  db.printSpoolJobs[processingIndex] = processingJob;
  await syncSinglePrintSpoolJobFast(db, processingJob.id);
  return processingJob;
}

async function claimNextPrintSpoolJob() {
  if (PRINT_SPOOL_SQL_PRIMARY) {
    return claimNextPrintSpoolJobSqlPrimary();
  }
  if (canUsePrintSpoolFastWorker()) {
    try {
      return await claimNextPrintSpoolJobFast();
    } catch (error) {
      console.warn(
        `[print] Fast worker claim non riuscito, uso fallback: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
  }
  return withDbMutation("print_spool_claim_next", async () => {
    const db = await readDb();
    const queue = sanitizePrintSpoolJobs(db.printSpoolJobs);
    const nextJob =
      queue.find((entry) => isPrintSpoolJobReadyForAttempt(entry)) ?? null;
    if (!nextJob) return null;

    const processingIndex = db.printSpoolJobs.findIndex(
      (entry) => String(entry?.id ?? "").trim() === nextJob.id,
    );
    if (processingIndex < 0) return null;

    const currentJob = sanitizePrintSpoolJob(
      db.printSpoolJobs[processingIndex],
      nextJob.id,
    );
    if (!currentJob) return null;

    const liveSettings = sanitizePosSettings(db.posSettings, {
      menuItems: db.menuItems,
      users: db.users,
    });
    const printPreferenceSource =
      currentJob.printPreferences &&
      typeof currentJob.printPreferences === "object"
        ? currentJob.printPreferences
        : liveSettings.printPreferences;

    const claimedJob = applyPrintSpoolClaimStateTransition(currentJob);
    const processingJob = sanitizePrintSpoolJob(
      {
        ...claimedJob,
        status: "processing",
        errorMessage: "",
        lastAttemptAt: nowIso(),
        nextRetryAt: null,
        printPreferences: printPreferenceSource,
      },
      nextJob.id,
    );
    db.printSpoolJobs[processingIndex] = processingJob;
    db.meta.lastWriteAt = nowIso();
    await writePrintSpoolDb(db);
    return processingJob;
  }, { shouldPreserveHotCaches: () => true });
}

async function completePrintSpoolJobFast(
  safeJobId,
  safeStatus,
  errorMessage = "",
) {
  const db = await readDb();
  const jobIndex = db.printSpoolJobs.findIndex(
    (entry) => String(entry?.id ?? "").trim() === safeJobId,
  );
  if (jobIndex < 0) return null;

  const currentJob = sanitizePrintSpoolJob(
    db.printSpoolJobs[jobIndex],
    safeJobId,
  );
  if (!currentJob) return null;

  const completedJob = buildCompletedPrintSpoolJob(
    currentJob,
    safeJobId,
    safeStatus,
    errorMessage,
  );
  db.printSpoolJobs[jobIndex] = completedJob;
  await syncSinglePrintSpoolJobFast(db, completedJob.id);
  return completedJob;
}

async function completePrintSpoolJobSqlPrimary(jobId, status, errorMessage = "") {
  const safeJobId = String(jobId ?? "").trim();
  const safeStatus = PRINT_SPOOL_STATUSES.has(status) ? status : "failed";
  const repo = getPrintSpoolRepository();
  if (!repo || !safeJobId) return null;
  const currentJob = toRuntimePrintSpoolJob(repo.getById(safeJobId));
  if (!currentJob) return null;
  const completedJob = buildCompletedPrintSpoolJob(
    currentJob,
    safeJobId,
    safeStatus,
    errorMessage,
  );
  if (safeStatus === "printed") {
    repo.markConfirmed(safeJobId);
  } else {
    const retryable = completedJob.status === "queued" && Boolean(completedJob.nextRetryAt);
    repo.markFailed(safeJobId, {
      retryable,
      retryDelayMs: PRINT_SPOOL_RETRY_DELAY_MS,
      errorMessage: completedJob.errorMessage || errorMessage,
    });
  }
  mirrorLegacyPrintSpoolJobBestEffort(completedJob, "completion");
  refreshPrintSpoolQueueGauges();
  return completedJob;
}

async function completePrintSpoolJob(jobId, status, errorMessage = "") {
  const safeJobId = String(jobId ?? "").trim();
  const safeStatus = PRINT_SPOOL_STATUSES.has(status) ? status : "failed";
  if (PRINT_SPOOL_SQL_PRIMARY) {
    return completePrintSpoolJobSqlPrimary(safeJobId, safeStatus, errorMessage);
  }
  if (canUsePrintSpoolFastWorker()) {
    try {
      return await completePrintSpoolJobFast(
        safeJobId,
        safeStatus,
        errorMessage,
      );
    } catch (error) {
      console.warn(
        `[print] Fast worker complete non riuscito, uso fallback: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
  }
  return withDbMutation(
    `print_spool_${safeStatus}_${safeJobId || "unknown"}`,
    async () => {
      const db = await readDb();
      const jobIndex = db.printSpoolJobs.findIndex(
        (entry) => String(entry?.id ?? "").trim() === safeJobId,
      );
      if (jobIndex < 0) return null;

      const currentJob = sanitizePrintSpoolJob(
        db.printSpoolJobs[jobIndex],
        safeJobId,
      );
      if (!currentJob) return null;
      const completedJob = buildCompletedPrintSpoolJob(
        currentJob,
        safeJobId,
        safeStatus,
        errorMessage,
      );
      db.printSpoolJobs[jobIndex] = completedJob;
      db.meta.lastWriteAt = nowIso();
      await writePrintSpoolDb(db);
      return completedJob;
    },
    { shouldPreserveHotCaches: () => true },
  );
}

function clearPrintSpoolRetryTimer() {
  if (!printSpoolRetryTimer) return;
  clearTimeout(printSpoolRetryTimer);
  printSpoolRetryTimer = null;
  printSpoolRetryTimerAt = 0;
}

function schedulePrintSpoolWorkerRetry(delayMs) {
  if (!PRINTING_ENABLED) return;
  const safeDelay = Math.max(
    250,
    Math.trunc(Number(delayMs) || PRINT_SPOOL_RETRY_DELAY_MS),
  );
  const targetAt = Date.now() + safeDelay;
  if (
    printSpoolRetryTimer &&
    printSpoolRetryTimerAt > 0 &&
    printSpoolRetryTimerAt <= targetAt
  ) {
    return;
  }
  clearPrintSpoolRetryTimer();
  printSpoolRetryTimerAt = targetAt;
  printSpoolRetryTimer = setTimeout(() => {
    printSpoolRetryTimer = null;
    printSpoolRetryTimerAt = 0;
    queuePrintSpoolWorker();
  }, safeDelay);
}

async function scheduleNextPrintSpoolRetryFromDb() {
  if (!PRINTING_ENABLED) return;
  if (PRINT_SPOOL_SQL_PRIMARY) {
    try {
      const nextDelay = getPrintSpoolRepository()?.nextRetryDelayMs() ?? null;
      if (nextDelay !== null) {
        schedulePrintSpoolWorkerRetry(nextDelay);
      }
    } catch (error) {
      console.warn(
        `[print] Scheduling retry spool SQL non riuscito: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
    return;
  }
  try {
    const db = await readDb();
    const nextDelay = getNextPrintSpoolRetryDelayMs(db.printSpoolJobs);
    if (nextDelay !== null) {
      schedulePrintSpoolWorkerRetry(nextDelay);
    }
  } catch (error) {
    console.warn(
      `[print] Scheduling retry spool non riuscito: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
}

async function recoverPrintSpoolJobsOnStartup() {
  if (!PRINTING_ENABLED)
    return { recovered: 0, pending: 0, skippedMissingFiles: 0 };
  return withDbMutation("print_spool_startup_recovery", async () => {
    const db = await readDb();
    const jobs = sanitizePrintSpoolJobs(db.printSpoolJobs);
    let changed = false;
    let recovered = 0;
    let skippedMissingFiles = 0;
    const recoveredAt = nowIso();

    db.printSpoolJobs = jobs.map((job) => {
      if (!job || job.status === "printed" || job.status === "disabled")
        return job;
      const spoolFilePath = path.join(PRINT_SPOOL_DIR, job.fileName);
      if (!safePathExists(spoolFilePath)) {
        if (job.status === "queued" || job.status === "processing") {
          changed = true;
          skippedMissingFiles += 1;
          return sanitizePrintSpoolJob(
            {
              ...job,
              status: "failed",
              processedAt: recoveredAt,
              nextRetryAt: null,
              errorMessage:
                "File spool mancante: stampa non recuperabile automaticamente.",
            },
            job.id,
          );
        }
        return job;
      }

      if (job.status === "processing") {
        changed = true;
        recovered += 1;
        return sanitizePrintSpoolJob(
          {
            ...job,
            status: "unknown_after_crash",
            processedAt: recoveredAt,
            nextRetryAt: recoveredAt,
            recoveredAt,
            errorMessage:
              "Job rimasto in elaborazione al riavvio: possibile invio gia avvenuto, ristampa manuale richiesta.",
          },
          job.id,
        );
      }

      return job;
    });

    const pending = sanitizePrintSpoolJobs(db.printSpoolJobs).filter(
      (job) => job.status === "queued",
    ).length;
    if (changed) {
      db.meta.lastWriteAt = recoveredAt;
      await writePrintSpoolDb(db);
    }
    return { recovered, pending, skippedMissingFiles };
  }, { shouldPreserveHotCaches: () => true });
}

async function runPrintSpoolRetention(reason = "scheduled") {
  if (!PRINT_SPOOL_RETENTION_ENABLED) {
    return { enabled: false, orphanFiles: 0, deletedCount: 0, errorCount: 0 };
  }
  const db = await readDb();
  const summary = await cleanupPrintSpoolRetention({
    spoolDir: PRINT_SPOOL_DIR,
    jobs: db.printSpoolJobs,
    terminalRetentionMs: PRINT_SPOOL_RETENTION_TERMINAL_HOURS * 60 * 60 * 1000,
    orphanRetentionMs: PRINT_SPOOL_RETENTION_ORPHAN_HOURS * 60 * 60 * 1000,
  });
  runtimeMetrics.incrementCounter("printSpoolRetentionRuns");
  runtimeMetrics.incrementCounter(
    "printSpoolRetentionDeletedFiles",
    summary.deletedCount,
  );
  runtimeMetrics.incrementCounter(
    "printSpoolRetentionErrors",
    summary.errorCount,
  );
  runtimeMetrics.setGauge("printSpoolOrphanFiles", summary.orphanFiles);
  if (
    summary.deletedCount > 0 ||
    summary.errorCount > 0 ||
    summary.orphanFiles > PRINT_SPOOL_ORPHAN_ALERT_THRESHOLD
  ) {
    const level =
      summary.errorCount > 0 ||
      summary.orphanFiles > PRINT_SPOOL_ORPHAN_ALERT_THRESHOLD
        ? "warn"
        : "log";
    console[level](
      `[print] Retention spool (${reason}): file=${summary.files}, orfani=${summary.orphanFiles}, cancellati=${summary.deletedCount}, errori=${summary.errorCount}`,
    );
  }
  return { enabled: true, ...summary };
}

function startPrintSpoolRetentionScheduler() {
  if (!PRINT_SPOOL_RETENTION_ENABLED || printSpoolRetentionTimer) return;
  const run = () => {
    runPrintSpoolRetention("scheduled").catch((error) => {
      runtimeMetrics.incrementCounter("printSpoolRetentionErrors");
      console.warn(
        `[print] Retention spool non riuscita: ${error instanceof Error ? error.message : String(error)}`,
      );
    });
  };
  printSpoolRetentionTimer = setInterval(
    run,
    Math.max(60_000, PRINT_SPOOL_RETENTION_INTERVAL_MS),
  );
  printSpoolRetentionTimer.unref?.();
}

function queuePrintSpoolWorker() {
  if (!PRINTING_ENABLED || !SHOULD_RUN_BACKEND_OWNER_JOBS || printSpoolWorkerQueued) return;
  printSpoolWorkerQueued = true;
  clearPrintSpoolRetryTimer();
  printSpoolWorker = printSpoolWorker
    .then(async () => {
      while (true) {
        const claimStartedAt = Date.now();
        const nextJob = await claimNextPrintSpoolJob();
        if (!nextJob) {
          await scheduleNextPrintSpoolRetryFromDb();
          return;
        }
        mirrorPrintSpoolClaim(nextJob, claimStartedAt);

        // Circuit breaker: se il circuito della stampante e' aperto non tentiamo
        // (evita di martellare una stampante offline); il job resta a retry.
        if (
          PRINT_CIRCUIT_BREAKER_ENABLED &&
          !printerCircuitBreaker.canAttempt(nextJob.printerId)
        ) {
          const skipped = await completePrintSpoolJob(
            nextJob.id,
            "failed",
            "Circuito stampante aperto: tentativo posticipato.",
          );
          mirrorPrintSpoolCompletion(skipped);
          continue;
        }

        try {
          const filePath = path.join(PRINT_SPOOL_DIR, nextJob.fileName);
          const text = await fs.readFile(filePath, "utf8");
          if (nextJob.printerHost) {
            const reachable = !PRINT_SPOOL_PRE_SEND_PROBE || await probeNetworkPrinter({
              host: nextJob.printerHost,
              port: nextJob.printerPort,
            });
            if (!PRINT_SPOOL_PRE_SEND_PROBE) runtimeMetrics.incrementCounter("printSpoolPreSendProbeSkipped");
            if (!reachable) {
              throw new Error(
                "Stampante non raggiungibile, riprovo appena torna online.",
              );
            }
            getPrintSpoolRepository()?.markSent(nextJob.id);
            if (PRINT_SPOOL_INTERMEDIATE_STATUS_EVENTS) emitPrintStatusEvent(nextJob, "sent"); else runtimeMetrics.incrementCounter("printSpoolIntermediateEventsSkipped");
            await sendNetworkPrintJob(
              {
                host: nextJob.printerHost,
                port: nextJob.printerPort,
              },
              text,
              buildPrintJobOptions(nextJob.kind, nextJob),
            );
          } else {
            throw new Error(
              "Stampante non disponibile per la configurazione indicata.",
            );
          }

          const printedJob = await completePrintSpoolJob(nextJob.id, "printed");
          mirrorPrintSpoolCompletion(printedJob);
        } catch (error) {
          const failedJob = await completePrintSpoolJob(
            nextJob.id,
            "failed",
            String(error?.message ?? "Errore stampa sconosciuto."),
          );
          mirrorPrintSpoolCompletion(failedJob);
        }
      }
    })
    .catch(() => {})
    .finally(() => { printSpoolWorkerQueued = false; });
}
function stopPrintSpoolOwnerPollScheduler() { if (printSpoolOwnerPollTimer) clearInterval(printSpoolOwnerPollTimer); printSpoolOwnerPollTimer = null; }
function startPrintSpoolOwnerPollScheduler() { if (!PRINTING_ENABLED || !SHOULD_RUN_BACKEND_OWNER_JOBS || printSpoolOwnerPollTimer) return; printSpoolOwnerPollTimer = setInterval(queuePrintSpoolWorker, PRINT_SPOOL_OWNER_POLL_INTERVAL_MS); printSpoolOwnerPollTimer.unref?.(); queuePrintSpoolWorker(); }

async function enqueuePrintSpoolJob(payload) {
  if (PRINT_SPOOL_SQL_PRIMARY) {
    return enqueuePrintSpoolJobSqlPrimary(payload, { throwOnMissingTarget: true });
  }
  const acceptStartedAt = Date.now();
  const db = await readDb();
  const nextJob = buildPrintSpoolJobFromPayload(db, payload, {
    throwOnMissingTarget: true,
  });
  await persistPrintSpoolJobFile(nextJob, payload);
  db.printSpoolJobs = [...sanitizePrintSpoolJobs(db.printSpoolJobs), nextJob];
  prunePrintSpoolJobs(db);
  db.meta.lastWriteAt = nowIso();
  await writePrintSpoolDb(db);
  mirrorPrintSpoolJobEnqueue(nextJob, acceptStartedAt);
  if (PRINTING_ENABLED) queuePrintSpoolWorker();
  return nextJob;
}

async function enqueuePrintSpoolJobFast(payload) {
  const acceptStartedAt = Date.now();
  const db = await readDb();
  const nextJob = await appendPrintSpoolJobToDb(db, payload);
  db.meta.lastWriteAt = nowIso();
  await syncSinglePrintSpoolJobFast(db, nextJob.id);
  mirrorPrintSpoolJobEnqueue(nextJob, acceptStartedAt);
  if (PRINTING_ENABLED && nextJob.status === "queued") {
    queuePrintSpoolWorker();
  }
  return nextJob;
}

const HANDHELD_SESSION_REPORT_AUTO_PRINT_CHECK_MS = 60 * 1000;
let handheldSessionReportAutoPrintTimer = null;

async function enqueueHandheldSessionReportPrint({
  date,
  reason = "manual",
  idempotent = false,
} = {}) {
  const db = await readDb();
  const report = buildHandheldSessionReport(db, { date });
  const reportDate =
    report.sessionDate || date || resolveHandheldOperationalSessionDateKey();
  const printKey = String(report.printKey || reportDate);
  if (!db.meta || typeof db.meta !== "object") db.meta = {};
  if (
    !db.meta.handheldSessionReportPrints ||
    typeof db.meta.handheldSessionReportPrints !== "object"
  ) {
    db.meta.handheldSessionReportPrints = {};
  }
  const alreadyPrinted = db.meta.handheldSessionReportPrints[printKey];
  if (idempotent && alreadyPrinted?.printedAt) {
    return {
      skipped: true,
      reason: "already_printed",
      sessionDate: reportDate,
      printKey,
      printedAt: alreadyPrinted.printedAt,
      printJobId: alreadyPrinted.printJobId ?? null,
    };
  }

  const settings = sanitizePosSettings(db.posSettings, {
    menuItems: db.menuItems,
    users: db.users,
  });
  const printerId = resolveHandheldSessionReportPrinterId(settings);
  if (!printerId) {
    throw new Error(
      "Stampante preconti Bar non configurata per il riepilogo palmari.",
    );
  }

  const printJob = await enqueuePrintSpoolJob({
    kind: "handheld_session_report",
    printerId,
    text: formatHandheldSessionReportText(report),
    userId: "system",
    deviceUuid: "backend-scheduler",
    clientApp: "backend-scheduler",
  });

  const latestDb = await readDb();
  if (!latestDb.meta || typeof latestDb.meta !== "object") latestDb.meta = {};
  if (
    !latestDb.meta.handheldSessionReportPrints ||
    typeof latestDb.meta.handheldSessionReportPrints !== "object"
  ) {
    latestDb.meta.handheldSessionReportPrints = {};
  }
  latestDb.meta.handheldSessionReportPrints[printKey] = {
    printedAt: nowIso(),
    printJobId: printJob.id,
    printerId,
    reason,
    sessionDate: reportDate,
  };
  appendAuditEvent(latestDb, {
    actorUserId: "system",
    actorRole: "system",
    deviceId: "backend-scheduler",
    action: "reports.handheld_session_auto_printed",
    entityType: "report",
    entityId: `handheld_session:${reportDate}`,
    payload: {
      reason,
      sessionDate: reportDate,
      printKey,
      printJobId: printJob.id,
      printerId,
      totals: report.totals,
    },
  });
  latestDb.meta.lastWriteAt = nowIso();
  await writeDb(latestDb);
  return {
    skipped: false,
    sessionDate: reportDate,
    printKey,
    printJob,
    report,
  };
}

function startHandheldSessionReportAutoPrintScheduler() {
  if (handheldSessionReportAutoPrintTimer) return;
  let lastMinuteKey = "";
  const check = () => {
    const now = new Date();
    const minuteKey = `${now.getFullYear()}-${now.getMonth()}-${now.getDate()}-${now.getHours()}-${now.getMinutes()}`;
    if (minuteKey === lastMinuteKey) return;
    lastMinuteKey = minuteKey;
    readDb()
      .then((db) => {
        const ready = findNextClosedHandheldSessionReport(db, {
          printed: db.meta?.handheldSessionReportPrints,
        });
        if (!ready) return null;
        return enqueueHandheldSessionReportPrint({
          date: ready.sessionDate,
          reason: "all_handheld_cash_sessions_closed",
          idempotent: true,
        });
      })
      .catch((error) => {
        console.error(
          `[reports] stampa automatica riepilogo palmari non riuscita: ${error instanceof Error ? error.message : String(error)}`,
        );
      });
  };
  check();
  handheldSessionReportAutoPrintTimer = setInterval(
    check,
    HANDHELD_SESSION_REPORT_AUTO_PRINT_CHECK_MS,
  );
}

function stopHandheldSessionReportAutoPrintScheduler() {
  if (!handheldSessionReportAutoPrintTimer) return;
  clearInterval(handheldSessionReportAutoPrintTimer);
  handheldSessionReportAutoPrintTimer = null;
}

function findPaymentMethod(settings, methodId) {
  const normalizedId = String(methodId ?? "").trim();
  if (!normalizedId) return null;
  return (
    settings.paymentMethods.find(
      (method) => method.id === normalizedId && method.enabled !== false,
    ) ?? null
  );
}

function assertUserPaymentMethodAllowed(user, methodId, settings = null) {
  const normalizedId = String(methodId ?? "").trim();
  if (!normalizedId) return;
  const allowedIds = Array.isArray(user?.allowedPaymentMethodIds)
    ? sanitizeUserPaymentMethodIds(user.allowedPaymentMethodIds, settings)
    : resolveDefaultPaymentMethodIdsForUser(user, settings);
  if (allowedIds.length > 0 && !allowedIds.includes(normalizedId)) {
    throw new HttpError(
      403,
      "Metodo di pagamento non autorizzato per questo utente.",
      {
        code: "PAYMENT_METHOD_NOT_ALLOWED_FOR_USER",
        details: {
          methodId: normalizedId,
          userId: String(user?.id ?? "").trim(),
        },
      },
    );
  }
}

function runMockFiscalMiddleware(command, payload = {}) {
  const now = nowIso();
  return {
    ok: true,
    command,
    responseCode: "RT_OK",
    responseMessage: "Esito fiscale mock: operazione completata.",
    processedAt: now,
    payload,
  };
}

function executeFiscalProvider(command, payload = {}) {
  const provider = FISCAL_PROVIDER || "";
  const normalizedCommand = String(command ?? "").trim();
  if (!normalizedCommand) {
    throw new HttpError(400, "Comando fiscale non valido.");
  }
  if (!IS_PRODUCTION && (!provider || provider === "mock")) {
    return {
      fiscalStatus: "ISSUED",
      fiscalProvider: provider || "development-mock",
      requiresFiscalRetry: false,
      middleware: runMockFiscalMiddleware(normalizedCommand, payload),
    };
  }
  throw new HttpError(
    503,
    "Provider fiscale non configurato per operazioni reali.",
    {
      code: "FISCAL_PROVIDER_UNAVAILABLE",
      details: {
        fiscalProvider: provider || null,
        fiscalStatus: "FAILED",
        requiresFiscalRetry: true,
      },
    },
  );
}

function ensureFiscalTrackingArrays(db) {
  if (!Array.isArray(db.fiscalReceipts)) db.fiscalReceipts = [];
  if (!Array.isArray(db.fiscalEvents)) db.fiscalEvents = [];
}

function resolvePosFiscalRetryCutoffMs(value) {
  const createdAtMs = parseTimestampMs(value, 0);
  if (!Number.isFinite(createdAtMs) || createdAtMs <= 0)
    return Number.POSITIVE_INFINITY;
  const createdAt = new Date(createdAtMs);
  const cutoff = new Date(createdAtMs);
  cutoff.setHours(POS_FISCAL_RETRY_CUTOFF_HOUR, 0, 0, 0);
  if (createdAt.getTime() >= cutoff.getTime()) {
    cutoff.setDate(cutoff.getDate() + 1);
  }
  return cutoff.getTime();
}

function isPosFiscalRetryWindowOpen(receiptOrCreatedAt, nowMs = Date.now()) {
  const createdAt =
    receiptOrCreatedAt && typeof receiptOrCreatedAt === "object"
      ? receiptOrCreatedAt.manualRetryStartedAt ?? receiptOrCreatedAt.createdAt
      : receiptOrCreatedAt;
  return nowMs < resolvePosFiscalRetryCutoffMs(createdAt);
}

function posFiscalRetryCutoffIso(receiptOrCreatedAt) {
  const createdAt =
    receiptOrCreatedAt && typeof receiptOrCreatedAt === "object"
      ? receiptOrCreatedAt.manualRetryStartedAt ?? receiptOrCreatedAt.createdAt
      : receiptOrCreatedAt;
  const cutoffMs = resolvePosFiscalRetryCutoffMs(createdAt);
  return Number.isFinite(cutoffMs) ? new Date(cutoffMs).toISOString() : null;
}

function buildPosFiscalRecoveryRetryResult(
  job = {},
  receipt = null,
  attempt = 1,
) {
  if (!isPosFiscalRetryWindowOpen(receipt ?? job?.createdAt)) return null;
  const nextAttempt = Math.max(1, Math.trunc(Number(attempt) || 1)) + 1;
  return {
    retry: true,
    delayMs: POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
    job: {
      ...job,
      attempt: nextAttempt,
      delayMs: POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
    },
  };
}

function formatFiscalReceiptMoney(value) {
  return roundMoney(Math.max(Number(value) || 0, 0)).toFixed(2);
}

function formatFiscalReceiptQuantity(value) {
  const quantity = Math.max(Number(value) || 0, 0);
  if (Number.isInteger(quantity)) return String(quantity);
  return roundMoney(quantity).toFixed(2);
}

function totalFiscalReceiptItemsCents(items) {
  return (Array.isArray(items) ? items : []).reduce((sum, item) => {
    const unitCents = moneyToCents(Number(item?.price));
    const quantity = Math.max(Number(item?.quantity) || 0, 0);
    return sum + Math.max(Math.round(unitCents * quantity), 0);
  }, 0);
}

function normalizeFiscalReceiptItemName(value, fallback = "Articolo") {
  const name = String(value ?? "").trim();
  return name || fallback;
}

function addFiscalReceiptAccumulatorLine(
  linesByKey,
  { name, unitPrice, quantity = 1 } = {},
) {
  const safeName = normalizeFiscalReceiptItemName(name);
  const safeUnitPrice = roundMoney(Math.max(Number(unitPrice) || 0, 0));
  const safeQuantity = Math.max(Number(quantity) || 0, 0);
  if (!safeName || safeUnitPrice <= 0 || safeQuantity <= 0) return;
  const key = `${safeName.toLowerCase()}|${safeUnitPrice.toFixed(2)}`;
  const current = linesByKey.get(key) ?? {
    name: safeName,
    unitPrice: safeUnitPrice,
    quantity: 0,
  };
  current.quantity = roundMoney(current.quantity + safeQuantity);
  linesByKey.set(key, current);
}

function fiscalReceiptAccumulatorToItems(linesByKey) {
  return [...linesByKey.values()].map((line) => ({
    name: line.name,
    price: formatFiscalReceiptMoney(line.unitPrice),
    quantity: formatFiscalReceiptQuantity(line.quantity),
    department: "1",
  }));
}

function buildFiscalReceiptItemsFromPaymentItems(items) {
  const linesByKey = new Map();
  (Array.isArray(items) ? items : []).forEach((entry) => {
    const item = sanitizePaymentItem(entry);
    if (!item) return;
    const quantity = Math.max(Number(item.qty) || 0, 0);
    const unitPrice =
      Number(item.unitPriceApplied) > 0
        ? Number(item.unitPriceApplied)
        : quantity > 0
          ? Number(item.lineTotal) / quantity
          : Number(item.unitPrice) || 0;
    addFiscalReceiptAccumulatorLine(linesByKey, {
      name: item.name,
      unitPrice,
      quantity,
    });
  });
  return fiscalReceiptAccumulatorToItems(linesByKey);
}

function buildFiscalReceiptItemsFromIntegrationOrders(
  db,
  { orderIds = [], articleUnitIds = [] } = {},
) {
  const orders = Array.isArray(db.integration?.orders)
    ? db.integration.orders
    : [];
  const selectedOrderIds = normalizePaymentOrderIdList(orderIds, "");
  const selectedUnitIds = new Set(
    normalizeStringList(articleUnitIds, 1000, 120),
  );
  const linesByKey = new Map();
  selectedOrderIds.forEach((orderId) => {
    const orderIndex = findIntegrationOrderIndexByLookup(orders, orderId);
    if (orderIndex < 0) return;
    const order = sanitizeIntegrationOrder(orders[orderIndex], String(orderId));
    if (selectedUnitIds.size > 0) {
      forEachIntegrationOrderArticleUnit(
        order,
        ({ unitId, amountCents, item }) => {
          if (!selectedUnitIds.has(unitId)) return;
          addFiscalReceiptAccumulatorLine(linesByKey, {
            name: item?.productNameSnapshot ?? item?.name,
            unitPrice: centsToMoney(amountCents),
            quantity: 1,
          });
        },
      );
      return;
    }
    const snapshots = [...buildIntegrationOrderLineSnapshots(order).values()];
    if (snapshots.length > 0) {
      snapshots.forEach((line) => {
        const quantity = Math.max(Number(line.qty) || 0, 0);
        addFiscalReceiptAccumulatorLine(linesByKey, {
          name: line.productNameSnapshot,
          unitPrice:
            quantity > 0
              ? Number(line.lineTotal) / quantity
              : Number(line.unitPriceApplied) || 0,
          quantity,
        });
      });
      return;
    }
    (Array.isArray(order.items) ? order.items : []).forEach((item) => {
      if (!item || item.voidedAt) return;
      const quantity = Math.max(Math.trunc(Number(item.qty) || 1), 1);
      const lineTotal = roundMoney(Math.max(Number(item.lineTotal) || 0, 0));
      const unitPrice =
        lineTotal > 0
          ? lineTotal / quantity
          : Number(item.unitPriceApplied) > 0
            ? Number(item.unitPriceApplied)
            : Number(item.listPriceAtTime) || 0;
      addFiscalReceiptAccumulatorLine(linesByKey, {
        name: item.productNameSnapshot ?? item.name,
        unitPrice,
        quantity,
      });
    });
  });
  return fiscalReceiptAccumulatorToItems(linesByKey);
}

function buildFallbackPosFiscalReceiptItem({
  amount = 0,
  orderId = "",
  paymentId = "",
} = {}) {
  const safeAmount = roundMoney(Math.max(Number(amount) || 0, 0));
  if (safeAmount <= 0) return [];
  const safeOrderId = String(orderId ?? "").trim();
  const safePaymentId = String(paymentId ?? "").trim();
  return [
    {
      name: safeOrderId
        ? `Pagamento POS comanda ${safeOrderId}`
        : safePaymentId
          ? `Pagamento POS ${safePaymentId}`
          : "Pagamento POS",
      price: formatFiscalReceiptMoney(safeAmount),
      quantity: "1",
      department: "1",
    },
  ];
}

function buildPosFiscalReceiptItems(db, options = {}) {
  const amountCents = moneyToCents(options.amount);
  const explicitItems = buildFiscalReceiptItemsFromPaymentItems(
    options.paymentItems,
  );
  if (explicitItems.length > 0) {
    const explicitCents = totalFiscalReceiptItemsCents(explicitItems);
    if (amountCents <= 0 || Math.abs(explicitCents - amountCents) <= 1)
      return explicitItems;
  }
  const orderItems = buildFiscalReceiptItemsFromIntegrationOrders(db, {
    orderIds: options.orderIds,
    articleUnitIds: options.articleUnitIds,
  });
  if (orderItems.length > 0) {
    const orderItemsCents = totalFiscalReceiptItemsCents(orderItems);
    if (amountCents <= 0 || Math.abs(orderItemsCents - amountCents) <= 1)
      return orderItems;
  }
  return buildFallbackPosFiscalReceiptItem({
    amount: options.amount,
    orderId: options.orderId,
    paymentId: options.paymentId,
  });
}

function findExistingPosFiscalReceipt(db, paymentId) {
  const normalizedPaymentId = String(paymentId ?? "").trim();
  if (!normalizedPaymentId) return null;
  return (
    (Array.isArray(db.fiscalReceipts) ? db.fiscalReceipts : [])
      .map((receipt, index) =>
        sanitizeFiscalReceipt(receipt, `fiscal_${index + 1}`),
      )
      .find(
        (receipt) =>
          receipt &&
          receipt.paymentId === normalizedPaymentId &&
          receipt.fiscalProvider === POS_FISCAL_API_PROVIDER &&
          receipt.fiscalStatus === "ISSUED" &&
          receipt.requiresFiscalRetry !== true,
      ) ?? null
  );
}

function findPosFiscalReceiptByPaymentId(db, paymentId) {
  const normalizedPaymentId = String(paymentId ?? "").trim();
  if (!normalizedPaymentId) return null;
  return (
    (Array.isArray(db.fiscalReceipts) ? db.fiscalReceipts : [])
      .map((receipt, index) =>
        sanitizeFiscalReceipt(receipt, `fiscal_${index + 1}`),
      )
      .find(
        (receipt) =>
          receipt &&
          receipt.paymentId === normalizedPaymentId &&
          receipt.fiscalProvider === POS_FISCAL_API_PROVIDER,
      ) ?? null
  );
}

function updatePosFiscalReceiptByPaymentId(db, paymentId, patch = {}) {
  ensureFiscalTrackingArrays(db);
  const normalizedPaymentId = String(paymentId ?? "").trim();
  if (!normalizedPaymentId) return null;
  const index = db.fiscalReceipts.findIndex((receipt) => {
    const safeReceipt = sanitizeFiscalReceipt(receipt, "");
    return (
      safeReceipt &&
      safeReceipt.paymentId === normalizedPaymentId &&
      safeReceipt.fiscalProvider === POS_FISCAL_API_PROVIDER
    );
  });
  if (index < 0) return null;
  const current = sanitizeFiscalReceipt(
    db.fiscalReceipts[index],
    `fiscal_${index + 1}`,
  );
  const nextReceipt = sanitizeFiscalReceipt(
    {
      ...current,
      ...patch,
      id: current.id,
      paymentId: normalizedPaymentId,
      fiscalProvider: POS_FISCAL_API_PROVIDER,
    },
    current.id,
  );
  if (!nextReceipt) return null;
  db.fiscalReceipts[index] = nextReceipt;
  return nextReceipt;
}

function linkPosFiscalReceiptToPaymentRecords(db, receipt, options = {}) {
  if (!receipt) return;
  const fiscalPaymentId = String(
    receipt.paymentId ?? options.paymentId ?? "",
  ).trim();
  const paymentContainerId = String(
    options.paymentContainerId ?? options.appPaymentId ?? "",
  ).trim();
  const issuedBy = String(options.issuedBy ?? "").trim();
  const paymentContainer = paymentContainerId
    ? ((Array.isArray(db.paymentContainers) ? db.paymentContainers : []).find(
        (entry) => String(entry?.id ?? "").trim() === paymentContainerId,
      ) ?? null)
    : null;
  if (paymentContainer) {
    paymentContainer.fiscalDocType =
      paymentContainer.fiscalDocType || "RECEIPT";
    paymentContainer.fiscalDocNo = paymentContainer.fiscalDocNo || receipt.id;
    paymentContainer.fiscalIssuedAt =
      paymentContainer.fiscalIssuedAt || receipt.createdAt;
    paymentContainer.fiscalIssuedBy =
      paymentContainer.fiscalIssuedBy || issuedBy || null;
  }
  (Array.isArray(db.payments) ? db.payments : []).forEach((payment) => {
    const paymentId = String(payment?.id ?? "").trim();
    const paymentTxId = String(payment?.paymentTxId ?? "").trim();
    const containerId = String(payment?.paymentContainerId ?? "").trim();
    if (
      paymentTxId === fiscalPaymentId ||
      paymentId === fiscalPaymentId ||
      (paymentContainerId &&
        (paymentId === paymentContainerId ||
          containerId === paymentContainerId))
    ) {
      payment.receiptId = payment.receiptId || receipt.id;
      payment.fiscal = true;
    }
  });
}

function appendPosFiscalEvent(db, event = {}) {
  ensureFiscalTrackingArrays(db);
  db.fiscalEvents.push({
    id: `fiscal_event_${randomUUID().replace(/-/g, "")}`,
    provider: POS_FISCAL_API_PROVIDER,
    paymentId: event.paymentId ? String(event.paymentId) : null,
    orderId: event.orderId ? String(event.orderId) : null,
    command: String(event.command ?? "pos_receipt"),
    result: String(event.result ?? "info"),
    message: String(event.message ?? "").slice(0, 300),
    requiresFiscalRetry: event.requiresFiscalRetry === true,
    createdAt: nowIso(),
    payload:
      event.payload && typeof event.payload === "object"
        ? cloneJson(event.payload, {})
        : null,
  });
}

function buildPosFiscalRequestId(paymentId) {
  const safePaymentId = String(paymentId ?? "").trim();
  return safePaymentId ? `pos_fiscal_${safePaymentId}` : "";
}

function hashPosFiscalPayload(payload) {
  if (!payload || typeof payload !== "object") return null;
  try {
    return createHash("sha256").update(JSON.stringify(payload)).digest("hex");
  } catch {
    return null;
  }
}

function fiscalApiErrorMessage(error) {
  if (error instanceof Error && error.name === "AbortError") {
    return "timeout durante la comunicazione con il server fiscale";
  }
  return error instanceof Error
    ? error.message
    : String(error ?? "errore fiscale sconosciuto");
}

async function fetchPosFiscalApiJson(pathname, options = {}) {
  const baseUrl = String(options.baseUrl ?? POS_FISCAL_API_BASE_URL ?? "")
    .trim()
    .replace(/\/+$/, "");
  if (!baseUrl) {
    throw new Error("URL server fiscale POS non configurato");
  }
  const controller = new AbortController();
  const timeout = setTimeout(
    () => controller.abort(),
    POS_FISCAL_API_TIMEOUT_MS,
  );
  try {
    const response = await fetch(`${baseUrl}${pathname}`, {
      method: options.method ?? "GET",
      headers: {
        ...(options.body ? { "Content-Type": "application/json" } : {}),
        ...(options.idempotencyKey
          ? { "Idempotency-Key": String(options.idempotencyKey) }
          : {}),
        ...(options.fiscalDeviceId
          ? { "X-Fiscal-Device-Id": String(options.fiscalDeviceId) }
          : {}),
        ...(options.headers && typeof options.headers === "object"
          ? options.headers
          : {}),
      },
      body: options.body ? JSON.stringify(options.body) : undefined,
      signal: controller.signal,
    });
    const text = await response.text();
    let json = null;
    if (text.trim()) {
      try {
        json = JSON.parse(text);
      } catch {
        json = { raw: text };
      }
    }
    if (!response.ok) {
      const error = new Error(
        json?.message ||
          json?.error ||
          `server fiscale ha risposto HTTP ${response.status}`,
      );
      error.status = response.status;
      error.response = json;
      throw error;
    }
    return json ?? {};
  } finally {
    clearTimeout(timeout);
  }
}

function normalizePosFiscalApiPath(pathname, fallback = "/api/fiscal/reprint") {
  const raw = String(pathname ?? "").trim() || fallback;
  return raw.startsWith("/") ? raw : `/${raw}`;
}

function buildPosFiscalReprintPayload({
  receipt,
  container,
  transaction,
  movementId,
} = {}) {
  const orderIds = normalizePaymentOrderIdList(
    [
      container?.orderId,
      ...(Array.isArray(container?.orderIds) ? container.orderIds : []),
    ],
    "",
  );
  const paymentId = String(
    receipt?.paymentId ?? transaction?.id ?? movementId ?? "",
  ).trim();
  const target = resolveFiscalReprintTarget(receipt);
  if (!target) return null;
  return {
    documentKind: target.documentKind,
    providerRef: target.providerRef,
    request: target.request,
    audit: {
      documentKind: target.documentKind,
      fiscalReceiptId: String(receipt?.id ?? "").trim(),
      fiscalDeviceId: String(receipt?.fiscalDeviceId ?? "").trim() || null,
      originalFiscalProviderRef:
        String(receipt?.fiscalProviderRef ?? "").trim() || null,
      originalFiscalMovementId:
        String(receipt?.fiscalMovementId ?? "").trim() || null,
      originalFiscalReceiptDate:
        normalizeFiscalReceiptDate(receipt?.fiscalReceiptDate) || null,
      originalFiscalDocumentNumber:
        String(receipt?.fiscalDocumentNumber ?? "").trim() || null,
      reprintProviderRef: target.providerRef,
      reprintMovementId: target.movementId,
      reprintReceiptDate: target.receiptDate,
      reprintDocumentNumber: target.documentNumber,
    },
    paymentId,
    transactionId: String(transaction?.id ?? paymentId).trim() || paymentId,
    movementId: String(movementId ?? container?.id ?? "").trim() || null,
    orderId: orderIds[0] ?? null,
    orderIds,
    paymentMethod: normalizePosFiscalApiPaymentMethod({
      methodType: transaction?.method,
      paymentMethodId: container?.paymentMethod,
      paymentMethodLabel: container?.paymentMethod,
    }),
    fiscalDevice: normalizePosFiscalDeviceJobConfig({
      id: receipt?.fiscalDeviceId,
      apiBaseUrl: receipt?.fiscalApiBaseUrl,
      statusEndpoint: receipt?.fiscalStatusEndpoint,
      verifyEndpoint: receipt?.fiscalVerifyEndpoint,
      receiptEndpoint: receipt?.fiscalReceiptEndpoint,
      reprintEndpoint: receipt?.fiscalReprintEndpoint,
      voidEndpoint: receipt?.fiscalVoidEndpoint,
    }),
  };
}

function normalizeFiscalReceiptDate(value) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const isoDate = raw.match(/^(\d{4}-\d{2}-\d{2})/);
  if (isoDate) return isoDate[1];
  const parsed = Date.parse(raw);
  if (!Number.isFinite(parsed)) return "";
  return new Date(parsed).toISOString().slice(0, 10);
}

function extractPosFiscalReferenceFromApiResponse(response = {}) {
  if (!response || typeof response !== "object") {
    return {
      fiscalProviderRef: null,
      fiscalMovementId: null,
      fiscalReceiptDate: null,
      fiscalDocumentNumber: null,
    };
  }
  const fiscalMovementId =
    firstFiscalApiScalar(
      response.movementId,
      response.movement_id,
      response.fiscalMovementId,
      response.movement?.id,
      response.movement?.movementId,
    ) || null;
  const fiscalDocumentNumber =
    firstFiscalApiScalar(
      response.documentNumber,
      response.documentNo,
      response.receiptNumber,
      response.document?.documentNumber,
      response.document?.receiptNumber,
      response.movement?.documentNumber,
      response.movement?.rawDocumentInfo?.documentNumber,
    ) || null;
  const fiscalReceiptDate =
    normalizeFiscalReceiptDate(
      firstFiscalApiScalar(
        response.receiptDate,
        response.date,
        response.createdAt,
        response.document?.documentDate,
        response.movement?.documentDate,
        response.movement?.createdAt,
      ),
    ) || null;
  const fiscalProviderRef =
    firstFiscalApiScalar(
      response.receiptId,
      response.id,
      response.documentId,
      response.document?.reference,
      response.movement?.rawDocumentInfo?.reference,
      fiscalMovementId,
      fiscalDocumentNumber,
    ) || null;
  return {
    fiscalProviderRef,
    fiscalMovementId,
    fiscalReceiptDate,
    fiscalDocumentNumber,
  };
}

async function issueQueuedPosFiscalReprint(job = {}, options = {}) {
  const paymentId = String(job.paymentId ?? "").trim();
  const receiptId = String(job.receiptId ?? "").trim();
  const documentKind =
    String(job.documentKind ?? "").trim().toLowerCase() === "void"
      ? "void"
      : "receipt";
  const jobKey =
    buildFiscalReprintJobKey({ ...job, documentKind }) ||
    `${paymentId || "payment"}:${receiptId || "receipt"}:${documentKind}`;
  const reprintSubject =
    documentKind === "void"
      ? "documento fiscale di annullamento"
      : "documento fiscale";
  const claimAlreadyRegistered = options.claimed === true;
  if (
    !paymentId ||
    !receiptId ||
    (!claimAlreadyRegistered && posFiscalReprintJobsInFlight.has(jobKey))
  )
    return;
  if (FISCAL_REAL_IO_DISABLED) {
    console.warn(
      `[fiscal-pos] ristampa POS non inviata: I/O reale disabilitato per test (${jobKey}).`,
    );
    return;
  }
  const fiscalDevice = normalizePosFiscalDeviceJobConfig(job.fiscalDevice);
  if (!claimAlreadyRegistered) posFiscalReprintJobsInFlight.add(jobKey);
  try {
    if (!fiscalDevice) {
      await withDbMutation(
        `fiscal_pos_reprint_device_missing_${paymentId}`,
        async () => {
          const db = await readDb();
          appendPosFiscalEvent(db, {
            paymentId,
            orderId: job.orderId,
            command: "pos_receipt_reprint",
            result: "fiscal_device_not_available",
            message:
              "Ristampa fiscale POS non inviata: RT fiscale non disponibile.",
            requiresFiscalRetry: false,
            payload: {
              documentKind,
              request: job.request,
              ...(job.audit ? { audit: job.audit } : {}),
            },
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(db, "payments.fiscalReprint.deviceMissing.appStateWrite");
        },
      );
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprint_failed",
        {
          paymentId,
          receiptId,
        },
      );
      return;
    }
    let status = null;
    try {
      status = await fetchPosFiscalApiJson(fiscalDevice.statusEndpoint, {
        baseUrl: fiscalDevice.apiBaseUrl,
        fiscalDeviceId: fiscalDevice.id,
      });
    } catch (error) {
      const fiscalError = fiscalApiErrorMessage(error);
      await withDbMutation(
        `fiscal_pos_reprint_status_error_${paymentId}`,
        async () => {
          const db = await readDb();
          appendPosFiscalEvent(db, {
            paymentId,
            orderId: job.orderId,
            command: "pos_receipt_reprint",
            result: "status_error",
            message: `Ristampa fiscale POS non inviata: ${fiscalError}.`,
            requiresFiscalRetry: true,
            payload: {
              documentKind,
              request: job.request,
              ...(job.audit ? { audit: job.audit } : {}),
            },
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(db, "payments.fiscalReprint.statusError.appStateWrite");
        },
      );
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprint_failed",
        {
          paymentId,
          receiptId,
        },
      );
      return;
    }

    if (
      status?.dryRun !== true &&
      (status?.ok !== true || status?.fiscalApiEnabled !== true)
    ) {
      const message =
        "Ristampa fiscale POS non inviata: server fiscale non abilitato.";
      await withDbMutation(
        `fiscal_pos_reprint_disabled_${paymentId}`,
        async () => {
          const db = await readDb();
          appendPosFiscalEvent(db, {
            paymentId,
            orderId: job.orderId,
            command: "pos_receipt_reprint",
            result: "disabled",
            message,
            payload: { documentKind, status },
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(db, "payments.fiscalReprint.disabled.appStateWrite");
        },
      );
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprint_failed",
        {
          paymentId,
          receiptId,
        },
      );
      return;
    }

    if (status?.dryRun === true) {
      const message = `Ristampa fiscale POS non inviata: ${FISCAL_PROVIDER_DRY_RUN_MESSAGE}`;
      await withDbMutation(
        `fiscal_pos_reprint_dry_run_${paymentId}`,
        async () => {
          const db = await readDb();
          appendPosFiscalEvent(db, {
            paymentId,
            orderId: job.orderId,
            command: "pos_receipt_reprint",
            result: "provider_dry_run",
            message,
            requiresFiscalRetry: true,
            payload: {
              code: FISCAL_PROVIDER_DRY_RUN_CODE,
              documentKind,
              status,
            },
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(
            db,
            "payments.fiscalReprint.dryRun.appStateWrite",
          );
        },
      );
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprint_failed",
        { paymentId, receiptId, documentKind },
      );
      return;
    }

    const endpoint = fiscalDevice.reprintEndpoint;
    try {
      const response = await fetchPosFiscalApiJson(endpoint, {
        method: "POST",
        body: job.request,
        baseUrl: fiscalDevice.apiBaseUrl,
        idempotencyKey: `pos_fiscal_reprint_${paymentId}_${receiptId}_${documentKind}`,
        fiscalDeviceId: fiscalDevice.id,
      });
      if (response?.ok === false) {
        throw new Error(
          response?.message ||
            response?.error ||
            "API fiscale ha rifiutato la ristampa",
        );
      }
      await withDbMutation(`fiscal_pos_reprinted_${paymentId}`, async () => {
        const db = await readDb();
        appendPosFiscalEvent(db, {
          paymentId,
          orderId: job.orderId,
          command: "pos_receipt_reprint",
          result: "reprinted",
          message: `Ristampa ${reprintSubject} POS inviata.`,
          payload: {
            documentKind,
            request: job.request,
            ...(job.audit ? { audit: job.audit } : {}),
            endpoint,
            response,
          },
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReprint.sent.appStateWrite");
      });
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprinted",
        {
          paymentId,
          receiptId,
          documentKind,
        },
      );
    } catch (error) {
      const fiscalError = fiscalApiErrorMessage(error);
      await withDbMutation(
        `fiscal_pos_reprint_error_${paymentId}`,
        async () => {
          const db = await readDb();
          appendPosFiscalEvent(db, {
            paymentId,
            orderId: job.orderId,
            command: "pos_receipt_reprint",
            result: "reprint_error",
            message: `Ristampa fiscale POS non riuscita: ${fiscalError}.`,
            requiresFiscalRetry: true,
            payload: {
              documentKind,
              request: job.request,
              ...(job.audit ? { audit: job.audit } : {}),
            },
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(db, "payments.fiscalReprint.error.appStateWrite");
        },
      );
      publishIntegrationNotificationStreamRefresh(
        "pos_fiscal_receipt_reprint_failed",
        {
          paymentId,
          receiptId,
          documentKind,
        },
      );
    }
  } finally {
    if (options.releaseClaim !== false) {
      posFiscalReprintJobsInFlight.delete(jobKey);
    }
  }
}

function schedulePosFiscalReprintBackgroundJobs(jobs = []) {
  if (FISCAL_REAL_IO_DISABLED) {
    const count = (Array.isArray(jobs) ? jobs : []).filter(
      (job) => job && typeof job === "object",
    ).length;
    if (count > 0) {
      console.warn(
        `[fiscal-pos] ${count} job ristampa POS non schedulati: I/O reale disabilitato per test.`,
      );
    }
    return;
  }
  (Array.isArray(jobs) ? jobs : [])
    .filter((job) => job && typeof job === "object")
    .forEach((job) => {
      const jobKey = buildFiscalReprintJobKey(job);
      if (!jobKey || posFiscalReprintJobsInFlight.has(jobKey)) return;
      posFiscalReprintJobsInFlight.add(jobKey);
      setTimeout(() => {
        enqueueFiscalRetryLaneJob(
          `pos_fiscal_reprint_${jobKey}`,
          [`fiscal-reprint:${jobKey}`],
          () =>
            issueQueuedPosFiscalReprint(job, {
              claimed: true,
              releaseClaim: false,
            }),
        )
          .catch((error) => {
            console.error(
              `[fiscal-pos] ristampa asincrona fallita: paymentId=${job.paymentId ?? "-"} error=${
                error instanceof Error ? error.message : String(error)
              }`,
            );
          })
          .finally(() => {
            posFiscalReprintJobsInFlight.delete(jobKey);
          });
      }, 0);
    });
}

function buildPosFiscalReceiptPayload(db, options = {}, fiscalPaymentId = "") {
  const orderIds = normalizePaymentOrderIdList(
    [
      options.orderId,
      ...(Array.isArray(options.orderIds) ? options.orderIds : []),
    ],
    "",
  );
  const fiscalOrderId =
    String(options.orderId ?? orderIds[0] ?? "").trim() || null;
  const paymentMethod = normalizePosFiscalApiPaymentMethod(options);
  return {
    orderId: fiscalOrderId,
    paymentId: fiscalPaymentId,
    paymentMethod,
    items: buildPosFiscalReceiptItems(db, {
      ...options,
      paymentId: fiscalPaymentId,
      orderId: fiscalOrderId,
      orderIds,
    }),
  };
}

function normalizePosFiscalApiPaymentMethod(options = {}) {
  const explicit = String(
    options.fiscalPaymentMethod ?? options.apiPaymentMethod ?? "",
  )
    .trim()
    .toLowerCase();
  if (["cash", "contanti", "contante"].includes(explicit)) return "cash";
  if (["pos", "card", "carta", "electronic", "elettronico"].includes(explicit))
    return "pos";
  const rawMethodType =
    options.methodType ?? options.paymentMethodType ?? options.method;
  const methodType = normalizePaymentMethodType(rawMethodType);
  if (methodType === "CASH") return "cash";
  if (methodType === "POS") return "pos";
  const methodId = String(options.paymentMethodId ?? options.methodId ?? "")
    .trim()
    .toLowerCase();
  const methodLabel = String(
    options.paymentMethodLabel ?? options.methodLabel ?? "",
  )
    .trim()
    .toLowerCase();
  if (methodId.includes("cash") || methodLabel.includes("contant"))
    return "cash";
  if (
    methodId.includes("card") ||
    methodId.includes("pos") ||
    methodLabel.includes("carta") ||
    methodLabel.includes("pos")
  ) {
    return "pos";
  }
  const hasAnyMethodHint = Boolean(
    explicit || String(rawMethodType ?? "").trim() || methodId || methodLabel,
  );
  if (hasAnyMethodHint) {
    throw new HttpError(400, "Metodo pagamento fiscale non riconosciuto.", {
      code: "FISCAL_PAYMENT_METHOD_UNKNOWN",
      details: {
        methodType: String(rawMethodType ?? "").trim() || null,
        paymentMethodId: methodId || null,
        paymentMethodLabel: methodLabel || null,
      },
    });
  }
  return "pos";
}

function schedulePosFiscalReceiptBackgroundJob(job = {}, options = {}) {
  const fiscalPaymentId = String(job.paymentId ?? "").trim();
  if (!fiscalPaymentId || posFiscalReceiptJobsInFlight.has(fiscalPaymentId))
    return;
  if (FISCAL_REAL_IO_DISABLED) {
    console.warn(
      `[fiscal-pos] job POS non schedulato: I/O reale disabilitato per test (paymentId=${fiscalPaymentId}).`,
    );
    return;
  }
  posFiscalReceiptJobsInFlight.add(fiscalPaymentId);
  const delayMs = Math.max(
    0,
    Math.trunc(Number(options.delayMs ?? job.delayMs ?? 0) || 0),
  );
  setTimeout(() => {
    let retryJob = null;
    enqueueFiscalRetryLaneJob(
      `pos_fiscal_receipt_${fiscalPaymentId}`,
      [`fiscal-receipt:${fiscalPaymentId}`],
      () => issueQueuedPosFiscalReceipt(job),
    )
      .then((result) => {
        retryJob = result?.retry === true ? result : null;
      })
      .catch((error) => {
        console.error(
          `[fiscal-pos] job asincrono fallito: paymentId=${fiscalPaymentId} error=${
            error instanceof Error ? error.message : String(error)
          }`,
        );
      })
      .finally(() => {
        posFiscalReceiptJobsInFlight.delete(fiscalPaymentId);
        if (retryJob?.job) {
          schedulePosFiscalReceiptBackgroundJob(retryJob.job, {
            delayMs: retryJob.delayMs ?? POS_FISCAL_API_JOB_RETRY_DELAY_MS,
          });
        }
      });
  }, delayMs);
}

const posFiscalIssueVerificationService = createPosFiscalIssueVerificationService({
  appendEvent: appendPosFiscalEvent, buildRetryResult: buildPosFiscalRecoveryRetryResult,
  ensureFiscalTrackingArrays, errorMessage: fiscalApiErrorMessage, fetchJson: fetchPosFiscalApiJson,
  linkReceipt: linkPosFiscalReceiptToPaymentRecords, logger: console, nowIso,
  publishRefresh: publishIntegrationNotificationStreamRefresh, readDb,
  retryDelayMs: POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
  updateReceipt: updatePosFiscalReceiptByPaymentId, withDbMutation, writeFiscalDb: writePaymentFiscalDb,
});

async function issueQueuedPosFiscalReceipt(job = {}) {
  const fiscalPaymentId = String(job.paymentId ?? "").trim();
  if (!fiscalPaymentId) return;
  if (FISCAL_REAL_IO_DISABLED) {
    console.warn(
      `[fiscal-pos] emissione POS saltata: I/O reale disabilitato per test (paymentId=${fiscalPaymentId}).`,
    );
    return { skipped: true, reason: "real_io_disabled_for_tests" };
  }
  const attempt = Math.max(1, Math.trunc(Number(job.attempt) || 1));
  const fiscalDevice = normalizePosFiscalDeviceJobConfig(job.fiscalDevice);
  if (!fiscalDevice) {
    await withDbMutation(
      `fiscal_pos_device_missing_${fiscalPaymentId}`,
      async () => {
        const db = await readDb();
        ensureFiscalTrackingArrays(db);
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "FAILED",
          responseCode: "FISCAL_DEVICE_NOT_AVAILABLE",
          responseMessage: "RT fiscale non disponibile.",
          fiscalStatus: "FAILED",
          fiscalError:
            "RT fiscale non disponibile per la configurazione indicata.",
          requiresFiscalRetry: false,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "fiscal_device_not_available",
          message: "Scontrino fiscale non emesso: RT fiscale non disponibile.",
          requiresFiscalRetry: false,
          payload: {
            fiscalDeviceId: String(job.fiscalDevice?.id ?? "").trim() || null,
            originalPayload: job.payload,
          },
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReceipt.deviceMissing.appStateWrite");
        publishIntegrationNotificationStreamRefresh(
          "pos_fiscal_receipt_failed",
          {
            paymentId: fiscalPaymentId,
            receiptId: receipt?.id ?? "",
          },
        );
      },
    );
    return;
  }

  const claim = await withDbMutation(
      `fiscal_pos_claim_${fiscalPaymentId}`,
    async () => {
      const db = await readDb();
      ensureFiscalTrackingArrays(db); recoverPendingPosFiscalReceiptFromJob(db, job, { findReceipt: findPosFiscalReceiptByPaymentId, sanitizeReceipt: sanitizeFiscalReceipt });
      const existingIssued = findExistingPosFiscalReceipt(db, fiscalPaymentId);
      if (existingIssued)
        return { ok: false, receipt: existingIssued, reason: "already_issued" };
      const current = findPosFiscalReceiptByPaymentId(db, fiscalPaymentId);
      if (!current) return { ok: false, reason: "missing_pending_receipt" };
      const currentStatus = String(current.fiscalStatus ?? "").toUpperCase();
      const retryableFailure =
        current.requiresFiscalRetry === true &&
        ["FAILED", "ERROR"].includes(currentStatus);
      if (
        !["PENDING", "PROCESSING"].includes(currentStatus) &&
        !retryableFailure
      ) {
        return { ok: false, receipt: current, reason: "terminal_receipt" };
      }
      if (!isPosFiscalRetryWindowOpen(current)) {
        const retryCutoffAt = posFiscalRetryCutoffIso(current);
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "EXPIRED",
          fiscalStatus: "EXPIRED",
          responseCode: "FISCAL_RETRY_WINDOW_EXPIRED",
          responseMessage: "Finestra retry fiscale terminata.",
          fiscalError: `Finestra retry fiscale terminata${retryCutoffAt ? ` alle ${retryCutoffAt}` : ""}.`,
          requiresFiscalRetry: false,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "retry_window_expired",
          message: "Scontrino fiscale non emesso: finestra retry terminata.",
          requiresFiscalRetry: false,
          payload: {
            retryCutoffAt,
            originalPayload: job.payload,
          },
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReceipt.retryExpired.appStateWrite");
        return { ok: false, receipt, reason: "retry_window_expired" };
      }
      const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
        status: "PROCESSING",
        fiscalStatus: "PROCESSING",
        responseCode: "FISCAL_API_PROCESSING",
        responseMessage: "Invio scontrino fiscale POS in corso.",
        attemptCount:
          Math.max(Math.trunc(Number(current.attemptCount) || 0), 0) + 1,
        lastAttemptAt: nowIso(),
        nextRetryAt: null,
        requiresFiscalRetry: false,
      });
      appendPosFiscalEvent(db, {
        paymentId: fiscalPaymentId,
        orderId: job.orderId,
        result: "processing",
        message: "Invio scontrino fiscale POS in corso.",
      });
      db.meta.lastWriteAt = nowIso();
      await writePaymentFiscalDb(db, "payments.fiscalReceipt.processing.appStateWrite");
      return { ok: true, receipt };
    },
  );
  if (!claim?.ok) {
    if (
      claim?.reason === "missing_pending_receipt" &&
      attempt < POS_FISCAL_API_JOB_MAX_ATTEMPTS
    ) {
      console.warn(
        `[fiscal-pos] ricevuta pendente non ancora visibile, ritento: ` +
          `paymentId=${fiscalPaymentId} attempt=${attempt + 1}/${POS_FISCAL_API_JOB_MAX_ATTEMPTS}`,
      );
      return {
        retry: true,
        delayMs: POS_FISCAL_API_JOB_RETRY_DELAY_MS,
        job: {
          ...job,
          attempt: attempt + 1,
          delayMs: POS_FISCAL_API_JOB_RETRY_DELAY_MS,
        },
      };
    }
    if (claim?.reason === "missing_pending_receipt") {
      await withDbMutation(
        `fiscal_pos_missing_pending_${fiscalPaymentId}`,
        async () => {
          const db = await readDb();
          ensureFiscalTrackingArrays(db);
          appendPosFiscalEvent(db, {
            paymentId: fiscalPaymentId,
            orderId: job.orderId,
            result: "missing_pending_receipt",
            message:
              "Scontrino fiscale POS non avviato: ricevuta pendente non trovata nel DB.",
            requiresFiscalRetry: true,
            payload: job.payload,
          });
          db.meta.lastWriteAt = nowIso();
          await writePaymentFiscalDb(db, "payments.fiscalReceipt.missingPending.appStateWrite");
        },
      );
    }
    return;
  }

  let status = null;
  try {
    console.info(
      `[fiscal-pos] verifica status fiscale asincrona: paymentId=${fiscalPaymentId}`,
    );
    status = await fetchPosFiscalApiJson(fiscalDevice.statusEndpoint, {
      baseUrl: fiscalDevice.apiBaseUrl,
      fiscalDeviceId: fiscalDevice.id,
    });
  } catch (error) {
    const fiscalError = fiscalApiErrorMessage(error);
    const message = `Server fiscale non raggiungibile: ${fiscalError}. Stampato solo scontrino normale.`;
    console.error(
      `[fiscal-pos] status non raggiungibile: paymentId=${fiscalPaymentId} error=${fiscalError}`,
    );
    await withDbMutation(
      `fiscal_pos_status_error_${fiscalPaymentId}`,
      async () => {
        const db = await readDb();
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "FAILED",
          responseCode: "FISCAL_API_STATUS_ERROR",
          responseMessage: "Scontrino fiscale POS non emesso.",
          fiscalStatus: "FAILED",
          fiscalError,
          nextRetryAt: buildPosFiscalRecoveryRetryResult(
            job,
            claim.receipt,
            attempt,
          )?.retry
            ? new Date(
                Date.now() + POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
              ).toISOString()
            : null,
          requiresFiscalRetry: true,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "status_error",
          message,
          requiresFiscalRetry: true,
          payload: job.payload,
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReceipt.statusError.appStateWrite");
        publishIntegrationNotificationStreamRefresh(
          "pos_fiscal_receipt_failed",
          {
            paymentId: fiscalPaymentId,
            receiptId: receipt?.id ?? "",
          },
        );
      },
    );
    return buildPosFiscalRecoveryRetryResult(job, claim.receipt, attempt);
  }

  if (
    status?.dryRun !== true &&
    (status?.ok !== true || status?.fiscalApiEnabled !== true)
  ) {
    const message =
      "Server fiscale non pronto/abilitato: stampato solo scontrino normale, invio fiscale in retry.";
    console.warn(
      `[fiscal-pos] fiscale non pronto: paymentId=${fiscalPaymentId}`,
    );
    await withDbMutation(
      `fiscal_pos_status_not_ok_${fiscalPaymentId}`,
      async () => {
        const db = await readDb();
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "FAILED",
          responseCode: "FISCAL_API_STATUS_NOT_OK",
          responseMessage: message,
          fiscalStatus: "FAILED",
          fiscalError: String(
            status?.message ?? status?.error ?? "server fiscale non pronto",
          ).slice(0, 240),
          nextRetryAt: buildPosFiscalRecoveryRetryResult(
            job,
            claim.receipt,
            attempt,
          )?.retry
            ? new Date(
                Date.now() + POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
              ).toISOString()
            : null,
          requiresFiscalRetry: true,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "status_not_ok",
          message,
          requiresFiscalRetry: true,
          payload: status,
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReceipt.statusNotOk.appStateWrite");
        publishIntegrationNotificationStreamRefresh(
          "pos_fiscal_receipt_retry_pending",
          {
            paymentId: fiscalPaymentId,
            receiptId: receipt?.id ?? "",
          },
        );
      },
    );
    return buildPosFiscalRecoveryRetryResult(job, claim.receipt, attempt);
  }

  if (status?.dryRun === true) {
    const message = `${FISCAL_PROVIDER_DRY_RUN_MESSAGE} Stampato solo scontrino normale, invio fiscale in retry.`;
    console.warn(
      `[fiscal-pos] provider in dry-run: paymentId=${fiscalPaymentId}`,
    );
    await withDbMutation(
      `fiscal_pos_provider_dry_run_${fiscalPaymentId}`,
      async () => {
        const db = await readDb();
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "FAILED",
          responseCode: FISCAL_PROVIDER_DRY_RUN_CODE,
          responseMessage: "Scontrino fiscale POS reale non emesso.",
          fiscalStatus: "FAILED",
          fiscalError: FISCAL_PROVIDER_DRY_RUN_MESSAGE,
          nextRetryAt: buildPosFiscalRecoveryRetryResult(
            job,
            claim.receipt,
            attempt,
          )?.retry
            ? new Date(
                Date.now() + POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
              ).toISOString()
            : null,
          requiresFiscalRetry: true,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "provider_dry_run",
          message,
          requiresFiscalRetry: true,
          payload: { code: FISCAL_PROVIDER_DRY_RUN_CODE, status },
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(
          db,
          "payments.fiscalReceipt.dryRun.appStateWrite",
        );
        publishIntegrationNotificationStreamRefresh(
          "pos_fiscal_receipt_retry_pending",
          {
            paymentId: fiscalPaymentId,
            receiptId: receipt?.id ?? "",
          },
        );
      },
    );
    return buildPosFiscalRecoveryRetryResult(job, claim.receipt, attempt);
  }

  const verificationResult =
    await posFiscalIssueVerificationService.verifyBeforeWrite({
      job,
      fiscalDevice,
      receipt: claim.receipt,
      attempt,
    });
  if (verificationResult.handled) return verificationResult.result;

  try {
    console.info(
      `[fiscal-pos] invio scontrino fiscale asincrono: paymentId=${fiscalPaymentId} ` +
        `orderId=${job.orderId ?? "-"} items=${Array.isArray(job.payload?.items) ? job.payload.items.length : 0}`,
    );
    const response = await fetchPosFiscalApiJson(fiscalDevice.receiptEndpoint, {
      method: "POST",
      body: job.payload,
      baseUrl: fiscalDevice.apiBaseUrl,
      idempotencyKey: job.idempotencyKey,
      fiscalDeviceId: fiscalDevice.id,
    });
    if (response?.ok === false) {
      throw new Error(
        response?.message ||
          response?.error ||
          "API fiscale ha rifiutato lo scontrino",
      );
    }
    const {
      fiscalProviderRef: providerRef,
      fiscalMovementId,
      fiscalReceiptDate,
      fiscalDocumentNumber,
    } = extractPosFiscalReferenceFromApiResponse(response);
    return await withDbMutation(`fiscal_pos_issued_${fiscalPaymentId}`, async () => {
      const db = await readDb();
      const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
        status: "ISSUED",
        responseCode: providerRef || "FISCAL_API_OK",
        responseMessage: String(
          response?.message ?? "Scontrino fiscale POS emesso.",
        ),
        fiscalStatus: "ISSUED",
        fiscalProviderRef: providerRef,
        fiscalMovementId,
        fiscalReceiptDate,
        fiscalDocumentNumber,
        fiscalError: null,
        requiresFiscalRetry: false,
      });
      linkPosFiscalReceiptToPaymentRecords(db, receipt, {
        paymentId: fiscalPaymentId,
        paymentContainerId: job.paymentContainerId,
        issuedBy: job.issuedBy,
      });
      appendPosFiscalEvent(db, {
        paymentId: fiscalPaymentId,
        orderId: job.orderId,
        result: "issued",
        message: "Scontrino fiscale POS emesso.",
        payload: { receiptId: receipt?.id ?? null, providerRef, response },
      });
      db.meta.lastWriteAt = nowIso();
      await writePaymentFiscalDb(db, "payments.fiscalReceipt.issued.appStateWrite");
      publishIntegrationNotificationStreamRefresh("pos_fiscal_receipt_issued", {
        paymentId: fiscalPaymentId,
        receiptId: receipt?.id ?? "",
        providerRef: providerRef ?? "",
      });
      console.info(
        `[fiscal-pos] scontrino fiscale emesso: paymentId=${fiscalPaymentId} ` +
          `receiptId=${receipt?.id ?? "-"} providerRef=${providerRef ?? "-"}`,
      );
      return { issued: true, receipt };
    });
  } catch (error) {
    const fiscalError = fiscalApiErrorMessage(error);
    const message = `Scontrino fiscale POS non emesso: ${fiscalError}. Stampato scontrino normale; recupero manuale necessario.`;
    console.error(
      `[fiscal-pos] errore emissione: paymentId=${fiscalPaymentId} error=${fiscalError}`,
    );
    await withDbMutation(
      `fiscal_pos_receipt_error_${fiscalPaymentId}`,
      async () => {
        const db = await readDb();
        const receipt = updatePosFiscalReceiptByPaymentId(db, fiscalPaymentId, {
          status: "FAILED",
          responseCode: "FISCAL_API_ERROR",
          responseMessage: "Scontrino fiscale POS non emesso.",
          fiscalStatus: "FAILED",
          fiscalError,
          nextRetryAt: buildPosFiscalRecoveryRetryResult(
            job,
            claim.receipt,
            attempt,
          )?.retry
            ? new Date(
                Date.now() + POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS,
              ).toISOString()
            : null,
          requiresFiscalRetry: true,
        });
        appendPosFiscalEvent(db, {
          paymentId: fiscalPaymentId,
          orderId: job.orderId,
          result: "receipt_error",
          message,
          requiresFiscalRetry: true,
          payload: job.payload,
        });
        db.meta.lastWriteAt = nowIso();
        await writePaymentFiscalDb(db, "payments.fiscalReceipt.error.appStateWrite");
        publishIntegrationNotificationStreamRefresh(
          "pos_fiscal_receipt_failed",
          {
            paymentId: fiscalPaymentId,
            receiptId: receipt?.id ?? "",
          },
        );
      },
    );
    return buildPosFiscalRecoveryRetryResult(job, claim.receipt, attempt);
  }
}

function findLatestPosFiscalPayloadFromEvents(db, paymentId) {
  const normalizedPaymentId = String(paymentId ?? "").trim();
  if (!normalizedPaymentId) return null;
  const events = Array.isArray(db.fiscalEvents) ? db.fiscalEvents : [];
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (String(event?.provider ?? "").trim() !== POS_FISCAL_API_PROVIDER)
      continue;
    if (String(event?.paymentId ?? "").trim() !== normalizedPaymentId) continue;
    const payload =
      event?.payload && typeof event.payload === "object"
        ? event.payload
        : null;
    if (payload && Array.isArray(payload.items) && payload.items.length > 0) {
      return cloneJson(payload, null);
    }
  }
  return null;
}

function buildRecoveredPosFiscalJob(db, receipt) {
  const fiscalPaymentId = String(receipt?.paymentId ?? "").trim();
  if (!fiscalPaymentId) return null;
  const payments = Array.isArray(db.payments) ? db.payments : [];
  const payment =
    payments.find(
      (entry) => String(entry?.paymentTxId ?? "").trim() === fiscalPaymentId,
    ) ??
    payments.find(
      (entry) => String(entry?.id ?? "").trim() === fiscalPaymentId,
    ) ??
    null;
  const transaction =
    (Array.isArray(db.paymentTransactions) ? db.paymentTransactions : []).find(
      (entry) => String(entry?.id ?? "").trim() === fiscalPaymentId,
    ) ?? null;
  const paymentContainerId = String(
    payment?.paymentContainerId ?? payment?.id ?? "",
  ).trim();
  const container = paymentContainerId
    ? ((Array.isArray(db.paymentContainers) ? db.paymentContainers : []).find(
        (entry) => String(entry?.id ?? "").trim() === paymentContainerId,
      ) ?? null)
    : null;
  const receiptPayloadSnapshot =
    receipt?.payloadSnapshot && typeof receipt.payloadSnapshot === "object"
      ? cloneJson(receipt.payloadSnapshot, null)
      : null;
  const storedPayload =
    receiptPayloadSnapshot ??
    findLatestPosFiscalPayloadFromEvents(db, fiscalPaymentId);
  const fallbackPayload = buildPosFiscalReceiptPayload(
    db,
    {
      paymentId: paymentContainerId || fiscalPaymentId,
      transactionId: fiscalPaymentId,
      orderId: payment?.orderId ?? container?.orderId ?? null,
      orderIds: Array.isArray(payment?.orderIds)
        ? payment.orderIds
        : container?.orderIds,
      articleUnitIds: Array.isArray(payment?.items)
        ? payment.items.flatMap((item) =>
            normalizeStringList(item?.articleUnitIds, 1000, 120),
          )
        : container?.articleUnitIds,
      amount: payment?.amount ?? container?.amount,
      paymentItems: payment?.items,
      methodType: transaction?.method,
      paymentMethodId: payment?.methodId ?? container?.paymentMethod,
      paymentMethodLabel: payment?.methodLabel ?? container?.paymentMethod,
    },
    fiscalPaymentId,
  );
  const payload =
    storedPayload &&
    Array.isArray(storedPayload.items) &&
    storedPayload.items.length > 0
      ? storedPayload
      : fallbackPayload;
  if (!payload || !Array.isArray(payload.items) || payload.items.length === 0)
    return null;
  const paymentMethodId = String(
    payment?.methodId ?? container?.paymentMethod ?? "",
  ).trim();
  const storedFiscalDevice = normalizePosFiscalDeviceJobConfig({
    id: receipt?.fiscalDeviceId,
    apiBaseUrl: receipt?.fiscalApiBaseUrl,
    statusEndpoint: receipt?.fiscalStatusEndpoint,
    verifyEndpoint: receipt?.fiscalVerifyEndpoint,
    receiptEndpoint: receipt?.fiscalReceiptEndpoint,
    reprintEndpoint: receipt?.fiscalReprintEndpoint,
    voidEndpoint: receipt?.fiscalVoidEndpoint,
  });
  const configuredFiscalDevice = storedFiscalDevice
    ? null
    : normalizePosFiscalDeviceJobConfig(
        selectConfiguredPosFiscalApiDevice(
          db.posSettings,
          paymentMethodId,
          "receipt",
        ),
      );
  const legacyProviderFiscalDevice =
    storedFiscalDevice || configuredFiscalDevice
      ? null
      : String(receipt?.fiscalProvider ?? "").trim() === POS_FISCAL_API_PROVIDER
        ? normalizePosFiscalDeviceJobConfig({
            id: "pos_fiscal_api_recovery",
            apiBaseUrl: POS_FISCAL_API_BASE_URL,
          })
        : null;
  return {
    paymentId: fiscalPaymentId,
    paymentContainerId,
    orderId:
      String(
        payload.orderId ?? payment?.orderId ?? container?.orderId ?? "",
      ).trim() || null,
    issuedBy:
      String(
        payment?.collectedByUserId ?? container?.collectedByUserId ?? "",
      ).trim() || null,
    payload,
    fiscalDevice:
      storedFiscalDevice ??
      configuredFiscalDevice ??
      legacyProviderFiscalDevice,
    idempotencyKey:
      receipt?.idempotencyKey ||
      receipt?.fiscalRequestId ||
      buildPosFiscalRequestId(fiscalPaymentId),
  };
}

async function resumePendingPosFiscalReceiptJobs() {
  if (FISCAL_REAL_IO_DISABLED) {
    console.warn(
      "[fiscal-pos] ripresa job POS pendenti disabilitata: I/O reale disabilitato per test.",
    );
    return;
  }
  const db = await readDb();
  ensureFiscalTrackingArrays(db);
  const pendingReceipts = (
    Array.isArray(db.fiscalReceipts) ? db.fiscalReceipts : []
  )
    .map((receipt, index) =>
      sanitizeFiscalReceipt(receipt, `fiscal_${index + 1}`),
    )
    .filter((receipt) => {
      if (!receipt || receipt.fiscalProvider !== POS_FISCAL_API_PROVIDER)
        return false;
      const status = String(receipt.fiscalStatus ?? "").toUpperCase();
      if (["PENDING", "PROCESSING"].includes(status)) return true;
      return (
        receipt.requiresFiscalRetry === true &&
        ["FAILED", "ERROR"].includes(status)
      );
    });
  pendingReceipts.forEach((receipt) => {
    const job = buildRecoveredPosFiscalJob(db, receipt);
    if (job) {
      schedulePosFiscalReceiptBackgroundJob(job);
    }
  });
  if (pendingReceipts.length > 0) {
    console.info(
      `[fiscal-pos] ripresi job fiscali POS pendenti/retry: ${pendingReceipts.length}`,
    );
  }
}

const fiscalOutboxWorkerRuntime = createFiscalOutboxPosWorkerRuntime({ enabled: FISCAL_OUTBOX_WORKER_ENABLED, relationalRuntime, FiscalOutboxRepository, PaymentsRelationalRepository, intervalMs: FISCAL_OUTBOX_WORKER_INTERVAL_MS, batchSize: FISCAL_OUTBOX_WORKER_BATCH_SIZE, leaseMs: FISCAL_OUTBOX_WORKER_LEASE_MS, retryDelayMs: POS_FISCAL_API_RECOVERY_RETRY_DELAY_MS, maxAttempts: POS_FISCAL_API_JOB_MAX_ATTEMPTS, provider: POS_FISCAL_API_PROVIDER, nowIso, readDb, ensureFiscalTrackingArrays, findPosFiscalReceiptByPaymentId, issueQueuedPosFiscalReceipt, logger: console });

async function maybeIssuePosFiscalReceipt(db, options = {}) {
  ensureFiscalTrackingArrays(db);
  const fiscalPaymentId = String(
    options.transactionId ?? options.paymentId ?? "",
  ).trim();
  const paymentContainerId = String(options.paymentId ?? "").trim();
  if (isPosDemoModeEnabled(db?.posSettings)) {
    appendPosFiscalEvent(db, {
      paymentId: fiscalPaymentId || null,
      orderId: options.orderId ?? null,
      result: "demo_mode_skipped",
      message: "Emissione fiscale non eseguita: modalita demo attiva.",
      requiresFiscalRetry: false,
      payload: {
        paymentMethodId: options.paymentMethodId ?? null,
        methodType: options.methodType ?? null,
      },
    });
    return {
      issued: false,
      skipped: true,
      demoMode: true,
      warning: "Modalita demo attiva: nessuna emissione fiscale eseguita.",
    };
  }
  if (
    !isMobileDeviceFiscalAllowed(db?.posSettings, {
      deviceUuid: options.deviceUuid,
      methodType: options.methodType,
      paymentMethodId: options.paymentMethodId,
    })
  ) {
    appendPosFiscalEvent(db, {
      paymentId: fiscalPaymentId || null,
      orderId: options.orderId ?? null,
      result: "mobile_device_fiscal_disabled",
      message:
        "Emissione fiscale non eseguita: palmare non abilitato alla fiscalita per questo metodo.",
      requiresFiscalRetry: false,
      payload: {
        deviceUuid: options.deviceUuid ?? null,
        paymentMethodId: options.paymentMethodId ?? null,
        methodType: options.methodType ?? null,
      },
    });
    return {
      issued: false,
      skipped: true,
      warning: "Palmare non abilitato alla fiscalita per questo metodo.",
    };
  }
  if (!fiscalPaymentId) {
    return {
      issued: false,
      skipped: true,
      warning:
        "Scontrino normale stampato; scontrino fiscale POS non emesso per id pagamento mancante.",
    };
  }
  const existing = findExistingPosFiscalReceipt(db, fiscalPaymentId);
  if (existing) {
    console.info(
      `[fiscal-pos] ricevuta gia emessa: paymentId=${fiscalPaymentId} receiptId=${existing.id}`,
    );
    return {
      issued: true,
      duplicate: true,
      receipt: existing,
    };
  }
  if (FISCAL_REAL_IO_DISABLED) {
    appendPosFiscalEvent(db, {
      paymentId: fiscalPaymentId,
      orderId: options.orderId ?? null,
      result: "real_io_disabled_for_tests",
      message:
        "Emissione fiscale POS non eseguita: I/O reale disabilitato per test.",
      requiresFiscalRetry: false,
      payload: {
        deviceUuid: options.deviceUuid ?? null,
        paymentMethodId: options.paymentMethodId ?? null,
        methodType: options.methodType ?? null,
      },
    });
    return {
      issued: false,
      skipped: true,
      warning:
        "Emissione fiscale POS disabilitata per test: nessun invio al dispositivo reale.",
    };
  }
  const existingTracked = findPosFiscalReceiptByPaymentId(db, fiscalPaymentId);
  if (existingTracked) {
    const trackedFiscalDeviceConfig = normalizePosFiscalDeviceJobConfig({
      id: existingTracked.fiscalDeviceId,
      apiBaseUrl: existingTracked.fiscalApiBaseUrl,
      statusEndpoint: existingTracked.fiscalStatusEndpoint,
      verifyEndpoint: existingTracked.fiscalVerifyEndpoint,
      receiptEndpoint: existingTracked.fiscalReceiptEndpoint,
      reprintEndpoint: existingTracked.fiscalReprintEndpoint,
      voidEndpoint: existingTracked.fiscalVoidEndpoint,
    });
    const trackedPayloadSnapshot =
      existingTracked.payloadSnapshot &&
      typeof existingTracked.payloadSnapshot === "object"
        ? cloneJson(existingTracked.payloadSnapshot, null)
        : null;
    const backgroundJob = {
      paymentId: fiscalPaymentId,
      paymentContainerId,
      orderId: options.orderId,
      issuedBy: options.issuedBy,
      payload:
        trackedPayloadSnapshot ??
        buildPosFiscalReceiptPayload(db, options, fiscalPaymentId),
      fiscalDevice: trackedFiscalDeviceConfig,
      idempotencyKey:
        existingTracked.idempotencyKey ||
        existingTracked.fiscalRequestId ||
        buildPosFiscalRequestId(fiscalPaymentId),
    };
    if (
      ["PENDING", "PROCESSING"].includes(
        String(existingTracked.fiscalStatus ?? "").toUpperCase(),
      )
    ) {
      if (options.deferSchedule === true) {
        // Il chiamante schedula il job dopo writeDb, cosi' il worker legge uno stato persistito.
      } else {
        schedulePosFiscalReceiptBackgroundJob(backgroundJob);
      }
    }
    return {
      issued: false,
      pending: ["PENDING", "PROCESSING"].includes(
        String(existingTracked.fiscalStatus ?? "").toUpperCase(),
      ),
      requiresRetry: existingTracked.requiresFiscalRetry === true,
      receipt: existingTracked,
      backgroundJob: ["PENDING", "PROCESSING"].includes(
        String(existingTracked.fiscalStatus ?? "").toUpperCase(),
      )
        ? backgroundJob
        : null,
      warning:
        existingTracked.requiresFiscalRetry === true
          ? "Scontrino fiscale POS non emesso; recupero manuale necessario."
          : "Scontrino fiscale POS gia in gestione per questa transazione.",
    };
  }

  const fiscalPayload = buildPosFiscalReceiptPayload(
    db,
    options,
    fiscalPaymentId,
  );
  const fiscalRequestId = buildPosFiscalRequestId(fiscalPaymentId);
  const fiscalPayloadSnapshot = cloneJson(fiscalPayload, fiscalPayload);
  const fiscalPayloadHash = hashPosFiscalPayload(fiscalPayloadSnapshot);
  const fiscalOrderId = String(fiscalPayload.orderId ?? "").trim() || null;
  if (!Array.isArray(fiscalPayload.items) || fiscalPayload.items.length === 0) {
    const message =
      "Scontrino fiscale POS non emesso: nessun articolo fiscale valido. Stampato solo scontrino normale.";
    const failedReceipt = sanitizeFiscalReceipt(
      {
        id: `fiscal_${randomUUID().replace(/-/g, "")}`,
        paymentId: fiscalPaymentId,
        command: "pos_receipt",
        status: "FAILED",
        responseCode: "FISCAL_ITEMS_EMPTY",
        responseMessage: message,
        fiscalStatus: "FAILED",
        fiscalProvider: POS_FISCAL_API_PROVIDER,
        fiscalRequestId,
        idempotencyKey: fiscalRequestId,
        payloadSnapshot: fiscalPayloadSnapshot,
        payloadHash: fiscalPayloadHash,
        fiscalError: "Nessun articolo fiscale valido nel payload.",
        requiresFiscalRetry: true,
        createdAt: nowIso(),
      },
      `fiscal_${Date.now()}`,
    );
    if (failedReceipt) db.fiscalReceipts.push(failedReceipt);
    appendPosFiscalEvent(db, {
      paymentId: fiscalPaymentId,
      orderId: fiscalOrderId,
      result: "items_empty",
      message,
      requiresFiscalRetry: true,
    });
    return {
      issued: false,
      requiresRetry: true,
      warning: message,
    };
  }
  const requestedFiscalDeviceIds = collectFiscalDeviceIdsForPaymentOptions(
    db,
    options,
  );
  const fiscalDevice = selectConfiguredPosFiscalApiDevice(
    db.posSettings,
    options.paymentMethodId,
    "receipt",
    requestedFiscalDeviceIds,
  );
  const fiscalDeviceConfig = normalizePosFiscalDeviceJobConfig(fiscalDevice);
  if (!fiscalDeviceConfig) {
    const message =
      requestedFiscalDeviceIds.length > 0
        ? "Scontrino fiscale POS non emesso: RT indicata non disponibile."
        : "Scontrino fiscale POS non emesso: RT non configurata per la transazione.";
    const failedReceipt = sanitizeFiscalReceipt(
      {
        id: `fiscal_${randomUUID().replace(/-/g, "")}`,
        paymentId: fiscalPaymentId,
        command: "pos_receipt",
        status: "FAILED_CONFIGURATION",
        responseCode: "FISCAL_DEVICE_NOT_AVAILABLE",
        responseMessage: message,
        fiscalStatus: "FAILED_CONFIGURATION",
        fiscalProvider: POS_FISCAL_API_PROVIDER,
        fiscalRequestId,
        idempotencyKey: fiscalRequestId,
        payloadSnapshot: fiscalPayloadSnapshot,
        payloadHash: fiscalPayloadHash,
        fiscalError:
          "RT fiscale non disponibile per la configurazione indicata.",
        requiresFiscalRetry: false,
        createdAt: nowIso(),
      },
      `fiscal_${Date.now()}`,
    );
    if (failedReceipt) db.fiscalReceipts.push(failedReceipt);
    appendPosFiscalEvent(db, {
      paymentId: fiscalPaymentId,
      orderId: fiscalOrderId,
      result: "fiscal_device_not_available",
      message,
      requiresFiscalRetry: false,
      payload: {
        requestedFiscalDeviceIds,
        paymentMethodId: options.paymentMethodId ?? null,
      },
    });
    return {
      issued: false,
      skipped: true,
      warning: message,
    };
  }

  const receipt = sanitizeFiscalReceipt(
    {
      id: `fiscal_${randomUUID().replace(/-/g, "")}`,
      paymentId: fiscalPaymentId,
      command: "pos_receipt",
      status: "PENDING",
      responseCode: "FISCAL_API_QUEUED",
      responseMessage: "Scontrino fiscale POS accodato.",
      fiscalStatus: "PENDING",
      fiscalProvider: POS_FISCAL_API_PROVIDER,
      fiscalDeviceId: fiscalDeviceConfig.id,
      fiscalApiBaseUrl: fiscalDeviceConfig.apiBaseUrl,
      fiscalStatusEndpoint: fiscalDeviceConfig.statusEndpoint,
      fiscalVerifyEndpoint: fiscalDeviceConfig.verifyEndpoint,
      fiscalReceiptEndpoint: fiscalDeviceConfig.receiptEndpoint,
      fiscalReprintEndpoint: fiscalDeviceConfig.reprintEndpoint,
      fiscalVoidEndpoint: fiscalDeviceConfig.voidEndpoint,
      fiscalRequestId,
      idempotencyKey: fiscalRequestId,
      payloadSnapshot: fiscalPayloadSnapshot,
      payloadHash: fiscalPayloadHash,
      retryCutoffAt: posFiscalRetryCutoffIso({ createdAt: nowIso() }),
      requiresFiscalRetry: false,
      createdAt: nowIso(),
    },
    `fiscal_${Date.now()}`,
  );
  if (receipt) db.fiscalReceipts.push(receipt);
  appendPosFiscalEvent(db, {
    paymentId: fiscalPaymentId,
    orderId: fiscalOrderId,
    result: "queued",
    message: "Scontrino fiscale POS accodato fuori dalla coda principale.",
    payload: {
      ...fiscalPayload,
      fiscalDeviceId: fiscalDeviceConfig.id,
    },
  });
  const backgroundJob = {
    paymentId: fiscalPaymentId,
    paymentContainerId,
    orderId: fiscalOrderId,
    issuedBy: options.issuedBy,
    payload: cloneJson(fiscalPayload, fiscalPayload),
    fiscalDevice: fiscalDeviceConfig,
    idempotencyKey: fiscalRequestId,
  };
  if (options.deferSchedule === true) {
    // Il pagamento e la ricevuta PENDING non sono ancora garantiti su disco.
    // Il chiamante avvia il job subito dopo writeDb.
  } else {
    schedulePosFiscalReceiptBackgroundJob(backgroundJob);
  }
  return {
    issued: false,
    pending: true,
    receipt,
    backgroundJob,
    warning:
      "Scontrino normale stampato; invio fiscale POS in corso in background.",
  };
}

function shouldIssuePosFiscalReceiptForPayload(payload = {}) {
  if (!payload || typeof payload !== "object") return false;
  const issueConfirmed =
    payload.issueFiscal === true ||
    payload.confirmFiscalReceipt === true ||
    payload.fiscalReceiptConfirmed === true;
  if (!issueConfirmed) return false;
  const fiscalDocType = String(payload.fiscalDocType ?? "")
    .trim()
    .toUpperCase();
  const receiptType = String(payload.receiptType ?? payload.documentType ?? "")
    .trim()
    .toLowerCase();
  if (
    fiscalDocType === "INVOICE" ||
    receiptType === "fattura" ||
    receiptType === "invoice"
  )
    return false;
  return (
    fiscalDocType === "RECEIPT" ||
    receiptType === "scontrino" ||
    receiptType === "receipt" ||
    !fiscalDocType
  );
}

function isPosDemoModeEnabled(settings) {
  return settings?.demoMode === true;
}

function findConfiguredMobileDeviceForFiscal(settings, deviceUuid = "") {
  const normalizedDeviceUuid = String(deviceUuid ?? "").trim();
  if (!normalizedDeviceUuid) return null;
  return (
    (Array.isArray(settings?.mobileDevices) ? settings.mobileDevices : []).find(
      (device) => {
        const deviceId = String(device?.deviceId ?? "").trim();
        const configuredDeviceUuid = String(
          device?.deviceUuid ?? device?.uuid ?? "",
        ).trim();
        const id = String(device?.id ?? "").trim();
        return (
          deviceId === normalizedDeviceUuid ||
          configuredDeviceUuid === normalizedDeviceUuid ||
          id === normalizedDeviceUuid
        );
      },
    ) ?? null
  );
}

function isMobileDeviceFiscalAllowed(
  settings,
  { deviceUuid = "", methodType = "", paymentMethodId = "" } = {},
) {
  const normalizedMethodType = normalizePaymentMethodType(methodType);
  const normalizedMethodId = String(paymentMethodId ?? "").trim();
  // Il pagamento elettronico POS deve essere fiscalizzabile per qualunque
  // palmare, anche non ancora registrato nelle impostazioni. Il vero gate resta
  // la configurazione RT + demo mode; il device non deve bloccare i POS futuri.
  if (normalizedMethodType === "POS" || normalizedMethodId === "pay_card") {
    return true;
  }
  const configured = findConfiguredMobileDeviceForFiscal(settings, deviceUuid);
  if (!configured) return false;
  if (configured.fiscalEnabled !== true) return false;
  if (normalizedMethodType === "CASH" || normalizedMethodId === "pay_cash") {
    return configured.cashPaymentEnabled === true;
  }
  return false;
}

function normalizePosFiscalDeviceJobConfig(device) {
  if (!device || typeof device !== "object") return null;
  const id = normalizeConfigId(device.id ?? device.fiscalDeviceId, "");
  const explicitApiBaseUrl = [device.apiBaseUrl, device.fiscalApiBaseUrl].find(
    (value) => String(value ?? "").trim(),
  );
  const apiBaseUrl = String(explicitApiBaseUrl ?? "")
    .trim()
    .replace(/\/+$/, "");
  if (!id || !apiBaseUrl) return null;
  return {
    id,
    apiBaseUrl,
    statusEndpoint: normalizePosFiscalApiPath(
      device.statusEndpoint,
      "/api/fiscal/status",
    ),
    verifyEndpoint: normalizePosFiscalApiPath(
      device.verifyEndpoint ?? device.fiscalVerifyEndpoint,
      "/api/fiscal/receipt/verify",
    ),
    receiptEndpoint: normalizePosFiscalApiPath(
      device.receiptEndpoint,
      "/api/fiscal/receipt",
    ),
    reprintEndpoint: normalizePosFiscalApiPath(
      device.reprintEndpoint,
      "/api/fiscal/reprint",
    ),
    voidEndpoint: normalizePosFiscalApiPath(
      device.voidEndpoint ?? device.fiscalVoidEndpoint,
      "/api/fiscal/void",
    ),
  };
}

function collectFiscalDeviceIdsForPaymentOptions(db, options = {}) {
  const explicitIds = normalizeReferenceIdList(
    [
      options.fiscalDeviceId,
      ...(Array.isArray(options.fiscalDeviceIds)
        ? options.fiscalDeviceIds
        : []),
    ],
    null,
    16,
  );
  const orderIds = normalizePaymentOrderIdList(
    [
      options.orderId,
      ...(Array.isArray(options.orderIds) ? options.orderIds : []),
    ],
    "",
  );
  const orders = Array.isArray(db?.integration?.orders)
    ? db.integration.orders
    : [];
  const orderDeviceIds = orderIds.flatMap((orderId) => {
    const order =
      orders.find((entry) => String(entry?.id ?? "").trim() === orderId) ??
      null;
    return normalizeReferenceIdList(
      order?.operationalSnapshot?.fiscalDeviceIds,
      null,
      16,
    );
  });
  return [...new Set([...explicitIds, ...orderDeviceIds])].filter(Boolean);
}

function selectConfiguredPosFiscalApiDevice(
  settings,
  paymentMethodId = "",
  capability = "receipt",
  requestedDeviceIds = [],
) {
  const safeMethodId = String(paymentMethodId ?? "").trim();
  const safeCapability = String(capability ?? "receipt")
    .trim()
    .toLowerCase();
  const requestedIds = new Set(
    normalizeReferenceIdList(
      Array.isArray(requestedDeviceIds)
        ? requestedDeviceIds
        : [requestedDeviceIds],
      null,
      16,
    ),
  );
  const configuredDevices = Array.isArray(settings?.fiscalDevices)
    ? settings.fiscalDevices
    : [];
  const matches = configuredDevices.filter((device) => {
    if (!device || device.active === false || device.status === "disabled")
      return false;
    const deviceId = normalizeConfigId(device.id ?? device.fiscalDeviceId, "");
    if (requestedIds.size > 0 && !requestedIds.has(deviceId)) return false;
    const provider = String(device.fiscalProvider ?? device.provider ?? "")
      .trim()
      .toLowerCase();
    if (provider && provider !== POS_FISCAL_API_PROVIDER) return false;
    if (!normalizePosFiscalDeviceJobConfig(device)) return false;
    if (safeCapability === "reprint" && device.supportsReprint === false)
      return false;
    const supportedMethods = normalizeReferenceIdList(
      device.paymentMethodIds ?? device.supportedPaymentMethodIds,
      null,
      16,
    );
    if (
      safeMethodId &&
      supportedMethods.length > 0 &&
      !supportedMethods.includes(safeMethodId)
    )
      return false;
    if (safeMethodId === "pay_cash" && device.supportsCash === false)
      return false;
    if (safeMethodId === "pay_card" && device.supportsElectronic === false)
      return false;
    return true;
  });
  if (matches.length > 1) {
    throw new HttpError(
      409,
      "Configurazione RT ambigua per il metodo di pagamento.",
      {
        code: "FISCAL_DEVICE_AMBIGUOUS",
        details: {
          paymentMethodId: safeMethodId || null,
          capability: safeCapability,
          fiscalDeviceIds: matches
            .map((device) =>
              normalizeConfigId(device.id ?? device.fiscalDeviceId, ""),
            )
            .filter(Boolean),
        },
      },
    );
  }
  return matches.length === 1 ? matches[0] : null;
}

function hasConfiguredPosFiscalApiDevice(
  settings,
  paymentMethodId = "",
  capability = "receipt",
  requestedDeviceIds = [],
) {
  return Boolean(
    selectConfiguredPosFiscalApiDevice(
      settings,
      paymentMethodId,
      capability,
      requestedDeviceIds,
    ),
  );
}

function shouldIssuePosFiscalReceiptForTransaction({
  settings,
  payload,
  methodType,
  paymentMethodId,
} = {}) {
  if (isPosDemoModeEnabled(settings)) return false;
  if (!shouldIssuePosFiscalReceiptForPayload(payload)) return false;
  if (
    !isMobileDeviceFiscalAllowed(settings, {
      deviceUuid: payload?.deviceUuid,
      methodType,
      paymentMethodId,
    })
  ) {
    return false;
  }
  const normalizedMethodType = normalizePaymentMethodType(methodType);
  if (normalizedMethodType === "POS") {
    return hasConfiguredPosFiscalApiDevice(settings, "pay_card");
  }
  if (normalizedMethodType === "CASH") {
    return hasConfiguredPosFiscalApiDevice(settings, "pay_cash");
  }
  return false;
}

function normalizeIdempotencyKey(payload = {}) {
  return String(payload.idempotencyKey ?? payload.clientPaymentId ?? "").trim();
}

function ensureServerIdempotencyKey(payload = {}, prefix = "pay") {
  const existing = normalizeIdempotencyKey(payload);
  if (existing) return existing;
  return `${prefix}_${randomUUID().replace(/-/g, "")}`;
}

function paymentErrorPayload(error) {
  return {
    message:
      error instanceof Error
        ? error.message
        : String(error ?? "Errore pagamento."),
    code: error?.code ? String(error.code) : null,
    status: Number.isFinite(Number(error?.status))
      ? Number(error.status)
      : null,
    details:
      error?.details && typeof error.details === "object"
        ? cloneJson(error.details, {})
        : null,
  };
}

function appendPaymentProviderAuditEvent(
  db,
  { action, transactionId, user, payload = {}, details = {} } = {},
) {
  const safeAction = String(action ?? "").trim();
  const safeTransactionId = String(transactionId ?? "").trim();
  if (!safeAction || !safeTransactionId) return;
  appendAuditEvent(db, {
    ...buildAuditActor(user, payload),
    action: safeAction,
    entityType: "payment_provider_transaction",
    entityId: safeTransactionId,
    payload: {
      transactionId: safeTransactionId,
      ...cloneJson(details, {}),
    },
  });
}

async function persistPaymentProviderTransaction(
  db,
  transactionId,
  patch = {},
  audit = {},
  writeOptions = {},
) {
  const auditStartIndex = Array.isArray(db.auditEvents) ? db.auditEvents.length : 0;
  const updated = paymentTransactionRepository.updateInDb(
    db,
    transactionId,
    patch,
  );
  if (!updated) {
    throw new HttpError(
      500,
      "Impossibile aggiornare la transazione provider del pagamento.",
    );
  }
  if (audit?.action) {
    appendPaymentProviderAuditEvent(db, {
      ...audit,
      transactionId,
      details: {
        status: updated.status,
        phase: updated.phase,
        ...(audit.details && typeof audit.details === "object"
          ? audit.details
          : {}),
      },
    });
  }
  db.meta.lastWriteAt = nowIso();
  await writePaymentFreeSplitDb(db, {
    metricLabel:
      writeOptions.metricLabel ?? "payments.provider.transaction.appStateWrite",
    splitDomains:
      writeOptions.splitDomains ?? PAYMENT_PROVIDER_WRITE_SPLIT_DOMAINS,
    auditEventIds: collectAuditEventIdsSince(db, auditStartIndex),
    collectionEntryIds: { paymentProviderTransactions: [transactionId] },
  });
  return updated;
}

async function persistPaymentProviderFailure(
  db,
  transactionId,
  error,
  { cardAuthorization = null, user, payload = {}, writeOptions = {} } = {},
) {
  const auditStartIndex = Array.isArray(db.auditEvents) ? db.auditEvents.length : 0;
  const errorPayload = paymentErrorPayload(error);
  const hasCapturedAuthorization =
    cardAuthorization && typeof cardAuthorization === "object";
  const status = hasCapturedAuthorization
    ? "manual_reconciliation_required"
    : "failed";
  const patch = {
    status,
    phase: status,
    settlementError: {
      ...errorPayload,
      authorizationCaptured: hasCapturedAuthorization,
    },
  };
  if (hasCapturedAuthorization) {
    patch.settlementResponse = {
      authorization: cloneJson(cardAuthorization, {}),
      persistenceError: errorPayload,
    };
  }
  const updated = paymentTransactionRepository.updateInDb(
    db,
    transactionId,
    patch,
  );
  if (!updated) {
    throw new HttpError(
      500,
      "Impossibile aggiornare l'esito provider del pagamento.",
    );
  }
  appendPaymentProviderAuditEvent(db, {
    action: hasCapturedAuthorization
      ? "payment.provider_manual_reconciliation_required"
      : "payment.provider_failed",
    transactionId,
    user,
    payload,
    details: {
      status: updated.status,
      phase: updated.phase,
      error: errorPayload,
      authorizationCaptured: hasCapturedAuthorization,
    },
  });
  db.meta.lastWriteAt = nowIso();
  await writePaymentFreeSplitDb(db, {
    metricLabel:
      writeOptions.metricLabel ?? "payments.provider.failure.appStateWrite",
    splitDomains:
      writeOptions.splitDomains ?? PAYMENT_PROVIDER_WRITE_SPLIT_DOMAINS,
    auditEventIds: collectAuditEventIdsSince(db, auditStartIndex),
    collectionEntryIds: { paymentProviderTransactions: [transactionId] },
  });
  return updated;
}

async function authorizeCardPayment({
  amount,
  paymentMethodId,
  payload = {},
  transactionId = "",
} = {}) {
  const providedRef = String(
    payload.posTxRef ??
      payload.posTxRefId ??
      payload.cardAuthorizationRef ??
      "",
  ).trim();
  const providedProvider = String(
    payload.posProvider ?? payload.cardProvider ?? "",
  ).trim();
  if (providedRef) {
    return {
      ok: true,
      provider: providedProvider || "external",
      posTxRef: providedRef,
      mock: false,
      authorizedAt: nowIso(),
    };
  }
  if (
    providedProvider &&
    providedProvider.toLowerCase() !== "pos" &&
    CARD_PAYMENT_PROVIDER === "disabled"
  ) {
    return {
      ok: true,
      provider: providedProvider,
      posTxRef: `EXT-POS-${String(transactionId || randomUUID())
        .replace(/[^a-z0-9]/gi, "")
        .slice(0, 18)
        .toUpperCase()}`,
      external: true,
      amount: roundMoney(Math.max(Number(amount) || 0, 0)),
      paymentMethodId: String(paymentMethodId ?? "").trim() || null,
      authorizedAt: nowIso(),
    };
  }

  if (
    CARD_PAYMENT_PROVIDER === "mock" &&
    CARD_PAYMENT_MOCK_ENABLED === true &&
    !IS_PRODUCTION
  ) {
    return {
      ok: true,
      provider: "mock",
      posTxRef: `MOCK-POS-${String(transactionId || randomUUID())
        .replace(/-/g, "")
        .slice(0, 16)
        .toUpperCase()}`,
      mock: true,
      amount: roundMoney(Math.max(Number(amount) || 0, 0)),
      paymentMethodId: String(paymentMethodId ?? "").trim() || null,
      authorizedAt: nowIso(),
    };
  }

  throw new HttpError(
    501,
    "Autorizzazione carta non implementata: terminale POS non configurato.",
    {
      code: "CARD_AUTHORIZATION_UNAVAILABLE",
      details: {
        cardPaymentProvider: CARD_PAYMENT_PROVIDER,
        cardPaymentMockEnabled: CARD_PAYMENT_MOCK_ENABLED,
      },
    },
  );
}

function validatePaymentLinesAndAmount(lines, amount) {
  const normalizedLines = Array.isArray(lines) ? lines : [];
  const amountFromLines = roundMoney(
    normalizedLines.reduce(
      (sum, line) => sum + roundMoney(Math.max(Number(line.lineTotal) || 0, 0)),
      0,
    ),
  );
  normalizedLines.forEach((line, index) => {
    const qty = Math.max(Number(line.qty) || 0, 0);
    const unit = roundMoney(
      Math.max(
        Number.isFinite(Number(line.variantPrice))
          ? Number(line.variantPrice)
          : Number(line.unitPriceApplied ?? line.unitPrice) || 0,
        0,
      ),
    );
    const expected = roundMoney(qty * unit);
    const lineTotal = roundMoney(Math.max(Number(line.lineTotal) || 0, 0));
    if (Math.abs(expected - lineTotal) > 0.01) {
      throw new HttpError(
        400,
        `Totale riga #${index + 1} non coerente con quantita e prezzo unitario.`,
        {
          code: "PAYMENT_LINE_TOTAL_MISMATCH",
          details: { lineIndex: index, expected, lineTotal },
        },
      );
    }
  });
  if (Math.abs(amountFromLines - roundMoney(amount)) > 0.01) {
    throw new HttpError(
      400,
      "Totale pagamento non coerente con le righe ricevute.",
      {
        code: "PAYMENT_AMOUNT_MISMATCH",
        details: {
          amount,
          amountFromLines,
        },
      },
    );
  }
  return amountFromLines;
}

function findExistingPaymentByIdempotency(db, key, user, session) {
  const safeKey = String(key ?? "").trim();
  if (!safeKey) return null;
  const userId = String(user?.id ?? "").trim();
  const deviceUuid = String(session?.deviceUuid ?? "").trim();
  const container =
    (Array.isArray(db.paymentContainers) ? db.paymentContainers : [])
      .map((entry, index) =>
        sanitizePaymentContainerRecord(entry, `payc_${index + 1}`),
      )
      .find((entry) => {
        if (!entry || entry.idempotencyKey !== safeKey) return false;
        if (
          userId &&
          entry.collectedByUserId &&
          entry.collectedByUserId !== userId
        )
          return false;
        if (
          deviceUuid &&
          entry.collectedByDeviceUuid &&
          entry.collectedByDeviceUuid !== deviceUuid
        )
          return false;
        return true;
      }) ?? null;
  if (!container) return null;
  const payments = (Array.isArray(db.payments) ? db.payments : [])
    .map((entry, index) => sanitizePaymentRecord(entry, `pay_${index + 1}`))
    .filter(
      (entry) =>
        entry &&
        (entry.paymentContainerId === container.id ||
          entry.id === container.id),
    );
  return { container, payments };
}

function findExistingIntegrationIdempotencyRecord(
  records,
  key,
  user,
  deviceUuid,
) {
  const safeKey = String(key ?? "").trim();
  if (!safeKey || !Array.isArray(records)) return null;
  const userId = String(user?.id ?? "").trim();
  const safeDeviceUuid = String(deviceUuid ?? "").trim();
  return (
    records.find((entry) => {
      if (!entry || typeof entry !== "object") return false;
      if (String(entry.idempotencyKey ?? "").trim() !== safeKey) return false;
      if (
        userId &&
        String(entry.createdByUserId ?? "").trim() &&
        String(entry.createdByUserId ?? "").trim() !== userId
      ) {
        return false;
      }
      if (
        safeDeviceUuid &&
        String(entry.createdByDeviceUuid ?? "").trim() &&
        String(entry.createdByDeviceUuid ?? "").trim() !== safeDeviceUuid
      ) {
        return false;
      }
      return true;
    }) ?? null
  );
}

async function appendPrintSpoolJobToDb(db, payload) {
  if (shouldFastAppendDisabledPrintSpoolJob()) return appendDisabledPrintSpoolJobFast(db, payload);
  if (PRINT_SPOOL_SQL_PRIMARY) {
    return enqueuePrintSpoolJobSqlPrimary(payload, {
      db,
      appendLegacyMirrorToDb: true,
    });
  }
  const nextJob = buildPrintSpoolJobFromPayload(db, payload);
  await persistPrintSpoolJobFile(nextJob, payload);
  db.printSpoolJobs = [...sanitizePrintSpoolJobs(db.printSpoolJobs), nextJob];
  prunePrintSpoolJobs(db);
  return nextJob;
}

function sanitizeSmartCustomerForResponse(customer) {
  return {
    id: customer.id,
    firstName: customer.firstName,
    lastName: customer.lastName,
    phone: customer.phone,
    cardCode: customer.cardCode,
    active: customer.active !== false,
    unifiedCredit: customer.unifiedCredit === true,
    capabilities: customer.capabilities,
    balances: customer.balances,
    passes: customer.passes,
    accessLog: customer.accessLog,
    transactions: customer.transactions,
    createdAt: customer.createdAt,
    updatedAt: customer.updatedAt,
  };
}

function resolveSmartBeachPassCandidates(customer, nowDate) {
  const passes = Array.isArray(customer?.passes) ? customer.passes : [];
  const weekday = toWeekDayId(nowDate);
  const month = nowDate.getMonth() + 1;
  const candidates = [];
  let hasInvalidWeekday = false;
  let hasInvalidSeason = false;
  let latestExpiredDate = null;

  for (const [index, rawPass] of passes.entries()) {
    const pass = normalizeSmartPass(rawPass, `pass_${index + 1}`);
    if (!pass) continue;
    if (pass.type !== "ingressi_spiaggia") continue;
    if (pass.quantity <= 0) continue;

    const expiresAtDate = parseIsoDateSafe(pass.expiresAt);
    if (expiresAtDate && nowDate.getTime() > expiresAtDate.getTime()) {
      if (
        !latestExpiredDate ||
        expiresAtDate.getTime() > latestExpiredDate.getTime()
      ) {
        latestExpiredDate = expiresAtDate;
      }
      continue;
    }

    if (pass.validityType === "giorni") {
      const allowedWeekDays = pass.weekDays.length
        ? pass.weekDays
        : [1, 2, 3, 4, 5, 6];
      if (!allowedWeekDays.includes(weekday)) {
        hasInvalidWeekday = true;
        continue;
      }
    }

    if (pass.validityType === "stagionale") {
      const allowedMonths = pass.months.length ? pass.months : [6, 7, 8, 9];
      if (!allowedMonths.includes(month)) {
        hasInvalidSeason = true;
        continue;
      }
    }

    candidates.push({
      index,
      pass,
      expiresAtDate,
      createdAtDate: parseIsoDateSafe(pass.createdAt),
    });
  }

  candidates.sort((left, right) => {
    const leftExpiry = left.expiresAtDate
      ? left.expiresAtDate.getTime()
      : Number.POSITIVE_INFINITY;
    const rightExpiry = right.expiresAtDate
      ? right.expiresAtDate.getTime()
      : Number.POSITIVE_INFINITY;
    if (leftExpiry !== rightExpiry) return leftExpiry - rightExpiry;
    const leftCreated = left.createdAtDate ? left.createdAtDate.getTime() : 0;
    const rightCreated = right.createdAtDate
      ? right.createdAtDate.getTime()
      : 0;
    return leftCreated - rightCreated;
  });

  return {
    candidates,
    hasInvalidWeekday,
    hasInvalidSeason,
    latestExpiredDate,
  };
}

function getLanServerUrls(port) {
  const interfaces = networkInterfaces();
  const urls = [];
  for (const items of Object.values(interfaces)) {
    if (!Array.isArray(items)) continue;
    for (const item of items) {
      if (!item || item.internal) continue;
      if (item.family !== "IPv4") continue;
      urls.push(`http://${item.address}:${port}`);
    }
  }
  return Array.from(new Set(urls));
}

const TOP_SOLD_MENU_DEFAULT_DAYS = 15;
const TOP_SOLD_MENU_DEFAULT_LIMIT = 10;
const TOP_SOLD_MENU_MAX_DAYS = 90;
const TOP_SOLD_MENU_MAX_LIMIT = 50;

function normalizeTopSoldText(value) {
  return String(value ?? "").trim().replace(/\s+/g, " ");
}

function normalizeTopSoldKey(value) {
  return normalizeTopSoldText(value).toLocaleLowerCase("it-IT");
}

function resolveTopSoldTimestampMs(...values) {
  for (const value of values) {
    if (value == null || value === "") continue;
    if (typeof value === "number" && Number.isFinite(value)) {
      const normalized = value > 9_999_999_999 ? value : value * 1000;
      if (normalized > 0) return normalized;
      continue;
    }
    const parsed = Date.parse(String(value));
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function buildTopSoldMenuLookups(menuItems) {
  const byId = new Map();
  const byName = new Map();
  for (const item of Array.isArray(menuItems) ? menuItems : []) {
    if (!item || typeof item !== "object") continue;
    const id = normalizeTopSoldText(item.id);
    const name = normalizeTopSoldText(item.name);
    if (!id || !name) continue;
    const type = normalizeTopSoldKey(item.type ?? item.kind ?? "");
    if (type === "divider") continue;
    const entry = {
      id,
      name,
      enabled: item.enabled !== false,
      category: normalizeTopSoldText(item.category ?? ""),
    };
    byId.set(id, entry);
    const nameKey = normalizeTopSoldKey(name);
    if (nameKey && !byName.has(nameKey)) byName.set(nameKey, entry);
  }
  return { byId, byName };
}

function resolveTopSoldProduct(line, lookups) {
  const explicitId = normalizeTopSoldText(
    line?.productId ?? line?.product_id ?? line?.menuItemId ?? line?.menu_item_id ?? ""
  );
  if (explicitId && lookups.byId.has(explicitId)) return lookups.byId.get(explicitId);
  const name = normalizeTopSoldText(
    line?.productNameSnapshot ?? line?.productName ?? line?.name ?? line?.label ?? ""
  );
  const nameKey = normalizeTopSoldKey(name);
  if (nameKey && lookups.byName.has(nameKey)) return lookups.byName.get(nameKey);
  return null;
}

function addTopSoldLine(groups, line, lookups, soldAtMs, source) {
  if (!line || typeof line !== "object") return false;
  const product = resolveTopSoldProduct(line, lookups);
  if (!product || product.enabled === false) return false;
  const qtyRaw = Number(line.qty ?? line.quantity ?? line.qta ?? 1);
  const quantity = Number.isFinite(qtyRaw) ? Math.max(Math.trunc(qtyRaw), 0) : 1;
  if (quantity <= 0) return false;
  const unitPrice = roundMoney(
    Math.max(
      Number(line.unitPriceApplied ?? line.unitPrice ?? line.price ?? line.listPriceAtTime) || 0,
      0
    )
  );
  const lineTotal = roundMoney(
    Math.max(Number(line.lineTotal ?? line.total) || unitPrice * quantity, 0)
  );
  const current = groups.get(product.id) ?? {
    productId: product.id,
    name: product.name,
    category: product.category,
    quantity: 0,
    revenue: 0,
    lastSoldAtMs: 0,
    source,
  };
  current.quantity += quantity;
  current.revenue = roundMoney(current.revenue + lineTotal);
  current.lastSoldAtMs = Math.max(current.lastSoldAtMs, soldAtMs || 0);
  if (source === "payments") current.source = "payments";
  groups.set(product.id, current);
  return true;
}

function buildTopSoldMenuPayload(db, { days, limit } = {}) {
  const safeDays = Math.min(
    Math.max(Math.trunc(Number(days) || TOP_SOLD_MENU_DEFAULT_DAYS), 1),
    TOP_SOLD_MENU_MAX_DAYS
  );
  const safeLimit = Math.min(
    Math.max(Math.trunc(Number(limit) || TOP_SOLD_MENU_DEFAULT_LIMIT), 1),
    TOP_SOLD_MENU_MAX_LIMIT
  );
  const generatedAtMs = Date.now();
  const sinceMs = generatedAtMs - safeDays * 24 * 60 * 60 * 1000;
  const lookups = buildTopSoldMenuLookups(db?.menuItems);
  const groups = new Map();

  for (const rawPayment of Array.isArray(db?.payments) ? db.payments : []) {
    const payment = sanitizePaymentRecord(rawPayment, "payment_top_sold");
    if (!payment) continue;
    const soldAtMs = resolveTopSoldTimestampMs(payment.createdAt);
    if (!soldAtMs || soldAtMs < sinceMs || soldAtMs > generatedAtMs + 60_000) continue;
    for (const item of Array.isArray(payment.items) ? payment.items : []) {
      addTopSoldLine(groups, item, lookups, soldAtMs, "payments");
    }
  }

  if (groups.size === 0) {
    for (const rawOrder of Array.isArray(db?.integration?.orders) ? db.integration.orders : []) {
      const order = sanitizeIntegrationOrder(rawOrder, normalizeTopSoldText(rawOrder?.id) || "order_top_sold");
      if (isCancelledIntegrationWorkflowStatus(order.workflowStatus)) continue;
      const settled =
        String(order.paymentStatus ?? "").trim().toLowerCase() === "paid" ||
        Number(order.paidAmount) > 0.009;
      if (!settled) continue;
      const soldAtMs = resolveTopSoldTimestampMs(
        order.completedAtMs,
        order.updatedAt,
        order.createdAtMs,
        order.createdAt,
        order.receivedAtMs
      );
      if (!soldAtMs || soldAtMs < sinceMs || soldAtMs > generatedAtMs + 60_000) continue;
      for (const item of Array.isArray(order.items) ? order.items : []) {
        addTopSoldLine(groups, item, lookups, soldAtMs, "orders_fallback");
      }
    }
  }

  const items = [...groups.values()]
    .sort((left, right) =>
      right.quantity - left.quantity ||
      right.revenue - left.revenue ||
      right.lastSoldAtMs - left.lastSoldAtMs ||
      left.name.localeCompare(right.name, "it-IT")
    )
    .slice(0, safeLimit)
    .map((entry, index) => ({
      rank: index + 1,
      productId: entry.productId,
      name: entry.name,
      category: entry.category || null,
      quantity: entry.quantity,
      revenue: roundMoney(entry.revenue),
      lastSoldAt: entry.lastSoldAtMs ? new Date(entry.lastSoldAtMs).toISOString() : null,
      source: entry.source,
    }));

  return {
    ok: true,
    generatedAt: new Date(generatedAtMs).toISOString(),
    since: new Date(sinceMs).toISOString(),
    days: safeDays,
    limit: safeLimit,
    items,
  };
}

async function readJsonBody(req) {
  if (req.__jsonBodyParsed === true) {
    return mergeRequestAuthPayload(req, req.__jsonBodyPayload ?? {});
  }
  try {
    const requestMaxBodySize = Number(req.__jsonBodyMaxSize);
    const maxBodySize =
      Number.isFinite(requestMaxBodySize) && requestMaxBodySize > 0
        ? Math.min(requestMaxBodySize, MAX_BODY_SIZE)
        : MAX_BODY_SIZE;
    const payload = await readJsonBodyFromHttp(req, maxBodySize);
    req.__jsonBodyParsed = true;
    req.__jsonBodyPayload =
      payload && typeof payload === "object" ? payload : {};
    return mergeRequestAuthPayload(req, req.__jsonBodyPayload);
  } catch (error) {
    const message = error instanceof Error ? error.message : "JSON non valido.";
    throw new HttpError(
      message === "Payload troppo grande." ? 413 : 400,
      message,
    );
  }
}

function resolveRealtimeAggregateVersion(event) {
  const payload = event?.payload && typeof event.payload === "object" ? event.payload : {};
  const detail = payload.detail && typeof payload.detail === "object" ? payload.detail : {};
  const candidates = [
    payload.aggregateVersion,
    payload.revision,
    payload.currentRevision,
    detail.aggregateVersion,
    detail.revision,
    detail.currentRevision,
    detail.order?.aggregateVersion,
    detail.order?.revision,
    detail.order?.currentRevision,
    detail.table?.aggregateVersion,
    detail.table?.revision,
    detail.table?.currentRevision,
    detail.fromTable?.aggregateVersion,
    detail.fromTable?.revision,
    detail.fromTable?.currentRevision,
    detail.toTable?.aggregateVersion,
    detail.toTable?.revision,
    detail.toTable?.currentRevision,
  ];
  for (const candidate of candidates) {
    const numeric = Math.trunc(Number(candidate));
    if (Number.isFinite(numeric) && numeric > 0) return numeric;
  }
  return null;
}

function toRealtimeEventEnvelope(event) {
  return {
    eventId: event.id,
    type: event.eventType,
    aggregateType: event.aggregateType,
    aggregateId: event.aggregateId,
    aggregateVersion: resolveRealtimeAggregateVersion(event),
    scope: event.scope ?? null,
    payload: event.payload && typeof event.payload === "object" ? event.payload : {},
    createdAt: event.occurredAt,
  };
}

// Step 5 — endpoint di replay/catch-up durabile per Last-Event-ID. Restituisce
// gli eventi successivi ancora disponibili; se il gap e' troppo grande (eventi
// gia' potati dalla retention) segnala recoveryRequired per lo snapshot scoped.
function buildWaiterPauseResponse(db, user, session, state) {
  const pauseStatus =
    state ?? resolveWaiterPauseState(db.integration ?? {}, user, session);
  return {
    ok: true,
    pause: pauseStatus,
    user: {
      id: String(user?.id ?? "").trim(),
      username: String(user?.username ?? "").trim(),
      fullName: String(user?.fullName ?? user?.username ?? "").trim(),
    },
  };
}

async function handleMobileWaiterPauseStatus(req, res) {
  const telemetry = waiterPauseTelemetry.start("status");
  try {
    const payload = await readJsonBody(req);
    const db = await telemetry.measure("readDb.handler", () => readDb({
      refreshExternalizedSessions: true,
      refreshExternalizedTableLocks: true,
    }));
    const authContext = telemetry.measureSync("auth.resolve", () =>
      req.__authContext && typeof req.__authContext === "object"
        ? req.__authContext
        : validateSessionContext(db, payload));
    const { user, session } = authContext;
    if (!db.integration || typeof db.integration !== "object") {
      db.integration = createDefaultIntegrationState();
    }
    const response = telemetry.measureSync("state.resolve", () =>
      buildWaiterPauseResponse(db, user, session));
    telemetry.finish("ok");
    sendJson(res, 200, response);
  } catch (error) {
    telemetry.finish("error");
    throw error;
  }
}

async function reconcileWaiterPauseSideEffects({
  kind,
  db,
  user,
  effectiveSession,
  payload,
  telemetry,
}) {
  if (
    DB_MODE === "mysql" &&
    mysqlAuditEventsSplitRepository?.enabled === true &&
    typeof mysqlAuditEventsSplitRepository.listAuditEvents === "function"
  ) {
    db.auditEvents = await telemetry.measure("recovery.auditReload", () =>
      mysqlAuditEventsSplitRepository.listAuditEvents());
  }
  const plan = buildWaiterPauseRecoveryPlan({
    integration: db.integration,
    auditEvents: db.auditEvents,
    user,
    session: effectiveSession,
    kind,
  });
  if (!plan?.recoveryRequired) return false;

  const sessionHeartbeatChanged = telemetry.measureSync(
    "recovery.sessionHeartbeat",
    () => touchSessionHeartbeat(db, {
      ...payload,
      userId: user.id,
      clientApp: "mobile-frontend",
    }),
  );
  const auditEvent = telemetry.measureSync("recovery.auditAppend", () =>
    appendAuditEvent(db, {
      ...buildAuditActor(user, payload),
      action: plan.action,
      entityType: "user",
      entityId: user.id,
      correlationId: plan.correlationId,
      payload: plan.kind === "start"
        ? {
            userId: user.id,
            startedAtMs: plan.record.startedAtMs,
            endsAtMs: plan.record.endsAtMs,
            durationMinutes: normalizeWaiterPauseSettings(user).durationMinutes,
            recovered: true,
          }
        : {
            userId: user.id,
            stoppedAtMs: plan.record.stoppedAtMs,
            reenableAtMs: plan.record.reenableAtMs,
            reason: "stopped",
            recovered: true,
          },
    }));
  db.meta.lastWriteAt = nowIso();
  await writeWaiterPauseDb(db, {
    metricLabel: `waiter.pause.${plan.kind}.recovery.appStateWrite`,
    sessionIds: sessionHeartbeatChanged ? [effectiveSession.id] : [],
    auditEventIds: [auditEvent?.id],
    skipIntegrationFields: true,
    measure: (label, action) => telemetry.measure(label, action),
  });
  runtimeMetrics.incrementCounter("waiterPausePartialCommitRecoveries");
  return true;
}

function hasOwnRelationalLayoutTableValue(source, key) {
  return Boolean(source && typeof source === "object" && Object.hasOwn(source, key));
}

function pickRelationalTableValue(source, key, fallback) {
  if (!hasOwnRelationalLayoutTableValue(source, key)) return fallback;
  const value = source[key];
  return value === undefined ? fallback : value;
}

function moneyFromRelationalCents(source, centsKey, fallback) {
  if (!hasOwnRelationalLayoutTableValue(source, centsKey)) return fallback;
  const numeric = Number(source[centsKey]);
  if (!Number.isFinite(numeric)) return fallback;
  return roundMoney(Math.max(numeric, 0) / 100);
}

function mergeRelationalTableStateIntoPosTable(table, relationalTable, index) {
  const merged = {
    ...table,
    roomId: String(relationalTable.roomId ?? table.roomId ?? "").trim() || table.roomId,
    status: String(relationalTable.status ?? table.status ?? "").trim() || table.status,
    guestName: pickRelationalTableValue(
      relationalTable,
      "guestName",
      pickRelationalTableValue(relationalTable, "tableName", relationalTable.customerName ?? table.guestName),
    ),
    customerPhone: pickRelationalTableValue(relationalTable, "customerPhone", table.customerPhone),
    covers: pickRelationalTableValue(relationalTable, "covers", table.covers),
    reservation: pickRelationalTableValue(relationalTable, "reservation", table.reservation),
    seatedAt: pickRelationalTableValue(relationalTable, "seatedAt", table.seatedAt),
    totalDue: moneyFromRelationalCents(
      relationalTable,
      "totalDueCents",
      pickRelationalTableValue(relationalTable, "totalDue", table.totalDue),
    ),
    pendingBills: Array.isArray(relationalTable.pendingBills)
      ? relationalTable.pendingBills
      : table.pendingBills,
    note: pickRelationalTableValue(
      relationalTable,
      "note",
      pickRelationalTableValue(relationalTable, "notes", table.note),
    ),
    allergens: Array.isArray(relationalTable.allergens)
      ? relationalTable.allergens
      : table.allergens,
    manualIntolerance: pickRelationalTableValue(
      relationalTable,
      "manualIntolerance",
      table.manualIntolerance,
    ),
    workLock: pickRelationalTableValue(relationalTable, "workLock", table.workLock),
    revision: pickRelationalTableValue(relationalTable, "revision", table.revision),
    currentRevision: pickRelationalTableValue(
      relationalTable,
      "currentRevision",
      table.currentRevision,
    ),
  };
  return sanitizePosTable(merged, index + 1);
}

async function buildLayoutSettingsWithRelationalTableStates(settings) {
  if (!RELATIONAL_LAYOUT_TABLES_READ_PRIMARY || !RELATIONAL_TABLES_READ_PRIMARY) {
    return { settings, source: "legacy" };
  }
  if (!Array.isArray(settings?.tables) || settings.tables.length === 0) {
    return { settings, source: "legacy" };
  }
  try {
    await relationalRuntime.initialize();
    if (!relationalRuntime?.db) {
      runtimeMetrics.incrementCounter("integrationLayoutRelationalTablesFallback");
      return { settings, source: "legacy", fallbackReason: "relational_unavailable" };
    }
    const repository = new TablesBillsRelationalRepository(relationalRuntime.db);
    const relationalTables = repository.listTableStates();
    const relationalById = new Map(
      relationalTables
        .map((table) => [String(table?.id ?? table?.tableId ?? "").trim(), table])
        .filter(([id]) => id),
    );
    const missingTableIds = settings.tables
      .map((table) => String(table?.id ?? table?.tableId ?? "").trim())
      .filter((id) => id && !relationalById.has(id));
    if (missingTableIds.length > 0) {
      runtimeMetrics.incrementCounter("integrationLayoutRelationalTablesFallback");
      console.warn(
        `[integration:layout] read-primary tavoli fallback: ${missingTableIds.length} table_states mancanti.`,
      );
      return {
        settings,
        source: "legacy",
        fallbackReason: "missing_table_states",
        missingTableIds,
      };
    }
    const nextSettings = {
      ...settings,
      tables: settings.tables.map((table, index) => {
        const tableId = String(table?.id ?? table?.tableId ?? "").trim();
        const relationalTable = relationalById.get(tableId);
        return relationalTable
          ? mergeRelationalTableStateIntoPosTable(table, relationalTable, index)
          : table;
      }),
    };
    runtimeMetrics.incrementCounter("integrationLayoutRelationalTablesApplied");
    return { settings: nextSettings, source: "relational" };
  } catch (error) {
    runtimeMetrics.incrementCounter("integrationLayoutRelationalTablesFallback");
    console.warn(
      "[integration:layout] read-primary tavoli fallback:",
      error instanceof Error ? error.message : String(error),
    );
    return { settings, source: "legacy", fallbackReason: "error" };
  }
}

async function buildIntegrationLayoutCacheEntry() {
  const cachedLayout = readFastJsonCache(
    integrationLayoutFastResponseCache,
    "layout",
    INTEGRATION_LAYOUT_FAST_CACHE_MS,
  );
  if (cachedLayout) return cachedLayout;
  const cacheGeneration = integrationHotCacheGeneration;
  const db = await readDb();
  const reservationActivation = activateDuePosReservationsOnLayout(
    db,
    db.posSettings,
  );
  const layoutSettingsSource = await buildLayoutSettingsWithRelationalTableStates(db.posSettings);
  const layoutFinancialSource = buildOrderFinancialSyncState({ baseState: { ...db, posSettings: layoutSettingsSource.settings }, orderSnapshot: await listRelationalOrderWorkflowSnapshot({ enabled: RELATIONAL_LAYOUT_ORDERS_READ_PRIMARY, metricLabel: "integration.layout.relationalOrdersRead", relationalRuntime, runtimeMetrics, workflowStatuses: ["waiting", "prep", "ready", "delivered"] }) });
  const { settings, liveStats, changed } = syncPosTableFinancialsFromIntegrationOrders(layoutFinancialSource.state);
  if (layoutFinancialSource.state !== db && changed === true) db.posSettings = settings;
  if (changed && !reservationActivation.changed) runtimeMetrics.incrementCounter("integrationLayoutFinancialOverlayOnly");
  if (reservationActivation.changed) {
    db.integration.lastWriteAt = nowIso();
    db.meta.lastWriteAt = nowIso();
    try {
      await writeIntegrationLayoutRefreshDb(db, { syncTableGroups: reservationActivation.changed });
      runtimeMetrics.incrementCounter("integrationLayoutRefreshWrites");
      clearIntegrationHotResponseCaches();
      publishIntegrationNotificationStreamRefresh(
        "reservations_layout_activated",
        {
          changed: reservationActivation.changed,
        },
      );
    } catch (error) {
      runtimeMetrics.incrementCounter("integrationLayoutRefreshWriteSkipped");
      console.warn(
        "[integration:layout] refresh persistito in best-effort saltato:",
        error?.message || error,
      );
    }
  }
  const tableOrderStats = buildIntegrationTableOrderStats(layoutFinancialSource.state);
  const layout = overlayIntegrationLayoutFinancials(
    buildIntegrationLayoutFromSettings(settings, tableOrderStats),
    liveStats,
  );
  const version = new Date(db.meta?.lastWriteAt ?? nowIso()).getTime();
  const responsePayload = {
    ok: true,
    version: Number.isFinite(version) ? version : Date.now(),
    rooms: layout.rooms,
    tables: layout.tables,
  };
  const cacheEntry = writeFastJsonCache(
    integrationLayoutFastResponseCache,
    "layout",
    responsePayload,
    4,
  );
  if (cacheGeneration !== integrationHotCacheGeneration) integrationLayoutFastResponseCache.delete("layout");
  return cacheEntry;
}
const runIntegrationLayoutBuild = createSingleflight(buildIntegrationLayoutCacheEntry, { onStart: () => runtimeMetrics.incrementCounter("integrationLayoutBuildStarted"), onJoin: () => runtimeMetrics.incrementCounter("integrationLayoutBuildJoined") });
async function handleIntegrationLayout(_req, res) {
  const cachedLayout = readFastJsonCache(integrationLayoutFastResponseCache, "layout", INTEGRATION_LAYOUT_FAST_CACHE_MS);
  const cacheEntry = cachedLayout ?? await runIntegrationLayoutBuild();
  sendJsonString(res, 200, cacheEntry.json);
}

function resolvePosRoomSessionContext(db, payload, authenticatedContext = null) {
  const { user, session } = authenticatedContext?.user && authenticatedContext?.session
    ? authenticatedContext
    : validateSessionContext(db, payload);
  const roomId = String(payload.roomId ?? "").trim();
  if (!roomId) {
    throw new HttpError(400, "Sessione prenotazioni non valida.");
  }
  const room = findPosAllowedRoomForUser(db.posSettings, user, roomId);
  if (!room) {
    throw new HttpError(403, "Sala non disponibile per questo utente.");
  }
  return {
    user,
    session,
    roomId,
    room,
  };
}

function resolvePosReservationServiceDate(payload) {
  const serviceDate = toPosServiceDateKey(payload.serviceDate);
  if (!serviceDate) {
    throw new HttpError(400, "Data prenotazione non valida.");
  }
  return serviceDate;
}

function resolvePosReservationId(payload) {
  const reservationId = String(payload.reservationId ?? "").trim();
  if (!reservationId) {
    throw new HttpError(400, "Prenotazione non trovata.");
  }
  return reservationId;
}

function buildTableMoveUpdatePrintText({
  order,
  fromTable,
  toTable,
  sourceRoomId,
  targetRoomId,
  settings,
}) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const width = Math.max(
    48,
    sanitizePosPrintPreferences(settings?.printPreferences).order.lineWidth,
  );
  const titleStyle = {
    align: "center",
    bold: true,
    widthScale: 2,
    heightScale: 2,
    charSpacing: 0,
  };
  const bodyStyle = {
    align: "left",
    bold: true,
    widthScale: 1,
    heightScale: 1,
    charSpacing: 0,
  };
  const metaStyle = {
    align: "left",
    bold: true,
    widthScale: 0,
    heightScale: 1,
    charSpacing: 0,
  };
  const fromLabel = buildTableLocationLabel(fromTable, sourceRoomId, settings);
  const toLabel = buildTableLocationLabel(toTable, targetRoomId, settings);
  const orderLabel = `COMANDA ${formatIntegrationPrintOrderId(safeOrder.id)}`;
  const movementLines = [
    orderLabel,
    "SPOSTATO DA",
    fromLabel || fromTable?.id || "-",
    "A",
    toLabel || toTable?.id || "-",
  ];
  const lines = [...styleEscPosPrintLines("AGGIORNAMENTO", titleStyle), ""];
  movementLines.forEach((entry) => {
    wrapPrintText(
      toPrintSafeUppercase(entry),
      Math.max(16, Math.floor(width / 2)),
    ).forEach((line) => {
      lines.push(...styleEscPosPrintLines(line, bodyStyle));
    });
  });
  lines.push("");
  lines.push(
    ...styleEscPosPrintLines(
      formatIntegrationPrintDateTime(Date.now()),
      metaStyle,
    ),
  );
  lines.push("");
  return lines.join("\n");
}

function buildTableGroupMergeUpdatePrintText({
  order,
  group,
  settings,
  actionLabel = "UNIONE TAVOLI",
}) {
  const safeOrder = sanitizeIntegrationOrder(
    order,
    String(order?.id ?? "order").trim() || "order",
  );
  const safeSettings = sanitizePosSettings(settings, { menuItems: [] });
  const width = Math.max(
    48,
    sanitizePosPrintPreferences(safeSettings.printPreferences).order.lineWidth,
  );
  const titleStyle = {
    align: "center",
    bold: true,
    widthScale: 2,
    heightScale: 2,
    charSpacing: 0,
  };
  const bodyStyle = {
    align: "left",
    bold: true,
    widthScale: 1,
    heightScale: 1,
    charSpacing: 0,
  };
  const metaStyle = {
    align: "left",
    bold: true,
    widthScale: 0,
    heightScale: 1,
    charSpacing: 0,
  };
  const tableById = new Map(
    safeSettings.tables.map((table) => [String(table.id ?? "").trim(), table]),
  );
  const tableLabels = [...collectIntegrationTableGroupLeafIds(group)]
    .map((id) => tableById.get(id))
    .filter(Boolean)
    .map(
      (table) =>
        buildTableLocationLabel(table, table.roomId, safeSettings) ||
        `TAVOLO ${table.number}`,
    );
  const groupLabel =
    tableLabels.length > 0
      ? tableLabels.join(" + ")
      : sanitizeIntegrationTableLabel(group?.id) || "TAVOLI UNITI";
  const movementLines = [
    `COMANDA ${formatIntegrationPrintOrderId(safeOrder.id)}`,
    actionLabel,
    groupLabel,
  ];
  const lines = [...styleEscPosPrintLines("AGGIORNAMENTO", titleStyle), ""];
  movementLines.forEach((entry) => {
    wrapPrintText(
      toPrintSafeUppercase(entry),
      Math.max(16, Math.floor(width / 2)),
    ).forEach((line) => {
      lines.push(...styleEscPosPrintLines(line, bodyStyle));
    });
  });
  lines.push("");
  lines.push(
    ...styleEscPosPrintLines(
      formatIntegrationPrintDateTime(Date.now()),
      metaStyle,
    ),
  );
  lines.push("");
  return lines.join("\n");
}

async function appendTableGroupMergePrintJobsToDb(
  db,
  {
    previousGroups,
    groups,
    settings,
    userId,
    deviceUuid,
    clientApp,
    operation = "merge",
  },
) {
  const safePreviousGroups = sanitizeIntegrationTableGroups(previousGroups);
  const safeGroups = sanitizeIntegrationTableGroups(groups);
  const previousById = new Map(
    safePreviousGroups.map((group) => [group.id, JSON.stringify(group)]),
  );
  const nextById = new Map(
    safeGroups.map((group) => [group.id, JSON.stringify(group)]),
  );
  const normalizedOperation =
    String(operation ?? "")
      .trim()
      .toLowerCase() === "split"
      ? "split"
      : "merge";
  const changedGroups =
    normalizedOperation === "split"
      ? safePreviousGroups.filter(
          (group) => nextById.get(group.id) !== JSON.stringify(group),
        )
      : safeGroups.filter(
          (group) => previousById.get(group.id) !== JSON.stringify(group),
        );
  if (changedGroups.length === 0 || !Array.isArray(db.integration?.orders))
    return [];

  const printJobs = [];
  for (const group of changedGroups) {
    const leaves = collectIntegrationTableGroupLeafIds(group);
    if (leaves.size < 2) continue;
    const activeOrders = db.integration.orders
      .map((entry, index) =>
        sanitizeIntegrationOrder(entry, String(index + 1).padStart(5, "0")),
      )
      .filter((order) => leaves.has(String(order.tableId ?? "").trim()))
      .filter((order) => {
        const workflow = String(order.workflowStatus ?? "")
          .trim()
          .toLowerCase();
        const payment = String(order.paymentStatus ?? "")
          .trim()
          .toLowerCase();
        if (["cancelled", "annullata", "voided"].includes(workflow))
          return false;
        return (
          workflow !== "delivered" ||
          payment !== "paid" ||
          roundMoney(Math.max(Number(order.dueAmount) || 0, 0)) > 0.009
        );
      });
    for (const order of activeOrders) {
      const tableLabel =
        sanitizeIntegrationTableLabel(
          resolveIntegrationLogicalTableLabel(
            settings,
            db.integration,
            order.tableId,
            order.tableNumber,
          ),
        ) ||
        order.tableLabel ||
        order.logicalTableLabel ||
        String(order.tableNumber || order.table || "");
      const printableOrder = sanitizeIntegrationOrder(
        {
          ...order,
          tableLabel,
          logicalTableLabel: tableLabel,
        },
        order.id,
      );
      const updatePrintJob = await appendPrintSpoolJobToDb(db, {
        kind: "table_update",
        orderId: printableOrder.id,
        roomId: printableOrder.roomId,
        station: PRIMARY_INTEGRATION_STATION,
        fallbackStation: PRIMARY_INTEGRATION_STATION,
        userId,
        deviceUuid,
        clientApp,
        text: buildTableGroupMergeUpdatePrintText({
          order: printableOrder,
          group,
          settings,
          actionLabel:
            normalizedOperation === "split"
              ? "DISTACCO TAVOLI"
              : "UNIONE TAVOLI",
        }),
        printPreferences: settings.printPreferences,
      });
      const orderPrintStation = resolveIntegrationOrderPrintStation(
        printableOrder,
        {
          station:
            printableOrder.station ||
            printableOrder.ownerStation ||
            PRIMARY_INTEGRATION_STATION,
        },
      );
      const orderPrintJob = await appendPrintSpoolJobToDb(db, {
        kind: "order",
        orderId: printableOrder.id,
        roomId: printableOrder.roomId,
        station: orderPrintStation,
        fallbackStation: PRIMARY_INTEGRATION_STATION,
        userId,
        deviceUuid,
        clientApp,
        text: buildIntegrationOrderPrintText(
          printableOrder,
          orderPrintStation,
          settings.printPreferences?.order,
          settings,
        ),
        printPreferences: settings.printPreferences,
      });
      const precontoPrintJob = await appendPrintSpoolJobToDb(db, {
        kind: "preconto",
        orderId: printableOrder.id,
        roomId: printableOrder.roomId,
        station: PRIMARY_INTEGRATION_STATION,
        fallbackStation: PRIMARY_INTEGRATION_STATION,
        userId,
        deviceUuid,
        clientApp,
        precontoProfile: "cash",
        text: buildIntegrationPrecontoPrintTextWithOptions(
          printableOrder,
          settings.printPreferences,
          settings,
          { profile: "cash" },
        ),
        printPreferences: settings.printPreferences,
      });
      printJobs.push({
        orderId: printableOrder.id,
        groupId: group.id,
        updatePrintJobId: updatePrintJob?.id ?? null,
        orderPrintJobId: orderPrintJob?.id ?? null,
        precontoPrintJobId: precontoPrintJob?.id ?? null,
      });
    }
  }
  return printJobs;
}

function isActiveIntegrationOrderForTableMove(order) {
  return (
    String(order?.workflowStatus ?? "")
      .trim()
      .toLowerCase() !== "delivered" ||
    String(order?.paymentStatus ?? "")
      .trim()
      .toLowerCase() !== "paid" ||
    roundMoney(Math.max(Number(order?.dueAmount) || 0, 0)) > 0.009
  );
}

function collectRemovedSourceActiveOrders(db, tableId) {
  return (Array.isArray(db?.integration?.orders) ? db.integration.orders : [])
    .map((entry, index) =>
      sanitizeIntegrationOrder(entry, String(index + 1).padStart(5, "0")),
    )
    .filter(
      (order) =>
        String(order.tableId ?? "").trim() === tableId &&
        isActiveIntegrationOrderForTableMove(order),
    );
}

function collectRemovedSourceActiveReservations(db, tableId) {
  const matches = [];
  for (const rawState of Array.isArray(db?.posReservationStates)
    ? db.posReservationStates
    : []) {
    const state = sanitizePosReservationStateRecord(rawState);
    if (!state) continue;
    for (const reservation of state.reservations) {
      if (
        isPosReservationReleased(reservation) ||
        !posReservationIncludesTable(reservation, tableId)
      ) {
        continue;
      }
      matches.push({ state, reservation });
    }
  }
  return matches;
}

function collectRemovedOperationalEvidenceUserIds({
  activeOrders = [],
  activeReservations = [],
  sessionEvidence = null,
} = {}) {
  const values = [
    sessionEvidence?.lastOpenedEvent?.actorUserId,
    ...activeOrders.flatMap((order) => [
      order?.createdByUserId,
      order?.userId,
      order?.waiterUserId,
      order?.operatorUserId,
    ]),
    ...activeReservations.flatMap(({ reservation }) => [
      reservation?.createdByUserId,
      reservation?.userId,
      reservation?.waiterUserId,
    ]),
  ];
  return [
    ...new Set(values.map((value) => String(value ?? "").trim()).filter(Boolean)),
  ];
}

function findRemovedOperationalSessionEvidence(db, tableId) {
  let lastOpenedAtMs = 0;
  let lastReleasedAtMs = 0;
  let lastOpenedEvent = null;
  let lastReleasedEvent = null;
  forEachIntegrationCurrentTableSessionAuditEvent(db, (event) => {
    const payload =
      event.payload && typeof event.payload === "object" ? event.payload : {};
    const eventTableId = String(
      payload.tableId ?? event.entityId ?? "",
    ).trim();
    if (eventTableId !== tableId) return;
    const atMs = parseTimestampMs(event.occurredAt, 0);
    if (!Number.isFinite(atMs) || atMs <= 0) return;
    if (event.action === "table.session_opened") {
      if (atMs >= lastOpenedAtMs) {
        lastOpenedAtMs = Math.trunc(atMs);
        lastOpenedEvent = event;
      }
    } else {
      if (atMs >= lastReleasedAtMs) {
        lastReleasedAtMs = Math.trunc(atMs);
        lastReleasedEvent = event;
      }
    }
  });
  return {
    lastOpenedAtMs,
    lastReleasedAtMs,
    lastOpenedEvent,
    lastReleasedEvent,
    openedAtMs: lastOpenedAtMs > lastReleasedAtMs ? lastOpenedAtMs : 0,
  };
}

function findRemovedSourceOpenSessionEvidence(db, tableId) {
  return findRemovedOperationalSessionEvidence(db, tableId).openedAtMs;
}

function removedOperationalTableLockId(tableId) {
  return `removed_operational_table:${String(tableId ?? "").trim()}`;
}

function getRemovedOperationalTableLockEntry(db, tableId) {
  const normalizedTableId = String(tableId ?? "").trim();
  if (!normalizedTableId) return null;
  return (
    (Array.isArray(db?.tableLocks) ? db.tableLocks : []).find(
      (entry) =>
        entry &&
        typeof entry === "object" &&
        entry.kind === "removed_operational_table" &&
        String(entry.tableId ?? "").trim() === normalizedTableId,
    ) ?? null
  );
}

function getRemovedOperationalTableWorkLock(db, tableId) {
  return sanitizeTableWorkLock(getRemovedOperationalTableLockEntry(db, tableId));
}

function setRemovedOperationalTableWorkLock(db, context, lock) {
  const tableId = String(context?.table?.id ?? lock?.tableId ?? "").trim();
  const safeLock = sanitizeTableWorkLock(lock);
  if (!tableId || !safeLock) return null;
  const current = Array.isArray(db.tableLocks) ? db.tableLocks : [];
  db.tableLocks = [
    ...current.filter(
      (entry) =>
        !(
          entry &&
          typeof entry === "object" &&
          entry.kind === "removed_operational_table" &&
          String(entry.tableId ?? "").trim() === tableId
        ),
    ),
    {
      id: removedOperationalTableLockId(tableId),
      kind: "removed_operational_table",
      ...safeLock,
      roomId: String(context?.roomId ?? "").trim(),
      tableNumber: Math.max(Math.trunc(Number(context?.table?.number) || 0), 0),
      tableSnapshot: context?.table
        ? {
            ...context.table,
            workLock: null,
          }
        : null,
    },
  ];
  return safeLock;
}

function deleteRemovedOperationalTableWorkLock(db, tableId) {
  const normalizedTableId = String(tableId ?? "").trim();
  const current = Array.isArray(db?.tableLocks) ? db.tableLocks : [];
  const next = current.filter(
    (entry) =>
      !(
        entry &&
        typeof entry === "object" &&
        entry.kind === "removed_operational_table" &&
        String(entry.tableId ?? "").trim() === normalizedTableId
      ),
  );
  if (next.length === current.length) return false;
  db.tableLocks = next;
  return true;
}

function removedOperationalEvidenceTimestamp(context) {
  const orderTimestamps = context.activeOrders.flatMap((order) => [
    Number(order.receivedAtMs),
    parseTimestampMs(order.updatedAt, 0),
  ]);
  const reservationTimestamps = context.activeReservations.flatMap(
    ({ reservation }) => [
      Number(reservation.createdAt),
      Number(reservation.updatedAt),
      Number(reservation.arrivedAt),
    ],
  );
  return Math.max(
    context.sessionEvidence.lastOpenedAtMs,
    ...orderTimestamps.filter((value) => Number.isFinite(value) && value > 0),
    ...reservationTimestamps.filter(
      (value) => Number.isFinite(value) && value > 0,
    ),
    0,
  );
}

function resolveRemovedOperationalTableContext(
  db,
  settings,
  tableIdRaw,
  payload = {},
) {
  const tableId = String(tableIdRaw ?? "").trim();
  if (!tableId) {
    throw new HttpError(400, "Tavolo non valido.");
  }
  if (findPosTableWithLayout(settings, tableId)) {
    throw new HttpError(409, "Il tavolo risulta ancora configurato.", {
      code: "REMOVED_OPERATIONAL_TABLE_STILL_CONFIGURED",
    });
  }

  const activeOrders = collectRemovedSourceActiveOrders(db, tableId);
  const activeReservations = collectRemovedSourceActiveReservations(db, tableId);
  const sessionEvidence = findRemovedOperationalSessionEvidence(db, tableId);
  const hasServerEvidence =
    activeOrders.length > 0 ||
    activeReservations.length > 0 ||
    sessionEvidence.openedAtMs > 0;
  if (!hasServerEvidence) {
    throw new HttpError(
      409,
      "Il tavolo rimosso non ha una sessione operativa attiva.",
      { code: "REMOVED_SOURCE_OPERATIONAL_EVIDENCE_MISSING" },
    );
  }

  const evidenceContext = {
    activeOrders,
    activeReservations,
    sessionEvidence,
  };
  const evidenceUserIds = collectRemovedOperationalEvidenceUserIds(
    evidenceContext,
  );
  const latestEvidenceAt = removedOperationalEvidenceTimestamp(evidenceContext);
  if (
    activeOrders.length === 0 &&
    sessionEvidence.lastReleasedAtMs > 0 &&
    sessionEvidence.lastReleasedAtMs >= latestEvidenceAt
  ) {
    throw new HttpError(409, "Il tavolo rimosso e gia stato liberato.", {
      code: "REMOVED_SOURCE_ALREADY_RELEASED",
    });
  }

  const lockEntry = getRemovedOperationalTableLockEntry(db, tableId);
  const lockSnapshot =
    lockEntry?.tableSnapshot && typeof lockEntry.tableSnapshot === "object"
      ? lockEntry.tableSnapshot
      : null;
  const openedPayload =
    sessionEvidence.lastOpenedEvent?.payload &&
    typeof sessionEvidence.lastOpenedEvent.payload === "object"
      ? sessionEvidence.lastOpenedEvent.payload
      : {};
  const roomCandidates = [
    ...activeOrders.map((order) => String(order.roomId ?? "").trim()),
    ...activeReservations.flatMap(({ state, reservation }) => [
      String(state.roomId ?? "").trim(),
      String(reservation.roomId ?? "").trim(),
    ]),
    String(
      openedPayload.roomId ??
        sessionEvidence.lastOpenedEvent?.roomId ??
        lockEntry?.roomId ??
        lockSnapshot?.roomId ??
        "",
    ).trim(),
  ].filter(Boolean);
  const distinctRoomIds = [...new Set(roomCandidates)];
  if (distinctRoomIds.length > 1) {
    throw new HttpError(409, "Le evidenze operative del tavolo non sono coerenti.", {
      code: "REMOVED_SOURCE_ROOM_EVIDENCE_CONFLICT",
    });
  }
  const roomId = distinctRoomIds[0] ?? "";
  const requestedRoomId = String(payload.roomId ?? "").trim();
  if (!roomId || (requestedRoomId && requestedRoomId !== roomId)) {
    throw new HttpError(409, "Sala del tavolo rimosso non coerente.", {
      code: "REMOVED_SOURCE_ROOM_MISMATCH",
    });
  }
  const configuredRoom = findPosRoomById(settings, roomId);
  const room = configuredRoom ?? {
    id: roomId,
    name:
      String(
        openedPayload.roomName ??
          lockSnapshot?.roomName ??
          lockSnapshot?.type ??
          roomId,
      ).trim() || roomId,
    activityId: "",
    activityIds: [],
    removedFromConfiguration: true,
  };

  const evidenceNumbers = [
    ...activeOrders.map((order) => Math.trunc(Number(order.tableNumber) || 0)),
    Math.trunc(Number(openedPayload.tableNumber) || 0),
    Math.trunc(Number(lockEntry?.tableNumber ?? lockSnapshot?.number) || 0),
  ].filter((value) => value > 0);
  const distinctNumbers = [...new Set(evidenceNumbers)];
  if (distinctNumbers.length > 1) {
    throw new HttpError(409, "Numero del tavolo rimosso non coerente.", {
      code: "REMOVED_SOURCE_NUMBER_EVIDENCE_CONFLICT",
    });
  }
  const requestedNumber = Math.trunc(Number(payload.tableNumber ?? payload.table) || 0);
  const tableNumber =
    distinctNumbers[0] ||
    requestedNumber ||
    parseTableNumberFromValue(null, tableId);
  if (tableNumber <= 0 || (requestedNumber > 0 && requestedNumber !== tableNumber)) {
    throw new HttpError(409, "Numero del tavolo rimosso non coerente.", {
      code: "REMOVED_SOURCE_NUMBER_MISMATCH",
    });
  }

  const reservationEvidence = activeReservations
    .map((entry) => entry.reservation)
    .sort(
      (left, right) =>
        Number(right.updatedAt ?? right.createdAt ?? 0) -
        Number(left.updatedAt ?? left.createdAt ?? 0),
    )[0];
  const hasSeatedEvidence =
    activeOrders.length > 0 || sessionEvidence.openedAtMs > 0;
  const dueAmount = roundMoney(
    activeOrders.reduce(
      (sum, order) => sum + Math.max(Number(order.dueAmount) || 0, 0),
      0,
    ),
  );
  const table = sanitizePosTable(
    {
      ...(lockSnapshot ?? {}),
      id: tableId,
      number: tableNumber,
      type: room.name,
      roomId,
      status: hasSeatedEvidence
        ? activeOrders.length > 0
          ? "waiting"
          : "no_orders"
        : "reserved",
      guestName:
        String(reservationEvidence?.customerName ?? "").trim() ||
        String(lockSnapshot?.guestName ?? "").trim(),
      customerPhone:
        String(reservationEvidence?.customerPhone ?? "").trim() ||
        String(lockSnapshot?.customerPhone ?? "").trim(),
      covers: normalizeTableCovers(
        reservationEvidence?.covers ?? lockSnapshot?.covers,
      ),
      reservation:
        !hasSeatedEvidence && reservationEvidence
          ? {
              time: timeStringFromTimestamp(reservationEvidence.reservationAt),
              people: normalizeTableCovers(reservationEvidence.covers),
              mergeFlag: false,
            }
          : null,
      seatedAt: hasSeatedEvidence
        ? normalizeSeatedAtMs(
            lockSnapshot?.seatedAt ?? sessionEvidence.openedAtMs,
          )
        : null,
      totalDue: dueAmount,
      pendingBills: [],
      note:
        String(lockSnapshot?.note ?? "").trim() ||
        String(reservationEvidence?.note ?? "").trim(),
      allergens: normalizeStringList(lockSnapshot?.allergens, 12, 40),
      manualIntolerance:
        String(lockSnapshot?.manualIntolerance ?? "").trim() ||
        String(reservationEvidence?.intolerances ?? "").trim(),
      workLock: getRemovedOperationalTableWorkLock(db, tableId),
    },
    tableNumber,
  );
  return {
    ...evidenceContext,
    latestEvidenceAt,
    room,
    roomId,
    roomRemovedFromConfiguration: !configuredRoom,
    table,
    tableInfo: {
      table,
      tableIndex: -1,
      layoutTable: null,
      roomId,
      roomName: room.name,
      settings,
      removedOperational: true,
      removedOperationalEvidenceUserIds: evidenceUserIds,
    },
  };
}

function acquireOrRefreshRemovedOperationalTableWorkLock(
  db,
  context,
  {
    user,
    session,
    payload = {},
    purpose = "table_mutation",
    forceHeartbeat = false,
  },
) {
  const tableInfo = context.tableInfo;
  const actor = buildAuditActor(user, { ...payload, roomId: context.roomId });
  const previousLock = getRemovedOperationalTableWorkLock(db, context.table.id);
  const expired = previousLock ? isTableWorkLockExpired(previousLock) : false;
  if (previousLock && expired) {
    appendTableLockAudit(db, "table.lock_expired", {
      actor,
      tableInfo,
      previousLock,
      nextLock: null,
    });
  }
  if (
    previousLock &&
    !expired &&
    !isSameTableLockOwner(previousLock, user, session, payload)
  ) {
    appendTableLockAudit(db, "table.lock_denied", {
      actor,
      tableInfo,
      previousLock,
      nextLock: previousLock,
    });
    throw new HttpError(
      409,
      `Il tavolo e gia in modifica da ${previousLock.username}.`,
      {
        code: "TABLE_LOCKED",
        details: {
          lockedByUsername: previousLock.username,
          purpose: previousLock.purpose,
          expiresAt: previousLock.expiresAt,
        },
      },
    );
  }

  const normalizedPurpose =
    String(purpose ?? "table_mutation").trim() || "table_mutation";
  if (
    !forceHeartbeat &&
    previousLock &&
    !expired &&
    shouldReuseRecentTableWorkLock(previousLock, normalizedPurpose)
  ) {
    return { lock: previousLock, tableInfo };
  }
  const nextLock =
    previousLock && !expired
      ? sanitizeTableWorkLock({
          ...previousLock,
          heartbeatAt: nowIso(),
          expiresAt: new Date(Date.now() + TABLE_LOCK_TTL_MS).toISOString(),
          purpose: normalizedPurpose,
        })
      : buildTableWorkLock({
          tableId: context.table.id,
          user,
          session,
          payload,
          purpose: normalizedPurpose,
        });
  setRemovedOperationalTableWorkLock(db, context, nextLock);
  const nextTableInfo = {
    ...tableInfo,
    table: { ...context.table, workLock: nextLock },
  };
  appendTableLockAudit(
    db,
    previousLock && !expired ? "table.lock_heartbeat" : "table.lock_acquired",
    {
      actor,
      tableInfo: nextTableInfo,
      previousLock: previousLock && !expired ? previousLock : null,
      nextLock,
    },
  );
  return { lock: nextLock, tableInfo: nextTableInfo };
}

function assertActiveRemovedOperationalTableWorkLock(
  db,
  context,
  {
    user,
    session,
    payload = {},
    purpose = "table_mutation",
    requireExisting = false,
  },
) {
  const lock = getRemovedOperationalTableWorkLock(db, context.table.id);
  if (!lock || isTableWorkLockExpired(lock)) {
    if (requireExisting) {
      const actor = buildAuditActor(user, {
        ...payload,
        roomId: context.roomId,
      });
      appendTableLockAudit(db, "table.lock_required", {
        actor,
        tableInfo: context.tableInfo,
        previousLock: lock ?? null,
        nextLock: lock ?? null,
      });
      throw new HttpError(428, "Il tavolo deve essere bloccato prima di procedere.", {
        code: "TABLE_LOCK_REQUIRED",
        details: {
          tableId: context.table.id,
          purpose,
          expired: Boolean(lock),
        },
      });
    }
    return acquireOrRefreshRemovedOperationalTableWorkLock(db, context, {
      user,
      session,
      payload,
      purpose,
    });
  }
  if (!isSameTableLockOwner(lock, user, session, payload)) {
    throw new HttpError(
      409,
      "Il tavolo e gia in modifica da un altro operatore.",
      {
        code: "TABLE_LOCKED",
        details: {
          lockedByUsername: lock.username,
          purpose: lock.purpose,
          expiresAt: lock.expiresAt,
        },
      },
    );
  }
  return acquireOrRefreshRemovedOperationalTableWorkLock(db, context, {
    user,
    session,
    payload,
    purpose,
  });
}

function releaseRemovedOperationalTableWorkLock(
  db,
  context,
  { user, session, payload = {}, force = false },
) {
  const tableId = String(
    context?.table?.id ?? context?.tableInfo?.table?.id ?? "",
  ).trim();
  const previousLock = getRemovedOperationalTableWorkLock(db, tableId);
  if (!previousLock) {
    return {
      released: false,
      previousLock: null,
      tableInfo: context.tableInfo,
    };
  }
  if (!force && !isSameTableLockOwner(previousLock, user, session, payload)) {
    throw new HttpError(
      403,
      "Solo l'operatore che ha il lock puo rilasciarlo.",
    );
  }
  if (force && !canOverrideTableWorkLock(user)) {
    throw new HttpError(
      403,
      "Permesso insufficiente per forzare il rilascio del tavolo.",
    );
  }
  deleteRemovedOperationalTableWorkLock(db, tableId);
  const actor = buildAuditActor(user, { ...payload, roomId: context.roomId });
  appendTableLockAudit(
    db,
    force ? "table.lock_force_released" : "table.lock_released",
    {
      actor,
      tableInfo: context.tableInfo,
      previousLock,
      nextLock: null,
    },
  );
  return {
    released: true,
    previousLock,
    tableInfo: context.tableInfo,
  };
}

function buildRemovedOperationalLockReleaseContext(db, settings, tableId) {
  const entry = getRemovedOperationalTableLockEntry(db, tableId);
  if (!entry) return null;
  const table = sanitizePosTable(
    {
      ...(entry.tableSnapshot && typeof entry.tableSnapshot === "object"
        ? entry.tableSnapshot
        : {}),
      id: tableId,
      number:
        Math.trunc(Number(entry.tableNumber) || 0) ||
        parseTableNumberFromValue(null, tableId),
      workLock: sanitizeTableWorkLock(entry),
    },
    Math.trunc(Number(entry.tableNumber) || 0) || 1,
  );
  const roomId = String(entry.roomId ?? table.roomId ?? "").trim();
  return {
    roomId,
    table,
    tableInfo: {
      table,
      tableIndex: -1,
      layoutTable: null,
      roomId,
      roomName: String(findPosRoomById(settings, roomId)?.name ?? "").trim(),
      settings,
      removedOperational: true,
      removedOperationalEvidenceUserIds: [String(entry.userId ?? "").trim()].filter(
        Boolean,
      ),
    },
  };
}

async function handleRemovedOperationalTableSync({
  db,
  payload,
  res,
  settings,
  tableId,
  user,
  session,
}) {
  const context = resolveRemovedOperationalTableContext(
    db,
    settings,
    tableId,
    payload,
  );
  assertUserCanOperateInRemovedTableRoom(user, settings, context.tableInfo, {
    session,
  });
  assertActiveRemovedOperationalTableWorkLock(db, context, {
    user,
    session,
    payload,
    purpose: "table.sync",
  });

  const requestedStatusRaw = String(payload.status ?? "").trim();
  let safeStatus = POS_TABLE_STATUSES.has(requestedStatusRaw)
    ? requestedStatusRaw
    : "";
  if (!safeStatus) {
    const occupancy = String(payload.occupancyState ?? "").trim();
    if (occupancy === "free") safeStatus = "free";
    else if (occupancy === "reserved") safeStatus = "reserved";
    else if (occupancy === "seated") {
      safeStatus = context.activeOrders.length > 0 ? "waiting" : "no_orders";
    }
  }
  if (!safeStatus) safeStatus = context.table.status;
  const hasReservationPayload = Boolean(
    String(payload.reservationTime ?? "").trim() ||
      Number(payload.reservationAt) > 0,
  );
  const isRelease = safeStatus === "free" && !hasReservationPayload;
  if (isRelease && context.activeOrders.length > 0) {
    throw new HttpError(
      409,
      "Il tavolo rimosso ha ancora comande operative da completare o pagare.",
      { code: "REMOVED_SOURCE_HAS_ACTIVE_ORDERS" },
    );
  }

  const nowMs = Date.now();
  const requestedCovers = Number.isFinite(Number(payload.covers))
    ? normalizeTableCovers(payload.covers)
    : context.table.covers;
  const updated = sanitizePosTable(
    {
      ...context.table,
      revision:
        clampInt(
          context.table.revision ?? context.table.currentRevision,
          1,
          1_000_000,
          1,
        ) + 1,
      status: safeStatus,
      guestName: isRelease
        ? ""
        : String(payload.tableName ?? payload.guestName ?? context.table.guestName)
            .trim()
            .slice(0, 80),
      customerPhone: isRelease
        ? ""
        : String(payload.customerPhone ?? context.table.customerPhone)
            .trim()
            .slice(0, 24),
      covers: isRelease ? 0 : requestedCovers,
      reservation:
        safeStatus === "reserved" && Number(payload.reservationAt) > 0
          ? {
              time: timeStringFromTimestamp(payload.reservationAt),
              people: requestedCovers,
              mergeFlag: false,
            }
          : safeStatus === "reserved"
            ? context.table.reservation
            : null,
      seatedAt:
        safeStatus === "free" || safeStatus === "reserved"
          ? null
          : (normalizeSeatedAtMs(payload.seatedAt) ??
            normalizeSeatedAtMs(context.table.seatedAt) ??
            nowMs),
      totalDue: isRelease ? 0 : context.table.totalDue,
      pendingBills: isRelease ? [] : context.table.pendingBills,
      note: isRelease
        ? ""
        : String(payload.note ?? context.table.note).trim().slice(0, 240),
      allergens: isRelease
        ? []
        : normalizeStringList(
            payload.allergens ?? context.table.allergens,
            12,
            40,
          ),
      manualIntolerance: isRelease
        ? ""
        : String(
            payload.manualIntolerance ?? context.table.manualIntolerance,
          )
            .trim()
            .slice(0, 64),
      workLock: isRelease
        ? null
        : getRemovedOperationalTableWorkLock(db, tableId),
    },
    context.table.number,
  );

  const wasSeated =
    context.table.status !== "free" && context.table.status !== "reserved";
  const isSeated = updated.status !== "free" && updated.status !== "reserved";
  const arrivedFromReservation = context.table.status === "reserved" && isSeated;
  const reservationSplit =
    isRelease || arrivedFromReservation
      ? releaseActivatedPosReservationTableGroup(
          db,
          tableId,
          context.table,
          nowMs,
          arrivedFromReservation ? "arrived" : "released",
        )
      : { changed: false, releasedReservationIds: [] };

  if (isRelease) {
    appendAuditEvent(db, {
      actorUserId: String(user?.id ?? payload.userId ?? "system"),
      actorRole: "OPERATOR",
      action: "table.released",
      entityType: "table",
      entityId: tableId,
      roomId: context.roomId,
      payload: {
        tableId,
        tableNumber: context.table.number,
        roomId: context.roomId,
        removedFromConfiguration: true,
      },
    });
    deleteRemovedOperationalTableWorkLock(db, tableId);
  } else {
    const lock = getRemovedOperationalTableWorkLock(db, tableId);
    if (lock) {
      setRemovedOperationalTableWorkLock(
        db,
        {
          ...context,
          table: updated,
        },
        lock,
      );
    }
    if (!wasSeated && isSeated) {
      appendAuditEvent(db, {
        actorUserId: String(user?.id ?? payload.userId ?? "system"),
        actorRole: "OPERATOR",
        action: "table.session_opened",
        entityType: "table",
        entityId: tableId,
        roomId: context.roomId,
        payload: {
          tableId,
          tableNumber: context.table.number,
          roomId: context.roomId,
          seatedAt: updated.seatedAt,
          removedFromConfiguration: true,
        },
      });
    }
  }
  if (reservationSplit.changed) {
    appendAuditEvent(db, {
      actorUserId: String(user?.id ?? payload.userId ?? "system"),
      actorRole: "OPERATOR",
      action: "reservation.table_group_released",
      entityType: "table",
      entityId: tableId,
      roomId: context.roomId,
      payload: {
        tableId,
        tableNumber: context.table.number,
        releasedReservationIds: reservationSplit.releasedReservationIds,
        removedFromConfiguration: true,
      },
    });
    clearIntegrationHotResponseCaches();
  }
  db.meta.lastWriteAt = nowIso();
  await writeRoomDb(db, {
    metricLabel: "rooms.removedTable.sync.appStateWrite",
    splitDomains: [
      "tableLocks",
      "auditEvents",
      ...(reservationSplit.changed
        ? ["posReservationStates", "posReservationLocks", "integration"]
        : []),
    ],
  });
  sendJson(res, 200, {
    ok: true,
    table: isRelease ? null : updated,
    removedFromConfiguration: true,
    ...(isRelease ? { removedTableId: tableId } : {}),
  });
}

function sanitizeRemovedSourceTableMoveSnapshot(payload, fromTableId) {
  const source =
    payload?.removedSourceSnapshot &&
    typeof payload.removedSourceSnapshot === "object" &&
    !Array.isArray(payload.removedSourceSnapshot)
      ? payload.removedSourceSnapshot
      : null;
  if (!source) {
    throw new HttpError(404, "Tavolo sorgente non trovato.");
  }
  const lifecycle =
    source.offlineLifecycle &&
    typeof source.offlineLifecycle === "object" &&
    !Array.isArray(source.offlineLifecycle)
      ? source.offlineLifecycle
      : null;
  const id = String(source.id ?? "").trim();
  const roomId = String(source.roomId ?? "").trim();
  const number = Math.trunc(Number(source.number));
  const occupancyState = String(source.occupancyState ?? "").trim();
  const removedAt = Math.trunc(Number(lifecycle?.removedAt));
  const removedFromLayoutVersion = Math.trunc(
    Number(lifecycle?.removedFromLayoutVersion),
  );
  const lifecycleValid =
    lifecycle?.state === "removed_while_active" &&
    lifecycle?.usableUntil === "released" &&
    (lifecycle?.decision === "pending" || lifecycle?.decision === "keep") &&
    typeof lifecycle?.requiresDecision === "boolean" &&
    Number.isFinite(removedAt) &&
    removedAt > 0 &&
    removedAt <= Date.now() + 5 * 60_000 &&
    Number.isSafeInteger(removedFromLayoutVersion) &&
    removedFromLayoutVersion > 0;
  if (
    id !== fromTableId ||
    !roomId ||
    roomId.length > 80 ||
    !Number.isFinite(number) ||
    number <= 0 ||
    number > 999_999 ||
    !lifecycleValid
  ) {
    throw new HttpError(400, "Snapshot tavolo rimosso non valida.", {
      code: "REMOVED_SOURCE_SNAPSHOT_INVALID",
    });
  }
  if (occupancyState !== "reserved" && occupancyState !== "seated") {
    throw new HttpError(409, "Il tavolo sorgente rimosso non e attivo.", {
      code: "REMOVED_SOURCE_NOT_ACTIVE",
    });
  }
  const positiveTimestamp = (value) => {
    const parsed = Math.trunc(Number(value));
    return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
  };
  const nonNegativeInteger = (value) => {
    const parsed = Math.trunc(Number(value));
    return Number.isFinite(parsed) ? Math.max(parsed, 0) : 0;
  };
  return {
    id,
    number,
    roomId,
    tableName: String(source.tableName ?? "").trim().slice(0, 80),
    customerPhone: String(source.customerPhone ?? "").trim().slice(0, 24),
    covers: normalizeTableCovers(source.covers),
    occupancyState,
    reservationAt: positiveTimestamp(source.reservationAt),
    seatedAt: positiveTimestamp(source.seatedAt),
    ordersTaken: nonNegativeInteger(source.ordersTaken),
    ordersInProgress: nonNegativeInteger(source.ordersInProgress),
    amountDue: roundMoney(Math.max(Number(source.amountDue) || 0, 0)),
    note: String(source.note ?? "").trim().slice(0, 240),
    allergens: normalizeStringList(source.allergens, 12, 40),
    manualIntolerance: String(source.manualIntolerance ?? "")
      .trim()
      .slice(0, 64),
    offlineLifecycle: {
      state: "removed_while_active",
      removedAt,
      removedFromLayoutVersion,
      usableUntil: "released",
      requiresDecision: lifecycle.requiresDecision,
      decision: lifecycle.decision,
    },
  };
}

function resolveRemovedSourceTableMoveContext(
  db,
  settings,
  payload,
  fromTableId,
) {
  const snapshot = sanitizeRemovedSourceTableMoveSnapshot(
    payload,
    fromTableId,
  );
  const payloadRoomId = String(payload?.roomId ?? "").trim();
  if (payloadRoomId && payloadRoomId !== snapshot.roomId) {
    throw new HttpError(400, "Sala del tavolo sorgente non coerente.", {
      code: "REMOVED_SOURCE_ROOM_MISMATCH",
    });
  }
  const configuredSourceRoom = findPosRoomById(settings, snapshot.roomId);
  const sourceRoom = configuredSourceRoom ?? {
    id: snapshot.roomId,
    name: snapshot.roomId,
    activityId: "",
    activityIds: [],
    removedFromConfiguration: true,
  };
  const activeOrders = collectRemovedSourceActiveOrders(db, fromTableId);
  const activeReservations = collectRemovedSourceActiveReservations(
    db,
    fromTableId,
  );
  const sessionEvidence = findRemovedOperationalSessionEvidence(db, fromTableId);
  const openedAtMs = sessionEvidence.openedAtMs;
  if (snapshot.occupancyState === "reserved" && activeReservations.length === 0) {
    throw new HttpError(
      409,
      "La prenotazione del tavolo sorgente non risulta piu attiva.",
      { code: "REMOVED_SOURCE_RESERVATION_NOT_ACTIVE" },
    );
  }
  if (
    snapshot.occupancyState === "seated" &&
    activeOrders.length === 0 &&
    openedAtMs <= 0
  ) {
    throw new HttpError(
      409,
      "Il tavolo sorgente rimosso non ha piu una sessione operativa attiva.",
      { code: "REMOVED_SOURCE_OPERATIONAL_EVIDENCE_MISSING" },
    );
  }
  const reservationEvidence = activeReservations
    .map((entry) => entry.reservation)
    .sort((left, right) => {
      const reference = snapshot.reservationAt ?? Date.now();
      return (
        Math.abs(Number(left.reservationAt) - reference) -
        Math.abs(Number(right.reservationAt) - reference)
      );
    })[0];
  const reservationAt = reservationEvidence
    ? Number(reservationEvidence.reservationAt)
    : snapshot.reservationAt;
  const sourceCovers = reservationEvidence?.covers ?? snapshot.covers;
  const sourceTable = sanitizePosTable(
    {
      id: snapshot.id,
      number: snapshot.number,
      type: sourceRoom.name,
      roomId: snapshot.roomId,
      status:
        snapshot.occupancyState === "reserved"
          ? "reserved"
          : activeOrders.length > 0
            ? "waiting"
            : "no_orders",
      guestName:
        String(reservationEvidence?.customerName ?? "").trim() ||
        snapshot.tableName,
      customerPhone:
        String(reservationEvidence?.customerPhone ?? "").trim() ||
        snapshot.customerPhone,
      covers: sourceCovers,
      reservation:
        snapshot.occupancyState === "reserved" && reservationAt
          ? {
              time: timeStringFromTimestamp(reservationAt),
              people: sourceCovers,
              mergeFlag: false,
            }
          : null,
      seatedAt:
        snapshot.occupancyState === "seated"
          ? (snapshot.seatedAt ?? openedAtMs ?? null)
          : null,
      totalDue: 0,
      pendingBills: [],
      note: snapshot.note || String(reservationEvidence?.note ?? "").trim(),
      allergens: snapshot.allergens,
      manualIntolerance:
        snapshot.manualIntolerance ||
        String(reservationEvidence?.intolerances ?? "").trim(),
      workLock: null,
    },
    snapshot.number,
  );
  return {
    snapshot,
    sourceTable,
    sourceRoomId: snapshot.roomId,
    sourceRoomRemovedFromConfiguration: !configuredSourceRoom,
    activeOrders,
    activeReservations,
    evidenceUserIds: collectRemovedOperationalEvidenceUserIds({
      activeOrders,
      activeReservations,
      sessionEvidence,
    }),
  };
}

function buildRemovedSourceOperationalSettings(settings, sourceTable) {
  const roomId = String(sourceTable?.roomId ?? "").trim();
  const hasConfiguredRoom = Boolean(findPosRoomById(settings, roomId));
  const areas = Array.isArray(settings?.areas) ? settings.areas : [];
  return sanitizePosSettings({
    ...settings,
    areas:
      hasConfiguredRoom || !roomId
        ? areas
        : [
            ...areas,
            {
              id: roomId,
              name: String(sourceTable?.type ?? roomId).trim() || roomId,
            },
          ],
    tables: [...settings.tables, sourceTable],
  });
}

function assertRemovedSourceReservationsTransferable(
  context,
  db,
  toTableId,
  targetRoomId,
) {
  if (!context || context.activeReservations.length === 0) return;
  if (context.sourceRoomId !== targetRoomId) {
    throw new HttpError(
      409,
      "Sposta prima la prenotazione in un tavolo della stessa sala.",
      { code: "REMOVED_SOURCE_RESERVATION_ROOM_MOVE_UNSUPPORTED" },
    );
  }
  for (const { state, reservation } of context.activeReservations) {
    assertPosReservationAssignable(
      state.reservations,
      reservation.reservationAt,
      toTableId,
      reservation.id,
    );
  }
}

function transferRemovedSourceReservations(
  db,
  context,
  fromTableId,
  toTableId,
) {
  if (!context || context.activeReservations.length === 0) return 0;
  const reservationKeys = new Set(
    context.activeReservations.map(
      ({ state, reservation }) => `${state.key}::${reservation.id}`,
    ),
  );
  let transferred = 0;
  db.posReservationStates = (
    Array.isArray(db.posReservationStates) ? db.posReservationStates : []
  ).map((rawState) => {
    const state = sanitizePosReservationStateRecord(rawState);
    if (!state) return rawState;
    let changed = false;
    const reservations = state.reservations.map((reservation) => {
      if (!reservationKeys.has(`${state.key}::${reservation.id}`)) {
        return reservation;
      }
      const assignedTableIds = normalizePosReservationTableIds(
        posReservationAssignedTableIds(reservation).map((tableId) =>
          tableId === fromTableId ? toTableId : tableId,
        ),
      );
      changed = true;
      transferred += 1;
      return {
        ...reservation,
        assignedTableId: assignedTableIds[0] ?? null,
        assignedTableIds,
        updatedAt: Date.now(),
      };
    });
    return changed
      ? { ...state, version: state.version + 1, reservations }
      : state;
  });
  return transferred;
}

function queuePosTableRoomMoveNotification(db, request, kind = "request") {
  const notification = buildPosTableRoomMoveNotificationPayload(request, kind);
  return notification ? queueIntegrationNotification(db, notification) : null;
}

function queuePosTableRoomMovePausedWaiterNotifications(
  db,
  request,
  pausedWaiters = [],
) {
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  normalizeWaiterPauseCollections(db.integration);
  const safe = sanitizePosTableRoomMoveRequestRecord(request);
  if (!safe || !Array.isArray(pausedWaiters) || pausedWaiters.length === 0)
    return 0;
  let queued = 0;
  for (const waiter of pausedWaiters) {
    const targetUserId = String(waiter?.userId ?? "").trim();
    const targetUsername = String(waiter?.username ?? "").trim();
    const targetFullName = String(waiter?.fullName ?? "").trim();
    if (!targetUserId && !targetUsername && !targetFullName) continue;
    const alreadyQueued = db.integration.waiterDeferredCalls.some((entry) => {
      const deferred = sanitizeWaiterDeferredCall(entry);
      return (
        String(deferred.payload?.meta?.eventType ?? "") ===
          "table_room_move_after_pause" &&
        String(deferred.payload?.meta?.requestId ?? "") === safe.requestId &&
        ((targetUserId && deferred.targetUserId === targetUserId) ||
          (targetUsername && deferred.targetUsername === targetUsername) ||
          (targetFullName && deferred.targetFullName === targetFullName))
      );
    });
    if (alreadyQueued) continue;
    const pauseStatus =
      waiter?.pauseStatus && typeof waiter.pauseStatus === "object"
        ? waiter.pauseStatus
        : {};
    const deliverAfterMs = Math.max(
      Date.now(),
      Math.trunc(Number(pauseStatus.endsAtMs) || 0),
    );
    const tableLabel = safe.fromTableLabel || safe.fromTableId;
    const record = sanitizeWaiterDeferredCall({
      id: `waiter_deferred_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      targetUserId,
      targetUsername,
      targetFullName,
      createdAtMs: Date.now(),
      deliverAfterMs,
      payload: {
        type: "general",
        title: "Cambio sala tavolo",
        description: `${tableLabel} richiesto verso ${safe.targetRoomName} mentre eri in pausa.`,
        meta: {
          eventType: "table_room_move_after_pause",
          requestId: safe.requestId,
          targetRoomId: safe.targetRoomId,
          targetRoomName: safe.targetRoomName,
          fromTableId: safe.fromTableId,
          fromTableLabel: safe.fromTableLabel,
          targetTableIds: safe.targetTableIds,
          targetTableLabels: safe.targetTableLabels,
          targetUserId,
          targetUsername,
          targetFullName,
          targetClientApp: "mobile-frontend",
        },
      },
    });
    db.integration.waiterDeferredCalls.push(record);
    queued += 1;
  }
  return queued;
}

function rerouteManualTransferredOrder(order, targetStationRaw, options = {}) {
  const targetStation = normalizeIntegrationStationName(targetStationRaw);
  if (!targetStation || !order || typeof order !== "object") return order;
  const resetPreparation = options.resetPreparation !== false;
  return {
    ...order,
    station: targetStation,
    items: Array.isArray(order.items)
      ? order.items.map((item) =>
          item && typeof item === "object"
            ? { ...item, routeStations: [targetStation] }
            : item,
        )
      : order.items,
    tickets: Array.isArray(order.tickets)
      ? order.tickets.map((ticket) =>
          ticket && typeof ticket === "object"
            ? { ...ticket, stationId: targetStation }
            : ticket,
        )
      : order.tickets,
    lineRoutes: Array.isArray(order.lineRoutes)
      ? order.lineRoutes.map((route) =>
          route && typeof route === "object"
            ? { ...route, stationId: targetStation }
            : route,
        )
      : order.lineRoutes,
    ...(resetPreparation
      ? {
          workflowStatus: "waiting",
          readyAtMs: null,
          completedAtMs: null,
          preparationStartedAt: null,
          lockedByStationId: null,
          lockedByUserId: "",
          lockedAt: null,
          lockStatus: "unlocked",
          ownerStation: null,
          ownerOperator: null,
          ownerRole: null,
          ownerAtMs: null,
        }
      : {}),
  };
}

function buildIntegrationCurrentTableSessions(db, options = {}) {
  const targetFilter = normalizeIntegrationTableSnapshotTargets(options);
  const tables = targetFilter.hasTargetFilter
    ? (() => {
        const resolver = createIntegrationLayoutRoomResolver(db?.posSettings);
        const matches = [];
        for (const table of resolver.sourceTables) {
          const entry = buildIntegrationLayoutTableRecord(table, resolver.resolveRoom(table));
          const roomKey = entry.roomId && entry.number > 0 ? `${entry.roomId}::${entry.number}` : "";
          if (targetFilter.targetTableIds.has(entry.id) || targetFilter.targetRoomNumberKeys.has(roomKey)) matches.push(entry);
        }
        return matches;
      })()
    : buildIntegrationLayoutFromSettings(db?.posSettings).tables;
  const sessions = { byId: new Map(), byRoomNumber: new Map() };
  for (const table of tables) {
    const seatedAtMs = Number(table.seatedAt);
    const session = { seated: table.occupancyState === "seated", seatedAtMs: Number.isFinite(seatedAtMs) && seatedAtMs > 0 ? Math.trunc(seatedAtMs) : 0, lastOpenedAtMs: 0, lastReleasedAtMs: 0 };
    const tableId = String(table.id ?? "").trim();
    if (tableId) sessions.byId.set(tableId, session);
    const tableNumber = Math.trunc(Number(table.number) || 0);
    const roomId = String(table.roomId ?? "").trim();
    if (roomId && tableNumber > 0) sessions.byRoomNumber.set(`${roomId}::${tableNumber}`, session);
  }

  const touchSessionFromAudit = (
    event,
    key,
    tableId,
    roomId,
    tableNumber,
    atMs,
  ) => {
    if (!Number.isFinite(atMs) || atMs <= 0) return;
    const targets = [];
    if (tableId) targets.push(sessions.byId.get(tableId));
    if (roomId && tableNumber > 0)
      targets.push(sessions.byRoomNumber.get(`${roomId}::${tableNumber}`));
    for (const session of targets) {
      if (!session) continue;
      session[key] = Math.max(session[key] || 0, Math.trunc(atMs));
    }
  };

  forEachIntegrationCurrentTableSessionAuditEvent(db, (event) => {
    const payload = event.payload && typeof event.payload === "object" ? event.payload : {};
    if (event.action === "table.settled" && payload.keptOccupied === true) {
      return;
    }
    const tableId = String(payload.tableId ?? event.entityId ?? "").trim();
    const roomId = String(payload.roomId ?? event.roomId ?? "").trim();
    const tableNumber = Math.trunc(Number(payload.tableNumber) || 0);
    const atMs = parseTimestampMs(event.occurredAt, 0);
    touchSessionFromAudit(event, event.action === "table.session_opened" ? "lastOpenedAtMs" : "lastReleasedAtMs", tableId, roomId, tableNumber, atMs);
  });

  return sessions;
}

function forEachIntegrationCurrentTableSessionAuditEvent(db, callback) {
  if (typeof callback !== "function") return;
  const records = Array.isArray(db?.auditEvents) ? db.auditEvents : [];
  for (let index = 0; index < records.length; index += 1) {
    const rawEvent = records[index];
    if (!rawEvent || typeof rawEvent !== "object") continue;
    const action = String(rawEvent.action ?? "").trim();
    if (action !== "table.session_opened" && action !== "table.released" && action !== "table.settled") continue;
    const entityType = String(rawEvent.entityType ?? "").trim();
    const entityId = String(rawEvent.entityId ?? "").trim();
    if (!entityType || !entityId) continue;
    const payload = rawEvent.payload && typeof rawEvent.payload === "object" ? rawEvent.payload : {};
    const occurredAt = String(rawEvent.occurredAt ?? "").trim() || nowIso();
    callback({
      action,
      entityId,
      occurredAt,
      roomId: rawEvent.roomId ? String(rawEvent.roomId) : null,
      actorUserId: rawEvent.actorUserId
        ? String(rawEvent.actorUserId)
        : null,
      payload,
    });
  }
}

function getIntegrationTableSessionForOrder(tableSessions, order) {
  if (!tableSessions || !order) return null;
  const tableId = String(order.tableId ?? "").trim();
  const tableNumber = Math.trunc(Number(order.tableNumber) || 0);
  const roomId = String(order.roomId ?? "").trim();
  return (
    (tableId ? tableSessions.byId.get(tableId) : null) ??
    (roomId && tableNumber > 0
      ? tableSessions.byRoomNumber.get(`${roomId}::${tableNumber}`)
      : null) ??
    null
  );
}

function integrationStationMatchesFilter(value, stationFilter) {
  const raw = String(value ?? "").trim();
  if (!raw || !stationFilter) return false;
  return normalizeIntegrationStationName(raw) === stationFilter;
}

function integrationStationListMatchesFilter(values, stationFilter) {
  return (Array.isArray(values) ? values : []).some((entry) =>
    integrationStationMatchesFilter(entry, stationFilter),
  );
}

function integrationOrderMatchesStationOperatorFilter(
  order,
  operatorFilter = {},
  options = {},
) {
  const assignedUserId = String(
    order?.assignedStationOperatorUserId ?? "",
  ).trim();
  const assignedUsername = normalizeUsername(
    order?.assignedStationOperatorUsername,
  );
  const assignedDeviceUuid = String(
    order?.assignedStationDeviceUuid ?? "",
  ).trim();

  if (!assignedUserId && !assignedUsername && !assignedDeviceUuid) return true;

  const requesterUserId = String(operatorFilter.userId ?? "").trim();
  const requesterUsername = normalizeUsername(operatorFilter.username);
  const requesterDeviceUuid = String(operatorFilter.deviceUuid ?? "").trim();
  if (!requesterUserId && !requesterUsername && !requesterDeviceUuid) {
    return options.requireRequesterForAssigned === true ? false : true;
  }

  if (assignedUserId) return assignedUserId === requesterUserId;
  if (assignedUsername) return assignedUsername === requesterUsername;
  if (assignedDeviceUuid) return assignedDeviceUuid === requesterDeviceUuid;
  return true;
}

function isIntegrationOrderHistoricalForStationView(order) {
  const workflow = String(order?.workflowStatus ?? "")
    .trim()
    .toLowerCase();
  const paymentStatus = String(order?.paymentStatus ?? "")
    .trim()
    .toLowerCase();
  const dueAmount = roundMoney(Math.max(Number(order?.dueAmount) || 0, 0));
  return (
    paymentStatus === "paid" ||
    dueAmount <= 0.009 ||
    [
      "ready",
      "delivered",
      "done",
      "completed",
      "cancelled",
      "annullata",
      "voided",
    ].includes(workflow)
  );
}

function resolveIntegrationStationDoneHistoryLimit(rawValue) {
  const parsed = Math.trunc(Number(rawValue));
  if (Number.isFinite(parsed) && parsed >= 0) {
    return Math.min(parsed, 200);
  }
  return Math.min(Math.max(INTEGRATION_STATION_DONE_HISTORY_LIMIT, 0), 200);
}

function limitIntegrationStationDoneHistory(orders, options = {}) {
  const limit = resolveIntegrationStationDoneHistoryLimit(options.limit);
  if (!Array.isArray(orders) || orders.length === 0) return [];
  if (limit >= orders.length) return orders;

  const activeOrders = [];
  const historicalOrders = [];
  orders.forEach((order) => {
    if (isIntegrationOrderHistoricalForStationView(order)) {
      historicalOrders.push(order);
    } else {
      activeOrders.push(order);
    }
  });
  const recentHistorical = historicalOrders
    .sort(
      (left, right) => Number(right.receivedAtMs) - Number(left.receivedAtMs),
    )
    .slice(0, limit);
  return [...activeOrders, ...recentHistorical].sort(
    (left, right) => Number(left.receivedAtMs) - Number(right.receivedAtMs),
  );
}

function getStationOperatorAssignmentKey(source) {
  const userId = String(
    source?.operatorUserId ??
      source?.userId ??
      source?.assignedStationOperatorUserId ??
      "",
  ).trim();
  if (userId) return `user:${userId}`;
  const username = normalizeUsername(
    source?.operatorUsername ??
      source?.username ??
      source?.assignedStationOperatorUsername,
  );
  if (username) return `username:${username}`;
  const deviceUuid = String(
    source?.deviceUuid ?? source?.assignedStationDeviceUuid ?? "",
  ).trim();
  if (deviceUuid) return `device:${deviceUuid}`;
  const name = normalizeUsername(
    source?.operatorName ??
      source?.operator ??
      source?.assignedStationOperatorName,
  );
  return name ? `name:${name}` : "";
}

function integrationOrderHasAssignedOperator(order) {
  return Boolean(
    getStationOperatorAssignmentKey({
      assignedStationOperatorUserId: order?.assignedStationOperatorUserId,
      assignedStationOperatorUsername: order?.assignedStationOperatorUsername,
      assignedStationOperatorName: order?.assignedStationOperatorName,
      assignedStationDeviceUuid: order?.assignedStationDeviceUuid,
    }),
  );
}

function integrationOrderAssignmentStation(order) {
  return normalizeIntegrationStationName(
    order?.assignedStationId ??
      order?.ownerStation ??
      order?.lockedByStationId ??
      order?.station ??
      "",
  );
}

function isIntegrationOrderOpenForOperatorAssignment(order) {
  const workflow = String(order?.workflowStatus ?? "")
    .trim()
    .toLowerCase();
  if (
    [
      "delivered",
      "done",
      "completed",
      "cancelled",
      "annullata",
      "voided",
    ].includes(workflow)
  ) {
    return false;
  }
  if (
    String(order?.paymentStatus ?? "")
      .trim()
      .toLowerCase() === "paid"
  ) {
    return false;
  }
  return true;
}

function backfillStationOperatorAssignments(db, options = {}) {
  if (!db.integration || typeof db.integration !== "object") {
    db.integration = createDefaultIntegrationState();
  }
  if (
    !Array.isArray(db.integration.orders) ||
    db.integration.orders.length === 0
  ) {
    return [];
  }

  const stationFilterRaw = String(options.station ?? "").trim();
  const stationFilter = stationFilterRaw
    ? normalizeIntegrationStationName(stationFilterRaw)
    : "";
  const stationStates = buildIntegrationStationStatesWithSessionRecovery(db);
  db.integration.stationStates = stationStates;
  const activeStations = getActiveStations(
    { integration: { ...db.integration, stationStates } },
    { allowDemoStations: SHOW_DEMO_STATIONS },
  );
  const candidatesByStation = new Map();
  activeStations.forEach((stationState) => {
    const station = normalizeIntegrationStationName(stationState?.station);
    const operatorKey = getStationOperatorAssignmentKey(stationState);
    if (!station || !operatorKey) return;
    if (!candidatesByStation.has(station)) candidatesByStation.set(station, []);
    candidatesByStation.get(station).push({ ...stationState, operatorKey });
  });
  if (candidatesByStation.size === 0) return [];

  const workloadByKey = new Map();
  db.integration.orders.forEach((entry) => {
    if (!entry || typeof entry !== "object") return;
    if (!isIntegrationOrderOpenForOperatorAssignment(entry)) return;
    const station = integrationOrderAssignmentStation(entry);
    const operatorKey = getStationOperatorAssignmentKey({
      assignedStationOperatorUserId: entry.assignedStationOperatorUserId,
      assignedStationOperatorUsername: entry.assignedStationOperatorUsername,
      assignedStationOperatorName: entry.assignedStationOperatorName,
      assignedStationDeviceUuid: entry.assignedStationDeviceUuid,
    });
    if (!station || !operatorKey) return;
    const key = `${station}::${operatorKey}`;
    workloadByKey.set(key, (workloadByKey.get(key) ?? 0) + 1);
  });

  const changed = [];
  db.integration.orders = db.integration.orders.map((entry, index) => {
    const current = sanitizeIntegrationOrder(
      entry,
      String(index + 1).padStart(5, "0"),
    );
    if (!isIntegrationOrderOpenForOperatorAssignment(current)) return entry;
    const station = integrationOrderAssignmentStation(current);
    if (!station || (stationFilter && station !== stationFilter)) return entry;
    const candidates = candidatesByStation.get(station) ?? [];
    if (candidates.length === 0) return entry;
    const assignedOperatorKey = getStationOperatorAssignmentKey({
      assignedStationOperatorUserId: current.assignedStationOperatorUserId,
      assignedStationOperatorUsername: current.assignedStationOperatorUsername,
      assignedStationOperatorName: current.assignedStationOperatorName,
      assignedStationDeviceUuid: current.assignedStationDeviceUuid,
    });
    if (
      assignedOperatorKey &&
      candidates.some(
        (candidate) => candidate.operatorKey === assignedOperatorKey,
      )
    ) {
      return entry;
    }

    const selected = [...candidates].sort((left, right) => {
      const leftWorkload =
        workloadByKey.get(`${station}::${left.operatorKey}`) ?? 0;
      const rightWorkload =
        workloadByKey.get(`${station}::${right.operatorKey}`) ?? 0;
      if (leftWorkload !== rightWorkload) return leftWorkload - rightWorkload;
      const leftUpdated = Number(left.updatedAtMs) || 0;
      const rightUpdated = Number(right.updatedAtMs) || 0;
      if (leftUpdated !== rightUpdated) return leftUpdated - rightUpdated;
      return left.operatorKey.localeCompare(right.operatorKey, "it", {
        sensitivity: "base",
      });
    })[0];
    if (!selected) return entry;

    const workloadKey = `${station}::${selected.operatorKey}`;
    workloadByKey.set(workloadKey, (workloadByKey.get(workloadKey) ?? 0) + 1);
    const nextOrder = sanitizeIntegrationOrder(
      {
        ...current,
        station,
        assignedStationId: station,
        originalAssignedStationId: current.originalAssignedStationId || station,
        assignedStationOperatorUserId: String(
          selected.operatorUserId ?? selected.userId ?? "",
        ).trim(),
        assignedStationOperatorUsername: String(
          selected.operatorUsername ?? selected.username ?? "",
        ).trim(),
        assignedStationOperatorName: String(
          selected.operatorName ?? selected.operator ?? "",
        ).trim(),
        assignedStationDeviceUuid: String(selected.deviceUuid ?? "").trim(),
        assignedStationClientApp: normalizeClientApp(
          selected.clientApp ?? "postazione",
        ),
        assignmentReason: current.assignmentReason || "auto",
        assignmentStatus: "assigned",
        assignmentReasonDetail:
          current.assignmentReasonDetail || "operator_backfill",
        updatedAt: nowIso(),
      },
      current.id,
    );
    changed.push({
      orderId: nextOrder.id,
      station,
      operatorUserId: nextOrder.assignedStationOperatorUserId,
      operatorUsername: nextOrder.assignedStationOperatorUsername,
      operatorName: nextOrder.assignedStationOperatorName,
      deviceUuid: nextOrder.assignedStationDeviceUuid,
    });
    return nextOrder;
  });

  if (changed.length > 0) {
    db.integration.lastWriteAt = nowIso();
    db.meta.lastWriteAt = nowIso();
  }
  return changed;
}

function integrationOrderMatchesStationFilter(
  order,
  stationFilter,
  includeTransferred = false,
) {
  if (!stationFilter) return true;
  if (
    String(order?.assignmentStatus ?? "")
      .trim()
      .toLowerCase() === "queued_unassigned"
  ) {
    return false;
  }
  if (
    includeTransferred &&
    [order?.transferredFromStation, order?.transferredToStation].some((entry) =>
      integrationStationMatchesFilter(entry, stationFilter),
    )
  ) {
    return true;
  }

  const exclusiveStationFields = [
    order?.assignedStationId,
    order?.ownerStation,
    order?.lockedByStationId,
  ].filter((entry) => String(entry ?? "").trim());
  if (exclusiveStationFields.length > 0) {
    return exclusiveStationFields.some((entry) =>
      integrationStationMatchesFilter(entry, stationFilter),
    );
  }

  const fallbackStationFields = [order?.station].filter((entry) =>
    String(entry ?? "").trim(),
  );
  if (fallbackStationFields.length > 0) {
    return fallbackStationFields.some((entry) =>
      integrationStationMatchesFilter(entry, stationFilter),
    );
  }

  // Solo le comande legacy senza assegnazione possono usare route/ticket come fallback.
  if (
    (Array.isArray(order?.items) ? order.items : []).some((item) =>
      integrationStationListMatchesFilter(item?.routeStations, stationFilter),
    )
  ) {
    return true;
  }
  if (
    (Array.isArray(order?.tickets) ? order.tickets : []).some((ticket) =>
      integrationStationMatchesFilter(ticket?.stationId, stationFilter),
    )
  ) {
    return true;
  }
  return (Array.isArray(order?.lineRoutes) ? order.lineRoutes : []).some(
    (route) => integrationStationMatchesFilter(route?.stationId, stationFilter),
  );
}

function mergeIntegrationCompAvailabilityEntry(target, key, entry) {
  if (!key) return;
  const current = target[key];
  if (!current) {
    target[key] = { ...entry };
    return;
  }
  target[key] = {
    ...current,
    quantity:
      Math.max(Math.trunc(Number(current.quantity) || 0), 0) +
      Math.max(Math.trunc(Number(entry.quantity) || 0), 0),
    compedQuantity:
      Math.max(Math.trunc(Number(current.compedQuantity) || 0), 0) +
      Math.max(Math.trunc(Number(entry.compedQuantity) || 0), 0),
    zeroCostReplacementQuantity:
      Math.max(
        Math.trunc(Number(current.zeroCostReplacementQuantity) || 0),
        0,
      ) +
      Math.max(Math.trunc(Number(entry.zeroCostReplacementQuantity) || 0), 0),
    financialCompedQuantity:
      Math.max(Math.trunc(Number(current.financialCompedQuantity) || 0), 0) +
      Math.max(Math.trunc(Number(entry.financialCompedQuantity) || 0), 0),
    availableQuantity:
      Math.max(Math.trunc(Number(current.availableQuantity) || 0), 0) +
      Math.max(Math.trunc(Number(entry.availableQuantity) || 0), 0),
  };
}

function buildIntegrationOrderCompAvailability(order, db) {
  const safeOrderId = String(order?.id ?? "").trim();
  const byLine = {};
  const byProduct = {};
  if (!safeOrderId) return { byLine, byProduct };
  const seen = new Set();
  (Array.isArray(order?.items) ? order.items : []).forEach((item) => {
    if (
      !item ||
      item.voidedAt ||
      item.lineType === BAR_CHARGE_REPLACEMENT_LINE_TYPE
    )
      return;
    const lineId = String(item.lineId ?? item.id ?? "").trim();
    const productId = String(item.productId ?? "").trim();
    if (!lineId && !productId) return;
    const key = `${lineId}::${productId}`;
    if (seen.has(key)) return;
    seen.add(key);
    const line = findOrderLineForComp(order, lineId, productId);
    if (!line) return;
    const resolvedLineId = String(line.lineId || lineId).trim();
    const resolvedProductId = String(line.productId || productId).trim();
    const quantity = Math.max(Math.trunc(Number(line.quantity) || 0), 0);
    const compRecords = listOrderCompRecordsForOrderLine(
      db,
      safeOrderId,
      resolvedLineId,
      resolvedProductId,
    );
    const compedQuantity = compRecords.reduce(
      (sum, record) =>
        sum + Math.max(Math.trunc(Number(record?.quantity) || 0), 0),
      0,
    );
    const zeroCostReplacementQuantity = compRecords
      .filter((record) => isZeroCostReplacementCompRecord(record))
      .reduce(
        (sum, record) =>
          sum + Math.max(Math.trunc(Number(record?.quantity) || 0), 0),
        0,
      );
    const entry = {
      lineId: resolvedLineId,
      productId: resolvedProductId,
      quantity,
      compedQuantity,
      zeroCostReplacementQuantity,
      financialCompedQuantity: Math.max(
        compedQuantity - zeroCostReplacementQuantity,
        0,
      ),
      availableQuantity: Math.max(quantity - compedQuantity, 0),
    };
    mergeIntegrationCompAvailabilityEntry(byLine, resolvedLineId, entry);
    mergeIntegrationCompAvailabilityEntry(byProduct, resolvedProductId, entry);
  });
  return { byLine, byProduct };
}

function appendIntegrationRouteAuditEvents(db, auditActor, order, routeEvents) {
  const events = Array.isArray(routeEvents) ? routeEvents : [];
  if (events.length === 0) return;
  const orderId = String(order?.id ?? "").trim();
  const roomId = String(order?.roomId ?? auditActor?.roomId ?? "").trim();
  if (
    ORDER_AUDIT_DETAILED_ROUTE_MAX > 0 &&
    events.length <= ORDER_AUDIT_DETAILED_ROUTE_MAX
  ) {
    events.forEach((routeEvent) => {
      appendAuditEvent(db, {
        ...auditActor,
        action: routeEvent.action,
        entityType: "line_route",
        entityId: routeEvent.routeId,
        roomId,
        payload: {
          orderId,
          routeId: routeEvent.routeId,
          lineId: routeEvent.lineId,
          stationId: routeEvent.stationId,
          occurredAt: routeEvent.occurredAt,
        },
      });
    });
    return;
  }

  const actionCounts = events.reduce((acc, routeEvent) => {
    const action = String(routeEvent?.action ?? "order.route_event").trim();
    acc[action] = (acc[action] ?? 0) + 1;
    return acc;
  }, {});
  appendAuditEvent(db, {
    ...auditActor,
    action: "order.route_events",
    entityType: "line_routes",
    entityId: orderId,
    roomId,
    payload: {
      orderId,
      eventCount: events.length,
      actionCounts,
      sampleEvents: events
        .slice(0, ORDER_AUDIT_SUMMARY_LINE_SAMPLE_MAX)
        .map((routeEvent) => ({
          action: routeEvent.action,
          routeId: routeEvent.routeId,
          lineId: routeEvent.lineId,
          stationId: routeEvent.stationId,
          occurredAt: routeEvent.occurredAt,
        })),
      truncatedEventCount: Math.max(
        events.length - ORDER_AUDIT_SUMMARY_LINE_SAMPLE_MAX,
        0,
      ),
    },
  });
}

async function readTableWorkLockRequestDb(req) {
  const authenticatedDb = req?.__authDb && typeof req.__authDb === "object" ? req.__authDb : null;
  if (authenticatedDb && (RELATIONAL_TABLE_LOCKS_WRITE_PRIMARY || isTableWorkLockFastPathEnabled())) return authenticatedDb;
  return readDb({ refreshExternalizedSessions: true, refreshExternalizedTableLocks: true });
}

function validateReplacementReason(reasonRaw) {
  if (typeof reasonRaw !== "string" || !reasonRaw.trim()) {
    throw new HttpError(400, "Inserisci il motivo della sostituzione.", {
      code: "REPLACEMENT_REASON_REQUIRED",
    });
  }
  const reason = reasonRaw.trim();
  if (reason.length > 300) {
    throw new HttpError(400, "Il motivo della sostituzione è troppo lungo.", {
      code: "REPLACEMENT_REASON_TOO_LONG",
    });
  }
  if (reason.length < 3) {
    throw new HttpError(400, "Inserisci il motivo della sostituzione.", {
      code: "REPLACEMENT_REASON_REQUIRED",
    });
  }
  return reason;
}

function findOrderLineSnapshot(order, originalLineId, productId) {
  const lines = [...buildIntegrationOrderLineSnapshots(order).values()];
  const lineId = String(originalLineId ?? "").trim();
  const safeProductId = String(productId ?? "").trim();
  return (
    (lineId ? lines.find((line) => line.lineId === lineId) : null) ??
    (safeProductId
      ? lines.find(
          (line) => String(line.productId ?? "").trim() === safeProductId,
        )
      : null) ??
    null
  );
}

function resolveMenuProductForPayload(db, payload) {
  const menuLookup = buildIntegrationMenuItemsByName(db);
  const productId = String(payload?.productId ?? "").trim();
  const productName = String(
    payload?.productName ?? payload?.name ?? "",
  ).trim();
  return (
    (productId
      ? menuLookup.get(normalizeIntegrationLookupKey(productId))
      : null) ??
    (productName
      ? menuLookup.get(normalizeIntegrationLookupKey(productName))
      : null) ??
    null
  );
}

function buildReplacementPrintText(record, settings = null) {
  const width = Math.max(
    48,
    sanitizePosPrintPreferences(settings?.printPreferences).order.lineWidth,
  );
  const titleStyle = {
    align: "center",
    bold: true,
    widthScale: 2,
    heightScale: 2,
    charSpacing: 0,
  };
  const bodyStyle = {
    align: "left",
    bold: true,
    widthScale: 1,
    heightScale: 1,
    charSpacing: 0,
  };
  const productStyle = {
    align: "left",
    bold: true,
    widthScale: 1,
    heightScale: 2,
    charSpacing: 0,
  };
  const metaStyle = {
    align: "left",
    bold: true,
    widthScale: 0,
    heightScale: 1,
    charSpacing: 0,
  };
  const tableLocationLabel =
    buildPrintLocationLabel({
      tableLabel: record.tableLabel,
      tableNumber: record.tableNumber || record.tableId,
      roomLabel: resolvePrintRoomLabel(
        settings,
        record.roomId,
        record.roomName || record.roomLabel || "",
      ),
    }) ||
    record.tableLabel ||
    record.tableNumber ||
    record.tableId;
  const originalOrderId = String(record.originalOrderId ?? "").trim();
  const replacementOrderId = String(record.orderId ?? "").trim();
  const orderLines = [
    originalOrderId
      ? `COMANDA ${formatIntegrationPrintOrderId(originalOrderId)}`
      : `COMANDA ${formatIntegrationPrintOrderId(replacementOrderId)}`,
  ];
  if (
    originalOrderId &&
    replacementOrderId &&
    replacementOrderId !== originalOrderId
  ) {
    orderLines.push(
      `SOSTITUTIVA ${formatIntegrationPrintOrderId(replacementOrderId)}`,
    );
  }
  const detailLines = [...orderLines, tableLocationLabel || "-"];
  const quantityLabel = `${Math.max(1, Math.trunc(Number(record.quantity) || 1))} X`;
  const productName =
    String(record.productName || "Articolo").trim() || "Articolo";
  const lines = [...styleEscPosPrintLines("SOSTITUZIONE", titleStyle), ""];
  detailLines.forEach((entry) => {
    wrapPrintText(
      toPrintSafeUppercase(entry),
      Math.max(16, Math.floor(width / 2)),
    ).forEach((line) => {
      lines.push(...styleEscPosPrintLines(line, bodyStyle));
    });
  });
  lines.push("");
  lines.push(...styleEscPosPrintLines("ARTICOLO SOSTITUITO", metaStyle));
  wrapPrintText(
    toPrintSafeUppercase(`${quantityLabel} ${productName}`),
    Math.max(16, Math.floor(width / 2)),
  ).forEach((line) => {
    lines.push(...styleEscPosPrintLines(line, productStyle));
  });
  lines.push("");
  lines.push(...styleEscPosPrintLines("A COSTO 0 EUR", bodyStyle));
  const reason = String(record.reason ?? "").trim();
  if (reason) {
    lines.push("");
    lines.push(...styleEscPosPrintLines("MOTIVO", bodyStyle));
    wrapPrintText(
      toPrintSafeUppercase(reason),
      Math.max(16, Math.floor(width / 2)),
    ).forEach((line) => {
      lines.push(...styleEscPosPrintLines(line, bodyStyle));
    });
  }
  const originalLineId = String(record.originalLineId ?? "").trim();
  if (originalLineId) {
    lines.push("");
    lines.push(
      ...styleEscPosPrintLines(`RIGA ORIG. ${originalLineId}`, metaStyle),
    );
  }
  const operator = String(record.createdByUsername ?? "").trim();
  if (operator) {
    lines.push(...styleEscPosPrintLines(`OPERATORE ${operator}`, metaStyle));
  }
  lines.push(
    ...styleEscPosPrintLines(
      formatIntegrationPrintDateTime(new Date(record.createdAt).getTime()),
      metaStyle,
    ),
  );
  lines.push("");
  return lines.join("\n");
}

function buildCorrectionPrintText(record, settings = null) {
  const tableLocationLabel =
    buildPrintLocationLabel({
      tableLabel: record.tableLabel,
      tableNumber: record.tableNumber || record.tableId,
      roomLabel: resolvePrintRoomLabel(
        settings,
        record.roomId,
        record.roomName || record.roomLabel || "",
      ),
    }) ||
    record.tableLabel ||
    record.tableNumber ||
    record.tableId;
  const lines = [
    `MODIFICA COMANDA ${record.orderId} - REV. ${record.nextRevision}`,
    `Tavolo: ${tableLocationLabel}`,
    `Operatore: ${record.createdByUsername}`,
    "",
  ];
  if (record.addedItems.length) {
    lines.push("AGGIUNTI:");
    record.addedItems.forEach((item) => {
      lines.push(`+ ${item.quantity} ${item.productName ?? item.productId}`);
    });
    lines.push("");
  }
  if (record.removedItems.length) {
    lines.push("RIMOSSI:");
    record.removedItems.forEach((item) => {
      lines.push(
        `RIMOSSO ${item.quantity} ${item.productName ?? item.productId ?? item.lineId}`,
      );
    });
    lines.push("");
  }
  if (record.changedItems.length) {
    lines.push("MODIFICATI:");
    record.changedItems.forEach((item) => {
      lines.push(
        `${item.productName ?? item.productId ?? item.lineId}: ${item.previousQuantity} -> ${item.nextQuantity}`,
      );
    });
    lines.push("");
  }
  if (record.reason) {
    lines.push(`Motivo: ${record.reason}`);
  }
  return lines.join("\n").trimEnd();
}

