function calculateOrderFinancialsFromItems(items, currentOrder, options = {}) {
  const safeItems = Array.isArray(items) ? items : [];
  const itemsTotal = roundMoney(
    safeItems
      .filter(
        (item) =>
          !item?.voidedAt &&
          item?.lineType !== BAR_CHARGE_REPLACEMENT_LINE_TYPE,
      )
      .reduce(
        (sum, item) => sum + Math.max(Number(item?.lineTotal) || 0, 0),
        0,
      ),
  );
  const apericenaQty = Math.max(
    Math.trunc(Number(options?.apericena ?? currentOrder?.apericena) || 0),
    0,
  );
  const hasInlineApericena = countIntegrationApericenaEntries(safeItems) > 0;
  const apericenaCharge = hasInlineApericena
    ? 0
    : roundMoney(apericenaQty * APERICENA_STANDARD_TARGET_PRICE);
  const total = roundMoney(itemsTotal + apericenaCharge);
  const paidAmount = roundMoney(
    Math.min(Math.max(Number(currentOrder?.paidAmount) || 0, 0), total),
  );
  return {
    total,
    paidAmount,
    dueAmount: roundMoney(Math.max(total - paidAmount, 0)),
  };
}

function makeIntegrationOrderItemFromProduct({
  id,
  lineId,
  product,
  productId,
  productName,
  quantity = 1,
  unitPrice = 0,
  note = "",
  modifiers = null,
  routeStations = null,
  replacementMeta = null,
}) {
  const safeName =
    String(productName ?? product?.name ?? productId ?? "Articolo").trim() ||
    "Articolo";
  const safeProductId = String(
    productId ?? product?.id ?? slugifyId(safeName, "product"),
  ).trim();
  const price = roundMoney(
    Math.max(Number(unitPrice ?? product?.price) || 0, 0),
  );
  const qty = Math.max(Math.trunc(Number(quantity) || 1), 1);
  const stations =
    Array.isArray(routeStations) && routeStations.length
      ? routeStations.map((entry) => normalizeIntegrationStationName(entry))
      : [PRIMARY_INTEGRATION_STATION];
  const modifierData =
    modifiers && typeof modifiers === "object" ? cloneJson(modifiers, {}) : {};
  const variantName = String(
    modifierData.Variante ??
      modifierData.variant ??
      modifierData.label ??
      modifierData.name ??
      "",
  ).trim();
  return {
    id,
    lineId,
    productId: safeProductId,
    productNameSnapshot: safeName,
    name: safeName,
    qty,
    unitPriceApplied: replacementMeta ? 0 : price,
    listPriceAtTime: replacementMeta ? 0 : price,
    lineTotal: replacementMeta ? 0 : roundMoney(price * qty),
    variants: modifierData,
    variant: variantName,
    selectedVariantName: variantName || null,
    notes: String(note ?? "").trim(),
    note: String(note ?? "").trim(),
    allergens: normalizeStringList(product?.allergens, 20, 80),
    routeStations: stations,
    done: false,
    ...(replacementMeta ?? {}),
  };
}

function buildReplacementPrecontoOrder(record, fallbackOrder = null) {
  const createdAt = String(record?.createdAt ?? "").trim() || nowIso();
  const quantity = Math.max(1, Math.trunc(Number(record?.quantity) || 1));
  const orderId = String(
    record?.orderId ?? fallbackOrder?.id ?? `repl_${Date.now()}`,
  ).trim();
  const sourceOrderId = String(
    record?.originalOrderId ??
      fallbackOrder?.parentOrderId ??
      fallbackOrder?.id ??
      "",
  ).trim();
  const replacementLineId =
    String(record?.replacementLineId ?? record?.lineId ?? "").trim() ||
    `repl_${randomUUID().replace(/-/g, "").slice(0, 12)}`;
  const productId =
    String(record?.productId ?? "").trim() ||
    slugifyId(record?.productName, "product");
  const productName =
    String(record?.productName ?? "Articolo").trim() || "Articolo";
  const station = normalizeIntegrationStationName(
    record?.station ??
      record?.stationId ??
      fallbackOrder?.station ??
      PRIMARY_INTEGRATION_STATION,
  );
  const tableNumber = String(
    record?.tableNumber ??
      fallbackOrder?.tableNumber ??
      fallbackOrder?.table ??
      "",
  ).trim();
  const tableLabel =
    sanitizeIntegrationTableLabel(
      record?.tableLabel ??
        fallbackOrder?.tableLabel ??
        fallbackOrder?.logicalTableLabel,
    ) || tableNumber;
  const items = [];
  for (let index = 0; index < quantity; index += 1) {
    items.push(
      makeIntegrationOrderItemFromProduct({
        id: `oi_${index + 1}`,
        lineId: replacementLineId,
        product: { id: productId, name: productName, price: 0 },
        productId,
        productName,
        quantity: 1,
        unitPrice: 0,
        routeStations: [station],
        replacementMeta: {
          lineType: BAR_CHARGE_REPLACEMENT_LINE_TYPE,
          chargePolicy: "BAR_INTERNAL",
          payable: false,
          customerPrice: 0,
          tableId: record?.tableId ?? fallbackOrder?.tableId ?? "",
          tableNumber,
          tableLabel,
          roomId: record?.roomId ?? fallbackOrder?.roomId ?? "",
          orderId,
          orderIds: Array.isArray(record?.orderIds)
            ? record.orderIds
            : [orderId].filter(Boolean),
          originalOrderId: sourceOrderId || null,
          originalLineId: String(record?.originalLineId ?? "").trim(),
          replacementLineId,
          reason: String(record?.reason ?? "").trim(),
          createdByUserId: record?.createdByUserId ?? "",
          createdByUsername: record?.createdByUsername ?? "",
          createdByDeviceUuid: record?.createdByDeviceUuid ?? "",
          createdAt,
          fiscalTreatment: BAR_CHARGE_REPLACEMENT_FISCAL_TREATMENT,
        },
      }),
    );
  }
  return sanitizeIntegrationOrder(
    {
      id: orderId,
      table: tableNumber || fallbackOrder?.table,
      waiter: record?.createdByUsername ?? fallbackOrder?.waiter ?? "",
      covers: fallbackOrder?.covers ?? 0,
      apericena: 0,
      note: sourceOrderId
        ? `Sostituzione ${formatIntegrationPrintOrderId(sourceOrderId)}`
        : "Sostituzione",
      communications: String(record?.reason ?? "").trim(),
      station,
      workflowStatus: "delivered",
      items,
      tickets: [],
      lineRoutes: [],
      parentOrderId: sourceOrderId || fallbackOrder?.parentOrderId || null,
      isPartial: false,
      source: "replacement-preconto",
      broadcastToAllStations: false,
      roomId: record?.roomId ?? fallbackOrder?.roomId ?? "",
      tableId: record?.tableId ?? fallbackOrder?.tableId ?? "",
      tableNumber,
      tableLabel,
      logicalTableLabel: tableLabel,
      title: `Sostituzione ${productName}`,
      total: 0,
      paidAmount: 0,
      dueAmount: 0,
      paymentStatus: "paid",
      nonChargeableReplacement: true,
      replacementSettlement: "non_chargeable_zero",
      payable: false,
      orderNote: sourceOrderId
        ? `Sostituzione ${formatIntegrationPrintOrderId(sourceOrderId)}`
        : "Sostituzione",
      orderComment: String(record?.reason ?? "").trim(),
      createdByUserId: record?.createdByUserId ?? "",
      createdByUsername: record?.createdByUsername ?? "",
      createdAt,
      updatedAt: createdAt,
    },
    orderId,
  );
}

