// Step 4 — Command Inbox: repository condiviso (lazy) legato alla connessione
// relazionale dell'owner. La migrazione 018 gira dentro initialize().
let commandInboxRepositorySingleton = null;
async function getCommandInboxRepository() {
  if (!COMMAND_INBOX_ENABLED) return null;
  if (!["shadow", "primary"].includes(relationalRuntime.mode)) return null;
  await relationalRuntime.initialize();
  const relationalDb = relationalRuntime.db;
  if (!relationalDb) return null;
  if (
    !commandInboxRepositorySingleton ||
    commandInboxRepositorySingleton.db !== relationalDb
  ) {
    commandInboxRepositorySingleton = new CommandInboxRepository(relationalDb, {
      runtimeMetrics,
      nowIso,
    });
  }
  return commandInboxRepositorySingleton;
}

