const routeRegistry = createRouteRegistry(buildRouteRegistry(), routeHandlers), backendProcessRouteGuard = createBackendProcessRouteGuard({ routeRegistry, env: process.env }), SHOULD_RUN_BACKEND_OWNER_JOBS = shouldRunBackendOwnerJobs(backendProcessRouteGuard.role), SHOULD_RUN_REALTIME_OUTBOX_PUBLISHER = !["api-worker", "table-lock-worker"].includes(backendProcessRouteGuard.role);
function buildRequestMetricsContext(req, pathname) {
  const method = String(req?.method ?? "GET").toUpperCase();
  const route = routeRegistry.findRoute(method, pathname);
  const requestId =
    readHeaderValue(req, "x-request-id") ||
    readHeaderValue(req, "x-correlation-id") ||
    `req_${Date.now()}_${randomUUID().replace(/-/g, "").slice(0, 10)}`;
  return {
    requestId,
    method,
    path: pathname,
    route: `${method} ${route?.path ?? pathname}`,
    startedAtMs: Date.now(),
    readDbCount: 0,
    readDbMs: 0,
    writeDbCount: 0,
    writeDbMs: 0,
    queueWaitMs: 0,
    laneWaitMs: 0,
    handlerRunMs: 0,
    dirtyDomains: [],
    detectedDirtyDomains: [],
    undeclaredDirtyDomains: [],
    overDeclaredDirtyDomains: [],
    dirtyTrackingMode: APP_STATE_DIRTY_TRACKING_MODE,
    queueKinds: new Set(),
    fullStateFallbackUsed: false,
    mysqlRetryCount: 0,
    mysqlRetryScopes: [],
    mysqlRetryCodes: [],
    mysqlRetryStages: [],
    mysqlRetryLabels: [],
    userId: readHeaderValue(req, "x-user-id") || "",
    deviceId: readHeaderValue(req, "x-device-uuid") || readHeaderValue(req, "x-device-id") || "",
    stationId:
      readHeaderValue(req, "x-station-id") ||
      readHeaderValue(req, "x-integration-station-id") ||
      "",
  };
}

function markRequestQueueTiming(context, kind, waitMs) {
  if (!context) return;
  const safeWaitMs = Math.max(0, Math.trunc(Number(waitMs) || 0));
  const normalizedKind = String(kind ?? "queue").trim() || "queue";
  if (normalizedKind === "dbMutation") context.queueWaitMs += safeWaitMs;
  else context.laneWaitMs += safeWaitMs;
  context.queueKinds?.add?.(normalizedKind);
}

function recordRequestMetrics(context) {
  if (!context) return;
  const durationMs = Date.now() - context.startedAtMs;
  const record = {
    ...context,
    durationMs,
    responseMs: durationMs,
    handlerRunMs: Math.max(
      0,
      durationMs - (context.queueWaitMs || 0) - (context.laneWaitMs || 0),
    ),
    queueKinds: [...(context.queueKinds ?? [])],
  };
  runtimeMetrics.recordRequest(record);
  baselineDiagnostics.recordRequest(record);
}

function applyRouteBodyLimit(req, method, pathname) {
  const route = routeRegistry.findRoute(method, pathname);
  const routeMaxBodySize = Number(route?.maxBodySize);
  if (Number.isFinite(routeMaxBodySize) && routeMaxBodySize > 0) {
    req.__jsonBodyMaxSize = Math.min(routeMaxBodySize, MAX_BODY_SIZE);
  } else {
    delete req.__jsonBodyMaxSize;
  }
}

function mergeRequestAuthPayload(req, payload = {}) {
  const authPayload =
    req.__authPayload && typeof req.__authPayload === "object"
      ? req.__authPayload
      : {};
  return {
    ...payload,
    ...(payload.token
      ? {}
      : authPayload.token
        ? { token: authPayload.token }
        : {}),
    ...(payload.userId
      ? {}
      : authPayload.userId
        ? { userId: authPayload.userId }
        : {}),
    ...(payload.deviceUuid
      ? {}
      : authPayload.deviceUuid
        ? { deviceUuid: authPayload.deviceUuid }
        : {}),
  };
}

function buildHeaderAuthPayload(req, requestUrl) {
  const bearerToken = extractBearerToken(readHeaderValue(req, "authorization"));
  const queryToken = ALLOW_AUTH_QUERY_TOKEN
    ? String(requestUrl.searchParams.get("token") ?? "").trim()
    : "";
  const queryUserId = ALLOW_AUTH_QUERY_TOKEN
    ? String(requestUrl.searchParams.get("userId") ?? "").trim()
    : "";
  const queryDeviceUuid = ALLOW_AUTH_QUERY_TOKEN
    ? String(requestUrl.searchParams.get("deviceUuid") ?? "").trim()
    : "";
  const token = bearerToken || queryToken;
  return {
    token,
    userId: readHeaderValue(req, "x-user-id") || queryUserId,
    deviceUuid: readHeaderValue(req, "x-device-uuid") || queryDeviceUuid,
  };
}

function hasUsableSessionPayload(payload) {
  return Boolean(
    String(payload?.token ?? "").trim() &&
    String(payload?.deviceUuid ?? "").trim(),
  );
}

function requestMayHaveJsonBody(req) {
  if (!req || req.method === "GET" || req.method === "HEAD") return false;
  const contentLength = Number(readHeaderValue(req, "content-length"));
  if (Number.isFinite(contentLength) && contentLength > 0) return true;
  return Boolean(readHeaderValue(req, "transfer-encoding"));
}

function readServiceTokenFromRequest(req, requestUrl, payload = {}) {
  const queryServiceToken = ALLOW_SERVICE_TOKEN_QUERY_PARAM
    ? String(requestUrl.searchParams.get("serviceToken") ?? "").trim()
    : "";
  return (
    readHeaderValue(req, "x-service-token") ||
    readHeaderValue(req, "x-smart-card-token") ||
    queryServiceToken ||
    String(payload.serviceToken ?? "").trim() ||
    String(payload.token ?? "").trim() ||
    extractBearerToken(readHeaderValue(req, "authorization"))
  );
}

function isAllowedSmartCardLocalRequest(req) {
  const remoteAddress = req.socket?.remoteAddress ?? "";
  return (
    isLoopbackAddress(remoteAddress) ||
    (SMART_CARD_PUSH_ALLOW_PRIVATE_NETWORK &&
      isPrivateNetworkAddress(remoteAddress))
  );
}

async function resolveAuthenticatedRequestContext(req, requestUrl) {
  const headerPayload = buildHeaderAuthPayload(req, requestUrl);
  let authPayload = headerPayload;
  const shouldForceBodyAuth =
    req.method !== "GET" &&
    (requestUrl.pathname === "/api/auth/session/status" ||
      requestUrl.pathname === "/api/auth/logout" ||
      requestUrl.pathname === "/api/integration/orders/sync");
  if (
    (!hasUsableSessionPayload(authPayload) ||
      shouldForceBodyAuth ||
      requestMayHaveJsonBody(req)) &&
    req.method !== "GET"
  ) {
    try {
      const bodyPayload = await readJsonBody(req);
      const bodyToken = String(bodyPayload.token ?? "").trim();
      const bodyUserId = String(bodyPayload.userId ?? "").trim();
      const bodyDeviceUuid = String(bodyPayload.deviceUuid ?? "").trim();
      const bodyAuthPayload = {
        token: bodyToken,
        userId: bodyUserId,
        deviceUuid: bodyDeviceUuid,
      };
      const shouldPreferBodyAuth =
        hasUsableSessionPayload(bodyAuthPayload) &&
        (shouldForceBodyAuth ||
          !hasUsableSessionPayload(authPayload) ||
          bodyToken !== String(authPayload.token ?? "").trim() ||
          bodyDeviceUuid !== String(authPayload.deviceUuid ?? "").trim() ||
          (bodyUserId &&
            bodyUserId !== String(authPayload.userId ?? "").trim()));
      if (shouldPreferBodyAuth) {
        authPayload = {
          ...authPayload,
          ...bodyPayload,
          token: bodyToken,
          userId: bodyUserId || String(authPayload.userId ?? "").trim(),
          deviceUuid: bodyDeviceUuid,
        };
      } else if (!hasUsableSessionPayload(authPayload)) {
        authPayload = {
          ...bodyPayload,
          token: bodyToken || String(authPayload.token ?? "").trim(),
          userId: bodyUserId || String(authPayload.userId ?? "").trim(),
          deviceUuid:
            bodyDeviceUuid || String(authPayload.deviceUuid ?? "").trim(),
        };
      }
    } catch (error) {
      if (error instanceof HttpError && error.status === 400) {
        throw new HttpError(401, "Sessione login richiesta.");
      }
      throw error;
    }
  }

  if (!hasUsableSessionPayload(authPayload)) {
    throw new HttpError(401, "Sessione login richiesta.");
  }

  req.__authPayload = authPayload;
  if (isApiWorkerRequestAuthFastPathEnabled()) { const fastAuth = await apiWorkerRequestFastPath.authenticate(authPayload); if (fastAuth) { req.__authDb = fastAuth.db; req.__authContext = fastAuth.context; return fastAuth.context; } }
  if (isTableLockWorkerRequestFastPathEnabled()) {
    const fastAuth = await tableLockWorkerRequestFastPath.authenticate(authPayload);
    if (fastAuth) {
      req.__authDb = fastAuth.db;
      req.__authContext = fastAuth.context;
      return fastAuth.context;
    }
  }
  const isApiWorkerAuth = ["api-worker", "table-lock-worker"].includes(backendProcessRouteGuard.role);
  const shouldRefreshOrderSyncAuth =
    !isApiWorkerAuth &&
    requestUrl.pathname === "/api/integration/orders/sync";
  const canRefreshOrderSyncTarget =
    shouldRefreshOrderSyncAuth &&
    mysqlAppStateDomainsSplitRepository?.enabled === true &&
    typeof mysqlAppStateDomainsSplitRepository.readObjectArrayEntry ===
      "function";
  const orderSyncTargetId = shouldRefreshOrderSyncAuth
    ? resolveOrderSyncLaneKeyFromRequest(req)
    : "";
  const db = await readDb(
    isApiWorkerAuth
      ? { refreshExternalizedSessions: true }
      : canRefreshOrderSyncTarget
        ? {
            refreshExternalizedSessions: true,
            refreshExternalizedIntegrationOrderId: orderSyncTargetId,
          }
        : shouldRefreshOrderSyncAuth
          ? { forceReload: true, refreshExternalizedSessions: true }
        : {},
  );
  const context = validateSessionContext(db, authPayload);
  req.__authDb = db;
  req.__authContext = context;
  return context;
}

async function enforceRoutePolicy(req, res, requestUrl) {
  if (req.__corsRejected) {
    sendJson(res, 403, {
      ok: false,
      error: "Origine CORS non consentita.",
      code: "CORS_ORIGIN_REJECTED",
    });
    return false;
  }

  if (!requestUrl.pathname.startsWith("/api/")) return true;
  const policy = resolveRoutePolicy(
    req.method,
    requestUrl.pathname,
    routeRegistry,
  );
  if (policy.category === "public") return true;

  if (policy.category === "debug" && !ENABLE_DEBUG_ENDPOINTS) {
    sendJson(res, 404, { ok: false, error: "Endpoint non trovato." });
    return false;
  }

  if (policy.category === "serviceToken") {
    const payload =
      req.method === "GET" ? {} : await readJsonBody(req).catch(() => ({}));
    const providedToken = readServiceTokenFromRequest(req, requestUrl, payload);
    const expectedToken =
      policy.service === "smart-card"
        ? SMART_CARD_PUSH_TOKEN
        : INTEGRATION_SERVICE_TOKEN;
    if (expectedToken && safeTokenEquals(providedToken, expectedToken))
      return true;
    if (
      policy.service === "smart-card" &&
      !expectedToken &&
      isAllowedSmartCardLocalRequest(req)
    )
      return true;
    await resolveAuthenticatedRequestContext(req, requestUrl);
    return true;
  }

  const { user } = await resolveAuthenticatedRequestContext(req, requestUrl);
  if (policy.category === "admin" || policy.category === "debug") {
    if (!isAdminUser(user)) {
      throw new HttpError(403, "Utente non autorizzato.");
    }
    return true;
  }

  if (policy.category === "permission") {
    if (!hasPermission(user, policy.permission)) {
      throw new HttpError(403, "Permesso insufficiente.", {
        code: "PERMISSION_DENIED",
        details: { permission: policy.permission },
      });
    }
  }

  return true;
}

async function handleHttpRequest(req, res) {
  applyCors(req, res);

  if (req.method === "OPTIONS") {
    res.statusCode = req.__corsRejected ? 403 : 204;
    res.end();
    return;
  }

  const requestUrl = new URL(
    req.url ?? "/",
    `http://${req.headers.host ?? "localhost"}`,
  );
  applyRouteBodyLimit(req, req.method, requestUrl.pathname);

  try {
    if (!(await enforceRoutePolicy(req, res, requestUrl))) {
      return;
    }

    if (await dispatchRegisteredRoute(routeRegistry, req, res, requestUrl)) {
      return;
    }

    // Tutte le route API esatte note sono risolte dalla registry; i percorsi non registrati restano 404.
    sendJson(res, 404, { ok: false, error: "Endpoint non trovato." });
  } catch (error) {
    if (await retryTransientMysqlStationStateRequest({
        req,
        res,
        pathname: requestUrl.pathname,
        error,
        isStationStateFastPathRequest,
        retry: () => handleHttpRequest(req, res),
      })) {
      return;
    }

    if (await retryTransientMysqlOrderWorkflowRequest({
        req,
        res,
        pathname: requestUrl.pathname,
        error,
        isOrderSyncFastLaneRequest,
        retry: () => handleHttpRequest(req, res),
      })) {
      return;
    }
    if (await retryTransientMysqlPaymentRequest({ req, res, pathname: requestUrl.pathname, error, isPaymentLaneRequest, retry: () => handleHttpRequest(req, res) })) return;
    if (await retryTransientMysqlNotificationAckRequest({ req, res, pathname: requestUrl.pathname, error, retry: () => handleHttpRequest(req, res) })) return;
    if (error instanceof HttpError) {
      sendJson(res, error.status, {
        ok: false,
        error: error.message,
        ...(error.code ? { code: error.code } : {}),
        ...(error.details ? { details: error.details } : {}),
      });
      return;
    }

    const message = IS_PRODUCTION
      ? "Errore interno."
      : error instanceof Error
        ? error.message
        : "Errore interno.";
    sendJson(res, 500, { ok: false, error: message });
  }
}

async function primeJsonBodyBeforeSerializedMutation(req, res) {
  applyRouteBodyLimit(req, req.method, resolveRequestPathname(req));
  if (!requestMayHaveJsonBody(req)) return true;
  try {
    await readJsonBody(req);
    return true;
  } catch (error) {
    applyCors(req, res);
    if (error instanceof HttpError) {
      sendJson(res, error.status, {
        ok: false,
        error: error.message,
        ...(error.code ? { code: error.code } : {}),
        ...(error.details ? { details: error.details } : {}),
      });
      return false;
    }
    sendJson(res, 400, {
      ok: false,
      error: error instanceof Error ? error.message : "JSON non valido.",
    });
    return false;
  }
}

async function reconcileRelationalTablesAtStartup(appState) {
  if (!RELATIONAL_TABLES_STARTUP_RECONCILE || !SHOULD_RUN_BACKEND_OWNER_JOBS) {
    return null;
  }
  if (!["shadow", "primary"].includes(relationalRuntime.mode)) {
    return null;
  }
  try {
    await relationalRuntime.initialize();
    if (!relationalRuntime?.db) {
      console.warn("[relational:tables] startup reconcile saltato: DB non disponibile.");
      return null;
    }
    const result = syncTablesBillsFromAppState(relationalRuntime.db, appState, { nowIso });
    console.info(
      `[relational:tables] startup reconcile completato: ${result.rowCount} righe, checksum ${result.checksum}`,
    );
    return result;
  } catch (error) {
    console.warn(
      "[relational:tables] startup reconcile fallito:",
      error instanceof Error ? error.message : String(error),
    );
    return null;
  }
}

await relationalRuntime.initialize();
const initialAppState = await readDb();
refreshHealthSnapshotFromDb(initialAppState);
await reconcileRelationalTablesAtStartup(initialAppState);
if (STATION_STATE_LAST_WRITE_COALESCE && SHOULD_RUN_BACKEND_OWNER_JOBS && ORDERS_ANY_ASYNC_ACK) { await persistReconciledOrders({ pending: pendingOrdersStartupReconcile, readDb, writeOrderSyncDb: writeIntegrationOrderSyncDb, pruneIntegrationState, nowIso, runtimeMetrics, logger: console }); pendingOrdersStartupReconcile = null; } if (STATION_STATE_LAST_WRITE_COALESCE && SHOULD_RUN_BACKEND_OWNER_JOBS) await stationStateLastWriteFlush.recoverFromAppState(initialAppState);
if (SHOULD_RUN_BACKEND_OWNER_JOBS) await relationalRuntime.syncAfterAppStateWrite(initialAppState);
if (SHOULD_RUN_REALTIME_OUTBOX_PUBLISHER && mqttRealtimeBridge.enabled) mqttRealtimeBridge.start();
if (SHOULD_RUN_REALTIME_OUTBOX_PUBLISHER) realtimeEventOutboxCoordinator.startPolling({ intervalMs: EVENT_OUTBOX_DRAIN_INTERVAL_MS, retentionHours: EVENT_OUTBOX_RETENTION_HOURS, retentionIntervalMs: EVENT_OUTBOX_RETENTION_INTERVAL_MS });

const server = createServer(async (req, res) => {
  const pathname = resolveRequestPathname(req);
  const metricsContext = buildRequestMetricsContext(req, pathname);
  req.__requestMetricsContext = metricsContext;
  let metricsRecorded = false;
  const finalizeMetrics = () => {
    if (metricsRecorded) return;
    metricsRecorded = true;
    metricsContext.status = res.statusCode;
    recordRequestMetrics(metricsContext);
  };
  res.once("finish", finalizeMetrics);
  res.once("close", finalizeMetrics);
  if (req.method !== "OPTIONS" && !backendProcessRouteGuard.decide(req.method, pathname).allowed) { applyCors(req, res); sendJson(res, 503, { ok: false, code: "BACKEND_PROCESS_ROUTE_BLOCKED", error: `Route non disponibile su processo ${backendProcessRouteGuard.role}.`, role: backendProcessRouteGuard.role }); return; }

  await requestMetricsStorage.run(metricsContext, async () => {
    if (isAuthSessionStatusFastPathRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) return;
      req.__authSessionStatusFastPath = true;
      await handleHttpRequest(req, res);
      return;
    }
    if (isWaiterPauseLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) return;
      await enqueuePresenceMutation(req, pathname, async () => handleHttpRequest(req, res), "waiter");
      return;
    }
    if (isStationStateFastPathRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      if (STATION_STATE_FAST_PATH_ENABLED && isStationStateFastPathEligibleFromRequest(req)) {
        req.__stationStateFastPath = true;
        await handleHttpRequest(req, res);
        return;
      }
      await enqueueStationStateMutation(req, res, pathname, async () => handleHttpRequest(req, res));
      return;
    }
    if (isNotificationLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      const notificationLaneKey = resolveNotificationLaneKeyFromRequest(
        req,
        pathname,
      );
      if (notificationLaneKey) {
        const notificationLaneLabel = `${req.method ?? "GET"} ${pathname}`;
        await notificationLane.enqueue(
          notificationLaneLabel,
          notificationLaneKey,
          async () => handleHttpRequest(req, res),
          {
            fallback: () =>
              withDbMutation(
                `${req.method ?? "GET"} ${pathname}`,
                async () => handleHttpRequest(req, res),
                {
                  shouldPreserveHotCaches: () =>
                    req.__preserveIntegrationHotCaches === true,
                },
              ),
            shouldPreserveHotCaches: () =>
              req.__preserveIntegrationHotCaches === true,
            priority: dbMutationPriority(notificationLaneLabel),
          },
        );
        return;
      }
    }
    if (isPrintLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) return;
      const printLaneKeys = resolvePrintLaneKeysFromRequest(req, pathname);
      if (printLaneKeys.length > 0) {
        await printLane.enqueue(`${req.method ?? "GET"} ${pathname}`, printLaneKeys, async () => handleHttpRequest(req, res), {
          fallback: () => withDbMutation(`${req.method ?? "GET"} ${pathname}`, async () => handleHttpRequest(req, res), { shouldPreserveHotCaches: () => req.__preserveIntegrationHotCaches === true }),
          shouldPreserveHotCaches: () => req.__preserveIntegrationHotCaches === true,
        });
        return;
      }
    }
    if (isOrderSyncFastLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      const terminalDuplicatePreLaneOptions = { applyCors, appStateOrderTargetedRefresh: mysqlAppStateDomainsSplitRepository?.enabled === true && typeof mysqlAppStateDomainsSplitRepository.readObjectArrayEntry === "function", findIntegrationOrderIndexByLookup, isIntegrationOrderCancelled, mergeRequestAuthPayload, normalizeIntegrationWorkflowStatus, orderLaneMetricLabeler, readDb, readRelationalOrderById: (orderId) => findRelationalOrderById({ enabled: RELATIONAL_ORDERS_SYNC_WRITE_PRIMARY, orderId, relationalRuntime, runtimeMetrics }), relationalSyncWritePrimary: RELATIONAL_ORDERS_SYNC_WRITE_PRIMARY, runtimeMetrics, sanitizeIntegrationOrder, sendJson, validateSessionContext };
      if (await tryHandleTerminalDuplicateOrderSyncPreLane(req, res, pathname, terminalDuplicatePreLaneOptions)) return;
      if (await tryHandleOrderWorkflowFastReject(req, res, pathname)) {
        return;
      }
      const orderSyncKey = resolveOrderSyncLaneKeyFromRequest(req);
      if (orderSyncKey) {
        await withOrderSyncLaneMutation(
          orderLaneMetricLabeler.buildLabel(req, pathname),
          orderSyncKey,
          async () => {
            req.__orderWorkflowFastLane = true;
            return handleHttpRequest(req, res);
          },
          {
            shouldPreserveHotCaches: () =>
              req.__preserveIntegrationHotCaches === true,
          },
        );
        return;
      }
    }
    if (isPaymentLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      const paymentLaneKey = resolvePaymentLaneKeyFromRequest(req, pathname);
      if (paymentLaneKey) {
        await withPaymentLaneMutation(
          `${req.method ?? "GET"} ${pathname}`,
          paymentLaneKey,
          async () => handleHttpRequest(req, res),
          {
            deferNamedLockAdmission: canDeferPaymentNamedLockAdmission(pathname, { relationalWritePrimary: RELATIONAL_PAYMENTS_FREE_SPLIT_WRITE_PRIMARY, durableMirror: PAYMENT_FREE_SPLIT_DURABLE_MIRROR, statelessMirror: PAYMENT_MIRROR_STATELESS_CONSUMER }),
            shouldPreserveHotCaches: () =>
              req.__preserveIntegrationHotCaches === true,
          },
        );
        return;
      }
    }
    if (posRoomChangeApprovePinProof.shouldPrepare(req, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) return;
      await posRoomChangeApprovePinProof.prepare(req, pathname);
    }
    if (isRoomLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      if (await tryHandleRoomLaneFastReject(req, res, pathname)) {
        return;
      }
      const roomLaneKeys = resolveRoomLaneKeysFromRequest(req, pathname);
      if (roomLaneKeys.length > 0) {
        await withRoomLaneMutation(
          `${req.method ?? "GET"} ${pathname}`,
          roomLaneKeys,
          async () => handleHttpRequest(req, res),
          {
            shouldPreserveHotCaches: () =>
              req.__preserveIntegrationHotCaches === true,
          },
        );
        return;
      }
    }
    if (isReservationLaneRequest(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      const reservationLaneKeys = resolveReservationLaneKeysFromRequest(
        req,
        pathname,
      );
      if (reservationLaneKeys.length > 0) {
        await reservationLane.enqueue(
          `${req.method ?? "GET"} ${pathname}`,
          reservationLaneKeys,
          async () => handleHttpRequest(req, res),
          {
            fallback: () =>
              withDbMutation(
                `${req.method ?? "GET"} ${pathname}`,
                async () => handleHttpRequest(req, res),
                {
                  shouldPreserveHotCaches: () =>
                    req.__preserveIntegrationHotCaches === true,
                },
              ),
            shouldPreserveHotCaches: () =>
              req.__preserveIntegrationHotCaches === true,
          },
        );
        return;
      }
    }
    if (shouldSerializeApiMutation(req.method, pathname)) {
      if (!(await primeJsonBodyBeforeSerializedMutation(req, res))) {
        return;
      }
      await withDbMutation(
        `${req.method ?? "GET"} ${pathname}`,
        async () => handleHttpRequest(req, res),
        {
          shouldPreserveHotCaches: () =>
            req.__preserveIntegrationHotCaches === true,
        },
      );
      return;
    }
    await handleHttpRequest(req, res);
  });
});

